function awardsToSearchText(awardsJson, awardMetaMap) {
  const items = parseAwards(awardsJson);
  if (!items.length) return "";
  const parts = [];
  for (const a of items) {
    // 🔧 v7.13.0: 동적(사용자 생성) 상도 검색 가능 — 이전엔 AWARD_META(레거시 9종) 미스 시 continue로 통째 누락.
    //   awardMetaMap(buildAwardMetaMap)으로 사용자 상 이름까지 해석. 둘 다 없으면 연도만이라도 포함.
    const meta = AWARD_META[a.type] || (awardMetaMap && awardMetaMap[a.type]);
    parts.push(String(a.year));
    if (meta?.label) parts.push(meta.label);
    else if (a.name) parts.push(a.name);
  }
  parts.push("수상");
  return parts.join(" ");
}

// 점수 기반 권장 티어 계산
// ⚙️ 전역 티어 설정 (설정에서 변경 가능, 앱 시작 시 로드됨)
let globalTierThresholds = { S: 1950, A: 1850, "B+": 1700, B: 1600, "B-": 1500 };
// 🆕 v6.0: 유연한 티어 시스템 - 전역 config (tierSystemConfig)
let globalTierConfig = { ...DEFAULT_TIER_SYSTEM_CONFIG };
// 🆕 v6.0: 티어 key→객체 룩업 테이블 (O(1) 성능 유지)
let globalTierLookup = new Map(DEFAULT_TIER_SYSTEM_CONFIG.tiers.map(t => [t.key, t]));
function rebuildTierLookup(config) {
  globalTierLookup = new Map((config && config.tiers || []).map(t => [t.key, t]));
}

// 🔧 v7.6.0 (포트 v3.10.0): ratio 모드 — id → tierKey 매핑 (loadList에서 재계산)
let globalRatioTierMap = new Map();

/**
 * 비율 기반 티어 매핑 계산
 * - rating DESC 정렬 → 누적 비율로 각 작품을 buckets에 분배
 * - ratio 합계 0이면 균등 분배 폴백
 * - 동점은 같은 티어 (boundary에서 같은 rating이면 같은 키)
 */
function computeRatioTierMap(novels, cfg) {
  const map = new Map();
  if (!cfg || !Array.isArray(cfg.tiers) || cfg.tiers.length === 0) return map;
  if (!Array.isArray(novels) || novels.length === 0) return map;

  // 정렬 가능한 작품만 (rating 숫자)
  const sorted = novels
    .filter(n => n && n.id)
    .map(n => ({ id: n.id, rating: Number(n.rating) || 0 }))
    .sort((a, b) => b.rating - a.rating);

  const total = sorted.length;
  if (total === 0) return map;

  // ratio 합계 — 0이면 균등 분배
  const ratios = cfg.tiers.map(t => Math.max(0, Number(t.ratio) || 0));
  let sumR = ratios.reduce((a, b) => a + b, 0);
  if (sumR <= 0) sumR = cfg.tiers.length, ratios.fill(1);

  // 각 티어 누적 경계 (count 기준)
  // 🔧 v7.14.0 (P1): 작품 수가 적을 때 Math.round 단독이면 상위 티어 누적 share가 0.5 미만→0으로
  //   반올림되어 최상위 티어가 비고 #1 작품이 S에 못 들어가던 버그(예: 3작품·S=10% → S 비고 #1→A).
  //   티어는 '순위'이기도 하므로, 비율>0인 티어는 작품이 남아있는 한 상위부터 최소 1개씩 채운다.
  const cumCounts = [];
  let acc = 0;
  let prevCum = 0;
  for (let i = 0; i < ratios.length; i++) {
    acc += (ratios[i] / sumR) * total;
    let c = Math.round(acc);
    if (c < prevCum) c = prevCum;                                            // 단조 비감소 보장
    if (ratios[i] > 0 && c === prevCum && prevCum < total) c = prevCum + 1;   // 상위 티어 starvation 방지
    cumCounts.push(c);
    prevCum = c;
  }
  // 마지막 경계는 항상 total
  cumCounts[cumCounts.length - 1] = total;

  // 위치(0-indexed) → 티어 인덱스. cumCounts는 비감소 + 마지막=total 보장이라 항상 유효.
  const tierForPos = (pos) => {
    for (let t = 0; t < cumCounts.length; t++) {
      if (pos < cumCounts[t]) return t;
    }
    return cumCounts.length - 1;
  };

  // 🔧 v7.6.0 사후검토: 동점 그룹 단위로 묶어 "그룹 중앙 위치"의 티어를 그룹 전체에 부여.
  // (이전: 직전 작품 티어를 그대로 복사 → 전원 동률(갓 만든 미매칭 데이터, 전부 1500)일 때
  //  연쇄적으로 0번 작품의 S 티어가 전체로 전파되어 "전원 S" 붕괴. 중앙 위치 방식은
  //  동일 레이팅=동일 티어 불변식을 유지하면서 전원 동률 시 중앙 티어로 수렴시킨다.)
  let i = 0;
  while (i < total) {
    let j = i;
    while (j + 1 < total && sorted[j + 1].rating === sorted[i].rating) j++;
    const mid = Math.floor((i + j) / 2);
    const key = cfg.tiers[tierForPos(mid)].key;
    for (let k = i; k <= j; k++) map.set(sorted[k].id, key);
    i = j + 1;
  }
  return map;
}

