// 🆕 v6.0: config-aware 티어 함수들
function tierFromRating(r, configOrThresholds) {
  // globalTierConfig 기본 사용
  const cfg = configOrThresholds || globalTierConfig;
  // tierSystemConfig 형태 (tiers 배열 보유)
  if (cfg && cfg.tiers && Array.isArray(cfg.tiers) && cfg.tiers.length > 0) {
    // 🆕 v7.0.2: threshold 내림차순 보장 (커스텀 프리셋/사용자 재정렬 대비) — 미정렬 시 조기 short-circuit으로 오티어 부여
    const sortedTiers = [...cfg.tiers].sort((a, b) => (Number(b.threshold) || 0) - (Number(a.threshold) || 0));
    for (const t of sortedTiers) {
      if (r >= t.threshold) return t.key;
    }
    return sortedTiers[sortedTiers.length - 1].key;
  }
  // 레거시 thresholds 객체 폴백
  const th = cfg || globalTierThresholds;
  if (r >= (th.S || 1950)) return "S";
  if (r >= (th.A || 1850)) return "A";
  if (r >= (th["B+"] || 1700)) return "B+";
  if (r >= (th.B || 1600)) return "B";
  if (r >= (th["B-"] || 1500)) return "B-";
  return "C";
}

function tierRank(tier, config) {
  const order = config ? getActiveTierOrder(config) : getActiveTierOrder(globalTierConfig);
  const idx = order.indexOf(tier);
  return idx === -1 ? order.length : idx;
}

// 🆕 v7.0: 하이브리드 모드 검증 — 두 작품 manual 순서와 사용자 선택 비교, 위반 종류 반환
// "tier" = manual_tier 위반, "order" = 같은 tier 내 manual_order 위반, "none" = 일치 (의심작이 짐)
function detectViolation(novelA, novelB, choice, tierConfig) {
  const cfg = tierConfig || globalTierConfig;
  const tIA = tierRank(novelA.manual_tier, cfg);
  const tIB = tierRank(novelB.manual_tier, cfg);
  if (tIA < tIB) return choice === "b" ? "tier" : "none";
  if (tIA > tIB) return choice === "a" ? "tier" : "none";
  const oA = Number(novelA.manual_order) || 0;
  const oB = Number(novelB.manual_order) || 0;
  if (oA < oB) return choice === "b" ? "order" : "none";
  if (oA > oB) return choice === "a" ? "order" : "none";
  return "none";
}

// 🆕 v7.0: 검증 큐 INSERT — 사용자 편집 행위 발생 시 호출. 시스템 변경(finalize)은 호출 X
// 🆕 v7.4.13: read_progress 제거(noise) + user_flag/auto_detected/conflict 신설.
// baseReason은 단일 축이고, computeVerificationPriority가 user_flagged_suspect/block_count도 합산.
const VERIFICATION_PRIORITY = {
  gatekeeper: 5,    // legacy (수문장 modal에서 enqueue 제거 — A3) — 기존 큐 row 처리용
  tier_change: 4,
  order_change: 3,
  new: 2,
  continue: 2,      // 🆕 v7.16.0 #2: 전승(변곡 없음) 시 이어서 수렴(계속 등반) 재등록
  conflict: 1,      // 🆕 v7.5.0 신작 충돌 캐스케이드 (Phase B)
  user_flag: 0,     // 🆕 v7.4.13 baseReason 0 — flagWeight(+3)로 가산
  auto_detected: 0, // 🆕 v7.5.0 전적 기반 자동 검출 (Phase B)
  meta_edit: 1,     // (m6 제거됨, legacy 큐 호환만)
};

// 🆕 v7.4.13: priority 다축 통합 — 단일 reason 상수가 아닌 동적 함수.
// 🆕 v7.5.0: conflictWeight + recordSkewWeight 추가 — Phase B 자가 시그널 통합.
// novel = { user_flagged_suspect, _block_count, conflict_hits, verification_wins/losses/count }
// 합산: baseReason(0-4) + flagWeight(+3) + blockWeight(0-3) + conflictWeight(0-3) + skewWeight(0-3) ≈ 0-16
function computeVerificationPriority(novel, reason) {
  const base = Number(VERIFICATION_PRIORITY[reason] || 0);
  const flagWeight = (novel && Number(novel.user_flagged_suspect)) ? 3 : 0;
  const blockCount = Number(novel && novel._block_count) || 0;
  const blockWeight = Math.min(blockCount, 3);
  const conflictHits = Number(novel && novel.conflict_hits) || 0;
  const conflictWeight = Math.min(conflictHits, 3);
  const vCount = Number(novel && novel.verification_count) || 0;
  const vWins = Number(novel && novel.verification_wins) || 0;
  const vLosses = Number(novel && novel.verification_losses) || 0;
  let skewWeight = 0;
  if (vCount >= 3) {
    const skewRatio = Math.abs(vWins - vLosses) / vCount;
    skewWeight = Math.min(Math.round(skewRatio * 3), 3);
  }
  // 🆕 v7.17.0: 관계형 누적 의심도 가중 (0~4) — 매칭 업셋·순위변동으로 쌓인 의심도가 큐 우선순위에 반영
  const suspWeight = Math.min(Math.round((Number(novel && novel.suspicion_score) || 0) / 4), 4);
  return base + flagWeight + blockWeight + conflictWeight + skewWeight + suspWeight;
}

// 🆕 v7.4.13: reason → 한글 매핑 (AI 프레이밍 — pending 이유 표시).
// HybridVerificationView/진단 패널에서 사용.
function formatVerificationReason(reason) {
  switch (reason) {
    case "user_flag":     return "사용자 의심 표시";
    case "tier_change":   return "최근 tier 변경";
    case "order_change":  return "최근 순위 변경";
    case "new":           return "새로 추가됨";
    case "conflict":      return "신작 추가로 영향";
    case "auto_detected": return "전적 시그널 의심 (W/L 쏠림)";
    case "continue":      return "이어서 수렴 중 (계속 등반)";
    case "gatekeeper":    return "수문장 누적 (레거시)";
    case "read_progress": return "읽기 진행 (레거시)";
    case "meta_edit":     return "메타 편집 (레거시)";
    default:              return reason || "기타";
  }
}

// v7.0.1 (M1 fix): 1초 디바운스 silent drop → UPSERT (작품당 pending 1건 보장 + 최신 의도 반영)
// 🆕 v7.0.8: source 인자 추가 — 호출자(addNovel/saveEdit/batchSetTier/swapRating/inline_chip/gatekeeper_up/gatekeeper_down) 추적
// 🆕 v7.4.13: priority 다축 통합 — computeVerificationPriority 사용. user_flag/auto_detected/conflict 지원.
// 🔬 v7.13.5 진단: 큐 등록 마지막 오류 캡처 (화면 표시)
let __lastEnqueueErr = null;
// 🔧 v7.13.6: 런타임 연결 기준 검증 보조테이블(세션/검증로그) 레거시 스키마 1회 복구.
//   enqueue가 쓰는 연결과 initDb 마이그레이션 연결이 달라(=큐 self-heal로 확인됨), 보조테이블도
//   런타임에선 옛 스키마('type' NOT NULL)일 수 있어 finalize/logVerificationMatch INSERT가 조용히
//   실패 → "비교는 되는데 결과 미저장"이 될 수 있다. 세션 시작 전 런타임 연결(exec/all)에서 복구.
//   (검증이 한 번도 완료된 적 없어 비어 있으므로 재생성 무손실. 큐는 enqueue self-heal이 담당.)
let __verifAuxFixed = false;
async function ensureVerificationAuxSchema() {
  if (__verifAuxFixed) return;
  __verifAuxFixed = true;
  const fixes = [
    { t: "tier_repositioning_session",
      create: `CREATE TABLE tier_repositioning_session (id TEXT PRIMARY KEY NOT NULL, novel_id TEXT NOT NULL, suspicion_type TEXT NOT NULL, trigger_type TEXT, state TEXT NOT NULL, result_tier TEXT, result_order INTEGER, result_action TEXT, total_responses INTEGER DEFAULT 0, blocker_id TEXT, created_at INTEGER NOT NULL, completed_at INTEGER);`,
      idx: [`CREATE INDEX IF NOT EXISTS idx_trs_blocker ON tier_repositioning_session(blocker_id, state);`, `CREATE INDEX IF NOT EXISTS idx_trs_novel ON tier_repositioning_session(novel_id);`] },
    { t: "tier_validation_log",
      create: `CREATE TABLE tier_validation_log (id TEXT PRIMARY KEY NOT NULL, session_id TEXT, novel_a_id TEXT NOT NULL, novel_b_id TEXT NOT NULL, user_choice TEXT NOT NULL, violation_type TEXT NOT NULL, created_at INTEGER NOT NULL);`,
      idx: [`CREATE INDEX IF NOT EXISTS idx_tvl_session ON tier_validation_log(session_id);`, `CREATE INDEX IF NOT EXISTS idx_tvl_a ON tier_validation_log(novel_a_id);`, `CREATE INDEX IF NOT EXISTS idx_tvl_b ON tier_validation_log(novel_b_id);`] },
  ];
  for (const f of fixes) {
    try {
      const cols = await all(`PRAGMA table_info(${f.t})`);
      if (cols && cols.some(c => c.name === "type")) {
        await exec(`DROP TABLE IF EXISTS ${f.t};`);
        await exec(f.create);
        for (const ix of f.idx) await exec(ix);
      }
    } catch (e) { console.warn("[v7.13.6] aux schema fix:", f.t, e?.message); }
  }
}
async function enqueueVerification(novelId, triggerType, suspicionType, source) {
  if (!novelId || !triggerType || !suspicionType) return;
  // 🚫 v7.6.0 (포트 v3.16.0): 매칭 밴 작품은 검증 큐에 등록하지 않음
  try {
    const banCheck = await first("SELECT match_ban FROM novels WHERE id = ?", [novelId]);
    if (banCheck?.match_ban) {
      console.log('[hybrid] enqueueVerification skipped: banned', novelId);
      return null;
    }
  } catch {}
  const now = Date.now();
  // 🆕 v7.4.13: priority 계산 시 user_flagged_suspect + block_count 조회
  // 🆕 v7.5.0: conflict_hits + verification_wins/losses/count 추가 (Phase B 가중치 통합)
  let priority = Number(VERIFICATION_PRIORITY[triggerType] || 0);
  try {
    const novelRow = await first(
      "SELECT user_flagged_suspect, conflict_hits, verification_wins, verification_losses, verification_count, suspicion_score FROM novels WHERE id=?",
      [novelId]
    );
    let blockCount = 0;
    try {
      const blockRow = await first(
        // 🔧 v7.10.0: result_action='moved' 한정 제거 — 의심작을 즉시 막아 이동을 무산시킨
        //   가장 강력한 수문장 케이스(no_change, infIdx=0)도 blocker로 카운트해야 통계 의미가 맞음.
        "SELECT COUNT(*) as cnt FROM tier_repositioning_session WHERE state='completed' AND blocker_id=?",
        [novelId]
      );
      blockCount = Number(blockRow?.cnt) || 0;
    } catch { /* block_count는 보조 시그널 — 실패 시 0 fallback */ }
    priority = computeVerificationPriority(
      { ...(novelRow || {}), _block_count: blockCount },
      triggerType
    );
  } catch { /* 우선순위 산출 실패 시 baseReason fallback (이미 위에서 priority 초기화됨) */ }
  // 🆕 v7.0.8: trigger_fire_log INSERT — UPSERT 동작과 무관하게 모든 enqueueVerification 호출 기록
  // 진단 탭에서 source × trigger 매트릭스 + 24h fire 카운트 등에 사용
  // 실패는 무음 — 진단 데이터 손실 < 사용자 작업 차단
  try {
    await exec(
      `INSERT INTO trigger_fire_log (id, trigger_type, novel_id, suspicion_type, source, created_at) VALUES (?, ?, ?, ?, ?, ?)`,
      [uuid(), triggerType, novelId, suspicionType, source || null, now]
    );
  } catch (logErr) { /* 무음 */ }
  try {
    __lastEnqueueErr = null; // 🔬 v7.13.5
    // 동일 novel_id의 pending 엔트리가 이미 있으면 최신 trigger/suspicion으로 UPDATE
    const existing = await first(
      `SELECT id, priority FROM tier_verification_queue WHERE novel_id=? AND state='pending' LIMIT 1`,
      [novelId]
    );
    if (existing) {
      // priority는 더 높은 쪽 유지 (다축 통합 시그널의 누적 보존)
      const finalPriority = Math.max(priority, Number(existing.priority) || 0);
      await exec(
        `UPDATE tier_verification_queue SET trigger_type=?, suspicion_type=?, priority=?, created_at=? WHERE id=?`,
        [triggerType, suspicionType, finalPriority, now, existing.id]
      );
    } else {
      await exec(
        `INSERT INTO tier_verification_queue (id, novel_id, trigger_type, suspicion_type, priority, state, created_at) VALUES (?, ?, ?, ?, ?, 'pending', ?)`,
        [uuid(), novelId, triggerType, suspicionType, priority, now]
      );
    }
  } catch (e) {
    __lastEnqueueErr = e?.message || String(e); // 🔬 v7.13.5
    // 🔧 v7.13.5 자가복구: 레거시 스키마(type 등 NOT NULL 잔재)로 큐 INSERT가 실패하면, INSERT를
    //   수행하는 바로 그 런타임 연결(exec)에서 큐 테이블을 정식 스키마로 통째 재생성 후 1회 재시도.
    //   initDb 마이그레이션이 다른 연결/타이밍이라 런타임에 미반영된 경우까지 확실히 복구한다.
    //   (큐는 휘발성 — 재생성해도 손실 없음. 검증/매칭이 영구 불능이던 근본원인 최종 차단.)
    if (/NOT NULL constraint failed: tier_verification_queue/i.test(__lastEnqueueErr || "")) {
      try {
        await exec(`DROP TABLE IF EXISTS tier_verification_queue;`);
        await exec(`CREATE TABLE tier_verification_queue (id TEXT PRIMARY KEY NOT NULL, novel_id TEXT NOT NULL, trigger_type TEXT NOT NULL, suspicion_type TEXT NOT NULL, priority INTEGER DEFAULT 0, state TEXT DEFAULT 'pending', created_at INTEGER NOT NULL, processed_at INTEGER);`);
        await exec(`CREATE INDEX IF NOT EXISTS idx_tvq_state ON tier_verification_queue(state, priority DESC, created_at);`);
        await exec(`CREATE INDEX IF NOT EXISTS idx_tvq_novel ON tier_verification_queue(novel_id);`);
        await exec(
          `INSERT INTO tier_verification_queue (id, novel_id, trigger_type, suspicion_type, priority, state, created_at) VALUES (?, ?, ?, ?, ?, 'pending', ?)`,
          [uuid(), novelId, triggerType, suspicionType, priority, now]
        );
        __lastEnqueueErr = null; // 자가복구 성공
      } catch (e2) {
        __lastEnqueueErr = "자가복구 실패: " + (e2?.message || String(e2));
      }
    }
    // 🔧 v7.4.2: 진단 강화 — params + source 함께 기록 (NULL 컬럼 추적용)
    console.warn("enqueueVerification 오류:", e?.message, {
      novelId,
      triggerType,
      suspicionType,
      priority,
      source,
    });
  }
}

// 🆕 v7.0: 시퀀스 후보 풀 fetch — 의심작 인접 정렬, Unrated/자기 자신 제외
async function getCandidatesForVerification(novelId, suspicionType, limit = 10) {
  const novel = await first("SELECT id, manual_tier, manual_order FROM novels WHERE id=?", [novelId]);
  if (!novel) return [];
  const mt = novel.manual_tier || "";
  // 🆕 v7.0.2: manual_tier 미설정(클리어/Unrated) 의심작은 후보 풀 정의 불가능
  // — 이전: ownTierIdx=-1로 모든 후보 rTierIdx>-1 → underrated 0건/overrated 전체 (오작동)
  if (!mt) return [];
  const mo = Number(novel.manual_order) || 0;

  // underrated: 위쪽 작품 (manual_tier가 더 높거나, 같은 tier에서 manual_order 더 작음)
  // overrated: 아래쪽 작품 (반대)
  const tierOrder = getActiveTierOrder(globalTierConfig);
  const ownTierIdx = tierOrder.indexOf(mt);
  // 비활성 티어(프리셋 전환 잔여)는 후보 비교 불가
  if (ownTierIdx === -1) return [];

  const allRows = await all(
    // 🚫 v7.6.0 (포트 v3.16.0): 매칭 밴 작품을 opponent 후보에서 제외
    // 🔧 v7.13.7: cover_image/platforms 추가 — 검증 매칭 UI에서 상대작 표지가 안 나오던 문제(미SELECT)
    `SELECT id, title, manual_tier, manual_order, rating, cover_image, platforms FROM novels
     WHERE id != ? AND manual_tier IS NOT NULL AND manual_tier != ''
        AND COALESCE(match_ban, 0) = 0`,
    [novelId]
  );

  // 🆕 v7.0.3: 거리 산출은 항상 "tier 경계에서 시작해서 멀어지는 방향"으로 정렬
  // (이전 버그: underrated cross-tier에서 rTierIdx=0(상위) 후보를 rOrder ASC로 정렬 → 상위 tier의 TOP부터
  // 매칭하던 문제. 정상은 tier 경계에 가까운 BOTTOM부터 walk-up이어야 알고리즘 일관성 보장.)
  const BIG = 1_000_000; // tier 간 분리 기준값 (rOrder 최대치를 충분히 초과)
  const scored = [];
  for (const r of allRows) {
    const rTierIdx = tierOrder.indexOf(r.manual_tier);
    if (rTierIdx === -1) continue; // 비활성 tier 후보 제외
    const rOrder = Number(r.manual_order) || 0;
    let isAbove, distance;
    if (rTierIdx < ownTierIdx) {
      // 상위 tier 후보(underrated 후보) — BOTTOM(큰 rOrder, 경계에 가까움) 부터 walk
      isAbove = true;
      distance = (ownTierIdx - rTierIdx) * BIG + (BIG - rOrder);
    } else if (rTierIdx > ownTierIdx) {
      // 하위 tier 후보(overrated 후보) — TOP(작은 rOrder, 경계에 가까움) 부터 walk
      isAbove = false;
      distance = (rTierIdx - ownTierIdx) * BIG + rOrder;
    } else {
      // 같은 tier
      if (rOrder < mo) { isAbove = true; distance = mo - rOrder; }
      else if (rOrder > mo) { isAbove = false; distance = rOrder - mo; }
      else continue; // 같은 자리 무시
    }
    if (suspicionType === "underrated" && !isAbove) continue;
    if (suspicionType === "overrated" && isAbove) continue;
    scored.push({ ...r, _distance: distance });
  }
  scored.sort((a, b) => a._distance - b._distance);
  return scored.slice(0, limit);
}

// 🆕 v7.0: 검증 시퀀스 상수 — 변곡점 알고리즘 / K=2 추가 매칭 / max=7
const VERIFICATION_MAX_RESPONSES = 7;
const VERIFICATION_K_AFTER_INFLECTION = 2;

// ⚠️ v7.4.13에서 read_progress(읽은 회차 누적) 트리거는 noise로 판단되어 제거됨 → 이 상수와
//    read_count_baseline 컬럼은 현재 어떤 검증도 발화시키지 않는 잔존(vestigial) 인프라다.
//    (컬럼은 백업 round-trip/마이그레이션 호환을 위해 유지. 회차를 올려도 의심작은 선정되지 않음 — 의도된 침묵.)
//    v7.13.0: 살아있는 기능처럼 읽히던 주석을 정정(코드 동작 변경 아님).
// 🗄️ (구) v7.0.15 설계: (현재 read_count − read_count_baseline) >= 이 값이면 read_progress fire (underrated).
//    누적 트래킹: read_count_baseline은 last-fire 시점 read_count. 청크 분할 저장(5화×10번=50)도 동일하게 잡힘.
const VERIFICATION_READ_COUNT_THRESHOLD = 30;

// 🆕 v7.0: 검증 큐에서 다음 처리 대상 작품 fetch (priority DESC, 디바운스 1초 적용)
async function getNextVerificationTarget() {
  try {
    const cutoff = Date.now() - 1000; // 1초 디바운스 (생성 직후는 제외)
    const row = await first(
      `SELECT q.*, n.id as novel_exists, n.title, n.manual_tier, n.manual_order
       FROM tier_verification_queue q
       LEFT JOIN novels n ON n.id = q.novel_id
       WHERE q.state='pending' AND q.created_at < ?
       ORDER BY q.priority DESC, q.created_at ASC
       LIMIT 1`,
      [cutoff]
    );
    if (!row || !row.novel_exists) {
      // 작품 삭제된 경우 큐 항목도 정리
      if (row && !row.novel_exists) {
        await exec(`UPDATE tier_verification_queue SET state='cancelled', processed_at=? WHERE id=?`, [Date.now(), row.id]);
      }
      return null;
    }
    return row;
  } catch (e) {
    console.warn("[v7.0] getNextVerificationTarget 오류:", e?.message);
    return null;
  }
}

// 🆕 v7.0: 변곡점(inflection point) 판정
// responses: [{candidateId, suspicionWon}] — suspicionWon=true면 의심작이 후보를 이김
// underrated 의심 → 의심작이 후보를 이기는 것이 "예상" (manual_order/tier 위반 발견)
// overrated 의심 → 의심작이 후보에게 지는 것이 "예상" (manual_order/tier 위반 발견)
// 변곡점 = 첫 번째 "예상 이탈" 인덱스 (-1이면 미발견)
function findInflectionPoint(responses, suspicionType) {
  if (!responses || responses.length === 0) return -1;
  // expected: 의심작이 어느 방향으로 이동해야 한다는 가설을 검증
  // underrated: 의심작이 위로 가야 함 → 의심작 이김 = 가설 강화, 짐 = 가설 부정 (변곡점)
  // overrated: 의심작이 아래로 가야 함 → 의심작 짐 = 가설 강화, 이김 = 가설 부정 (변곡점)
  for (let i = 0; i < responses.length; i++) {
    const r = responses[i];
    if (suspicionType === "underrated" && !r.suspicionWon) return i;
    if (suspicionType === "overrated" && r.suspicionWon) return i;
  }
  return -1;
}

// 🆕 v7.0: 시퀀스 종료 판정
// returns: { shouldStop, reason }
// reason: "max" | "decisive" | "no_inflection" | "continue"
function evaluateSequenceProgress(responses, suspicionType) {
  if (responses.length >= VERIFICATION_MAX_RESPONSES) {
    return { shouldStop: true, reason: "max" };
  }
  const infIdx = findInflectionPoint(responses, suspicionType);
  if (infIdx === -1) {
    // 변곡점 미발견 — max까지 계속
    return { shouldStop: false, reason: "no_inflection" };
  }
  // 🆕 v7.0.3: 첫 매치(idx=0)부터 가설 부정 → K=2 더 물어봐도 placement는 no_change
  // 즉시 종료하여 사용자에게 무의미한 추가 질문을 막음 (computeNewPosition에서 no_change 반환)
  if (infIdx === 0) {
    return { shouldStop: true, reason: "rejected" };
  }
  // 변곡점 발견 후 K=2 추가 매칭 필요
  const afterInflection = responses.length - 1 - infIdx;
  if (afterInflection >= VERIFICATION_K_AFTER_INFLECTION) {
    return { shouldStop: true, reason: "decisive" };
  }
  return { shouldStop: false, reason: "continue" };
}

// 🆕 v7.0: 시퀀스 종료 시 새 자리 산출 (system path — 트리거 X)
// 변곡점 = "이 후보까지는 의심작이 이동해야 함"의 경계
// blocker = 변곡점 인덱스의 후보 (수문장 후보)
function computeNewPosition(suspicionNovel, candidates, responses, suspicionType, tierConfig) {
  const cfg = tierConfig || globalTierConfig;
  const tierOrder = getActiveTierOrder(cfg);
  const infIdx = findInflectionPoint(responses, suspicionType);
  const ownTierIdx = tierOrder.indexOf(suspicionNovel.manual_tier);
  const ownOrder = Number(suspicionNovel.manual_order) || 0;

  // 변곡점 미발견 (모든 응답이 가설 방향)
  if (infIdx === -1) {
    // 가장 멀리 있는 응답 후보의 위치까지 이동
    const lastIdx = responses.length - 1;
    if (lastIdx < 0) {
      return { tier: suspicionNovel.manual_tier, order: ownOrder, blockerId: null, action: "no_change" };
    }
    const lastResp = responses[lastIdx];
    const lastCand = candidates.find(c => c.id === lastResp.candidateId);
    if (!lastCand) {
      return { tier: suspicionNovel.manual_tier, order: ownOrder, blockerId: null, action: "no_change" };
    }
    // suspicionType에 따라 "넘어선" 위치
    if (suspicionType === "underrated") {
      // 위쪽 후보 → 그 후보 바로 위로
      const newOrder = (Number(lastCand.manual_order) || 0) - 50;
      return { tier: lastCand.manual_tier, order: newOrder, blockerId: null, action: "moved" };
    } else {
      // 아래쪽 후보 → 그 후보 바로 아래로
      const newOrder = (Number(lastCand.manual_order) || 0) + 50;
      return { tier: lastCand.manual_tier, order: newOrder, blockerId: null, action: "moved" };
    }
  }

  // 변곡점 발견 — blocker = responses[infIdx].candidateId
  const blockerResp = responses[infIdx];
  const blockerCand = candidates.find(c => c.id === blockerResp.candidateId);
  if (!blockerCand) {
    return { tier: suspicionNovel.manual_tier, order: ownOrder, blockerId: null, action: "no_change" };
  }

  // 변곡점 직전(infIdx-1)까지의 후보들을 넘어섬, blocker에게 막힘
  if (infIdx === 0) {
    // 첫 매치부터 가설 부정 → 의심 무효
    return { tier: suspicionNovel.manual_tier, order: ownOrder, blockerId: blockerCand.id, action: "no_change" };
  }

  // 변곡점 직전 후보(passedCand) 위치 + blocker 사이로 자리 결정
  const passedResp = responses[infIdx - 1];
  const passedCand = candidates.find(c => c.id === passedResp.candidateId);
  if (!passedCand) {
    return { tier: suspicionNovel.manual_tier, order: ownOrder, blockerId: blockerCand.id, action: "no_change" };
  }

  // 🔧 v7.10.0: K단계(blocker 재대결) 결과로 경계 확정 여부 판정. infIdx 이후 응답은 모두 blocker와의
  //   재대결(respondVerificationMatch가 K단계에 blocker를 재present). 과반이 경계를 확인하면 아래의
  //   passed~blocker 사이 배치, 아니면(의심작이 재대결에서 blocker를 넘어섬) blocker 자리로 이동시켜
  //   K 응답이 실제 자리에 반영되도록 한다(이전엔 변곡점 이후 K 응답이 자리 산출에서 무시됐음).
  const blockerResults = responses.slice(infIdx).filter(r => r.candidateId === blockerCand.id);
  const confirms = blockerResults.filter(r => suspicionType === "underrated" ? !r.suspicionWon : r.suspicionWon).length;
  const boundaryConfirmed = confirms * 2 >= blockerResults.length; // 동률 포함 과반이 경계 확인
  if (!boundaryConfirmed) {
    // 재대결에서 의심작이 blocker를 넘어섬 → blocker가 실제로 막지 못함. blocker 자리(경계)로 이동.
    //   막지 못했으므로 수문장으로 기록하지 않음(blockerId=null).
    const bOrder = Number(blockerCand.manual_order) || 0;
    return suspicionType === "underrated"
      ? { tier: blockerCand.manual_tier, order: bOrder - 25, blockerId: null, action: "moved" }
      : { tier: blockerCand.manual_tier, order: bOrder + 25, blockerId: null, action: "moved" };
  }

  // 두 후보 사이 — 같은 tier면 단순 사이값, 다른 tier면 passed의 tier 끝/시작
  // v7.0.1 (C1 fix): collision/gap 압축 위험은 finalize 후 rebalanceTierOrder로 복구
  const passedOrder = Number(passedCand.manual_order) || 0;
  const blockerOrder = Number(blockerCand.manual_order) || 0;
  // 🆕 v7.0.3: cross-tier 방향 수정 — 이전 버그: passed보다 "약간 아래(+50)"로 배치하여
  // suspicion이 passed에게 졌다는 의미가 되어 hypothesis(suspicion이 passed 위)와 모순.
  // underrated: suspicion이 passed를 이김 → passed 위, blocker 아래(다른 tier).
  // overrated: suspicion이 passed에게 짐 → passed 아래, blocker 위(다른 tier).
  if (suspicionType === "underrated") {
    // 위쪽으로 이동: passed보다 위(작은 order), blocker보다 아래(큰 order, blocker tier가 더 위면 무관)
    if (passedCand.manual_tier === blockerCand.manual_tier) {
      // 같은 tier이면 두 사이값. 충돌 시 passed-1로 두고 finalize의 rebalance가 stable-sort로 정합성 회복
      const order = passedOrder === blockerOrder ? passedOrder - 1 : Math.floor((passedOrder + blockerOrder) / 2);
      return { tier: passedCand.manual_tier, order, blockerId: blockerCand.id, action: "moved" };
    } else {
      // 다른 tier — passed의 tier에서 passed 위(passedOrder - 50)
      return { tier: passedCand.manual_tier, order: passedOrder - 50, blockerId: blockerCand.id, action: "moved" };
    }
  } else {
    // overrated: 아래쪽으로 이동: passed보다 아래(큰 order), blocker보다 위
    if (passedCand.manual_tier === blockerCand.manual_tier) {
      const order = passedOrder === blockerOrder ? passedOrder + 1 : Math.floor((passedOrder + blockerOrder) / 2);
      return { tier: passedCand.manual_tier, order, blockerId: blockerCand.id, action: "moved" };
    } else {
      // 다른 tier — passed의 tier에서 passed 아래(passedOrder + 50)
      return { tier: passedCand.manual_tier, order: passedOrder + 50, blockerId: blockerCand.id, action: "moved" };
    }
  }
}

// 🆕 v7.0: 시퀀스 finalize — 검증 큐 마감 + 자리 UPDATE (시스템 path, 트리거 X) + 세션 INSERT
async function finalizeVerificationSession(queueRow, suspicionNovel, candidates, responses, suspicionType, stopReason) {
  const sessionId = uuid();
  const now = Date.now();
  // 🆕 v7.0.3: passed/blocker 후보를 DB에서 fresh fetch — 세션 동안 다른 경로가 manual_tier/order를
  // 변경했을 가능성 차단 (stale snapshot으로 finalize → 잘못된 자리 산출 방지)
  const refreshedCandidates = [...candidates];
  try {
    const refIds = responses.map(r => r.candidateId).filter(Boolean);
    if (refIds.length > 0) {
      const placeholders = refIds.map(() => "?").join(",");
      const fresh = await all(
        `SELECT id, manual_tier, manual_order FROM novels WHERE id IN (${placeholders})`,
        refIds
      );
      const freshById = new Map((fresh || []).map(r => [r.id, r]));
      for (let i = 0; i < refreshedCandidates.length; i++) {
        const c = refreshedCandidates[i];
        const upd = freshById.get(c.id);
        if (upd) refreshedCandidates[i] = { ...c, manual_tier: upd.manual_tier, manual_order: upd.manual_order };
      }
    }
  } catch (e) { console.warn("[v7.0.3] finalize refresh 실패:", e?.message); }
  const newPos = computeNewPosition(suspicionNovel, refreshedCandidates, responses, suspicionType, globalTierConfig);

  try {
    // 🆕 v7.0.2: session INSERT + novel UPDATE + queue UPDATE를 단일 트랜잭션으로 묶어 원자성 보장
    // (이전: 4개 별도 exec → 중간 크래시/SQLITE_BUSY 시 큐 pending인데 자리 이미 이동 → 재 finalize 시 자리 중복 이동)
    const txBatch = [];
    txBatch.push({
      sql: `INSERT INTO tier_repositioning_session (id, novel_id, suspicion_type, trigger_type, state, result_tier, result_order, result_action, total_responses, blocker_id, created_at, completed_at)
            VALUES (?, ?, ?, ?, 'completed', ?, ?, ?, ?, ?, ?, ?)`,
      params: [
        sessionId,
        suspicionNovel.id,
        suspicionType,
        queueRow.trigger_type || null,
        newPos.tier || null,
        newPos.order != null ? newPos.order : null,
        newPos.action,
        responses.length,
        newPos.blockerId || null,
        now,
        now,
      ],
    });

    if (newPos.action === "moved") {
      const tierChanged = newPos.tier && newPos.tier !== suspicionNovel.manual_tier;
      if (tierChanged) {
        txBatch.push({
          sql: "UPDATE novels SET manual_tier=?, manual_order=? WHERE id=?",
          params: [newPos.tier, newPos.order, suspicionNovel.id],
        });
      } else {
        txBatch.push({
          sql: "UPDATE novels SET manual_order=? WHERE id=?",
          params: [newPos.order, suspicionNovel.id],
        });
      }
    }

    // 🆕 v7.13.7: 검증 완료 시 사용자 의심 표시(🔍) 자동 해제 + 🆕 v7.17.0: 누적 의심도 리셋(점검 완료 = 의심 해소, 사용자 결정: 검증 시에만 리셋)
    txBatch.push({
      sql: "UPDATE novels SET user_flagged_suspect=0, suspicion_score=0 WHERE id=?",
      params: [suspicionNovel.id],
    });

    txBatch.push({
      sql: `UPDATE tier_verification_queue SET state='resolved', processed_at=? WHERE id=?`,
      params: [now, queueRow.id],
    });

    await execBatch(txBatch);

    // v7.0.1 (C1 fix): 자리 재배치 후 manual_order gap=100 invariant 회복 (트랜잭션 밖 — gap 복원은 멱등)
    if (newPos.action === "moved") {
      const tierChanged = newPos.tier && newPos.tier !== suspicionNovel.manual_tier;
      if (newPos.tier) {
        await rebalanceTierOrder(newPos.tier);
      }
      if (tierChanged && suspicionNovel.manual_tier) {
        await rebalanceTierOrder(suspicionNovel.manual_tier);
      }
      // 🆕 v7.17.0 증거①: 시스템 이동도 '변동' — 새 자리 인접권 작품 의심도 전파(가까울수록 큼).
      await propagateRankSuspicion(suspicionNovel.id);
    }

    // 🔧 v7.16.0 (#2): 응답 상한(max)까지 변곡 없이(전 구간 가설 방향 승) 이동한 경우 — 아직 더
    //   이동할 여지가 있다는 뜻이므로 같은 방향으로 재등록해 다음 세션에서 이어서 수렴(계속 등반).
    //   후보 소진은 stopReason="exhausted"라 여기 해당 없음 → 티어 극단 도달 시 자연 종료(무한루프 방지).
    if (newPos.action === "moved" && stopReason === "max" && findInflectionPoint(responses, suspicionType) === -1) {
      try { await enqueueVerification(suspicionNovel.id, "continue", suspicionType, "auto_continue"); }
      catch (ce) { console.warn("[v7.16.0 #2] 이어서 수렴 재등록 실패:", ce?.message); }
    }

    // 🆕 v7.5.0: 전적 기반 자동 의심 검출 — 방금 누적된 W/L 시그널 반영
    // suspicionNovel.id는 방금 처리됐으므로 제외 (즉시 재enqueue 루프 방지)
    try {
      await detectAutomaticSuspects(suspicionNovel.id);
    } catch (detectErr) {
      console.warn("[v7.5.0] finalize 후 detectAutomaticSuspects 실패:", detectErr?.message);
    }

    return { sessionId, ...newPos, stopReason };
  } catch (e) {
    console.warn("[v7.0] finalizeVerificationSession 오류:", e?.message);
    // 실패 시 큐는 다음 시도에 다시 잡히도록 pending 유지 (단, 무한 루프 방지를 위해 attempt count 같은 가드는 추후 도입 가능)
    throw e;
  }
}

// 🆕 v7.0: 시퀀스 도중 매칭 응답 1건 저장
// 🆕 v7.5.0: 양쪽 작품의 verification_wins/losses/count 카운터 증분 (evidence 누적).
// INSERT + 2 UPDATE를 execBatch 단일 트랜잭션으로 묶어 원자성 보장.
async function logVerificationMatch(sessionId, suspicionId, candidateId, suspicionWon, violationType) {
  try {
    await execBatch([
      {
        sql: `INSERT INTO tier_validation_log (id, session_id, novel_a_id, novel_b_id, user_choice, violation_type, created_at)
              VALUES (?, ?, ?, ?, ?, ?, ?)`,
        params: [
          uuid(),
          sessionId,
          suspicionId,
          candidateId,
          suspicionWon ? "a" : "b", // a=의심작 승, b=후보 승
          violationType || "none",
          Date.now(),
        ],
      },
      {
        sql: `UPDATE novels SET
                verification_count = verification_count + 1,
                verification_wins = verification_wins + ?,
                verification_losses = verification_losses + ?
              WHERE id = ?`,
        params: [suspicionWon ? 1 : 0, suspicionWon ? 0 : 1, suspicionId],
      },
      {
        sql: `UPDATE novels SET
                verification_count = verification_count + 1,
                verification_wins = verification_wins + ?,
                verification_losses = verification_losses + ?
              WHERE id = ?`,
        params: [suspicionWon ? 0 : 1, suspicionWon ? 1 : 0, candidateId],
      },
    ]);
  } catch (e) {
    console.warn("[v7.0] logVerificationMatch 오류:", e?.message);
  }
}

// 🆕 v7.5.0: 전적 기반 자동 의심 검출 (시스템 자가 시그널).
// 사용자 비전 "전적이 다음 의심 판단의 근거" 구현. finalizeVerificationSession 직후 호출.
// 조건: verification_count >= 3 AND |W-L|/count >= 0.6 (한쪽 쏠림)
// 가드: pending 큐에 이미 있거나 직전 finalize 작품(excludeNovelId)은 스킵 (루프 방지)
// LIMIT 5: finalize 후 한 번에 5개까지만 자동 enqueue — 갑작스러운 큐 플러드 방지
async function detectAutomaticSuspects(excludeNovelId) {
  try {
    // 🆕 v7.17.0: 전적 쏠림(기존) OR 누적 의심도(신규)로 자동 검출. 둘 다 ORDER 가중에 반영 →
    //   매칭 업셋·순위변동으로 의심도가 높아진 연관작이 자동으로 다음 검증 대상에 오름.
    const rows = await all(
      `SELECT n.id, n.verification_wins, n.verification_losses, n.verification_count, n.suspicion_score
       FROM novels n
       LEFT JOIN tier_verification_queue q ON q.novel_id = n.id AND q.state = 'pending'
       WHERE (n.verification_count >= 3 OR COALESCE(n.suspicion_score,0) >= ?)
         AND q.id IS NULL
         AND n.id != ?
         AND n.manual_tier IS NOT NULL AND n.manual_tier != ''
       ORDER BY (COALESCE(n.suspicion_score,0) + ABS(n.verification_wins - n.verification_losses)) DESC
       LIMIT 5`,
      [globalSuspicionConfig.checkLine, excludeNovelId || ""]
    );
    for (const r of (rows || [])) {
      const w = Number(r.verification_wins) || 0;
      const l = Number(r.verification_losses) || 0;
      const total = Number(r.verification_count) || 0;
      const susp = Number(r.suspicion_score) || 0;
      const skewRatio = total >= 3 ? Math.abs(w - l) / total : 0;
      const trigBySkew = total >= 3 && skewRatio >= 0.6;
      const trigBySusp = susp >= globalSuspicionConfig.checkLine;
      if (!trigBySkew && !trigBySusp) continue;
      // 방향: 전적 우세 쪽(동률·무전적 → underrated 기본; 시퀀스가 실제 방향을 확정)
      const direction = w >= l ? "underrated" : "overrated";
      try {
        await enqueueVerification(r.id, "auto_detected", direction, "system_inference");
      } catch (innerErr) {
        console.warn("[v7.5.0] auto_detected enqueue 실패:", r.id, innerErr?.message);
      }
    }
  } catch (e) {
    console.warn("[v7.5.0] detectAutomaticSuspects 오류:", e?.message);
  }
}

// 🆕 v7.17.0: 관계형 의심도 엔진 — 상수 + 헬퍼.
//   suspicion_score는 두 증거로 누적되고 검증 시 리셋(사용자 결정: 검증 시에만 리셋, 보통 민감도):
//   ① 순위/티어 변동 → 변동 지점 인접권 작품 상승(가까울수록 큼)  ② 검증 매칭 결과 → 상대(후보)를
//   현재 순위와의 모순(업셋) 정도로 상승. 표시·큐 우선순위가 이 점수를 사용.
// 🔧 v7.18.0: 의심도 계수를 사용자 설정화(설정>의심도 민감도). 모듈 헬퍼가 읽는 module-global을
//   globalTierConfig 패턴으로 동기화. DEFAULT는 v7.17.1 튜닝값('보통').
const DEFAULT_SUSPICION_CONFIG = {
  cap: 20,            // 누적 상한
  moveBase: 0.6,      // 순위변동 인접 전파 기본량
  moveWindow: 5,      // 전파 범위 (랭크 거리)
  matchBase: 0.25,    // 매칭 기본(예상된 결과에도 소폭)
  upsetBase: 0.8,     // 업셋(순위 모순) 추가 기본
  upsetPerGap: 0.2,   // 업셋 순위차 1당 가산
  checkLine: 6,       // 점검선 = 자동검출 트리거 + 표시 100% 기준
};
let globalSuspicionConfig = { ...DEFAULT_SUSPICION_CONFIG };
// 민감도 프리셋 — 설정 UI 빠른 적용용
const SUSPICION_PRESETS = {
  conservative: { cap: 20, moveBase: 0.3, moveWindow: 4, matchBase: 0.15, upsetBase: 0.5, upsetPerGap: 0.12, checkLine: 8 },
  balanced:     { ...DEFAULT_SUSPICION_CONFIG },
  sensitive:    { cap: 20, moveBase: 1.2, moveWindow: 6, matchBase: 0.5, upsetBase: 1.6, upsetPerGap: 0.35, checkLine: 5 },
};

// 누적 증분 쿼리 (0~CAP clamp). execBatch/exec 양쪽에서 사용.
function suspicionBumpQuery(novelId, delta) {
  return { sql: "UPDATE novels SET suspicion_score = MIN(?, MAX(0, COALESCE(suspicion_score,0) + ?)) WHERE id=?", params: [globalSuspicionConfig.cap, delta, novelId] };
}
// a가 b보다 상위(더 좋은 자리)인가 — 티어 우선, 같은 티어면 manual_order 작은 쪽
function isRankedAbove(a, b, cfg) {
  const ta = tierRank(a?.manual_tier, cfg), tb = tierRank(b?.manual_tier, cfg);
  if (ta !== tb) return ta < tb;
  return (Number(a?.manual_order) || 0) < (Number(b?.manual_order) || 0);
}
// 두 작품 순위차(랭크 상당) — 업셋 가중용. 티어차는 크게(1티어≈3랭크), 같은 티어는 order/100.
function suspicionRankGap(a, b, cfg) {
  const ta = tierRank(a?.manual_tier, cfg), tb = tierRank(b?.manual_tier, cfg);
  if (ta !== tb) return Math.abs(ta - tb) * 3;
  return Math.min(8, Math.abs((Number(a?.manual_order) || 0) - (Number(b?.manual_order) || 0)) / 100);
}
// 증거 ①: 순위/티어 변동 후 같은 티어 인접권(±window) 작품 의심도 상승(가까울수록 큼). 변동 주체 제외.
async function propagateRankSuspicion(centerNovelId) {
  try {
    const row = await first("SELECT manual_tier, manual_order FROM novels WHERE id=?", [centerNovelId]);
    if (!row || !row.manual_tier) return;
    const center = Number(row.manual_order) || 0;
    const sibs = await all(
      "SELECT id, manual_order FROM novels WHERE manual_tier=? AND id!=? AND manual_tier IS NOT NULL AND (match_ban IS NULL OR match_ban=0)",
      [row.manual_tier, centerNovelId]
    );
    const batch = [];
    for (const s of (sibs || [])) {
      const dist = Math.abs((Number(s.manual_order) || 0) - center) / 100; // order 100단위 → 랭크 거리
      if (dist > globalSuspicionConfig.moveWindow) continue;
      const delta = globalSuspicionConfig.moveBase * (1 - dist / (globalSuspicionConfig.moveWindow + 1)); // 가까울수록 큼
      if (delta > 0.02) batch.push(suspicionBumpQuery(s.id, Math.round(delta * 100) / 100));
    }
    if (batch.length) await execBatch(batch);
  } catch (e) { console.warn("[v7.17.0] propagateRankSuspicion 오류:", e?.message); }
}

// 🆕 v7.13.8→v7.17.0: 배정탭 표시용 의심도 — 관계형 누적 점수(suspicion_score) 기반.
//   user_flagged_suspect(명시 지정)는 분리 반환. score는 0~CAP.
function computeSuspicionLevel(novel) {
  const flagged = Number(novel?.user_flagged_suspect) === 1;
  const score = Number(novel?.suspicion_score) || 0;
  return { flagged, score };
}

// 🆕 v7.4.11: 순위탭 카드 height 추정 (export 위험 예측용 pure helper).
// rank tab 카드 구조:
//  - 외곽: padding 14×2 + border 2×2 + marginBottom 10 = 42dp
//  - 내부 row: cover 77dp(=55*1.4) vs 4줄 텍스트 ~88dp 중 max = 88dp
//  - awards row: parseAwards 결과 있을 때만 +24dp
function estimateCardHeight(item, awardSystemSettings) {
  const FRAME_DP = 42;
  const BASE_INNER_DP = 88;
  let extra = 0;
  if (item?.awards) {
    try {
      if (parseAwards(item.awards, awardSystemSettings).length > 0) extra += 24;
    } catch { /* parseAwards 예외 시 awards 무가산 */ }
  }
  return FRAME_DP + BASE_INNER_DP + extra; // 130dp 기본 / 154dp awards 포함
}

// 🆕 v7.4.11: N별 export 실패 사전 예측. Android bitmap 한계(8192px) 대비 청크 최대 height 시뮬레이션.
// 리턴: { maxChunkHeightPx, failCount, totalChunks }
function predictExportRisk(list, n, awardSystemSettings) {
  if (!list || list.length === 0 || n <= 0) {
    return { maxChunkHeightPx: 0, failCount: 0, totalChunks: 0 };
  }
  const pr = PixelRatio.get();
  const SECTION_PADDING_DP = 32;   // Section 외곽 padding 16×2
  const SAFE_LIMIT_PX = 7800;      // 8192 한계의 ~95% (안전 마진)
  const heights = list.map(item => estimateCardHeight(item, awardSystemSettings));
  let maxChunkHeightPx = 0;
  let failCount = 0;
  const totalChunks = Math.ceil(list.length / n);
  for (let i = 0; i < list.length; i += n) {
    const sumDp = heights.slice(i, i + n).reduce((a, b) => a + b, 0) + SECTION_PADDING_DP;
    const sumPx = sumDp * pr;
    if (sumPx > SAFE_LIMIT_PX) failCount++;
    if (sumPx > maxChunkHeightPx) maxChunkHeightPx = sumPx;
  }
  return {
    maxChunkHeightPx: Math.round(maxChunkHeightPx),
    failCount,
    totalChunks,
  };
}

// 🆕 v7.0.1 (C1 fix): tier 그룹 manual_order 재정렬 — gap=100 invariant 복원
// 시퀀스 finalize 후 호출하여 충돌/gap 압축 누적을 차단.
async function rebalanceTierOrder(tier) {
  if (!tier) return;
  try {
    const rows = await all(
      `SELECT id FROM novels WHERE manual_tier = ? ORDER BY manual_order ASC, created_at ASC`,
      [tier]
    );
    if (!rows || rows.length === 0) return;
    const queries = [];
    for (let i = 0; i < rows.length; i++) {
      queries.push({
        sql: `UPDATE novels SET manual_order = ? WHERE id = ?`,
        params: [(i + 1) * 100, rows[i].id],
      });
    }
    if (queries.length > 0) await execBatch(queries);
  } catch (e) {
    console.warn("[v7.0] rebalanceTierOrder 오류:", e?.message);
  }
}

// 🆕 v7.0.6 (M5): manual_tier + manual_order 동시 갱신 헬퍼.
// SQLite single statement 내 sub-select와 UPDATE가 atomic이므로 동시 saveEdit 시 동일 MAX 산출 race를 회피.
// 이전: saveEdit/batchSetTier/inline chip이 manual_tier만 UPDATE하여 새 tier에서 manual_order=0 충돌 또는 잔여 order 잔류.
async function setNovelTierAtomic(novelId, newTier) {
  if (!novelId) return;
  if (!newTier) {
    // tier 클리어 — manual_order도 0으로
    await exec(
      "UPDATE novels SET manual_tier=NULL, manual_order=0 WHERE id=?",
      [novelId]
    );
    return;
  }
  // 🛠️ v7.0.10: 같은 tier 재할당은 no-op으로 단축. 이전: sub-select가 자기 자신을 포함하여
  // MAX(self+others)+100을 산출 → novel이 이미 그 tier에 있으면 manual_order가 매번 늘어남
  // (batchSetTier가 이미 그 tier에 속한 작품에 적용되면 의도치 않게 bottom으로 밀림).
  // saveEdit/inline chip은 caller에서 tier diff를 가드하지만 batchSetTier는 그렇지 않음.
  const cur = await first("SELECT manual_tier FROM novels WHERE id=?", [novelId]);
  if (cur && cur.manual_tier === newTier) return;
  // sub-select는 UPDATE 시점 *이전*의 데이터를 참조 (SQLite 기본 동작)
  await exec(
    `UPDATE novels SET manual_tier=?,
      manual_order=(SELECT COALESCE(MAX(manual_order), 0) + 100 FROM novels WHERE manual_tier=?)
     WHERE id=?`,
    [newTier, newTier, novelId]
  );
}

// 🆕 v7.0: 수문장 식별 — 최근 N개 세션의 blocker_id 누적 통계
// 5개 누적 시 수문장 후보로 제안
async function getGatekeeperCandidates(threshold = 5) {
  try {
    const rows = await all(
      // 🔧 v7.10.0: result_action='moved' 한정 제거 — 즉시 막아 이동을 무산시킨(no_change) 세션도
      //   수문장 누적에 포함(블록할수록 카운트되도록). 막은 횟수가 많을수록 빠지던 역전 수정.
      `SELECT blocker_id, COUNT(*) as block_count
       FROM tier_repositioning_session
       WHERE state='completed' AND blocker_id IS NOT NULL
       GROUP BY blocker_id
       HAVING block_count >= ?
       ORDER BY block_count DESC
       LIMIT 20`,
      [threshold]
    );
    if (!rows || rows.length === 0) return [];

    // 작품 정보 join
    const ids = rows.map(r => r.blocker_id);
    const placeholders = ids.map(() => "?").join(",");
    const novels = await all(
      `SELECT id, title, manual_tier, manual_order, rating FROM novels WHERE id IN (${placeholders})`,
      ids
    );
    const byId = new Map(novels.map(n => [n.id, n]));
    return rows
      .map(r => ({ ...byId.get(r.blocker_id), block_count: r.block_count }))
      .filter(r => r.id);
  } catch (e) {
    console.warn("[v7.0] getGatekeeperCandidates 오류:", e?.message);
    return [];
  }
}

// 🆕 v6.0: 모드별 표시 티어 계산
function getDisplayTier(novel, config) {
  const cfg = config || globalTierConfig;
  // 🔧 v6.0.1: 커스텀 프리셋에서 "C" 키가 없을 수 있으므로 defaultTier 사용
  if (!cfg || !cfg.tiers) return DEFAULT_TIER_SYSTEM_CONFIG.defaultTier;

  const mode = cfg.mode || "match";
  const tierOrder = getActiveTierOrder(cfg);

  // manual 모드
  if (mode === "manual") {
    const mt = novel.manual_tier;
    if (mt && tierOrder.includes(mt)) return mt;
    return cfg.defaultTier || tierOrder[tierOrder.length - 1];
  }

  // hybrid 모드
  if (mode === "hybrid") {
    const mt = novel.manual_tier;
    if (mt && tierOrder.includes(mt)) return mt;
    return tierFromRating(novel.rating || (cfg.defaultRating || 1500), cfg);
  }

  // 🔧 v7.6.0 (포트 v3.10.0): ratio 모드 — globalRatioTierMap 사용 (loadList에서 사전 계산)
  if (mode === "ratio") {
    if (novel.manual_tier && tierOrder.includes(novel.manual_tier)) return novel.manual_tier;
    const ratioTier = globalRatioTierMap && globalRatioTierMap.get(novel.id);
    if (ratioTier && tierOrder.includes(ratioTier)) return ratioTier;
    // 폴백: 매핑 미완료 시 레이팅 기반
    return tierFromRating(novel.rating || (cfg.defaultRating || 1500), cfg);
  }

  // match 모드
  const recommended = tierFromRating(novel.rating || (cfg.defaultRating || 1500), cfg);

  if (novel.manual_tier && tierOrder.includes(novel.manual_tier)) {
    return novel.manual_tier;
  }

  if (isGatedTier(recommended, cfg)) {
    return getHighestNonGatedTier(cfg);
  }

  return recommended;
}

// 🆕 v6.0: 모드별 검토 상태 (match 모드에서만)
function getReviewStatus(novel, config) {
  const cfg = config || globalTierConfig;
  if (!cfg || !cfg.tiers) return null;
  if (cfg.mode !== "match") return null;

  const recommended = tierFromRating(novel.rating || (cfg.defaultRating || 1500), cfg);
  const actual = getDisplayTier(novel, cfg);

  if (isGatedTier(actual, cfg) && tierRank(recommended, cfg) > tierRank(actual, cfg)) {
    return { type: 'demote', from: actual, to: recommended };
  }

  if (isGatedTier(recommended, cfg) && tierRank(actual, cfg) > tierRank(recommended, cfg)) {
    return { type: 'promote', from: actual, to: recommended };
  }

  return null;
}

// 🆕 v6.0: config 기반 색상 조회
function getTierColor(tier, config) {
  const cfg = config || globalTierConfig;
  if (cfg && cfg.tiers) {
    // 🔧 v6.0.1: 전달된 config가 globalTierConfig와 같을 때만 룩업 테이블 사용
    if (!config || config === globalTierConfig) {
      const found = globalTierLookup.get(tier);
      if (found) return found.color;
    }
    // 배열 검색 (다른 config 전달 시 또는 룩업 미스 시)
    const t = cfg.tiers.find(t => t.key === tier);
    if (t) return t.color;
  }
  const legacyColors = { S: "#8b5cf6", A: "#3b82f6", "B+": "#22c55e", B: "#a3e635", "B-": "#f59e0b", C: "#ef4444" };
  return legacyColors[tier] || "#6b7280";
}

// 🆕 v6.0: config 기반 라벨 조회
function getTierLabel(tier, config) {
  const cfg = config || globalTierConfig;
  if (cfg && cfg.tiers) {
    // 🔧 v6.0.1: 전달된 config가 globalTierConfig와 같을 때만 룩업 테이블 사용
    if (!config || config === globalTierConfig) {
      const found = globalTierLookup.get(tier);
      if (found) return found.label;
    }
    const t = cfg.tiers.find(t => t.key === tier);
    if (t) return t.label;
  }
  return tier || "?";
}

function deriveMajorGenre(tagsStr) {
  const tags = (tagsStr || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (tags.length === 0) return "";
  const MAP = [
    ["무협", ["무협", "무림", "신무협", "패왕", "검술", "강호", "혈맹", "표국"]],
    ["선협", ["선협", "선계", "수련", "비급", "도법", "장생"]],
    ["현판", ["현판", "현대판타지", "헌터", "게이트", "던전", "각성", "레이드"]],
    ["현대", ["현대", "일상", "학원", "회사", "재벌", "범죄", "스포츠", "연예계"]],
    ["로판", ["로판", "로맨스판타지", "공작", "후작", "황자", "귀족", "궁정"]],
    ["로맨스", ["로맨스", "현로", "연애", "캠퍼스", "BL", "GL"]],
    ["판타지", ["판타지", "하이판타지", "마법", "용", "정령", "왕국", "모험"]],
    ["SF", ["SF", "사이버펑크", "우주", "로봇", "AI", "타임루프", "디스토피아"]],
  ];
  const tset = tags.map((t) => t.toLowerCase());
  for (const [label, keys] of MAP) {
    const hit = tset.some((t) =>
      keys.some((k) => t.includes(String(k).toLowerCase()))
    );
    if (hit) return label;
  }
  return "";
}

/** 📊 신뢰도 계산
 *  (읽은 회차수 / 전체 회차수) * (진행된 매칭수 / 해당 작품의 전체 가능 매칭수) * 100
 *  - 전체 가능 매칭수 = (전체 작품 수 - 1)
 */
function computeReliability(novel, totalNovelCount) {
  const totalEpisodes = Number(novel.total_episodes) || 0;
  const readCount = Number(novel.read_count) || 0;
  const matchCount = Number(novel.match_count) || 0;
  const maxMatchForNovel = Math.max(0, totalNovelCount - 1);

  if (totalEpisodes <= 0 || maxMatchForNovel <= 0) return 0;

  const readRatio = Math.min(1, readCount / totalEpisodes);
  const matchRatio = Math.min(1, matchCount / maxMatchForNovel);

  return readRatio * matchRatio * 100;
}

/* =========================================================
   🎯 취향 분석 시스템
   ========================================================= */

// 작품별 신뢰도 점수 계산 (분석용 확장 버전)
function calcNovelReliabilityScore(novel, totalCount) {
  let score = 0;
  const totalEp = Number(novel.total_episodes) || 0;
  const readCnt = Number(novel.read_count) || 0;
  const matchCnt = Number(novel.match_count) || 0;
  const rereadCnt = Number(novel.reread_count) || 1;
  const daysSinceCreated = (Date.now() - (novel.created_at || Date.now())) / (1000 * 60 * 60 * 24);
  
  // 1. 읽은 비율/양 (0-30점) - 연재작도 공정하게 평가
  if (totalEp > 0) {
    const readRatio = readCnt / totalEp;
    score += Math.min(30, readRatio * 30);
  } else {
    // 전체 회차 모를 때: 절대 읽은 회차로 평가 (연재작 불리 해소)
    if (readCnt >= 300) score += 30;
    else if (readCnt >= 200) score += 27;
    else if (readCnt >= 100) score += 24;
    else if (readCnt >= 50) score += 20;
    else if (readCnt >= 20) score += 15;
    else if (readCnt >= 10) score += 10;
    else if (readCnt >= 1) score += 5;
  }
  
  // 2. 매칭 참여도 (0-30점)
  const maxMatch = Math.max(1, totalCount - 1);
  const matchRatio = matchCnt / maxMatch;
  score += Math.min(30, matchRatio * 40);
  
  // 3. 등록 성숙도 (0-15점) - 약간 축소
  if (daysSinceCreated >= 30) score += 15;
  else if (daysSinceCreated >= 7) score += 12;
  else if (daysSinceCreated >= 1) score += 5;
  
  // 4. 상태 기반 (0-15점) - 약간 축소
  if (novel.status === "completed") score += 15;
  else if (novel.status === "reading") score += 12;
  else if (novel.status === "paused") score += 8;
  else if (novel.status === "dropped") score += 5;
  
  // 5. 다회독 보너스 (0-10점) - 신규 추가
  if (rereadCnt >= 5) score += 10;
  else if (rereadCnt >= 3) score += 7;
  else if (rereadCnt >= 2) score += 4;
  
  return Math.min(100, score);
}

// 헬퍼: 배열 평균
const avg = (arr) => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
// 헬퍼: 배열 중앙값
const median = (arr) => {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};
// 헬퍼: 표준편차
const stdDev = (arr) => {
  if (arr.length < 2) return 0;
  const m = avg(arr);
  return Math.sqrt(arr.reduce((sum, v) => sum + (v - m) ** 2, 0) / arr.length);
};

/* ═══════════════════════════════════════════════════════════════════════
   🆕 v7.1: 모드 인식 취향 분석 헬퍼 (Tier-Aware Taste Analysis)
   ═══════════════════════════════════════════════════════════════════════
   - getPrefScore: match=ELO, hybrid/manual=tier-derived 스코어 (단일 파이프라인)
   - formatPrefScore: 표시용 — match는 점수, hybrid/manual은 티어 라벨 (fraction-based)
   - computeTierStratification: 엔티티×티어 분포 매트릭스 (intensity 가중 + entropy + Wilson CI)
   - calcInversionScore: 다회독↑ + 티어↓ disconnect 감지
   ═══════════════════════════════════════════════════════════════════════ */

/**
 * 🆕 v7.1: 모드 인식 통합 취향 스코어
 * - match 모드: 기존 ELO rating 그대로 (회귀 0)
 * - hybrid/manual: tier_rank 기반 + manual_order 미세 조정
 * - getDisplayTier 사용 → manual_tier 미배정 작품도 ELO fallback으로 인클루시브
 */
function getPrefScore(novel, config) {
  const mode = config?.mode || 'match';
  const rating = Number(novel.rating) || 1500;
  if (mode === 'match') return rating;

  const tierOrder = getActiveTierOrder(config);
  const displayTier = getDisplayTier(novel, config);
  const tierRank = displayTier ? tierOrder.indexOf(displayTier) : -1;

  if (tierRank === -1) {
    // 비활성 tier(프리셋 잔여) 또는 미정: hybrid는 ELO fallback, manual은 중립
    return mode === 'hybrid' ? rating : 1500;
  }

  const tierCount = tierOrder.length;
  // S=2000, bottom=1000 (linear). 5-tier: [2000, 1750, 1500, 1250, 1000]
  const tierBase = 2000 - (tierRank / Math.max(1, tierCount - 1)) * 1000;
  // manual_order 미세 조정 (cap 80 — 티어 경계 침범 방지)
  const orderAdj = -Math.min(80, Math.max(0, Number(novel.manual_order) || 0) / 100 * 10);
  return Math.round(tierBase + orderAdj);
}

/**
 * 🆕 v7.1: 표시용 변환 — fraction-based 안정 라벨링 (round 진동 회피)
 */
function formatPrefScore(score, config) {
  const mode = config?.mode || 'match';
  if (mode === 'match') return `${Math.round(score)}점`;

  const tierOrder = getActiveTierOrder(config);
  const tierCount = tierOrder.length;
  if (tierCount === 0) return `${Math.round(score)}`;

  const exact = Math.max(0, Math.min(tierCount - 1, (2000 - score) / 1000 * (tierCount - 1)));
  const lower = Math.max(0, Math.min(tierCount - 1, Math.floor(exact)));
  const upper = Math.max(0, Math.min(tierCount - 1, Math.ceil(exact)));

  if (lower === upper) return `평균 ${getTierLabel(tierOrder[lower], config)}`;
  const fraction = exact - lower;
  if (fraction < 0.25) return `평균 ${getTierLabel(tierOrder[lower], config)}`;
  if (fraction > 0.75) return `평균 ${getTierLabel(tierOrder[upper], config)}`;
  return `평균 ${getTierLabel(tierOrder[lower], config)}~${getTierLabel(tierOrder[upper], config)}`;
}

// 🆕 v7.20.6: 취향분석 인라인 표시용 — match는 "{n}점"(withUnit) 또는 "{n}", tier 모드는
//   prefScore를 티어 라벨("B" / "B~A")로. (hybrid/manual에서 선호도 점수를 ELO 숫자처럼
//   보여주지 않도록 formatPrefScore와 동일 매핑을 간결 라벨로 제공.)
function prefScoreLabel(score, config, withUnit = true) {
  const mode = config?.mode || 'match';
  if (mode === 'match') return withUnit ? `${Math.round(score)}점` : `${Math.round(score)}`;
  return formatPrefScore(score, config).replace(/^평균\s*/, ""); // "B" 또는 "B~A"
}

/**
 * 🆕 v7.1: 엔티티×티어 스트라티피케이션 매트릭스
 * - getEntityKeys: (novel) => ["key1", ...] 또는 [{key, intensity}, ...]
 * - options.useIntensity: tag intensity(1-5) 가중치 적용 (1=0.33, 3=1.0, 5=1.67)
 * - 반환 stat: { totalCount, totalWeight, byTier, byTierWeight, topTierRatio, topTierCI, entropy, entropyNormalized, entropyLabel }
 */
function computeTierStratification(novels, getEntityKeys, config, options = {}) {
  const useIntensity = options.useIntensity || false;
  const tierOrder = getActiveTierOrder(config);
  const result = new Map();
  if (!tierOrder || tierOrder.length === 0) return result;

  for (const n of novels) {
    const tier = getDisplayTier(n, config);
    if (!tier || !tierOrder.includes(tier)) continue;
    const keys = getEntityKeys(n) || [];
    for (const k of keys) {
      const key = typeof k === 'string' ? k : k?.key;
      if (!key) continue;
      const weight = (typeof k === 'object' && useIntensity)
        ? Math.max(0.33, Math.min(1.67, (Number(k.intensity) || 3) / 3))
        : 1.0;
      if (!result.has(key)) {
        result.set(key, {
          key,
          totalCount: 0,
          totalWeight: 0,
          byTier: Object.fromEntries(tierOrder.map(t => [t, 0])),
          byTierWeight: Object.fromEntries(tierOrder.map(t => [t, 0])),
        });
      }
      const stat = result.get(key);
      stat.totalCount++;
      stat.totalWeight += weight;
      stat.byTier[tier]++;
      stat.byTierWeight[tier] += weight;
    }
  }

  // Post-process: ratios + Wilson CI + entropy + 라벨
  const tierCount = tierOrder.length;
  const topTierKeys = tierOrder.slice(0, Math.max(1, Math.ceil(tierCount / 3)));
  const maxEntropy = Math.log2(Math.max(2, tierCount));

  for (const stat of result.values()) {
    if (stat.totalWeight === 0) continue;
    let topWeight = 0;
    for (const t of topTierKeys) topWeight += stat.byTierWeight[t];
    stat.topTierRatio = topWeight / stat.totalWeight;
    // Wilson CI (재사용: wilsonConfidenceInterval 기존 헬퍼)
    stat.topTierCI = wilsonConfidenceInterval(
      Math.round(topWeight),
      Math.max(1, Math.round(stat.totalWeight))
    );
    let H = 0;
    for (const t of tierOrder) {
      const p = stat.byTierWeight[t] / stat.totalWeight;
      if (p > 0) H -= p * Math.log2(p);
    }
    stat.entropy = H;
    stat.entropyNormalized = maxEntropy > 0 ? H / maxEntropy : 0;
    stat.entropyLabel =
      stat.entropyNormalized < 1 / 3 ? "강한 선호" :
      stat.entropyNormalized > 2 / 3 ? "균등 분산" : "중간";
  }

  return result;
}

/**
 * 🆕 v7.1: 티어 inversion 점수 — 다회독↑ + 티어↓ disconnect 감지
 * 보수적 임계치: reread ≥ 4 OR readRatio ≥ 0.9, 하위 1/2 티어
 * 반환: 0 = no inversion, > 0 = inversion 강도
 */
function calcInversionScore(novel, config) {
  const tierOrder = getActiveTierOrder(config);
  if (!tierOrder || tierOrder.length === 0) return 0;
  const tier = getDisplayTier(novel, config);
  const tierRank = tier ? tierOrder.indexOf(tier) : -1;
  if (tierRank === -1) return 0;

  // 하위 1/2 티어
  if (tierRank < Math.ceil(tierOrder.length / 2)) return 0;

  const reread = Number(novel.reread_count) || 1;
  const readCount = Number(novel.read_count) || 0;
  const total = Number(novel.total_episodes) || 0;
  const readRatio = total > 0 ? readCount / total : 0;

  // 보수적 트리거
  const rereadHit = reread >= 4;
  const readRatioHit = readRatio >= 0.9 && readCount >= 30; // 너무 짧은 작품 제외

  if (!rereadHit && !readRatioHit) return 0;

  // 강도: 하위 티어 깊이 + 다회독/완독률
  const depthFactor = (tierRank - Math.ceil(tierOrder.length / 2) + 1) / Math.max(1, tierOrder.length / 2);
  const signalFactor = Math.min(1, (rereadHit ? reread / 4 : 0) + (readRatioHit ? readRatio : 0));
  return Math.round(depthFactor * signalFactor * 100);
}

// 메인 분석 함수
async function analyzePreferences(novels, matches) {
  try {
    if (!novels || novels.length === 0) {
      return { error: "분석할 작품이 없습니다.", novels: 0 };
    }

    const totalCount = novels.length;
    const now = Date.now();
    
    // 🆕 v3.4: 모든 대장르/부장르 태그 셋 (MAJOR_GENRES, SUB_GENRES 기준)
    const allMajorSet = new Set(MAJOR_GENRES);
    const allSubSet = new Set(SUB_GENRES);
    
    // 1. 신뢰도 계산 및 분류
    const enriched = novels.map(n => {
      // 🏷️ v5.0: tag_data 파싱
      let tagDataMap = {};
      try {
        const td = JSON.parse(n.tag_data || "[]");
        if (Array.isArray(td)) {
          for (const item of td) {
            if (item && item.tag) {
              tagDataMap[item.tag] = item.intensity || 3;
            }
          }
        }
      } catch (e) {}
      
      // 🆕 v3.4: 태그 기반 대장르/부장르 추출
      const tagList = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
      
      // 기존 major_genre, sub_genre 컬럼도 파싱 (하위호환)
      const legacyMajors = parseMajorSub(n.major_genre);
      const legacySubs = parseMajorSub(n.sub_genre);
      
      // 태그에서 대장르/부장르 속성 태그 추출
      const tagBasedMajors = tagList.filter(t => allMajorSet.has(t));
      const tagBasedSubs = tagList.filter(t => allSubSet.has(t));
      
      // 합치기 (중복 제거)
      const majorGenres = [...new Set([...legacyMajors, ...tagBasedMajors])];
      const subGenres = [...new Set([...legacySubs, ...tagBasedSubs])];
      
      return {
        ...n,
        reliability: calcNovelReliabilityScore(n, totalCount),
        readRatio: (Number(n.total_episodes) > 0)
          ? Number(n.read_count) / Number(n.total_episodes)
          : null,
        majorGenres,
        subGenres,
        tagList,
        tagDataMap, // 🏷️ v5.0: 태그별 농도
        platList: (() => { try { return JSON.parse(n.platforms || "[]"); } catch { return []; } })(),
        daysSinceCreated: (now - (n.created_at || now)) / (1000 * 60 * 60 * 24),
        rating: Number(n.rating) || 1500,
        // 🆕 v7.1: 모드 인식 통합 스코어 — match=ELO, hybrid/manual=tier-derived
        // 모든 score-aggregation 분석은 prefScore 사용. n.rating은 match-only 신호용으로 보존.
        prefScore: getPrefScore(n, globalTierConfig),
        rereadCount: Math.max(1, Number(n.reread_count) || 1), // 📚 v3.0.4: 다회독 카운트
        // 📚 v3.4: 다회독 가중치 강화 (1회독=1, 2회독=1.7, 3회독=2.2, 5회독=3)
        rereadWeight: 1 + Math.sqrt(Math.max(1, Number(n.reread_count) || 1) - 1) * 0.7,
      };
    });
    
    const highReliability = enriched.filter(n => n.reliability >= 60);
    const mediumReliability = enriched.filter(n => n.reliability >= 30 && n.reliability < 60);
    const lowReliability = enriched.filter(n => n.reliability < 30);
    
    // 📚 v3.0.4: 다회독 통계
    const rereadNovels = enriched.filter(n => n.rereadCount >= 2);
    const totalRereadCount = enriched.reduce((sum, n) => sum + n.rereadCount, 0);
    
    // 분석 대상 (신뢰도 30% 이상 또는 전체)
    let reliable = enriched.filter(n => n.reliability >= 30);
    if (reliable.length < 5) {
      reliable = enriched; // 신뢰 가능 데이터가 너무 적으면 전체 사용
    }
  
  // 2. 기본 통계
  // 🆕 v7.1: avgRating은 mode-aware prefScore로 교체. match에선 ELO 그대로(identity), hybrid/manual은 tier-derived.
  // UI는 formatPrefScore로 모드별 표시 (match='1720점', hybrid='평균 B+ 티어').
  const basicStats = {
    total: totalCount,
    highReliability: highReliability.length,
    mediumReliability: mediumReliability.length,
    lowReliability: lowReliability.length,
    avgRating: avg(reliable.map(n => n.prefScore)),
    medianRating: median(reliable.map(n => n.prefScore)),
    stdDevRating: stdDev(reliable.map(n => n.prefScore)),
    avgReadCount: avg(reliable.filter(n => n.read_count > 0).map(n => Number(n.read_count))),
    totalReadCount: reliable.reduce((sum, n) => sum + (Number(n.read_count) || 0), 0),
    completedCount: reliable.filter(n => n.status === "completed").length,
    droppedCount: reliable.filter(n => n.status === "dropped").length,
    readingCount: reliable.filter(n => n.status === "reading").length,
    // 📚 v3.0.4: 다회독 통계 추가
    rereadNovelCount: rereadNovels.length,
    totalRereadCount,
    avgRereadCount: totalCount > 0 ? totalRereadCount / totalCount : 1,
  };
  
  // 3. 대장르 분석
  // 🔧 v7.6.0 (포트 v3.12.1): work_status 기반 workDrop(연중) 카운트 + episodes 합계
  const majorGenreStats = {};
  for (const n of reliable) {
    for (const g of n.majorGenres) {
      if (!majorGenreStats[g]) {
        majorGenreStats[g] = { count: 0, weightedCount: 0, ratings: [], readRatios: [], completed: 0, dropped: 0, workDrop: 0, episodes: [], wins: 0, losses: 0, readCounts: [], rereadSum: 0 };
      }
      const stat = majorGenreStats[g];
      // 📚 v3.4: 강화된 다회독 가중치 사용
      const rereadWeight = n.rereadWeight || (1 + Math.sqrt(n.rereadCount - 1) * 0.7);
      stat.count++;
      stat.weightedCount += rereadWeight;
      // 🔧 v7.6.0 (포트 v3.12.1): 연중(dropped/discontinued) 작품 카운트
      if (n.work_status === "dropped" || n.work_status === "discontinued") stat.workDrop++;
      const epCnt = Number(n.total_episodes) || 0;
      if (epCnt > 0) stat.episodes.push(epCnt);
      // 🆕 v7.1: prefScore (mode-aware)
      stat.ratings.push(n.prefScore);
      if (n.readRatio !== null) stat.readRatios.push(n.readRatio);
      stat.readCounts.push(Number(n.read_count) || 0);
      if (n.status === "completed") stat.completed++;
      if (n.status === "dropped") stat.dropped++;
      stat.wins += Number(n.wins) || 0;
      stat.losses += Number(n.losses) || 0;
      stat.rereadSum += n.rereadCount;
    }
  }
  
  const majorGenreAnalysis = Object.entries(majorGenreStats)
    .map(([genre, stat]) => ({
      genre,
      count: stat.count,
      weightedCount: stat.weightedCount,
      avgRating: avg(stat.ratings),
      medianRating: median(stat.ratings),
      avgReadRatio: avg(stat.readRatios),
      completionRate: stat.count > 0 ? stat.completed / stat.count : 0,
      dropRate: stat.count > 0 ? stat.dropped / stat.count : 0,
      // 🔧 v7.6.0 (포트 v3.12.1): 연중률 + 평균 편수 (편수 기입된 작품만)
      workDropRate: stat.count > 0 ? stat.workDrop / stat.count : 0,
      avgEpisodes: stat.episodes.length > 0 ? avg(stat.episodes) : 0,
      winRate: (stat.wins + stat.losses) > 0 ? stat.wins / (stat.wins + stat.losses) : 0,
      totalRead: stat.readCounts.reduce((a, b) => a + b, 0),
      avgReread: stat.count > 0 ? stat.rereadSum / stat.count : 1,
    }))
    .sort((a, b) => b.weightedCount - a.weightedCount || b.avgRating - a.avgRating);

  // 4. 부장르 분석
  const subGenreStats = {};
  for (const n of reliable) {
    for (const g of n.subGenres) {
      if (!subGenreStats[g]) {
        subGenreStats[g] = { count: 0, weightedCount: 0, ratings: [], completed: 0, dropped: 0, rereadSum: 0 };
      }
      const rereadWeight = n.rereadWeight || (1 + Math.sqrt(n.rereadCount - 1) * 0.7);
      subGenreStats[g].count++;
      subGenreStats[g].weightedCount += rereadWeight;
      subGenreStats[g].ratings.push(n.prefScore);
      if (n.status === "completed") subGenreStats[g].completed++;
      if (n.status === "dropped") subGenreStats[g].dropped++;
      subGenreStats[g].rereadSum += n.rereadCount;
    }
  }
  
  const subGenreAnalysis = Object.entries(subGenreStats)
    .map(([genre, stat]) => ({
      genre,
      count: stat.count,
      weightedCount: stat.weightedCount,
      avgRating: avg(stat.ratings),
      dropRate: stat.count > 0 ? stat.dropped / stat.count : 0,
      avgReread: stat.count > 0 ? stat.rereadSum / stat.count : 1,
    }))
    .sort((a, b) => b.weightedCount - a.weightedCount || b.avgRating - a.avgRating);

  // 5. 일반 태그 분석 (🏷️ v5.0: 농도 가중치 적용)
  const tagStats = {};
  for (const n of reliable) {
    for (const tag of n.tagList) {
      if (!tagStats[tag]) {
        tagStats[tag] = { count: 0, weightedCount: 0, ratings: [], dropped: 0, rereadSum: 0, intensitySum: 0 };
      }
      const rereadWeight = n.rereadWeight || (1 + Math.sqrt(n.rereadCount - 1) * 0.7);
      // 🏷️ v5.0: 농도 가중치 (1~5, 기본 3)
      const intensity = n.tagDataMap[tag] || 3;
      const intensityWeight = intensity / 3; // 3이 기준(1.0)
      
      tagStats[tag].count++;
      tagStats[tag].weightedCount += rereadWeight * intensityWeight;
      tagStats[tag].ratings.push(n.prefScore);
      tagStats[tag].intensitySum += intensity;
      if (n.status === "dropped") tagStats[tag].dropped++;
    }
  }
  
  const tagAnalysis = Object.entries(tagStats)
    .filter(([_, stat]) => stat.count >= 2)
    .map(([tag, stat]) => ({
      tag,
      count: stat.count,
      weightedCount: stat.weightedCount,
      avgRating: avg(stat.ratings),
      avgIntensity: stat.count > 0 ? stat.intensitySum / stat.count : 3, // 🏷️ v5.0
      dropRate: stat.count > 0 ? stat.dropped / stat.count : 0,
    }))
    .sort((a, b) => b.weightedCount - a.weightedCount || b.avgRating - a.avgRating);

  // 6. 태그 조합 분석 (2개 조합)
  const combos = {};
  for (const n of reliable) {
    const allTags = [...n.majorGenres, ...n.subGenres];
    for (let i = 0; i < allTags.length; i++) {
      for (let j = i + 1; j < allTags.length; j++) {
        const key = [allTags[i], allTags[j]].sort().join(" + ");
        if (!combos[key]) combos[key] = { count: 0, ratings: [] };
        combos[key].count++;
        combos[key].ratings.push(n.prefScore);
      }
    }
  }
  
  const comboAnalysis = Object.entries(combos)
    .filter(([_, stat]) => stat.count >= 3)
    .map(([combo, stat]) => ({
      combo,
      count: stat.count,
      avgRating: avg(stat.ratings),
    }))
    .sort((a, b) => b.avgRating - a.avgRating)
    .slice(0, 15);

  // 7. 플랫폼 분석
  const platStats = {};
  for (const n of reliable) {
    for (const p of n.platList) {
      if (!platStats[p]) {
        platStats[p] = { count: 0, ratings: [], readRatios: [], completed: 0, dropped: 0 };
      }
      platStats[p].count++;
      platStats[p].ratings.push(n.prefScore);
      if (n.readRatio !== null) platStats[p].readRatios.push(n.readRatio);
      if (n.status === "completed") platStats[p].completed++;
      if (n.status === "dropped") platStats[p].dropped++;
    }
  }
  
  const platformAnalysis = Object.entries(platStats)
    .map(([platform, stat]) => ({
      platform,
      count: stat.count,
      avgRating: avg(stat.ratings),
      avgReadRatio: avg(stat.readRatios),
      completionRate: stat.count > 0 ? stat.completed / stat.count : 0,
      dropRate: stat.count > 0 ? stat.dropped / stat.count : 0,
    }))
    .sort((a, b) => b.count - a.count);

  // 8. 작가 분석 (상세)
  const authorStats = {};
  for (const n of reliable) {
    const author = (n.author || "").trim();
    if (!author) continue;
    if (!authorStats[author]) {
      authorStats[author] = {
        count: 0,
        ratings: [],
        novels: [],
        genres: [],      // 대장르 모음
        subGenres: [],   // 부장르 모음
        tags: [],        // 태그 모음
        completed: 0,    // 완독 수
        dropped: 0,      // 드롭 수
        // 🆕 v7.0.4: 작품 객관 상태(work_status) 기반 연중 카운트 — status(사용자 읽기 상태)와 분리
        discontinuedCount: 0,
        totalRead: 0,    // 총 읽은 회차
        totalEpisodes: 0, // 총 회차
      };
    }
    authorStats[author].count++;
    authorStats[author].ratings.push(n.prefScore);
    // 🆕 v7.1: novels 배열의 rating은 표시용으로 prefScore (mode-aware) 저장
    authorStats[author].novels.push({ title: n.title, rating: n.prefScore });
    authorStats[author].genres.push(...n.majorGenres);
    authorStats[author].subGenres.push(...n.subGenres);
    authorStats[author].tags.push(...n.tagList);
    if (n.status === "completed") authorStats[author].completed++;
    if (n.status === "dropped") authorStats[author].dropped++;
    // 🆕 v7.0.4: 연중/서비스종료 작품 카운트 (work_status 기반)
    if (n.work_status === "dropped" || n.work_status === "discontinued") {
      authorStats[author].discontinuedCount++;
    }
    authorStats[author].totalRead += Number(n.read_count) || 0;
    authorStats[author].totalEpisodes += Number(n.total_episodes) || 0;
  }
  
  // 작가별 특징 분석
  const loyalAuthors = Object.entries(authorStats)
    .filter(([_, stat]) => stat.count >= 2)
    .map(([author, stat]) => {
      // 가장 많이 쓰는 장르
      const genreCount = {};
      for (const g of stat.genres) {
        genreCount[g] = (genreCount[g] || 0) + 1;
      }
      const mainGenres = Object.entries(genreCount)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 2)
        .map(([g]) => g);
      
      // 가장 많이 쓰는 태그
      const tagCount = {};
      for (const t of stat.tags) {
        tagCount[t] = (tagCount[t] || 0) + 1;
      }
      const mainTags = Object.entries(tagCount)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([t]) => t);
      
      // 작가 특징 문자열 생성
      const features = [];
      if (mainGenres.length > 0) features.push(`${mainGenres.join("/")} 장르`);
      if (mainTags.length > 0) features.push(`${mainTags.slice(0, 2).join(", ")} 특징`);
      
      const completionRate = stat.count > 0 ? stat.completed / stat.count : 0;
      if (completionRate >= 0.7) features.push("높은 완독률");
      if (stat.dropped === 0 && stat.count >= 2) features.push("드롭 없음");

      // 🆕 v7.0.4: 작품 객관 상태 기반 연중 비율 (status 기반 dropRate와 분리)
      const discontinuedRate = stat.count > 0 ? stat.discontinuedCount / stat.count : 0;
      const tooManyDiscontinued = stat.count >= 3 && discontinuedRate >= 0.40;
      if (tooManyDiscontinued) features.push(`연중 비율 높음 (${stat.discontinuedCount}/${stat.count})`);

      return {
        author,
        count: stat.count,
        avgRating: avg(stat.ratings),
        novels: stat.novels || [],
        mainGenres,
        mainTags,
        completionRate,
        dropRate: stat.count > 0 ? stat.dropped / stat.count : 0,
        // 🆕 v7.0.4: 객관적 연중률 (작가 평가에서 "너무 많은 연중" 시 작품 저평가 원인으로 surface)
        discontinuedCount: stat.discontinuedCount,
        discontinuedRate,
        tooManyDiscontinued,
        totalRead: stat.totalRead,
        features: features.join(" · ") || "분석 중",
        // 점수 편향 (평균 대비)
        ratingBias: avg(stat.ratings) - basicStats.avgRating,
      };
    })
    .sort((a, b) => b.avgRating - a.avgRating);

  // 9. 읽기 패턴 분석
  const lengthGroups = { short: [], medium: [], long: [] };
  for (const n of reliable) {
    const ep = Number(n.total_episodes) || 0;
    if (ep > 0 && ep < 100) lengthGroups.short.push(n);
    else if (ep >= 100 && ep < 400) lengthGroups.medium.push(n);
    else if (ep >= 400) lengthGroups.long.push(n);
  }
  
  const readingPattern = {
    lengthPreference: {
      short: { count: lengthGroups.short.length, avgRating: avg(lengthGroups.short.map(n => n.prefScore)) },
      medium: { count: lengthGroups.medium.length, avgRating: avg(lengthGroups.medium.map(n => n.prefScore)) },
      long: { count: lengthGroups.long.length, avgRating: avg(lengthGroups.long.map(n => n.prefScore)) },
    },
    preferredLength: (() => {
      const lens = [
        { key: "short", rating: avg(lengthGroups.short.map(n => n.prefScore)) || 0 },
        { key: "medium", rating: avg(lengthGroups.medium.map(n => n.prefScore)) || 0 },
        { key: "long", rating: avg(lengthGroups.long.map(n => n.prefScore)) || 0 },
      ];
      return lens.sort((a, b) => b.rating - a.rating)[0]?.key || "unknown";
    })(),
    completedVsOngoing: {
      completed: reliable.filter(n => n.work_status === "completed"),
      ongoing: reliable.filter(n => n.work_status === "ongoing"),
    },
    // 🆕 v7.0.4: work_status 기반 분류 — 연중(dropped/discontinued) 작품을 별도 그룹으로 분리하여 평가 패턴 분석에 포함
    // 🔧 v7.0.4 polish: hiatus(휴재)도 별도 버킷으로 분리 (이전: 모든 4 버킷에서 누락 → counts 합 ≠ reliable.length)
    byWorkStatus: {
      completed: reliable.filter(n => n.work_status === "completed"),
      ongoing: reliable.filter(n => n.work_status === "ongoing"),
      dropped: reliable.filter(n => n.work_status === "dropped"),
      discontinued: reliable.filter(n => n.work_status === "discontinued"),
      hiatus: reliable.filter(n => n.work_status === "hiatus"),
    },
    droppedNovels: reliable.filter(n => n.status === "dropped").map(n => ({
      title: n.title,
      readCount: n.read_count,
      totalEpisodes: n.total_episodes,
      tags: [...n.majorGenres, ...n.subGenres].join(", "),
    })),
    // 🔧 v7.6.0 (포트 v3.12.1): 완결작 편수별 평가 (단편/중편/장편)
    episodeAnalysis: (() => {
      const eligible = reliable.filter(n => n.work_status === "completed" && (Number(n.total_episodes) || 0) > 0);
      const buckets = {
        short: eligible.filter(n => Number(n.total_episodes) < 100),
        medium: eligible.filter(n => Number(n.total_episodes) >= 100 && Number(n.total_episodes) < 400),
        long: eligible.filter(n => Number(n.total_episodes) >= 400),
      };
      const m = {};
      for (const [k, list] of Object.entries(buckets)) {
        m[k] = { count: list.length, avgRating: avg(list.map(n => n.prefScore)) };
      }
      return m;
    })(),
    // 🔧 v7.6.0 (포트 v3.12.1): 고평가 연중작 — '아깝다' 후보 surface
    // 🔧 v7.13.0: 임계 mode-relative — match는 ELO 1800, tier모드는 평균+1σ(prefScore 양자화로 1800이
    //   S티어 전용 필터로 변질되던 문제 해소).
    highRatingDropped: reliable
      .filter(n => (n.work_status === "dropped" || n.work_status === "discontinued") && n.prefScore >= (globalTierConfig.mode === "match" ? 1800 : basicStats.avgRating + (basicStats.stdDevRating || 0)))
      .sort((a, b) => b.prefScore - a.prefScore)
      .slice(0, 5)
      .map(n => ({ id: n.id, title: n.title, rating: n.prefScore, workStatus: n.work_status })),
  };

  // 🆕 v7.0.4: 연중(dropped/discontinued) 작품의 평가 패턴 — 완결작 평균 대비 격차 산출
  // 작품 단위로 "이 작품은 연중이라서 저평가됐을 수 있다"는 원인 surface의 근거
  // 🔧 v7.0.4 polish: completedRows 비어있으면 delta=null + isSignificant=false (방어). affectedTitles 제거(미사용 dead data)
  const discontinuedRows = [
    ...readingPattern.byWorkStatus.dropped,
    ...readingPattern.byWorkStatus.discontinued,
  ];
  const completedRows = readingPattern.byWorkStatus.completed;
  const completedAvgRating = completedRows.length > 0 ? avg(completedRows.map(n => n.prefScore)) : null;
  const discontinuedAvgRating = discontinuedRows.length > 0 ? avg(discontinuedRows.map(n => n.prefScore)) : null;
  const discontinuedDelta = (completedAvgRating != null && discontinuedAvgRating != null)
    ? completedAvgRating - discontinuedAvgRating
    : null;
  const discontinuedAnalysis = {
    counts: {
      completed: completedRows.length,
      ongoing: readingPattern.byWorkStatus.ongoing.length,
      dropped: readingPattern.byWorkStatus.dropped.length,
      discontinued: readingPattern.byWorkStatus.discontinued.length,
      hiatus: readingPattern.byWorkStatus.hiatus.length,
      total: reliable.length,
    },
    avgRating: {
      completed: completedAvgRating,
      droppedDiscontinued: discontinuedAvgRating,
    },
    delta: discontinuedDelta, // 양수 = 연중 작품 평가가 완결보다 낮음, null = 비교 불가
    isSignificant:
      reliable.length >= 10 &&
      discontinuedRows.length >= 3 &&
      discontinuedDelta != null &&
      discontinuedDelta >= 80,
  };

  // 10. 매칭 분석
  let matchAnalysis = { total: 0, autoCount: 0, manualCount: 0, genreVsGenre: [] };
  if (matches && matches.length > 0) {
    const novelMap = {};
    for (const n of enriched) novelMap[n.id] = n;
    
    let autoCount = 0;
    let manualCount = 0;
    const genreVsGenre = {};
    
    for (const m of matches) {
      if (m.decided_by === "auto") autoCount++;
      else manualCount++;
      
      const a = novelMap[m.a_id];
      const b = novelMap[m.b_id];
      if (!a || !b) continue;
      
      const winnerGenres = m.winner_id === m.a_id ? a.majorGenres : b.majorGenres;
      const loserGenres = m.winner_id === m.a_id ? b.majorGenres : a.majorGenres;
      
      for (const wg of winnerGenres) {
        for (const lg of loserGenres) {
          if (wg === lg) continue;
          const key = `${wg}_vs_${lg}`;
          if (!genreVsGenre[key]) genreVsGenre[key] = { wins: 0, losses: 0 };
          genreVsGenre[key].wins++;
          
          const reverseKey = `${lg}_vs_${wg}`;
          if (!genreVsGenre[reverseKey]) genreVsGenre[reverseKey] = { wins: 0, losses: 0 };
          genreVsGenre[reverseKey].losses++;
        }
      }
    }
    
    matchAnalysis = {
      total: matches.length,
      autoCount,
      manualCount,
      autoRatio: matches.length > 0 ? autoCount / matches.length : 0,
      genreVsGenre: Object.entries(genreVsGenre)
        .filter(([_, v]) => v.wins + v.losses >= 3)
        .map(([key, v]) => ({
          matchup: key.replace("_vs_", " > "),
          wins: v.wins,
          total: v.wins + v.losses,
          winRate: (v.wins + v.losses) > 0 ? v.wins / (v.wins + v.losses) : 0,
        }))
        .sort((a, b) => b.winRate - a.winRate)
        .slice(0, 10),
    };
  }

  // 11. 시간 트렌드 (최근 3개월 vs 이전)
  const threeMonthsAgo = now - (90 * 24 * 60 * 60 * 1000);
  const recent = reliable.filter(n => (n.created_at || 0) >= threeMonthsAgo);
  const older = reliable.filter(n => (n.created_at || 0) < threeMonthsAgo);
  
  const trendAnalysis = {
    recent: {
      count: recent.length,
      avgRating: avg(recent.map(n => n.prefScore)),
      topGenres: (() => {
        const gc = {};
        for (const n of recent) {
          for (const g of n.majorGenres) gc[g] = (gc[g] || 0) + 1;
        }
        return Object.entries(gc).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([g]) => g);
      })(),
    },
    older: {
      count: older.length,
      avgRating: avg(older.map(n => n.prefScore)),
      topGenres: (() => {
        const gc = {};
        for (const n of older) {
          for (const g of n.majorGenres) gc[g] = (gc[g] || 0) + 1;
        }
        return Object.entries(gc).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([g]) => g);
      })(),
    },
  };

  // 12. 이상치 탐지 (v3.4: 기준 완화)
  // 🆕 v7.0.4: 항목마다 causes[] 배열 부착 — 단순 통계가 아닌 "원인" 표시.
  // 연중(work_status ∈ {dropped, discontinued}) 작품은 강제로 "discontinued" 원인 태그
  const buildCauses = (n) => {
    const causes = [];
    if (n.work_status === "dropped" || n.work_status === "discontinued") causes.push("discontinued");
    return causes;
  };
  // 🆕 v7.1: anomaly 임계치 mean ± std 기반 (mode-aware 자동 적응)
  // 기존 절대치 1500/1700/1550/1600은 ELO 가정. hybrid의 prefScore 분포는 다름 → 동적 σ 기반.
  const _prefMean = basicStats.avgRating || 1500;
  const _prefStd = Math.max(50, basicStats.stdDevRating || 100); // 최소 50 (분산 0 회피)
  const HIGH_THRESHOLD = _prefMean + _prefStd;       // ≈ 1σ 위 (예: ELO ~1700)
  const LOW_THRESHOLD = _prefMean - _prefStd;        // ≈ 1σ 아래 (예: ELO ~1300)
  const MID_LOW_THRESHOLD = _prefMean - 0.5 * _prefStd;  // ≈ 0.5σ 아래
  const MID_HIGH_THRESHOLD = _prefMean + 0.5 * _prefStd; // ≈ 0.5σ 위
  const anomalies = {
    // 고평가 but 적게 읽음
    highRatingLowRead: reliable.filter(n =>
      n.prefScore >= HIGH_THRESHOLD && n.readRatio !== null && n.readRatio < 0.3
    ).map(n => ({ title: n.title, rating: n.prefScore, readRatio: n.readRatio, work_status: n.work_status, causes: buildCauses(n) })),
    // 저평가 but 많이 읽음
    lowRatingHighRead: reliable.filter(n =>
      n.prefScore < LOW_THRESHOLD && n.readRatio !== null && n.readRatio > 0.6
    ).map(n => ({ title: n.title, rating: n.prefScore, readRatio: n.readRatio, work_status: n.work_status, causes: buildCauses(n) })),
    // 매칭 부족한 고레이팅 — match 모드에서만 의미 (hybrid는 매치 X로 모든 작품이 해당 → noise)
    noMatchHighRating: (globalTierConfig?.mode === "match") ? enriched.filter(n =>
      (Number(n.match_count) || 0) <= 2 && n.prefScore >= HIGH_THRESHOLD
    ).map(n => ({ title: n.title, rating: n.prefScore, matchCount: n.match_count, work_status: n.work_status, causes: buildCauses(n) })) : [],
    // 🆕 v3.4: 다회독 but 저평가 (숨겨진 명작 후보)
    rereadButLowRating: enriched.filter(n =>
      (Number(n.reread_count) || 1) >= 2 && n.prefScore < MID_LOW_THRESHOLD
    ).map(n => ({ title: n.title, rating: n.prefScore, rereadCount: Number(n.reread_count) || 1, work_status: n.work_status, causes: buildCauses(n) })),
    // 🆕 v3.4: 정보 불완전 (신뢰도 낮음)
    lowInfoQuality: enriched.filter(n =>
      n.reliability < 25 && n.prefScore >= MID_HIGH_THRESHOLD
    ).map(n => ({ title: n.title, rating: n.prefScore, reliability: n.reliability, work_status: n.work_status, causes: buildCauses(n) })),
    // 🆕 v7.0.4: 연중/서비스종료 저평가 작품
    discontinuedLowRating: reliable
      .filter(n =>
        (n.work_status === "dropped" || n.work_status === "discontinued") &&
        (n.prefScore || 0) < (_prefMean - 0.7 * _prefStd)
      )
      .sort((a, b) => (a.prefScore || 0) - (b.prefScore || 0))
      .map(n => ({
        title: n.title,
        rating: n.prefScore,
        work_status: n.work_status,
        gapVsAvg: _prefMean - n.prefScore,
        causes: ["discontinued"],
      })),
  };

  // 13. 🎯 v3.1.2 스펙트럼 분석 (태그 연속 스케일 분석)
  const spectrumAnalysis = {};
  const spectrumIds = Object.keys(TAG_SPECTRUM_GROUPS);
  
  for (const spectrumId of spectrumIds) {
    const spectrum = TAG_SPECTRUM_GROUPS[spectrumId];
    const spectrumLength = spectrum.tags.length;
    
    // 각 작품별 스펙트럼 분석
    const novelAnalyses = [];
    for (const n of reliable) {
      // tag_data 파싱
      let tagData = [];
      try {
        tagData = JSON.parse(n.tag_data || "[]");
        if (!Array.isArray(tagData)) tagData = [];
      } catch { tagData = []; }
      
      // 이 작품이 해당 스펙트럼에 해당하는 태그를 가지고 있는지 확인
      const matches = tagData.filter(t => 
        spectrum.tags.includes(t.tag) || spectrum.tags.includes(normalizeTag(t.tag))
      );
      
      if (matches.length > 0) {
        // 가중 평균 위치 계산
        let sumPos = 0, sumWeight = 0;
        for (const m of matches) {
          const tag = normalizeTag(m.tag);
          const pos = spectrum.tags.indexOf(tag);
          if (pos >= 0) {
            const intensity = m.intensity || 3;
            sumPos += (pos + 1) * intensity;
            sumWeight += intensity;
          }
        }
        
        if (sumWeight > 0) {
          const avgPosition = sumPos / sumWeight;
          const normalizedPosition = spectrumLength > 1 ? (avgPosition - 1) / (spectrumLength - 1) : 0.5; // 0~1 범위 (pos 0→0, 마지막→1)
          novelAnalyses.push({
            id: n.id,
            title: n.title,
            // 🆕 v7.1: prefScore (mode-aware)
            rating: n.prefScore,
            position: avgPosition,
            normalizedPosition,
            tags: matches.map(m => m.tag),
          });
        }
      }
    }
    
    if (novelAnalyses.length >= 2) {
      // 통계 계산
      const positions = novelAnalyses.map(n => n.normalizedPosition);
      const avgPos = positions.reduce((a, b) => a + b, 0) / positions.length;
      
      // 고평점 작품의 평균 위치 — 🆕 v7.1: mean+1σ 기반 (mode-aware)
      const highRated = novelAnalyses.filter(n => n.rating >= HIGH_THRESHOLD);
      const highRatedAvgPos = highRated.length > 0 
        ? highRated.reduce((sum, n) => sum + n.normalizedPosition, 0) / highRated.length 
        : avgPos;
      
      // 위치별 레이팅 분포 (5구간)
      const segments = [
        { range: "1구간", novels: [], avgRating: 0 },
        { range: "2구간", novels: [], avgRating: 0 },
        { range: "3구간", novels: [], avgRating: 0 },
        { range: "4구간", novels: [], avgRating: 0 },
        { range: "5구간", novels: [], avgRating: 0 },
      ];
      
      for (const n of novelAnalyses) {
        const segIdx = Math.min(4, Math.max(0, Math.floor((n.normalizedPosition || 0) * 5)));
        if (segments[segIdx]) {
          segments[segIdx].novels.push(n);
        }
      }
      
      for (const seg of segments) {
        if (seg.novels.length > 0) {
          seg.avgRating = seg.novels.reduce((sum, n) => sum + n.rating, 0) / seg.novels.length;
        }
      }
      
      // 선호 구간 찾기 (평점이 가장 높은 구간)
      const validSegments = segments.filter(s => s.novels.length >= 1);
      const preferredSegment = validSegments.length > 0
        ? validSegments.reduce((best, s) => s.avgRating > best.avgRating ? s : best)
        : null;
      
      spectrumAnalysis[spectrumId] = {
        name: spectrum.name,
        description: spectrum.description,
        tags: spectrum.tags,
        novelCount: novelAnalyses.length,
        avgPosition: avgPos,
        highRatedAvgPosition: highRatedAvgPos,
        segments,
        preferredSegment: preferredSegment?.range || null,
        preferredSegmentAvgRating: preferredSegment?.avgRating || 0,
        // 선호 성향 해석 (0~1 범위를 텍스트로)
        preferenceLabel: avgPos < 0.35 ? spectrum.tags[0] + " 선호" 
                       : avgPos > 0.65 ? spectrum.tags[spectrumLength - 1] + " 선호"
                       : "중간 성향",
      };
    }
  }

  // 14. 종합 인사이트 생성
  // 🆕 v7.0.4: discontinuedAnalysis 전달 — generateInsights가 연중을 원인으로 surface
  // 🔧 v7.0.4 polish: UI에 표시되는 top10과 동일 슬라이스 전달 — avoidFactors의 작가가 화면에 안 보이는 모순 방지
  const loyalAuthorsTop10 = loyalAuthors.slice(0, 10);
  const insights = generateInsights({
    basicStats, majorGenreAnalysis, subGenreAnalysis, tagAnalysis,
    comboAnalysis, platformAnalysis, loyalAuthors: loyalAuthorsTop10, readingPattern,
    matchAnalysis, trendAnalysis, anomalies, reliable,
    discontinuedAnalysis,
  });

  // 15. 🧠 v3.5.4: 매칭 행동 분석 (preference_patterns 연동)
  let matchBehavior = null;
  try {
    const patterns = await all(`SELECT * FROM preference_patterns WHERE sample_size >= 5 ORDER BY significance DESC`);
    
    if (patterns && patterns.length > 0) {
      // 장르 상성 TOP 5
      const genreMatchups = patterns
        .filter(p => p.category === "genre_matchup" && p.sample_size >= 8)
        .sort((a, b) => Math.abs((b.win_rate || 0.5) - 0.5) - Math.abs((a.win_rate || 0.5) - 0.5))
        .slice(0, 5)
        .map(p => ({
          matchup: p.pattern_key,
          winRate: p.win_rate || 0.5,
          sample: p.sample_size,
          significance: p.significance || 0,
        }));

      // 장르 선호도 (동적)
      const genreAffinity = patterns
        .filter(p => p.category === "genre_affinity" && p.sample_size >= 5)
        .sort((a, b) => (b.win_rate || 0) - (a.win_rate || 0))
        .slice(0, 8)
        .map(p => ({
          genre: p.pattern_key.replace("genre:", ""),
          winRate: p.win_rate || 0.5,
          sample: p.sample_size,
        }));

      // 태그 파워 TOP 10
      const tagPower = patterns
        .filter(p => p.category === "tag_power" && p.sample_size >= 8)
        .sort((a, b) => (b.win_rate || 0) - (a.win_rate || 0))
        .slice(0, 10)
        .map(p => ({
          tag: p.pattern_key.replace("tag:", ""),
          winRate: p.win_rate || 0.5,
          sample: p.sample_size,
        }));

      // 작가 충성도 TOP 5
      const authorLoyalty = patterns
        .filter(p => p.category === "author_loyalty" && p.sample_size >= 5)
        .sort((a, b) => (b.win_rate || 0) - (a.win_rate || 0))
        .slice(0, 5)
        .map(p => ({
          author: p.pattern_key.replace("author:", ""),
          winRate: p.win_rate || 0.5,
          sample: p.sample_size,
        }));

      // 예측 정확도
      const predAcc = await calculateBehaviorPredictionAccuracy(30);

      // 🧠 핵심: 정적 vs 동적 불일치 인사이트 생성
      const behaviorInsights = generateBehaviorInsights(
        majorGenreAnalysis, genreAffinity, tagAnalysis, tagPower, loyalAuthors, authorLoyalty, predAcc
      );

      matchBehavior = {
        genreMatchups,
        genreAffinity,
        tagPower,
        authorLoyalty,
        predictionAccuracy: predAcc,
        insights: behaviorInsights,
        totalPatterns: patterns.length,
      };
    }
  } catch (mbErr) {
    console.warn("[analyzePreferences] matchBehavior 분석 오류:", mbErr.message);
  }

  // 🆕 v7.1: 티어 인사이트 (hybrid/manual 모드 강화) — match 모드에선 UI에서 그룹 숨김
  // ─────────────────────────────────────────────────────────────────
  const _isHybridOrManual = (globalTierConfig?.mode === "hybrid" || globalTierConfig?.mode === "manual");

  // 1. 엔티티×티어 스트라티피케이션 (intensity 가중)
  const tierStratification = {
    byMajorGenre: computeTierStratification(
      enriched,
      (n) => n.majorGenres,
      globalTierConfig
    ),
    bySubGenre: computeTierStratification(
      enriched,
      (n) => n.subGenres,
      globalTierConfig
    ),
    byTag: computeTierStratification(
      enriched,
      (n) => {
        const items = [];
        for (const tag of n.tagList) {
          const intensity = (n.tagDataMap && n.tagDataMap[tag]) || 3;
          items.push({ key: tag, intensity });
        }
        return items;
      },
      globalTierConfig,
      { useIntensity: true }
    ),
    byAuthor: computeTierStratification(
      enriched,
      (n) => (n.author && n.author.trim()) ? [n.author.trim()] : [],
      globalTierConfig
    ),
  };

  // 2. 상위 티어 집중도 (sample_size 임계치 적용)
  const _toSortedArray = (map, sampleThreshold) =>
    Array.from(map.values())
      .filter(s => s.totalCount >= sampleThreshold)
      .sort((a, b) => b.topTierRatio - a.topTierRatio);

  const tierConcentration = {
    topGenres: _toSortedArray(tierStratification.byMajorGenre, 2).slice(0, 5),
    topSubGenres: _toSortedArray(tierStratification.bySubGenre, 2).slice(0, 5),
    topTags: _toSortedArray(tierStratification.byTag, 3).slice(0, 10),
    topAuthors: _toSortedArray(tierStratification.byAuthor, 3).slice(0, 5),
  };

  // 3. 티어 분산도 (entropy 기반 — 강한 선호 vs 균등 분산)
  const _allEntities = [
    ...Array.from(tierStratification.byMajorGenre.values()).map(s => ({ ...s, kind: "majorGenre" })),
    ...Array.from(tierStratification.bySubGenre.values()).map(s => ({ ...s, kind: "subGenre" })),
    ...Array.from(tierStratification.byTag.values()).map(s => ({ ...s, kind: "tag" })),
    ...Array.from(tierStratification.byAuthor.values()).map(s => ({ ...s, kind: "author" })),
  ].filter(s => s.totalCount >= 3);
  const tierEntropy = {
    strong: _allEntities
      .filter(s => s.entropyLabel === "강한 선호")
      .sort((a, b) => a.entropyNormalized - b.entropyNormalized)
      .slice(0, 10),
    dispersed: _allEntities
      .filter(s => s.entropyLabel === "균등 분산")
      .sort((a, b) => b.entropyNormalized - a.entropyNormalized)
      .slice(0, 10),
  };

  // 4. 티어 inversion (보수적 임계치 + 부드러운 톤)
  const tierInversion = {
    items: enriched
      .map(n => ({ novel: n, score: calcInversionScore(n, globalTierConfig) }))
      .filter(x => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 5)
      .map(x => ({
        id: x.novel.id,
        title: x.novel.title,
        author: x.novel.author,
        tier: getDisplayTier(x.novel, globalTierConfig),
        rereadCount: Number(x.novel.reread_count) || 1,
        readRatio: x.novel.readRatio,
        score: x.score,
        message: `이 작품을 ${Number(x.novel.reread_count) || 1}회독 했지만 ${getTierLabel(getDisplayTier(x.novel, globalTierConfig), globalTierConfig)} 티어 — 한 번 재고해보세요`,
      })),
  };

  // 5. Award-Tier 상관 (수상 ≥5건 가드)
  const awardTierCorrelation = (() => {
    const allAwardWinners = [];
    for (const n of enriched) {
      if (!n.awards) continue;
      try {
        const awards = JSON.parse(n.awards);
        if (Array.isArray(awards) && awards.length > 0) {
          for (const aw of awards) {
            if (aw && aw.type) allAwardWinners.push({ novel: n, award: aw });
          }
        }
      } catch {}
    }
    if (allAwardWinners.length < 5) return null;

    const tierOrder = getActiveTierOrder(globalTierConfig);
    const byAward = {};
    for (const { novel, award } of allAwardWinners) {
      const key = award.type;
      if (!byAward[key]) {
        byAward[key] = {
          awardId: key,
          count: 0,
          byTier: Object.fromEntries(tierOrder.map(t => [t, 0])),
          prefScores: [],
          tagFreq: {},
        };
      }
      const stat = byAward[key];
      stat.count++;
      const tier = getDisplayTier(novel, globalTierConfig);
      if (tier && tierOrder.includes(tier)) stat.byTier[tier]++;
      if (typeof novel.prefScore === "number") stat.prefScores.push(novel.prefScore);
      for (const tag of (novel.tagList || [])) {
        stat.tagFreq[tag] = (stat.tagFreq[tag] || 0) + 1;
      }
    }
    // post-process
    const result = { byAward: {}, sharedTags: [] };
    for (const [key, stat] of Object.entries(byAward)) {
      const sortedTags = Object.entries(stat.tagFreq)
        .filter(([, c]) => c >= 2)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([t, c]) => ({ tag: t, count: c }));
      result.byAward[key] = {
        awardId: key,
        count: stat.count,
        byTier: stat.byTier,
        avgPrefScore: stat.prefScores.length > 0 ? avg(stat.prefScores) : null,
        topTags: sortedTags,
      };
    }
    // 전체 수상작에서 공통적으로 자주 등장하는 태그
    const allTagFreq = {};
    for (const { novel } of allAwardWinners) {
      for (const tag of (novel.tagList || [])) {
        allTagFreq[tag] = (allTagFreq[tag] || 0) + 1;
      }
    }
    result.sharedTags = Object.entries(allTagFreq)
      .filter(([, c]) => c >= Math.max(2, Math.floor(allAwardWinners.length * 0.3)))
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([t, c]) => ({ tag: t, count: c, ratio: c / allAwardWinners.length }));
    return result;
  })();

  // 6. 전체 티어 분포 (UI TierDistribution용)
  const tierDistribution = (() => {
    const tierOrder = getActiveTierOrder(globalTierConfig);
    const counts = Object.fromEntries(tierOrder.map(t => [t, 0]));
    let unrated = 0;
    for (const n of enriched) {
      const tier = getDisplayTier(n, globalTierConfig);
      if (tier && tierOrder.includes(tier)) counts[tier]++;
      else unrated++;
    }
    return { counts, unrated, total: enriched.length };
  })();

  // ─────────────────────────────────────────────────────────────────
  // 🆕 v7.1: preference_patterns + insight_queue 영속화 (사용자 결정대로)
  // hybrid/manual 모드일 때만 저장 (match는 그룹 숨김)
  // ─────────────────────────────────────────────────────────────────
  if (_isHybridOrManual) {
    try {
      // 🆕 v7.1: 신규 분석 기준으로 stale tier_* row 정리 (deleted novel 등)
      // — 기존 tier_concentration/tier_inversion/award_tier 모두 삭제 후 재생성
      // — UPSERT만 하면 사라진 entity의 row가 영구 잔존하기 때문
      try {
        await exec(
          `DELETE FROM preference_patterns WHERE category IN ('tier_concentration','tier_inversion','award_tier')`
        );
        await exec(
          `DELETE FROM insight_queue WHERE source = 'v7.1_tier_analysis' AND status = 'pending'`
        );
      } catch (cleanErr) {
        console.warn("[v7.1] tier_* row 정리 실패 (계속 진행):", cleanErr?.message);
      }

      const upserts = [];
      const queueInserts = [];
      const _now = Date.now();

      // tier_concentration 패턴 (top entity별)
      const _addConcentrationRow = (entityKind, stat, sampleThreshold) => {
        if (stat.totalCount < sampleThreshold) return;
        const isNotable = stat.topTierRatio >= 0.6;
        const _ci = stat.topTierCI; const ciHalf = _ci ? (_ci.upper - _ci.lower) / 2 : 0;
        const detailsObj = {
          byTier: stat.byTier,
          byTierWeight: stat.byTierWeight,
          topTierCI: stat.topTierCI,
          entropyLabel: stat.entropyLabel,
          entropyNormalized: stat.entropyNormalized,
          totalWeight: stat.totalWeight,
        };
        upserts.push({
          category: "tier_concentration",
          pattern_key: `${entityKind}:${stat.key}`,
          sample_size: stat.totalCount,
          static_metric: "topTierRatio",
          static_value: stat.topTierRatio,
          static_deviation: ciHalf,
          details: JSON.stringify(detailsObj),
          is_notable: isNotable ? 1 : 0,
          insight_level: Math.round(stat.topTierRatio * 50),
          insight_title: isNotable ? `${stat.key} 강세 (상위 티어 ${Math.round(stat.topTierRatio * 100)}%)` : null,
          insight_description: isNotable ? `${entityKind === "tag" ? "태그" : entityKind === "author" ? "작가" : "장르"} '${stat.key}' 작품의 ${Math.round(stat.topTierRatio * 100)}%가 상위 티어 — ${stat.entropyLabel} 시그널` : null,
        });
      };
      tierConcentration.topGenres.forEach(s => _addConcentrationRow("majorGenre", s, 2));
      tierConcentration.topSubGenres.forEach(s => _addConcentrationRow("subGenre", s, 2));
      tierConcentration.topTags.forEach(s => _addConcentrationRow("tag", s, 3));
      tierConcentration.topAuthors.forEach(s => _addConcentrationRow("author", s, 3));

      // tier_inversion 패턴
      for (const item of tierInversion.items) {
        upserts.push({
          category: "tier_inversion",
          pattern_key: `novel:${item.id}`,
          sample_size: 1,
          static_metric: "inversionScore",
          static_value: item.score,
          static_deviation: 0,
          details: JSON.stringify({
            title: item.title,
            tier: item.tier,
            rereadCount: item.rereadCount,
            readRatio: item.readRatio,
          }),
          is_notable: 1,
          insight_level: 50,
          insight_title: `${item.title} — 티어 재고 권유`,
          insight_description: item.message,
        });
      }

      // award_tier 패턴
      if (awardTierCorrelation && awardTierCorrelation.byAward) {
        for (const stat of Object.values(awardTierCorrelation.byAward)) {
          if (stat.count < 5) continue;
          upserts.push({
            category: "award_tier",
            pattern_key: `award:${stat.awardId}`,
            sample_size: stat.count,
            static_metric: "winnersAvgScore",
            static_value: stat.avgPrefScore || 0,
            static_deviation: 0,
            details: JSON.stringify({
              byTier: stat.byTier,
              topTags: stat.topTags,
              sharedTags: awardTierCorrelation.sharedTags,
            }),
            is_notable: 1,
            insight_level: 30,
            insight_title: `${stat.awardId} 수상 패턴`,
            insight_description: `${stat.count}건 수상작 분석 — 공통 태그 ${stat.topTags.slice(0, 3).map(t => t.tag).join(", ")}`,
          });
        }
      }

      // UPSERT into preference_patterns
      for (const row of upserts) {
        try {
          await exec(
            `INSERT INTO preference_patterns
             (id, category, pattern_key, sample_size, win_count, win_rate, confidence_lower, confidence_upper, significance,
              static_metric, static_value, static_deviation, details, is_notable, insight_level, insight_title, insight_description,
              first_seen_at, last_updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(category, pattern_key) DO UPDATE SET
               sample_size=excluded.sample_size,
               static_metric=excluded.static_metric,
               static_value=excluded.static_value,
               static_deviation=excluded.static_deviation,
               details=excluded.details,
               is_notable=excluded.is_notable,
               insight_level=excluded.insight_level,
               insight_title=excluded.insight_title,
               insight_description=excluded.insight_description,
               last_updated_at=excluded.last_updated_at`,
            [
              uuid(),
              row.category, row.pattern_key,
              row.sample_size, 0, null, null, null, null,
              row.static_metric, row.static_value, row.static_deviation, row.details,
              row.is_notable,
              String(row.insight_level || ""),       // schema: TEXT
              row.insight_title, row.insight_description,
              _now, _now,
            ]
          );
          if (row.is_notable) queueInserts.push(row);
        } catch (e) {
          // upsert 실패 시 개별 row만 skip — 전체 분석 차단 X
        }
      }

      // insight_queue에 notable 항목 surface
      for (const row of queueInserts) {
        try {
          await exec(
            `INSERT INTO insight_queue
             (id, source, insight_type, priority, confidence, title, description, content, status, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?)`,
            [
              uuid(),
              "v7.1_tier_analysis",
              row.category,
              Number(row.insight_level) || 30,
              0.7,                       // 보수적 confidence
              row.insight_title || row.category,
              row.insight_description || "",
              JSON.stringify({ pattern_key: row.pattern_key, category: row.category }),
              _now,
            ]
          );
        } catch (e) {}
      }
    } catch (persistErr) {
      console.warn("[v7.1] tier 인사이트 영속화 실패:", persistErr?.message);
    }
  }

  return {
    timestamp: now,
    basicStats,
    majorGenreAnalysis,
    subGenreAnalysis,
    tagAnalysis: tagAnalysis.slice(0, 20),
    comboAnalysis,
    platformAnalysis,
    loyalAuthors: loyalAuthors.slice(0, 10),
    readingPattern,
    matchAnalysis,
    trendAnalysis,
    anomalies,
    spectrumAnalysis, // 🎯 v3.1.2: 스펙트럼 분석
    matchBehavior, // 🧠 v3.5.4: 매칭 행동 분석
    discontinuedAnalysis, // 🆕 v7.0.4: 연중 원인 분석
    insights,
    // 🆕 v7.1: tier-aware 분석 (hybrid/manual에서 주로 의미, match에선 UI 숨김)
    tierStratification: {
      // Map → Array 변환 (직렬화 용이)
      byMajorGenre: Array.from(tierStratification.byMajorGenre.values()),
      bySubGenre: Array.from(tierStratification.bySubGenre.values()),
      byTag: Array.from(tierStratification.byTag.values()),
      byAuthor: Array.from(tierStratification.byAuthor.values()),
    },
    tierConcentration,
    tierEntropy,
    tierInversion,
    awardTierCorrelation,
    tierDistribution,
  };
  } catch (e) {
    console.warn("analyzePreferences error:", e);
    return { error: "분석 처리 중 오류: " + (e.message || e.toString()), novels: novels?.length || 0 };
  }
}

/* ================================================================
   🧠 v3.5.4: 매칭 행동 인사이트 생성 (preference_patterns → 자연어)
   - 정적 분석(보유 작품)과 동적 분석(매칭 선택)의 불일치를 발견
   - 비서 톤으로 자연어 인사이트 카드 생성
   ================================================================ */
async function calculateBehaviorPredictionAccuracy(recentN = 30) {
  try {
    const logs = await all(
      `SELECT predicted_winner_id, winner_id, was_correct FROM choice_logs 
       WHERE predicted_winner_id IS NOT NULL AND was_correct IS NOT NULL 
         AND match_type = 'user'
       ORDER BY created_at DESC LIMIT ?;`, [recentN]
    );
    if (!logs || logs.length < 10) return null;
    const correct = logs.filter(l => l.was_correct === 1).length;
    return { accuracy: correct / logs.length, sample: logs.length };
  } catch { return null; }
}

function generateBehaviorInsights(staticGenres, dynamicGenres, staticTags, dynamicTags, staticAuthors, dynamicAuthors, predAcc) {
  const insights = [];

  // 1) 장르: 정적 TOP3 vs 동적 TOP3 비교
  if (staticGenres.length >= 2 && dynamicGenres.length >= 2) {
    const staticTop = staticGenres[0]?.genre;
    const dynamicTop = dynamicGenres[0]?.genre;
    const dynamicWinRate = dynamicGenres[0]?.winRate;
    
    if (staticTop && dynamicTop && staticTop !== dynamicTop && dynamicWinRate > 0.55) {
      insights.push({
        type: "genre_gap",
        icon: "🔄",
        title: "보유 장르와 선택 장르가 다릅니다",
        body: `보유 작품 수 기준으로는 '${staticTop}'이 가장 많지만, 매칭에서는 '${dynamicTop}'을 ${(dynamicWinRate * 100).toFixed(0)}% 확률로 선택하고 있습니다.`,
        severity: "high",
      });
    }
    
    // 동적에서 높은데 정적에서 낮은 장르 (숨겨진 선호)
    for (const dg of dynamicGenres.slice(0, 5)) {
      if (dg.winRate < 0.58) continue;
      const staticMatch = staticGenres.find(sg => sg.genre === dg.genre);
      const staticRank = staticMatch ? staticGenres.indexOf(staticMatch) : 999;
      if (staticRank > 4 && dg.sample >= 8) {
        insights.push({
          type: "hidden_genre",
          icon: "💎",
          title: `'${dg.genre}' — 숨겨진 선호 장르`,
          body: `보유량은 적지만, 매칭에서 ${(dg.winRate * 100).toFixed(0)}% 승률(${dg.sample}전)로 꾸준히 선택하는 장르입니다.`,
          severity: "medium",
        });
        break; // 1개만
      }
    }
  }

  // 2) 태그 파워: 동적 TOP 태그 인사이트
  if (dynamicTags.length >= 3) {
    const topTag = dynamicTags[0];
    if (topTag.winRate >= 0.65 && topTag.sample >= 10) {
      insights.push({
        type: "power_tag",
        icon: "⚡",
        title: `'${topTag.tag}' 태그가 압도적 선호입니다`,
        body: `이 태그가 있는 작품을 매칭에서 ${(topTag.winRate * 100).toFixed(0)}% 확률로 선택합니다(${topTag.sample}전). 작품 선택의 핵심 요인으로 보입니다.`,
        severity: "high",
      });
    }
    
    // 정적 빈도 높은데 동적 승률 낮은 태그 (과대평가)
    for (const st of staticTags.slice(0, 8)) {
      const dynMatch = dynamicTags.find(dt => dt.tag === (st.tag || st.genre));
      if (dynMatch && dynMatch.winRate < 0.40 && dynMatch.sample >= 8) {
        insights.push({
          type: "overrated_tag",
          icon: "📉",
          title: `'${st.tag || st.genre}' — 생각보다 덜 선호`,
          body: `많은 작품에 달려 있지만, 매칭에서의 선택률은 ${(dynMatch.winRate * 100).toFixed(0)}%에 불과합니다.`,
          severity: "medium",
        });
        break;
      }    }
  }

  // 3) 작가 충성도
  if (dynamicAuthors.length >= 1 && dynamicAuthors[0].winRate >= 0.70 && dynamicAuthors[0].sample >= 5) {
    const topAuthor = dynamicAuthors[0];
    insights.push({
      type: "loyal_author",
      icon: "✍️",
      title: `'${topAuthor.author}' 작가에 대한 충성도가 매우 높습니다`,
      body: `이 작가의 작품이 매칭에 등장하면 ${(topAuthor.winRate * 100).toFixed(0)}% 확률로 선택합니다(${topAuthor.sample}전).`,
      severity: "medium",
    });
  }

  // 4) 예측 정확도
  if (predAcc && predAcc.accuracy > 0) {
    const accPct = (predAcc.accuracy * 100).toFixed(1);
    let accMsg;
    if (predAcc.accuracy >= 0.70) {
      accMsg = `시스템 예측 정확도가 ${accPct}%로 높은 수준입니다. 취향 패턴이 일관적입니다.`;
    } else if (predAcc.accuracy >= 0.55) {
      accMsg = `시스템 예측 정확도가 ${accPct}%입니다. 취향이 다양하거나 상황에 따라 달라지는 경향이 있습니다.`;
    } else {
      accMsg = `시스템 예측 정확도가 ${accPct}%로 낮습니다. 예측하기 어려운 독특한 취향을 가지고 계십니다.`;
    }
    insights.push({
      type: "prediction",
      icon: "🎯",
      title: `예측 정확도: ${accPct}%`,
      body: accMsg + ` (최근 ${predAcc.sample}전 기준)`,
      severity: predAcc.accuracy >= 0.65 ? "low" : "medium",
    });
  }

  // 5) 패턴 부족 시
  if (insights.length === 0) {
    insights.push({
      type: "insufficient",
      icon: "📊",
      title: "아직 충분한 매칭 데이터가 없습니다",
      body: "매칭을 더 진행하면 '보유 작품 취향'과 '실제 선택 취향'의 차이를 분석해드립니다.",
      severity: "low",
    });
  }

  return insights;
}

// 인사이트 생성
function generateInsights(data) {
  const { basicStats, majorGenreAnalysis, subGenreAnalysis, tagAnalysis,
          comboAnalysis, platformAnalysis, loyalAuthors, readingPattern,
          matchAnalysis, trendAnalysis, anomalies, reliable,
          discontinuedAnalysis } = data;
  
  // 핵심 선호 장르
  const topMajorGenres = majorGenreAnalysis.slice(0, 3).map(g => g.genre);
  const topSubGenres = subGenreAnalysis.slice(0, 3).map(g => g.genre);
  const topPlatform = platformAnalysis[0]?.platform || "";
  
  // 선호 길이
  const lengthLabel = {
    short: "단편(100화 미만)",
    medium: "중편(100~400화)",
    long: "장편(400화 이상)",
    unknown: "다양한 길이"
  }[readingPattern.preferredLength];
  
  // 핵심 취향 문장
  const corePreference = `${topMajorGenres[0] || "다양한 장르"} 기반에 ${topSubGenres.slice(0, 2).join(", ") || "다양한 소재"}를 선호하며, ${lengthLabel}의 작품을 즐겨 읽습니다.${topPlatform ? ` ${topPlatform} 플랫폼을 주로 이용합니다.` : ""}`;

  // 숨겨진 패턴
  const hiddenPatterns = [];
  
  // 작가 충성도
  if (loyalAuthors.length > 0) {
    const topAuthor = loyalAuthors[0];
    hiddenPatterns.push(`'${topAuthor.author}' 작가의 작품을 ${topAuthor.count}개 읽으며 평균 ${prefScoreLabel(topAuthor.avgRating, globalTierConfig)}`); // 🔧 v7.20.6
  }
  
  // 태그 시너지
  if (comboAnalysis.length > 0 && comboAnalysis[0].avgRating > basicStats.avgRating + 50) {
    // 🔧 v7.20.6: tier 모드는 점수 델타 대신 질적 표현
    hiddenPatterns.push(globalTierConfig.mode !== "match"
      ? `'${comboAnalysis[0].combo}' 조합에서 평균보다 높은 만족도`
      : `'${comboAnalysis[0].combo}' 조합에서 평균보다 +${(comboAnalysis[0].avgRating - basicStats.avgRating).toFixed(0)}점 높은 만족도`);
  }
  
  // 완결작 vs 연재중 선호
  const completedAvg = avg(readingPattern.completedVsOngoing.completed.map(n => n.prefScore));
  const ongoingAvg = avg(readingPattern.completedVsOngoing.ongoing.map(n => n.prefScore));
  if (Math.abs(completedAvg - ongoingAvg) > 30) {
    if (completedAvg > ongoingAvg) {
      hiddenPatterns.push(`완결작을 연재중 작품보다 평균 +${(completedAvg - ongoingAvg).toFixed(0)}점 높게 평가`);
    } else {
      hiddenPatterns.push(`연재중 작품을 완결작보다 평균 +${(ongoingAvg - completedAvg).toFixed(0)}점 높게 평가`);
    }
  }

  // 🆕 v7.0.4: 연중(dropped/discontinued) 작품 평가 패턴 — 통계가 아닌 "원인"으로 hiddenPatterns에 surface
  if (discontinuedAnalysis && discontinuedAnalysis.isSignificant) {
    const dCount = discontinuedAnalysis.counts.dropped + discontinuedAnalysis.counts.discontinued;
    hiddenPatterns.push(
      `📺 연중/미완 작품 ${dCount}개를 완결작 대비 평균 −${discontinuedAnalysis.delta.toFixed(0)}점 낮게 평가 (저평가 원인으로 추정)`
    );
  }

  // 기피 요소
  const avoidFactors = [];

  // 🆕 v7.0.4: 연중 비율 높은 작가 — 강한 신호 → 최우선 push (이전: 마지막에 push 되어 slice(0,3) 시 항상 잘림)
  const highDiscontinuedAuthors = (loyalAuthors || []).filter(a => a.tooManyDiscontinued).slice(0, 2);
  for (const a of highDiscontinuedAuthors) {
    avoidFactors.push(`${a.author} (연중 ${a.discontinuedCount}/${a.count} · ${(a.discontinuedRate * 100).toFixed(0)}%)`);
  }

  // 드롭률 높은 태그
  const highDropTags = [...subGenreAnalysis, ...tagAnalysis]
    .filter(t => t.dropRate > 0.3 && t.count >= 3)
    .slice(0, 3);
  for (const t of highDropTags) {
    avoidFactors.push(`${t.genre || t.tag} (드롭률 ${(t.dropRate * 100).toFixed(0)}%)`);
  }

  // 저평가 장르
  const lowRatedGenres = majorGenreAnalysis.filter(g => g.avgRating < basicStats.avgRating - 80);
  for (const g of lowRatedGenres.slice(0, 2)) {
    avoidFactors.push(`${g.genre} (평균 대비 -${(basicStats.avgRating - g.avgRating).toFixed(0)}점)`);
  }
  
  // 추천 조건
  const recommendConditions = {
    mustHave: topMajorGenres.slice(0, 2),
    preferred: topSubGenres.slice(0, 3),
    avoid: avoidFactors.slice(0, 3),
  };
  
  // 취향 변화 감지
  let trendNote = "";
  if (trendAnalysis.recent.count >= 5 && trendAnalysis.older.count >= 5) {
    const recentTopGenre = trendAnalysis.recent.topGenres[0];
    const olderTopGenre = trendAnalysis.older.topGenres[0];
    if (recentTopGenre && olderTopGenre && recentTopGenre !== olderTopGenre) {
      trendNote = `최근 취향이 '${olderTopGenre}'에서 '${recentTopGenre}'로 변화하는 추세`;
    }
  }
  
  // 데이터 품질 점수
  const dataQualityScore = Math.round(
    (basicStats.highReliability / basicStats.total) * 100
  );
  
  return {
    corePreference,
    hiddenPatterns,
    avoidFactors,
    recommendConditions,
    trendNote,
    dataQualityScore,
    reliableCount: basicStats.highReliability + basicStats.mediumReliability,
    suspiciousCount: basicStats.lowReliability,
  };
}

