  // 🆕 갤러리에서 이미지 선택
  // 🔧 v3.6.2: autoRegister 옵션 — ON이면 라이브러리에 자동 등록 + file_path 반환
  async function pickImageFromGallery(setter) {
    try {
      const autoRegister = appSettings.coverLibrary?.autoRegister === true;
      const compressionLevel = appSettings.coverLibrary?.compressionLevel || "light";
      const preset = COMPRESSION_PRESETS[compressionLevel] || COMPRESSION_PRESETS.light;

      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ['images'],
        allowsEditing: true,
        aspect: [3, 4],
        quality: autoRegister ? preset.quality : 0.5,
        base64: !autoRegister,
      });
      // 🔧 v3.5.3: 갤러리 복귀 후 DB 연결 강제 재설정
      await resetDbConnection();
      try { await openDb(); } catch (dbErr) {
        console.warn("pickImage DB 재연결 실패:", dbErr.message);
      }

      if (result.canceled || !result.assets?.[0]) return;
      const asset = result.assets[0];

      if (autoRegister) {
        // 🆕 v3.6.2: 파일 저장 + 라이브러리 DB 등록 + file_path 반환
        const { ext } = getImageFormat(asset);
        const saved = await saveCoverToLibrary(asset.uri, compressionLevel, ext);
        if (saved && saved.id && !saved.error) {
          await exec(
            `INSERT INTO cover_library (id, file_path, status, novel_id, original_name, width, height, file_size, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);`,
            [saved.id, saved.file_path, "unused", null, asset.fileName || `cover_${saved.id}.${ext}`, asset.width || 0, asset.height || 0, saved.file_size, Date.now()]
          );
          await loadCoverLibrary();
          setter(saved.file_path);
        } else {
          // 폴백: 라이브러리 등록 실패 시 base64로 전환
          try {
            const b64 = await FileSystem.readAsStringAsync(asset.uri, { encoding: FileSystem.EncodingType.Base64 });
            const { mime } = getImageFormat(asset);
            setter(`data:${mime};base64,` + b64);
          } catch {
            Alert.alert("오류", "이미지 저장에 실패했습니다.");
          }
        }
      } else {
        // 기존 동작: base64 data URI
        if (asset.base64) {
          const { mime } = getImageFormat(asset);
          setter(`data:${mime};base64,` + asset.base64);
        }
      }
    } catch (e) {
      Alert.alert("오류", "이미지 선택 실패: " + e.message);
    }
  }

  /* =========================================================
     🆕 티어표 텍스트 공유 (이미지 캡처 대신)
     ========================================================= */
  async function shareTierText() {
    try {
      const sorted = [...list].sort((a, b) => b.rating - a.rating);
      const lines = ["🏆 내 웹소설 티어표 🏆", ""];
      
      const tierOrder = getActiveTierOrder(globalTierConfig);
      const tiers = Object.fromEntries(tierOrder.map(t => [t, []]));
      for (const n of sorted) {
        const t = getDisplayTier(n, globalTierConfig);
        if (tiers[t]) tiers[t].push(n.title);
      }
      
      for (const [tier, novels] of Object.entries(tiers)) {
        if (novels.length > 0) {
          lines.push(`【${tier}티어】`);
          novels.forEach((title, i) => lines.push(`  ${i + 1}. ${title}`));
          lines.push("");
        }
      }
      
      await Share.share({
        message: lines.join("\n"),
        title: "웹소설 티어표",
      });
    } catch (e) {
      Alert.alert("오류", "공유 실패: " + e.message);
    }
  }

  /* =========================================================
     🆕 v7.4.0 티어표 이미지 내보내기 (블로그 업로드용)
     - 카드 경계 스냅: 폰 화면 높이에 가깝게, 작품 카드 중간 절단 방지
     - 갤러리 저장 (expo-media-library)
     - 내보내기 시 "보이는 것만 / 전체" 선택 모달
     ========================================================= */
  async function waitForAllCardsRendered(expectedIds, timeoutMs = 5000) {
    const start = Date.now();
    while (true) {
      let missing = 0;
      for (const id of expectedIds) {
        if (!cardRefsRef.current.has(id)) missing++;
      }
      if (missing === 0) return;
      if (Date.now() - start > timeoutMs) {
        throw new Error(`카드 렌더 대기 타임아웃: ${missing}/${expectedIds.length}개 누락`);
      }
      await new Promise(r => setTimeout(r, 50));
    }
  }

  // 🆕 v7.4.0 필터 해제 후 rankedEntriesRef 동기 폴링 (timing-only 회피)
  async function waitForRankedEntriesCount(expectedCount, timeoutMs = 2000) {
    const start = Date.now();
    while (rankedEntriesRef.current.length !== expectedCount) {
      if (Date.now() - start > timeoutMs) return; // 폴백: timing 무시하고 진행
      await new Promise(r => setTimeout(r, 30));
    }
  }

  async function measureAllCards(expectedIds) {
    itemLayoutsRef.current.clear();
    const tierNode = tierImageRef.current;
    if (!tierNode) throw new Error("티어 영역 ref가 없습니다");
    const tierHandle = findNodeHandle(tierNode);
    if (!tierHandle) throw new Error("티어 영역 node handle 없음");

    // 측정 도중 카드 unmount race 방지: 시작 시점 ref 스냅샷
    const refsSnapshot = new Map(cardRefsRef.current);

    const promises = [];
    for (const id of expectedIds) {
      const cardNode = refsSnapshot.get(id);
      if (!cardNode) continue;
      promises.push(new Promise((resolve) => {
        try {
          const cardHandle = findNodeHandle(cardNode);
          if (!cardHandle) { resolve(); return; }
          UIManager.measureLayout(
            cardHandle,
            tierHandle,
            () => resolve(), // 실패 콜백
            (x, y, w, h) => {
              itemLayoutsRef.current.set(id, { y, height: h });
              resolve();
            }
          );
        } catch { resolve(); }
      }));
    }
    await Promise.all(promises);
  }

  // 🆕 v7.4.11: appSettings.exportCardsPerImage에서 읽기 (사용자 설정 노출).
  // 1~30 범위로 clamp — UI에서 5/10/15/20/25/30 프리셋, 외부 경로 방어용 가드.
  // N=20: 평균 카드 ~130dp 기준 ~7900px(PR=3), Android bitmap 한계(8192px) 가까움.
  // 한계 초과 시 captureRef catch에서 친화 메시지 + 부분 export 안내.
  const EXPORT_CARDS_PER_IMAGE = Math.max(
    1,
    Math.min(30, Number(appSettings?.exportCardsPerImage) || 20)
  );

  // 🆕 v7.4.10: count-based chunking. 페이지 분할(ImageManipulator.crop) 제거에 따라
  // 1청크=1이미지=1저장. 마지막 청크가 N장 미만이어도 병합 없이 그대로 (사용자 결정).
  function planChunks(entries) {
    if (!entries || entries.length === 0) return [];
    const chunks = [];
    for (let i = 0; i < entries.length; i += EXPORT_CARDS_PER_IMAGE) {
      const slice = entries.slice(i, i + EXPORT_CARDS_PER_IMAGE);
      const ids = slice.map(e => e?.item?.id).filter(Boolean);
      chunks.push({ startIdx: i, endIdx: i + slice.length, ids });
    }
    return chunks;
  }

  // 🆕 v7.4.10: 사전 경고 P장 추정 — 단순 ceil(n/N).
  function estimateExportPageCount(n) {
    if (n <= 0) return 0;
    return Math.ceil(n / EXPORT_CARDS_PER_IMAGE);
  }

  // 🆕 v7.4.3 청크 slice setState + mount 안정화 대기 (line 27594-27596 패턴 미러).
  async function setExportSliceAndWait(slice) {
    setExportSlice(slice);
    await new Promise(r => requestAnimationFrame(() =>
      requestAnimationFrame(() => setTimeout(r, 100))
    ));
  }

  // 🆕 v7.4.0 카드 ref 등록자 — useCallback으로 stable, 매 render 재생성 방지
  const registerCardRef = useCallback((id, node) => {
    if (!id) return;
    if (node) cardRefsRef.current.set(id, node);
    else cardRefsRef.current.delete(id);
  }, []);

  // 🆕 v7.4.0 Image.getSize — Android에서 file:// URI hang 방지 + ImageManipulator fallback
  async function getImageSizeRobust(uri) {
    const primary = new Promise((resolve, reject) => {
      RNImage.getSize(uri, (w, h) => resolve({ width: w, height: h }), reject);
    });
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject(new Error("Image.getSize timeout")), 4000)
    );
    try {
      return await Promise.race([primary, timeout]);
    } catch {
      // Fallback: no-op manipulateAsync는 결과에 width/height 포함
      const r = await ImageManipulator.manipulateAsync(uri, [], {
        compress: 1,
        format: ImageManipulator.SaveFormat.JPEG,
      });
      return { width: r.width, height: r.height };
    }
  }

  function openExportScopeChoice() {
    const visibleN = rankedEntries.length;
    const totalN = (list || []).length;
    Alert.alert(
      "내보낼 범위",
      `현재 보이는 ${visibleN}작 또는 전체 ${totalN}작 중 선택하세요.`,
      [
        { text: "취소", style: "cancel" },
        { text: `보이는 ${visibleN}작`, onPress: () => exportTierImages("visible") },
        { text: `전체 ${totalN}작`, onPress: () => exportTierImages("all") },
      ]
    );
  }

  async function exportTierImages(scope) {
    if (isExportingRef.current) return;
    if (isAutoMatchingRef.current) {
      Alert.alert("진행 불가", "자동 매칭 중에는 사용할 수 없습니다.");
      return;
    }
    if (screen !== "rank") return;

    // 🛡️ 더블탭 차단: 어떤 await 직전에라도 isExportingRef를 즉시 설정
    isExportingRef.current = true;

    Breadcrumbs.add("export", "start", { scope, visible: rankedEntries.length });

    const filterWasActive = !!rankQuery || rankTier !== "ALL";
    const willResetFilter = scope === "all" && filterWasActive;

    try {
      if (willResetFilter) {
        setRankQuery("");
        setRankTier("ALL");
        // rankedEntriesRef가 새 길이로 동기화될 때까지 폴링 (timing 의존 회피)
        const expectedFullCount = (list || []).length;
        await waitForRankedEntriesCount(expectedFullCount);
        // 추가로 한 frame 더 기다려 onLayout/ref 등록 안정화
        await new Promise(r => requestAnimationFrame(() =>
          requestAnimationFrame(() => setTimeout(r, 80))
        ));
      }

      // 🆕 v7.4.3: 메모리 윈도우 가드 — setIsExportRendering(true) 후 첫 setExportSlice 전까지
      // FlatList의 data가 rankedEntries 전체였다면 boost된 windowSize로 모든 카드가 잠깐 mount됨.
      // 빈 배열을 먼저 넣어서 카드 mount 0개 보장. 첫 청크 slice는 loop 안에서 setExportSliceAndWait로 진입.
      setExportSlice([]);
      setExportChunkIdx(0);
      setIsExportRendering(true);

      // FlatList prop 부스트가 반영되어 모든 카드 렌더 시작될 때까지 한 frame
      await new Promise(r => requestAnimationFrame(() =>
        requestAnimationFrame(() => setTimeout(r, 100))
      ));

      const targetEntries = rankedEntriesRef.current;
      const targetCount = targetEntries.length;

      if (targetCount === 0) {
        Alert.alert("알림", "내보낼 작품이 없습니다.");
        return;
      }

      // 🆕 v7.4.3: 임계값 20 사전 경고 → 예상 페이지 수 P 기반 안내로 교체.
      // 청크 캡처가 Bitmap 한계를 우회하므로 실패 공포 문구 X. 갤러리 노이즈만 사전 동의.
      const prGet = PixelRatio.get();
      const pPredict = estimateExportPageCount(targetCount);
      if (pPredict > 5) {
        const ok = await new Promise(res => {
          Alert.alert(
            "이미지 저장 안내",
            `${targetCount}작을 약 ${pPredict}장의 이미지로 저장합니다.\n갤러리에 ${pPredict}개 항목이 추가됩니다. 진행할까요?`,
            [
              { text: "취소", style: "cancel", onPress: () => res(false) },
              { text: "진행", onPress: () => res(true) },
            ]
          );
        });
        if (!ok) return;
      }

      // 권한 — writeOnly 모드: 갤러리 읽기 권한 없이 저장만 가능 (Android 13+ privacy-friendly)
      const perm = await MediaLibrary.requestPermissionsAsync(true);
      if (perm.status !== "granted") {
        Alert.alert("권한 필요", "갤러리 저장 권한이 거부되어 진행할 수 없습니다.");
        return;
      }

      // 🆕 v7.4.10: 1청크 = 1이미지 = 1저장. count-based chunking으로 페이지 분할 사라짐.
      // captureRef 영역은 v7.4.6 구조(<View ref>가 <Section> wrap)로 복귀 — width race 차단.
      // bitmap 한계(8192px) 근접 시 Breadcrumb 경고, 초과 실패 시 친화 메시지.
      const chunks = planChunks(targetEntries);
      let totalSaved = 0;
      const totalPages = chunks.length;

      for (let ci = 0; ci < chunks.length; ci++) {
        if (!isExportingRef.current) break;
        const chunk = chunks[ci];

        setExportChunkIdx(ci);
        setExportProgress({
          current: totalSaved,
          total: totalPages,
          label: `${ci + 1}/${totalPages} · 렌더 중`,
        });
        await setExportSliceAndWait(targetEntries.slice(chunk.startIdx, chunk.endIdx));
        if (!isExportingRef.current) break;

        await waitForAllCardsRendered(chunk.ids);
        if (!isExportingRef.current) break;

        let chunkUri = null;
        try {
          chunkUri = await captureRef(tierImageRef, {
            format: "jpg",
            quality: 0.92,
            result: "tmpfile",
          });
          if (!isExportingRef.current) break;
          Breadcrumbs.add("export", "chunk_done", { ci, ids: chunk.ids.length });

          // bitmap 한계 모니터링 (비차단)
          try {
            const { width: imgWpx, height: imgHpx } = await getImageSizeRobust(chunkUri);
            if (imgHpx > 7800) Breadcrumbs.add("export", "near_bitmap_limit", { ci, w: imgWpx, h: imgHpx });
          } catch { /* 크기 측정 실패해도 저장은 진행 */ }

          setExportProgress({
            current: totalSaved + 1,
            total: totalPages,
            label: `${ci + 1}/${totalPages} · 저장 중`,
          });
          await MediaLibrary.saveToLibraryAsync(chunkUri);
          totalSaved++;
        } catch (e) {
          // 🆕 v7.4.10: captureRef 실패 (대개 bitmap 한계) — 친화 메시지 후 안전 중단
          Breadcrumbs.add("export", "chunk_failed", { ci, msg: (e?.message || "").substring(0, 100) });
          if (!isAutoMatchingRef.current) {
            Alert.alert(
              "이미지 너무 큼",
              `청크 ${ci + 1}/${chunks.length}에서 캡처 실패. 한 이미지당 ${EXPORT_CARDS_PER_IMAGE}장이 이 데이터셋에는 과합니다.\n필터/티어별 부분 export로 다시 시도해주세요.`
            );
          }
          break;
        } finally {
          if (chunkUri) await FileSystem.deleteAsync(chunkUri, { idempotent: true }).catch(() => {});
        }
      }

      Breadcrumbs.add("export", "save_done", { saved: totalSaved, total: totalPages });

      setExportProgress(null);
      if (totalSaved === totalPages && totalPages > 0) {
        const filterMsg = willResetFilter ? "\n(검색/티어 필터가 해제되었습니다.)" : "";
        Alert.alert("완료", `${totalPages}장의 이미지가 갤러리에 저장되었습니다.${filterMsg}`);
      } else if (totalSaved > 0) {
        Alert.alert("취소됨", `${totalSaved}/${totalPages}장이 저장된 후 중단되었습니다.`);
      } else {
        Alert.alert("취소됨", "저장 전 중단되었습니다.");
      }
    } catch (e) {
      Breadcrumbs.add("export", "error", { msg: (e?.message || "").substring(0, 100) });
      setExportProgress(null);
      Alert.alert(
        "오류",
        `이미지 내보내기 실패: ${e?.message || "unknown"}`
      );
    } finally {
      isExportingRef.current = false;
      setIsExportRendering(false);
      setExportSlice(null);
      setExportChunkIdx(0);
    }
  }

  /* =========================================================
     🆕 비교 모드 토글
     ========================================================= */
  const toggleCompare = useCallback((id) => {
    setCompareIds(prev => {
      if (prev.includes(id)) return prev.filter(x => x !== id);
      if (prev.length >= 2) return [prev[1], id];
      return [...prev, id];
    });
  }, []);
  // 🚀 v3.5.4 최적화: id→novel O(1) 조회 맵 (list.find 11곳 → Map.get 교체)
  const listMap = useMemo(() => {
    const map = new Map();
    for (const n of list) map.set(n.id, n);
    return map;
  }, [list]);
  
  const compareNovels = useMemo(() => compareIds.map(id => listMap.get(id)).filter(Boolean), [compareIds, listMap]);
  
  // 💬 v3.5.4: 명언 카드 데이터 (list 변경 시 재계산)
  const quotesCards = useMemo(() => {
    const cards = [];
    // 🆕 v7.12.0: 본작 + 예정작 공통 처리 (예정작 명대사도 쇼츠/상세에 표시 — 이전엔 본작만 순회해
    //   예정 편집기로 공들여 꾸민 명대사가 어디에도 안 보였음). 예정작은 tier "예정"(보라).
    const pushFrom = (n, isPlanned) => {
      const quotes = parseQuotes(n.memorable_quote);
      if (quotes.length === 0) return; // 🚀 빈 명언 작품 스킵
      const t = isPlanned ? "예정" : getDisplayTier(n, globalTierConfig); // 🚀 v3.5.4: 1회 계산 캐시
      const tc = isPlanned ? "#8b5cf6" : getTierColor(t);
      const mg = (() => { try { const mg = JSON.parse(n.major_genre || "[]"); return Array.isArray(mg) ? mg[0] || "" : mg || ""; } catch { return n.major_genre || ""; } })();
      for (let qi = 0; qi < quotes.length; qi++) {
        const q = quotes[qi];
        const img = isImageQuote(q);
        cards.push({
          id: `${isPlanned ? "p-" : ""}${n.id}-q${qi}`,
          novelId: n.id,
          isPlanned: !!isPlanned, // 🆕 v7.12.0: 탭→편집/원격수정 테이블 분기용
          qIndex: qi, // 🆕 v7.9.0: 명언 탭 원격 수정용
          quote: img ? (q.caption || "") : getQuoteText(q),
          quoteStyle: img ? null : getQuoteStyle(q), // 🆕 v7.8.0: 텍스트 서식
          isImage: img,
          imageUri: img ? q.uri : null,
          title: n.title,
          author: n.author || "작가 미상",
          tier: t,
          tierColor: tc,
          rating: Number(n.rating) || 1500,
          coverImage: n.cover_image || null,
          platforms: n.platforms,
          rereadCount: n.reread_count || 1,
          majorGenre: mg,
        });
      }
    };
    for (const n of (list || [])) pushFrom(n, false);
    for (const p of (plannedList || [])) pushFrom(p, true);
    return cards;
  }, [list, plannedList]);

  // 🔧 v3.5.6: editItemRef를 렌더 시점마다 동기화 (기본 동기화)
  // 핵심: 함수형 업데이트 내에서도 ref를 갱신하여 saveEdit이 최신값을 읽도록 함
  editItemRef.current = editItem;

  // 💬 v7.9.2: quotesShuffled 내용 동기화 — 편집/삭제 시 위치·순서 보존 (재셔플/인덱스 리셋 X)
  //   (이전 v3.5.5: quotesCards 변경마다 재셔플 + idx 0 → 명언 탭에서 문장 편집 시 첫 카드로 튕김)
  useEffect(() => {
    if (!quotesShuffled) return; // 원래순서 모드: quotesCards 직접 사용 (항상 최신)
    if (quotesCards.length === 0) { setQuotesShuffled(null); setQuotesIdx(0); return; }
    // 기존 셔플 순서를 유지하면서 카드 내용만 최신으로 교체 (삭제 제거 / 신규 말미 추가)
    const byId = new Map(quotesCards.map(c => [c.id, c]));
    const kept = [];
    const seen = new Set();
    for (const c of quotesShuffled) { const nc = byId.get(c.id); if (nc && !seen.has(c.id)) { kept.push(nc); seen.add(c.id); } }
    for (const c of quotesCards) { if (!seen.has(c.id)) kept.push(c); }
    setQuotesShuffled(kept); // quotesIdx는 렌더 시 safeIdx로 clamp → 보던 위치 유지
  }, [quotesCards]);

  // 🔀 v7.9.2: 명언 탭 "첫 진입" 시에만 자동 셔플 — resetOrder("원래순서")가 즉시 재셔플되던 문제 수정
  useEffect(() => {
    if (screen !== "quotes") { quotesEnteredRef.current = false; return; }
    if (!quotesEnteredRef.current && quotesShuffled === null && quotesCards.length > 0) {
      quotesEnteredRef.current = true;
      const arr = [...quotesCards];
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      setQuotesShuffled(arr);
      setQuotesIdx(0);
    }
  }, [screen, quotesShuffled, quotesCards]);

  // 🎨 v3.8.0: 갤러리 useMemo + useEffect
  const galleryCards = useMemo(() => {
    return (galleryImages || []).map(img => {
      const t = img.tier || tierFromRating(Number(img.rating) || 1500, globalTierConfig);
      const tc = getTierColor(t);
      let mg = "";
      try { const parsed = JSON.parse(img.major_genre || "[]"); mg = Array.isArray(parsed) ? parsed[0] || "" : parsed || ""; } catch { mg = img.major_genre || ""; }
      return { ...img, tier: t, tierColor: tc, majorGenre: mg };
    });
  }, [galleryImages]);

  const galleryGrouped = useMemo(() => {
    const groups = {};
    for (const img of galleryImages) {
      const key = img.novel_id;
      if (!groups[key]) {
        groups[key] = {
          novelId: key,
          title: img.title,
          author: img.author,
          cover_image: img.cover_image,
          platforms: img.platforms,
          images: [],
        };
      }
      groups[key].images.push(img);
    }
    return Object.values(groups);
  }, [galleryImages]);

  // 🎨 작품별 갤러리 이미지 수 캐시 (renderItem 내 O(n) filter 방지)
  const galleryCountByNovel = useMemo(() => {
    const counts = {};
    for (const img of galleryImages) {
      counts[img.novel_id] = (counts[img.novel_id] || 0) + 1;
    }
    return counts;
  }, [galleryImages]);

  const galleryRegFilteredNovels = useMemo(() => {
    if (!galleryRegSearch.trim()) return list;
    const q = galleryRegSearch.toLowerCase();
    return list.filter(n => n.title.toLowerCase().includes(q) || (n.author || "").toLowerCase().includes(q));
  }, [list, galleryRegSearch]);

  // 갤러리 셔플 stale 방지
  useEffect(() => {
    if (galleryShuffled && galleryCards.length > 0) {
      const arr = [...galleryCards];
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      setGalleryShuffled(arr);
      setGalleryIdx(0);
    } else if (galleryShuffled && galleryCards.length === 0) {
      setGalleryShuffled(null);
    }
  }, [galleryCards]);

  // 🔧 v3.6.0: 진단탭 비동기 데이터 로드 (조건부 IIFE 내 hooks 금지 → 최상위 useEffect로 이동)
  // 🛠️ v7.0.10: mounted 가드 추가 — 비동기 쿼리 도중 언마운트/탭전환 시 setState after unmount 방지
  useEffect(() => {
    if (settingsSubTab !== "diag") return;
    let mounted = true;
    (async () => {
      try {
        // DB 테이블 규모
        // 🛠️ v7.0.12: 진단 탭 테이블 카운트에 v7.0 하이브리드 테이블 추가 (이전: 누락되어 orphan 누적이 진단에 안 보임)
        const tables = ["novels", "matches", "choice_logs", "cover_library", "novel_folders", "folders", "gallery_images", "planned_novels", "preference_patterns", "insight_queue", "tier_verification_queue", "tier_validation_log", "tier_repositioning_session", "trigger_fire_log"];
        const counts = {};
        for (const t of tables) {
          try { const r = await first(`SELECT COUNT(*) as cnt FROM ${t}`); counts[t] = r?.cnt ?? "?"; } catch { counts[t] = "N/A"; }
        }
        if (!mounted) return;
        let dbSize = "?";
        try {
          const pc = await first("PRAGMA page_count"); const ps = await first("PRAGMA page_size");
          if (pc && ps) { const bytes = (pc.page_count || pc[0]) * (ps.page_size || ps[0]); dbSize = bytes > 1048576 ? `${(bytes / 1048576).toFixed(1)}MB` : `${(bytes / 1024).toFixed(0)}KB`; }
        } catch {}
        if (!mounted) return;
        setDiagTableStats({ counts, dbSize });
        // 인사이트/패턴 통계
        const cats = await all("SELECT category, COUNT(*) as cnt FROM preference_patterns GROUP BY category");
        const totalPatterns = (cats || []).reduce((s, c) => s + c.cnt, 0);
        const insights = await all("SELECT status, COUNT(*) as cnt FROM insight_queue GROUP BY status");
        const oldestPending = await first("SELECT MIN(created_at) as oldest FROM insight_queue WHERE status='pending'");
        let oldestAge = null;
        if (oldestPending?.oldest) {
          const diff = Date.now() - new Date(oldestPending.oldest).getTime();
          oldestAge = diff > 86400000 ? `${Math.floor(diff / 86400000)}일` : diff > 3600000 ? `${Math.floor(diff / 3600000)}시간` : `${Math.floor(diff / 60000)}분`;
        }
        if (!mounted) return;
        setDiagPatternStats({ categories: cats || [], totalPatterns, insights: insights || [], oldestAge });
      } catch {}
    })();
    return () => { mounted = false; };
  }, [settingsSubTab, refreshKey]);

  // 갤러리 탭 진입 시 자동 셔플 + 데이터 로드
  useEffect(() => {
    if (screen === "gallery") {
      if (galleryImages.length === 0) loadGalleryImages();
      if (!galleryShuffled && galleryCards.length > 0) {
        const arr = [...galleryCards];
        for (let i = arr.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [arr[i], arr[j]] = [arr[j], arr[i]];
        }
        setGalleryShuffled(arr);
        setGalleryIdx(0);
      }
    }
  }, [screen, galleryCards.length]);

  /* =========================================================
     📂 v3.7.0: 폴더 시스템 함수
     ========================================================= */
  async function loadFolders() {
    try {
      const rows = await all("SELECT * FROM folders ORDER BY sort_order ASC, name ASC;");
      setFolders(rows || []);
    } catch (e) { console.warn("loadFolders 실패:", e); setFolders([]); }
  }

  async function loadNovelFolderMap() {
    try {
      const rows = await all("SELECT novel_id, folder_id FROM novel_folders;");
      const map = new Map();
      for (const r of (rows || [])) {
        if (!map.has(r.novel_id)) map.set(r.novel_id, []);
        map.get(r.novel_id).push(r.folder_id);
      }
      setNovelFolderMap(map);
    } catch (e) { console.warn("loadNovelFolderMap 실패:", e); setNovelFolderMap(new Map()); }
  }

  async function createFolder(name, color, icon) {
    const trimmed = (name || "").trim().slice(0, 20);
    if (!trimmed) { Alert.alert("알림", "폴더 이름을 입력해주세요."); return null; }
    try {
      const id = uuid();
      await exec("INSERT INTO folders (id, name, color, icon, sort_order, created_at) VALUES (?,?,?,?,?,?);",
        [id, trimmed, color || '#6366f1', icon || '📂', folders.length, Date.now()]);
      await loadFolders();
      return id;
    } catch (e) {
      if (e.message?.includes("UNIQUE")) {
        Alert.alert("알림", "이미 같은 이름의 폴더가 있습니다.");
      }
      return null;
    }
  }

  async function renameFolder(id, newName) {
    const trimmed = (newName || "").trim().slice(0, 20);
    if (!trimmed) return;
    try {
      await exec("UPDATE folders SET name=? WHERE id=?;", [trimmed, id]);
      await loadFolders();
    } catch (e) {
      if (e.message?.includes("UNIQUE")) {
        Alert.alert("알림", "이미 같은 이름의 폴더가 있습니다.");
      }
    }
  }

  async function deleteFolder(id) {
    try {
      await execBatch([
        { sql: "DELETE FROM novel_folders WHERE folder_id=?;", params: [id] },
        { sql: "DELETE FROM folders WHERE id=?;", params: [id] },
      ]);
      await loadFolders();
      await loadNovelFolderMap();
      if (filterFolder === id) setFilterFolder("ALL");
    } catch (e) { console.warn("deleteFolder 실패:", e); }
  }

  async function updateFolderColor(id, color) {
    try {
      await exec("UPDATE folders SET color=? WHERE id=?;", [color, id]);
      await loadFolders();
    } catch (e) { console.warn("updateFolderColor 실패:", e); }
  }

  async function updateFolderIcon(id, icon) {
    try {
      await exec("UPDATE folders SET icon=? WHERE id=?;", [icon, id]);
      await loadFolders();
    } catch (e) { console.warn("updateFolderIcon 실패:", e); }
  }

  async function reorderFolder(id, direction) {
    const idx = folders.findIndex(f => f.id === id);
    if (idx < 0) return;
    const targetIdx = direction === "up" ? idx - 1 : idx + 1;
    if (targetIdx < 0 || targetIdx >= folders.length) return;
    try {
      const queries = [
        { sql: "UPDATE folders SET sort_order=? WHERE id=?;", params: [targetIdx, folders[idx].id] },
        { sql: "UPDATE folders SET sort_order=? WHERE id=?;", params: [idx, folders[targetIdx].id] },
      ];
      await execBatch(queries);
      await loadFolders();
    } catch (e) { console.warn("reorderFolder 실패:", e); }
  }

  async function toggleNovelFolder(novelId, folderId) {
    const current = novelFolderMap.get(novelId) || [];
    const oldMap = novelFolderMap;
    const newMap = new Map(novelFolderMap);
    if (current.includes(folderId)) {
      newMap.set(novelId, current.filter(f => f !== folderId));
      setNovelFolderMap(newMap);
      try {
        await exec("DELETE FROM novel_folders WHERE folder_id=? AND novel_id=?;", [folderId, novelId]);
      } catch (e) { setNovelFolderMap(oldMap); }
    } else {
      newMap.set(novelId, [...current, folderId]);
      setNovelFolderMap(newMap);
      try {
        await exec("INSERT OR IGNORE INTO novel_folders (folder_id, novel_id, added_at) VALUES (?,?,?);",
          [folderId, novelId, Date.now()]);
      } catch (e) { setNovelFolderMap(oldMap); }
    }
  }

  async function setNovelFolders(novelId, folderIds) {
    const queries = [{ sql: "DELETE FROM novel_folders WHERE novel_id=?;", params: [novelId] }];
    for (const fid of folderIds) {
      queries.push({ sql: "INSERT INTO novel_folders (folder_id, novel_id, added_at) VALUES (?,?,?);", params: [fid, novelId, Date.now()] });
    }
    await execBatch(queries);
    const newMap = new Map(novelFolderMap);
    newMap.set(novelId, [...folderIds]);
    setNovelFolderMap(newMap);
  }

  async function batchSetFolder(folderId, mode) {
    const ids = selectedIdsRef.current;
    if (!ids.length) { Alert.alert("알림", "먼저 작품을 선택해주세요."); return; }
    const folder = folders.find(f => f.id === folderId);
    if (!folder) return;
    if (mode === "add") {
      const queries = ids.map(nid => ({
        sql: "INSERT OR IGNORE INTO novel_folders (folder_id, novel_id, added_at) VALUES (?,?,?);",
        params: [folderId, nid, Date.now()],
      }));
      await execBatch(queries);
      await loadNovelFolderMap();
      Alert.alert("완료", `${ids.length}개 작품을 "${folder.name}" 폴더에 추가했습니다.`);
    } else {
      const queries = ids.map(nid => ({
        sql: "DELETE FROM novel_folders WHERE folder_id=? AND novel_id=?;",
        params: [folderId, nid],
      }));
      await execBatch(queries);
      await loadNovelFolderMap();
      Alert.alert("완료", `${ids.length}개 작품을 "${folder.name}" 폴더에서 제거했습니다.`);
    }
  }

  // 📂 v7.6.0 (포트 v3.9.8): 폴더별 작품 수 O(n) 1회 → 조회 O(1)
  const folderCounts = useMemo(() => {
    const counts = new Map();
    novelFolderMap.forEach((folderIds) => {
      folderIds.forEach((fid) => counts.set(fid, (counts.get(fid) || 0) + 1));
    });
    return counts;
  }, [novelFolderMap]);

  function getFolderNovelCount(folderId) {
    return folderCounts.get(folderId) || 0;
  }

  // 📂 폴더 필터용 파생 상태 (Set.has()로 O(1) 조회)
  const folderFilteredIds = useMemo(() => {
    if (filterFolder === "ALL") return null;
    const ids = new Set();
    novelFolderMap.forEach((folderIds, novelId) => {
      if (folderIds.includes(filterFolder)) ids.add(novelId);
    });
    return ids;
  }, [filterFolder, novelFolderMap]);

  /* =========================================================
     🆕 고급 필터 함수
     ========================================================= */
  function advancedFilter(novels) {
    return novels.filter(n => {
      if (filterTier !== "ALL" && getDisplayTier(n, globalTierConfig) !== filterTier) return false;
      if (filterPlatform !== "ALL" && !parsePlatforms(n.platforms).includes(filterPlatform)) return false;
      if (filterGenre !== "ALL" && (getFirstGenre(n.major_genre) || deriveMajorGenre(n.tags)) !== filterGenre) return false;
      if (filterStatus !== "ALL" && (n.status || "reading") !== filterStatus) return false;
      if (folderFilteredIds !== null && !folderFilteredIds.has(n.id)) return false;
      return true;
    });
  }

  useEffect(() => {
    let mounted = true;
    
    // 🔄 v3.4.6: 매칭 큐 상태 콜백 등록
    setMatchQueueCallback((status) => {
      if (mounted) {
        setMatchQueueStatus(status);
      }
    });
    
    const initialize = async () => {
      setIsLoading(true);

      // 💥 v3.9.0: 이전 크래시 로그 로드
      try {
        const lastCrash = await CrashLog.loadLastCrash();
        if (lastCrash && mounted) setLastCrashLog(lastCrash);
        const history = await CrashLog.loadHistory();
        if (history.length > 0 && mounted) setCrashHistory(history);
      } catch {}

      // 📁 v3.5.15d: 슬롯 메타 먼저 로드 → 활성 슬롯 DB로 연결
      try {
        const meta = await loadSlotMeta();
        activeSlotId = meta.activeSlotId || 0;
        if (mounted) setSlotMeta(meta);
      } catch (e) {
        console.warn("슬롯 메타 로드 실패, 기본 슬롯 사용:", e);
        activeSlotId = 0;
      }
      
      const maxRetries = 3;

      // 🆕 v7.3.0: initDb 진행 상태를 ProgressOverlay에 노출 (대규모 마이그레이션 안내)
      setLoadingProgress({ label: "데이터베이스 초기화 중..." });
      for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
          await initDb((p) => setLoadingProgress(p));

          // 🏷️ v5.0 태그 시스템 마이그레이션
          setLoadingProgress({ label: "태그 시스템 마이그레이션 중..." });
          await migrateTagSystem();

          // 🔧 v3.6.0: Tag Registry 로드 (없으면 FACTORY에서 시드 + 기존 사용자 데이터 병합)
          // 🔧 v3.6.1: registry 반환값 보존 — useEffect 내에서는 React state가 배치 업데이트 전이므로
          //   tagRegistry 클로저가 null. addTagToRegistry 등 registry를 참조하는 함수 사용 불가.
          const loadedRegistry = await loadTagRegistry();
          await loadPlatformRegistry(); // 🆕 플랫폼 레지스트리 로드

          // 🔧 v3.5.15b: 기존 작품 중복 태그 일괄 정리 (1회 자동 실행)
          const dedupDone = await getAppMeta("tag_dedup_v1");
          if (!dedupDone) {
            const dedupResult = await deduplicateExistingNovelTags();
            await setAppMeta("tag_dedup_v1", { done: true, fixed: dedupResult.fixed, total: dedupResult.total, ts: Date.now() });
            if (dedupResult.fixed > 0) {
              console.log(`[tag_dedup_v1] ${dedupResult.total}개 작품 중 ${dedupResult.fixed}개 중복 태그 정리 완료`);
            }
          }
          
          // 🔧 v3.5.8: 데이터 무결성 자동 검증 (앱 시작 시 1회)
          await verifyDataIntegrity({ silent: true });
          
          if (!mounted) return;
          
          // 🚀 v2.8.1: 병렬 로드로 초기화 속도 개선
          // 🔧 v3.4.4: Promise.all 인덱스 매칭 버그 수정
          // ⚠️ 이전에 getAppMeta("tag_sentiments")가 중복 호출되어 인덱스가 밀려
          //    savedRecentChanges에 award_system_settings가 들어가는 버그 발생했음
          // 🔧 v3.6.1: custom_tags, user_major_genres, user_sub_genres 전부 제거 (tagRegistry에서 파생)
          const [
            savedDarkMode,
            savedPlatformCovers,
            savedSettings,
            savedTierHistory,
            savedComboTags,
            savedTagSentiments,
            savedTagAttributes, // 🆕 v3.4: 태그 속성
            savedHiddenTags,
            savedAwardSystemSettings, // 🏆 v2.9
            savedRecentChanges, // 📰 v3.0
            savedMatchInsights, // 🔮 v3.0.3
            savedTagRelations, // 🔗 v3.0.3
            savedUpsetFactors, // 🔮 v3.0.3
            savedAutoMatchSettings, // 🎯 v3.0.4
            savedCustomComboTraits, // 🔗 v3.0.4: 조합 특성
            savedCustomComboTargets, // 🔗 v3.0.4: 조합 대상
            savedCoordinateSystems, // 📐 v3.2.0: 태그 좌표계
            savedCustomTagCategories, // 🆕 v3.5.9: 커스텀 태그 카테고리
            savedMatchFilterSettings, // 🆕 v3.5.11: 매치 필터링 설정
            savedPinnedTags,          // 🔧 19: 별도 useEffect에서 이동 (슬롯 경쟁 조건 방지)
            savedTagSortMode,         // 🔧 20: 동일 이유
            savedTagLastTab,          // 🔧 21: 동일 이유
            savedTagPreviewExpanded,  // 22: 태그 칩 프리뷰 펼침 상태
            savedHomeSortSettings,    // 23: 🔧 v7.6.0 (포트 v3.12.1): 홈 정렬/필터
          ] = await Promise.all([
            getAppMeta("settings_darkMode"),      // 0: savedDarkMode
            getAppMeta("platform_covers"),        // 1: savedPlatformCovers
            getAppMeta("app_settings"),           // 2: savedSettings
            getAppMeta("tier_history"),           // 3: savedTierHistory
            getAppMeta("combo_tags"),             // 4: savedComboTags (마이그레이션용)
            getAppMeta("tag_sentiments"),         // 5: savedTagSentiments
            getAppMeta("tag_attributes"),         // 6: savedTagAttributes
            getAppMeta("hidden_tags"),            // 7: savedHiddenTags
            getAppMeta("award_system_settings"),  // 8: savedAwardSystemSettings
            getAppMeta("recent_changes"),         // 9: savedRecentChanges
            getAppMeta("match_insights"),         // 10: savedMatchInsights
            getAppMeta("tag_relations"),          // 11: savedTagRelations
            getAppMeta("upset_factors"),          // 12: savedUpsetFactors
            getAppMeta("auto_match_settings"),    // 13: savedAutoMatchSettings
            getAppMeta("custom_combo_traits"),    // 14: savedCustomComboTraits
            getAppMeta("custom_combo_targets"),   // 15: savedCustomComboTargets
            getTagCoordinateSystems(),            // 16: savedCoordinateSystems
            getAppMeta("custom_tag_categories"),  // 17: savedCustomTagCategories
            getAppMeta("match_filter_settings"),  // 18: savedMatchFilterSettings
            getAppMeta("pinned_tags"),            // 19: savedPinnedTags (🔧 별도 useEffect에서 이동 — 슬롯 경쟁 조건 방지)
            getAppMeta("tag_sort_mode"),           // 20: savedTagSortMode (🔧 동일 이유)
            getAppMeta("tag_last_tab"),            // 21: savedTagLastTab (🔧 동일 이유)
            getAppMeta("tag_preview_expanded"),    // 22: savedTagPreviewExpanded
            getAppMeta("home_sort_settings"),      // 23: 🔧 v7.6.0 (포트 v3.12.1)
          ]);
          
          if (!mounted) return;
          
          // 다크모드
          if (savedDarkMode !== null && savedDarkMode !== undefined) {
            setDarkModeState(savedDarkMode);
          }
          
          // 플랫폼별 기본 표지
          if (savedPlatformCovers && typeof savedPlatformCovers === "object") {
            setPlatformCovers(savedPlatformCovers);
          }
          
          // ⚙️ 앱 설정 (v2.6)
          if (savedSettings && typeof savedSettings === "object") {
            const merged = { ...DEFAULT_SETTINGS, ...savedSettings };
            // 🆕 v3.4: nested object deep merge
            if (savedSettings.supplement) {
              merged.supplement = { ...DEFAULT_SETTINGS.supplement, ...savedSettings.supplement };
            }
            if (savedSettings.recentChanges) {
              merged.recentChanges = { ...DEFAULT_SETTINGS.recentChanges, ...savedSettings.recentChanges };
            }
            if (savedSettings.plannedFields) {
              merged.plannedFields = { ...DEFAULT_SETTINGS.plannedFields, ...savedSettings.plannedFields };
            }
            if (savedSettings.coverLibrary) {
              merged.coverLibrary = { ...DEFAULT_SETTINGS.coverLibrary, ...savedSettings.coverLibrary };
            }
            // 🆕 v6.0: tierSystemConfig 마이그레이션 (레거시 → 새 구조)
            if (!savedSettings.tierSystemConfig && merged.tierThresholds) {
              // 레거시 tierThresholds에서 tierSystemConfig 자동 생성
              const legacyTh = merged.tierThresholds;
              merged.tierSystemConfig = {
                ...DEFAULT_TIER_SYSTEM_CONFIG,
                tiers: DEFAULT_TIER_SYSTEM_CONFIG.tiers.map(t => ({
                  ...t,
                  threshold: legacyTh[t.key] !== undefined ? legacyTh[t.key] : t.threshold,
                })),
              };
            }
            if (savedSettings.tierSystemConfig) {
              // tiers 배열은 교체 (deep merge에서 배열은 덮어쓰기)
              merged.tierSystemConfig = { ...DEFAULT_TIER_SYSTEM_CONFIG, ...savedSettings.tierSystemConfig };
              if (savedSettings.tierSystemConfig.tiers) {
                merged.tierSystemConfig.tiers = savedSettings.tierSystemConfig.tiers;
              }
            }

            setAppSettings(merged);
            // 🔧 v7.18.0: 의심도 계수 전역 동기화
            globalSuspicionConfig = { ...DEFAULT_SUSPICION_CONFIG, ...(merged.suspicionConfig || {}) };
            if (merged.tierThresholds) {
              globalTierThresholds = { ...DEFAULT_SETTINGS.tierThresholds, ...merged.tierThresholds };
            }
            // 🆕 v6.0: globalTierConfig 초기화
            if (merged.tierSystemConfig) {
              globalTierConfig = { ...merged.tierSystemConfig };
              rebuildTierLookup(globalTierConfig);
            }
            // 🆕 v3.4.4: 전체 화면 모드 적용
            // 🔧 v3.4.6: NavigationBar null 체크 추가
            if (Platform.OS === "android" && NavigationBar && merged.fullscreenMode === true) {
              try {
                await NavigationBar.setVisibilityAsync("hidden");
                await NavigationBar.setBehaviorAsync("overlay-swipe");
              } catch (e) {
                console.warn("NavigationBar init error:", e);
              }
            }
          }
          
          // 🏆 티어 히스토리
          if (Array.isArray(savedTierHistory)) {
            setTierHistory(savedTierHistory.slice(0, 50));
          }
          
          // 🆕 v3.5.9: 커스텀 태그 카테고리
          if (savedCustomTagCategories && typeof savedCustomTagCategories === "object") {
            setCustomTagCategories(savedCustomTagCategories);
          }
          
          // 🆕 v3.5.11: 매치 필터링 설정
          if (savedMatchFilterSettings && typeof savedMatchFilterSettings === "object") {
            if (savedMatchFilterSettings.enabled !== undefined) setMatchFilterEnabled(savedMatchFilterSettings.enabled);
            if (savedMatchFilterSettings.minTags !== undefined) setMatchFilterMinTags(savedMatchFilterSettings.minTags);
          }
          
          // 🔧 v3.5.12: 조합식 태그 → 커스텀 태그로 통합 마이그레이션
          // 🔧 v3.6.1: addTagToRegistry는 tagRegistry 클로저(null)를 참조하므로
          //   loadedRegistry를 직접 수정하여 updateTagRegistry 호출
          if (Array.isArray(savedComboTags) && savedComboTags.length > 0 && loadedRegistry) {
            let migrated = 0;
            const newGeneralTags = { ...(loadedRegistry.generalTags || {}) };
            if (!newGeneralTags["📁 사용자 태그"]) newGeneralTags["📁 사용자 태그"] = [];
            const userTags = [...newGeneralTags["📁 사용자 태그"]];
            for (const ct of savedComboTags) {
              if (!ALL_DEFAULT_TAGS.some(t => isSameTag(t, ct)) && !userTags.some(t => isSameTag(t, ct))) {
                userTags.push(ct);
                migrated++;
              }
            }
            if (migrated > 0) {
              newGeneralTags["📁 사용자 태그"] = userTags;
              updateTagRegistry({ ...loadedRegistry, generalTags: newGeneralTags });
              console.log(`[태그 마이그레이션] 조합식 ${migrated}개 → 커스텀 태그로 통합`);
            }
            setComboTags([]);
            await setAppMeta("combo_tags", []);
          }
          
          // 🎭 v2.8: 사용자 태그 속성
          if (savedTagSentiments && typeof savedTagSentiments === "object") {
            setTagSentiments(savedTagSentiments);
          }
          
          // 🆕 v3.4: 태그 속성 (대장르/부장르 동등화)
          if (savedTagAttributes && typeof savedTagAttributes === "object") {
            setTagAttributes(savedTagAttributes);
          }
          
          // 🏷️ 사용자 대장르/부장르 — useMemo derives from tagRegistry, no setState needed
          
          // 🙈 숨김 태그
          if (Array.isArray(savedHiddenTags)) {
            setHiddenTags(savedHiddenTags);
          }

          // 📌 고정 태그 (🔧 별도 useEffect에서 이동 — 슬롯 경쟁 조건 방지)
          if (Array.isArray(savedPinnedTags)) {
            setPinnedTags(savedPinnedTags);
          }
          // 🔧 태그 정렬 모드 / 마지막 탭 (별도 useEffect에서 이동)
          if (savedTagSortMode && ["usage", "name", "registered"].includes(savedTagSortMode)) {
            setTagSortMode(savedTagSortMode);
          }
          if (savedTagLastTab) {
            const VALID_TAB_KEYS = ["genre", "general", "sentiment", "combo", "intensity"];
            if (VALID_TAB_KEYS.includes(savedTagLastTab)) setTagLastTab(savedTagLastTab);
          }
          if (savedTagPreviewExpanded === true) setTagPreviewExpanded(true);

          // 🔧 v7.6.0 (포트 v3.12.1): 홈 정렬/필터 영속화 복원
          if (savedHomeSortSettings && typeof savedHomeSortSettings === "object") {
            if (savedHomeSortSettings.sortKey) setHomeSortKey(savedHomeSortSettings.sortKey);
            if (savedHomeSortSettings.sortDir) setHomeSortDir(savedHomeSortSettings.sortDir);
            if (savedHomeSortSettings.filterTier) setFilterTier(savedHomeSortSettings.filterTier);
            if (savedHomeSortSettings.filterPlatform) setFilterPlatform(savedHomeSortSettings.filterPlatform);
            if (savedHomeSortSettings.filterGenre) setFilterGenre(savedHomeSortSettings.filterGenre);
            if (savedHomeSortSettings.filterStatus) setFilterStatus(savedHomeSortSettings.filterStatus);
            if (savedHomeSortSettings.filterFolder) setFilterFolder(savedHomeSortSettings.filterFolder);
          }
          homeSortInitRef.current = true; // 초기 복원 완료 → 이후 변경은 deferSetAppMeta로 저장됨

          // 🏆 v2.9: 수상 시스템 설정
          if (savedAwardSystemSettings && typeof savedAwardSystemSettings === "object") {
            // 기존 설정과 병합 (새 연도 자동 추가)
            const merged = { ...DEFAULT_AWARD_SYSTEM_SETTINGS };
            if (savedAwardSystemSettings.yearlyAwards) {
              merged.yearlyAwards = { ...savedAwardSystemSettings.yearlyAwards };
            }
            // 현재 연도까지 없는 연도 추가
            const years = getAwardYears();
            for (const y of years) {
              if (!merged.yearlyAwards[y]) {
                // 이전 연도 설정 복사 또는 기본 템플릿
                const prevYear = String(Number(y) - 1);
                merged.yearlyAwards[y] = merged.yearlyAwards[prevYear] 
                  ? merged.yearlyAwards[prevYear].map(a => ({ ...a }))
                  : DEFAULT_AWARD_TEMPLATE.map(a => ({ ...a }));
              }
            }
            setAwardSystemSettings(merged);
          } else {
            // 초기 설정 - 현재 연도까지 모두 생성
            const initial = { ...DEFAULT_AWARD_SYSTEM_SETTINGS, yearlyAwards: {} };
            const years = getAwardYears();
            for (const y of years) {
              initial.yearlyAwards[y] = DEFAULT_AWARD_TEMPLATE.map(a => ({ ...a }));
            }
            setAwardSystemSettings(initial);
          }
          
          // 📰 v3.0: 최신 변화 기록 로드 및 만료 기록 정리
          if (Array.isArray(savedRecentChanges)) {
            const retentionDays = savedSettings?.recentChanges?.retentionDays || DEFAULT_SETTINGS.recentChanges.retentionDays;
            const cutoff = Date.now() - retentionDays * 24 * 60 * 60 * 1000;
            // 만료되지 않은 기록만 유지
            const validChanges = savedRecentChanges.filter(c => c.timestamp > cutoff);
            setRecentChanges(validChanges);
            // 정리된 기록 저장 (만료 기록 삭제)
            if (validChanges.length !== savedRecentChanges.length) {
              await setAppMeta("recent_changes", validChanges);
            }
          }
          
          // 🔮 v3.0.3: 매칭 인사이트 로드
          if (Array.isArray(savedMatchInsights)) {
            setMatchInsights(savedMatchInsights);
          }
          
          // 🔗 v3.0.3: 태그 관계도 로드
          if (savedTagRelations && typeof savedTagRelations === "object") {
            let loaded = {
              groups: savedTagRelations.groups || {},
              tagToGroup: savedTagRelations.tagToGroup || {},
            };
            
            // 🔗 v3.5.5: TAG_ALIASES → similar 그룹 자동 마이그레이션
            const { relations: migrated, addedCount } = migrateAliasesToRelations(loaded);
            if (addedCount > 0) {
              loaded = migrated;
              safeDefer(() => setAppMeta("tag_relations", migrated));
              console.log(`[태그 관계] ${addedCount}개 약어 그룹 자동 마이그레이션`);
            }
            
            setTagRelations(loaded);
          } else {
            // 최초 실행: TAG_ALIASES 기반으로 초기 그룹 생성
            const { relations: initial, addedCount } = migrateAliasesToRelations(null);
            if (addedCount > 0) {
              setTagRelations(initial);
              safeDefer(() => setAppMeta("tag_relations", initial));
              console.log(`[태그 관계] 초기 ${addedCount}개 약어 그룹 생성`);
            }
          }
          
          // 🔮 v3.0.3: 이변 요인 로드
          if (savedUpsetFactors && typeof savedUpsetFactors === "object") {
            setUpsetFactors({
              factors: Array.isArray(savedUpsetFactors.factors) ? savedUpsetFactors.factors : [],
              lastUpdated: savedUpsetFactors.lastUpdated || 0,
            });
          }
          
          // 🎯 v3.0.4: 자동승패 설정 로드
          if (savedAutoMatchSettings && typeof savedAutoMatchSettings === "object") {
            setAutoMatchSettings(prev => ({
              ...prev,
              ...savedAutoMatchSettings,
              criteria: {
                ...prev.criteria,
                ...(savedAutoMatchSettings.criteria || {}),
              },
            }));
          }
          
          // 🔗 v3.0.4: 조합 요소 로드
          if (Array.isArray(savedCustomComboTraits)) {
            setCustomComboTraits(savedCustomComboTraits);
          }
          if (Array.isArray(savedCustomComboTargets)) {
            setCustomComboTargets(savedCustomComboTargets);
          }
          
          // 📐 v3.2.0: 태그 좌표계 로드
          if (savedCoordinateSystems && typeof savedCoordinateSystems === "object") {
            setCoordinateSystems(savedCoordinateSystems);
          }
          
          await loadList(undefined, undefined, "init");
          
          // 📋 v3.3.0: 예정 작품 목록 로드
          await loadPlannedList();
          
          // 🖼️ v3.4.5: 표지 라이브러리 로드
          await loadCoverLibrary();

          // 📂 v3.7.0: 폴더 데이터 로드
          await loadFolders();
          await loadNovelFolderMap();

          // 🎨 v3.8.0: 갤러리 카운트 로드 (뱃지용, 전체 데이터는 탭 진입 시)
          await loadGalleryCount();

          // 🧠 v3.5.0: 취향 발견 시스템 마이그레이션 (기존 매칭 데이터에서 패턴 추출)
          // 🆕 v3.5.8: savedTagAttributes 전달 (작품명 태그 제외)
          // 🛠️ v7.0.12: mounted 가드 추가 — 100ms/2000ms 사이 슬롯 전환/언마운트 발생 시 stale DB write 방지
          const migrateTagAttrs = savedTagAttributes || {};
          setTimeout(async () => {
            if (!mounted) return;
            try {
              await migrateExistingMatchesToPatterns(migrateTagAttrs);
            } catch (e) {
              console.warn("취향 발견 시스템 마이그레이션 오류:", e);
            }
          }, 2000); // 초기 로딩 완료 후 실행

          // 🏷️ 태그 자동 수집 (비동기 - UI 블로킹 없음)
          // 🔧 v3.6.1: loadedRegistry 직접 사용 (stale closure 방지)
          setTimeout(async () => {
            if (!mounted) return;
            try {
              const novels = await all("SELECT tags, major_genre, sub_genre FROM novels;");
              if (!novels || novels.length === 0) return;

              // 🔧 v3.6.1: 실행 시점의 최신 registry를 DB에서 직접 읽어 race condition 방지
              // (loadedRegistry는 init 시점 스냅샷이라, 100ms 사이 다른 조작이 있으면 덮어씀)
              const freshRegistry = await getAppMeta("tag_registry");
              if (!freshRegistry) return;

              const allDefaultSet = new Set([...ALL_DEFAULT_TAGS, ...MAJOR_GENRES, ...SUB_GENRES]);
              const newTags = new Set();

              for (const n of novels) {
                const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
                for (const tag of tags) {
                  if (!allDefaultSet.has(tag)) {
                    newTags.add(tag);
                  }
                }
                const majors = parseMajorSub(n.major_genre);
                for (const g of majors) {
                  if (!listHasTag(MAJOR_GENRES, g) && !allDefaultSet.has(g)) {
                    newTags.add(g);
                  }
                }
                const subs = parseMajorSub(n.sub_genre);
                for (const g of subs) {
                  if (!listHasTag(SUB_GENRES, g) && !allDefaultSet.has(g)) {
                    newTags.add(g);
                  }
                }
              }

              if (newTags.size > 0) {
                const newGeneralTags = { ...(freshRegistry.generalTags || {}) };
                if (!newGeneralTags["📁 사용자 태그"]) newGeneralTags["📁 사용자 태그"] = [];
                const userTags = [...newGeneralTags["📁 사용자 태그"]];
                let added = 0;
                for (const t of newTags) {
                  if (!userTags.some(ut => isSameTag(ut, t))) {
                    userTags.push(t);
                    added++;
                  }
                }
                if (added > 0) {
                  newGeneralTags["📁 사용자 태그"] = userTags;
                  updateTagRegistry({ ...freshRegistry, generalTags: newGeneralTags });
                }
              }
            } catch (e) {
              console.warn("태그 자동 수집 실패:", e);
            }
          }, 100); // UI 렌더링 후 실행
          
          // ℹ️ What's New 버전 체크
          try {
            const lastSeenVer = await getAppMeta("last_seen_version");
            if (lastSeenVer !== APP_VERSION) {
              const newChanges = lastSeenVer
                ? CHANGELOG_DATA.filter(e => compareVersions(e.version, lastSeenVer) > 0)
                : CHANGELOG_DATA.slice(0, 1);
              if (newChanges.length > 0) {
                setTimeout(() => {
                  if (!mounted) return;
                  setWhatsNewEntries(newChanges);
                  deferOpen(setShowWhatsNewModal);
                }, 500);
              }
            }
          } catch (e) { console.warn("What's New check error:", e); }

          setLoadingProgress(null);  // 🆕 v7.3.0: 초기화 진행도 클리어
          setIsLoading(false);
          return; // 성공하면 종료

        } catch (e) {
          console.warn(`앱 초기화 오류 (시도 ${attempt + 1}/${maxRetries}):`, e);
          await resetDbConnection();
          
          if (attempt === maxRetries - 1) {
            if (mounted) {
              setLoadingProgress(null);  // 🆕 v7.3.0
              setIsLoading(false);
              Alert.alert(
                "데이터베이스 오류",
                "앱을 다시 시작해주세요.\n\n오류: " + e.message,
                [{ text: "확인" }]
              );
            }
          } else {
            // 재시도 전 대기
            await new Promise(r => setTimeout(r, 500 * (attempt + 1)));
          }
        }
      }
    };
    
    initialize();

    return () => {
      mounted = false;
      setMatchQueueCallback(null); // 🔄 v3.4.6: 콜백 정리
      if (coOccTimerRef.current) { clearTimeout(coOccTimerRef.current); coOccTimerRef.current = null; }
    };
  }, []);

  // 💥 v3.9.0: CrashLog 상태 스냅샷 — 매 렌더마다 최신 클로저로 등록 (stale closure 방지)
  CrashLog.registerStateSnapshot(() => ({
    screen: screen || "unknown",
    listCount: list?.length || 0,
    slotId: activeSlotId,
    isAutoMatching: isAutoMatchingRef.current,
  }));

  // 📁 v3.5.15d: 슬롯 전환 함수 (전체 state 리셋 + 새 DB 초기화 + 재로드)
  const performSlotSwitch = async (newSlotId) => {
    if (newSlotId === activeSlotId || slotSwitching) return;
    // 🔧 v7.6.0 (포트 v3.12.2): 자동매칭 중 슬롯 전환 차단 — in-flight 매칭 DB 오염 방지
    if (isAutoMatchingRef.current) {
      Alert.alert("슬롯 전환 불가", "자동 매칭을 먼저 중지해주세요.");
      return;
    }
    Breadcrumbs.action("slot_switch", `${activeSlotId} → ${newSlotId}`);
    const previousSlotId = activeSlotId; // 🔧 롤백용 백업
    setSlotSwitching(true);
    setIsLoading(true);
    
    try {
      // 1. DB 레벨 전환 (flush → close → open new)
      await switchSlotDb(newSlotId);

      // 2. 새 DB 초기화 (테이블 생성 등) — 🆕 v7.3.0: progress 콜백
      setLoadingProgress({ label: "슬롯 DB 초기화 중..." });
      await initDb((p) => setLoadingProgress(p));
      setLoadingProgress({ label: "태그 시스템 마이그레이션 중..." });
      await migrateTagSystem();
      const slotRegistry = await loadTagRegistry(); // 🔧 v3.6.1: 반환값 보존
      await loadPlatformRegistry(); // 🆕 플랫폼 레지스트리 로드

      // 3. 모든 데이터 state 초기값으로 리셋
      setList([]);
      setPair(null);
      setMatchAnalysis(null);
      setMatchPrediction(null);
      setLastMatchId(null);
      setFocusMatchNovel(null);
      setSelectedIds([]);
      setEditOpen(false);
      updateEditItem(null);
      setDailyReco(null);
      setUndoStack([]);
      setMatchInsights([]);
      setUpsetFactors({ factors: [], lastUpdated: 0 });
      setTagRelations({ groups: {}, tagToGroup: {} });
      setTagCoOccurrences({});
      // v7.0.1 (M2 fix): hybrid 검증 state도 슬롯 격리 (이전 슬롯 sessionId/응답 누수 방지)
      // 🆕 v7.0.2: setVerificationLoading(false) 추가 — 이전 슬롯에서 in-flight 시 새 슬롯에서 자동 시작 차단되던 문제
      setVerificationSession(null);
      setVerificationStats({ pending: 0, resolved: 0 });
      setVerificationLoading(false);
      setGatekeeperCandidates([]);
      setGatekeeperModalOpen(false);
      verificationSessionIdRef.current = null;
      verificationLoadingRef.current = false;
      // 🔧 v6.0.1: 새 슬롯의 registry를 그대로 사용 (사용자 정의 태그 보존)
      // 🔧 슬롯 전환: slotRegistry가 null이면 팩토리 기본값으로 초기화 (이전 슬롯 데이터 잔류 방지)
      if (slotRegistry) {
        updateTagRegistry(slotRegistry);
      } else {
        updateTagRegistry({
          version: 1,
          majorGenres: [...FACTORY_MAJOR_GENRES],
          subGenres: [...FACTORY_SUB_GENRES],
          generalTags: { ...FACTORY_GENERAL_TAGS },
          characterCategories: { ...FACTORY_CHARACTER_CATEGORIES },
          aliases: { ...FACTORY_TAG_ALIASES },
          spectrumGroups: { ...FACTORY_TAG_SPECTRUM_GROUPS },
        });
      }
      setComboTags([]);
      setTagSentiments({});
      setTagAttributes({});
      setHiddenTags([]);
      setPinnedTags([]);
      setCustomComboTraits([]);
      setCustomComboTargets([]);
      setCoordinateSystems(null);
      setCustomTagCategories({});
      setRecentChanges([]);
      setTierHistory([]);
      setCoverLibrary([]);
      setCoverLibrarySize(0);
      setPlatformCovers({});
      setInsightList([]);
      setPreferencePatterns([]);
      setAutoEnabled(false);
      // 🔧 v3.5.15e: appSettings + globalTierThresholds 리셋 (이전 슬롯 설정 잔류 방지)
      setAppSettings(DEFAULT_SETTINGS);
      globalTierThresholds = { ...DEFAULT_SETTINGS.tierThresholds };
      // 🔧 v6.0.1: globalTierConfig + lookup 리셋 (이전 슬롯 커스텀 프리셋 잔류 방지)
      globalTierConfig = { ...DEFAULT_TIER_SYSTEM_CONFIG };
      rebuildTierLookup(globalTierConfig);
      // 🆕 플랫폼 레지스트리 리셋 (이전 슬롯 커스텀 플랫폼 잔류 방지)
      PLATFORM_OPTIONS = [...FACTORY_PLATFORM_OPTIONS];
      PLATFORM_URLS = { ...FACTORY_PLATFORM_URLS };
      setPlatformRegistry(null);
      // 📂 v3.7.0: 폴더 상태 리셋
      setFolders([]);
      setNovelFolderMap(new Map());
      setFilterFolder("ALL");
      setFolderModalOpen(false);
      setFolderAssignModalOpen(false);
      setFolderAssignTarget(null);
      // 🎨 v3.8.0: 갤러리 상태 리셋
      setGalleryImages([]);
      setGalleryIdx(0);
      setGalleryShuffled(null);
      setGalleryRegNovel(null);
      setGalleryRegSearch("");
      setGallerySubTab("view");
      setGalleryExpandImg(null);
      setGalleryChangeNovelTarget(null);
      setGalleryNovelPickerOpen(false);
      setGalleryCaptionEditOpen(false);
      setGalleryCaptionEditId(null);
      setGalleryCount(0);
      setGalleryExpandedGroups({});
      // 🔧 누락 리셋 보완
      setMatchStats({ total: 0, done: 0, percent: 0 });
      setIsAutoMatching(false);
      setMatchFilterEnabled(false);
      setMatchFilterMinTags(15);
      setAutoMatchSettings({
        mode: "any",
        speed: "fast",
        criteria: {
          ratingGap: { enabled: true, threshold: 250 },
          predictionRate: { enabled: false, threshold: 75 },
          winStreakGap: { enabled: false, threshold: 5 },
        },
      });
      setAwardSystemSettings(DEFAULT_AWARD_SYSTEM_SETTINGS);
      setSupplementSessionCount(0);
      setSupplementRecentDone([]);
      setSupplementCurrentNovel(null);
      setTagUsageCounts({});
      setQuotesIdx(0);
      setQuotesShuffled(null);
      // refs (🔧 슬롯 전환 시 이전 슬롯 데이터 잔류 방지)
      isAutoMatchingRef.current = false;
      needsListRefreshRef.current = false;
      loadListRunningRef.current = false; // 🔧 v3.5.15e: 이전 loadList 비정상 종료 시 잔류 방지
      editItemRef.current = null;
      editOriginalSnapshotRef.current = null;
      selectedIdsRef.current = [];
      plannedEditItemRef.current = null;
      if (matchStatsTimerRef.current) { clearTimeout(matchStatsTimerRef.current); matchStatsTimerRef.current = null; }
      if (pairAnalysisTimerRef.current) { clearTimeout(pairAnalysisTimerRef.current); pairAnalysisTimerRef.current = null; }
      // 캐시 무효화
      invalidateMatchCache();
      invalidatePatternCache();
      invalidateWeightsCache();
      genreMatchupCacheRef.current = { data: {}, ts: 0, TTL: 30000 };
      // 메모리 큐 정리
      choiceLogQueue.pending = [];
      if (choiceLogQueue.timer) { clearTimeout(choiceLogQueue.timer); choiceLogQueue.timer = null; }
      patternUpdateBatch.length = 0;
      patternUpdateScheduled = false;
      
      // 4. 새 DB에서 app_meta 로드
      // 🔧 v3.6.1: custom_tags, user_major_genres, user_sub_genres 제거 (tagRegistry에서 파생)
      const [
        savedPlatformCovers, savedSettings, savedTierHistory,
        savedComboTags, savedTagSentiments,
        savedTagAttributes,
        savedHiddenTags, savedAwardSystemSettings, savedRecentChanges,
        savedMatchInsights, savedTagRelations, savedUpsetFactors,
        savedAutoMatchSettings, savedCustomComboTraits, savedCustomComboTargets,
        savedCoordinateSystems, savedCustomTagCategories, savedMatchFilterSettings,
        savedPinnedTags,
        savedHomeSortSettings,                 // 🔧 v7.6.0 (포트 v3.12.1)
      ] = await Promise.all([
        getAppMeta("platform_covers"),         // 0
        getAppMeta("app_settings"),            // 1
        getAppMeta("tier_history"),            // 2
        getAppMeta("combo_tags"),              // 3 (마이그레이션용)
        getAppMeta("tag_sentiments"),          // 4
        getAppMeta("tag_attributes"),          // 5
        getAppMeta("hidden_tags"),             // 6
        getAppMeta("award_system_settings"),   // 7
        getAppMeta("recent_changes"),          // 8
        getAppMeta("match_insights"),          // 9
        getAppMeta("tag_relations"),           // 10
        getAppMeta("upset_factors"),           // 11
        getAppMeta("auto_match_settings"),     // 12
        getAppMeta("custom_combo_traits"),     // 13
        getAppMeta("custom_combo_targets"),    // 14
        getTagCoordinateSystems(),             // 15
        getAppMeta("custom_tag_categories"),   // 16
        getAppMeta("match_filter_settings"),   // 17
        getAppMeta("pinned_tags"),             // 18
        getAppMeta("home_sort_settings"),      // 19: 🔧 v7.6.0 (포트 v3.12.1)
      ]);
      
      // 5. state 복원 (간소화 — 핵심 데이터만)
      if (savedPlatformCovers && typeof savedPlatformCovers === "object") setPlatformCovers(savedPlatformCovers);
      if (savedSettings && typeof savedSettings === "object") {
        const merged = { ...DEFAULT_SETTINGS, ...savedSettings };
        if (savedSettings.supplement) merged.supplement = { ...DEFAULT_SETTINGS.supplement, ...savedSettings.supplement };
        if (savedSettings.recentChanges) merged.recentChanges = { ...DEFAULT_SETTINGS.recentChanges, ...savedSettings.recentChanges };
        if (savedSettings.plannedFields) merged.plannedFields = { ...DEFAULT_SETTINGS.plannedFields, ...savedSettings.plannedFields };
        if (savedSettings.coverLibrary) merged.coverLibrary = { ...DEFAULT_SETTINGS.coverLibrary, ...savedSettings.coverLibrary };
        // 🆕 v6.0: tierSystemConfig 마이그레이션 (슬롯 전환 시에도 적용)
        if (!savedSettings.tierSystemConfig && merged.tierThresholds) {
          const legacyTh = merged.tierThresholds;
          merged.tierSystemConfig = {
            ...DEFAULT_TIER_SYSTEM_CONFIG,
            tiers: DEFAULT_TIER_SYSTEM_CONFIG.tiers.map(t => ({
              ...t,
              threshold: legacyTh[t.key] !== undefined ? legacyTh[t.key] : t.threshold,
            })),
          };
        }
        if (savedSettings.tierSystemConfig) {
          merged.tierSystemConfig = { ...DEFAULT_TIER_SYSTEM_CONFIG, ...savedSettings.tierSystemConfig };
          if (savedSettings.tierSystemConfig.tiers) {
            merged.tierSystemConfig.tiers = savedSettings.tierSystemConfig.tiers;
          }
        }
        setAppSettings(merged);
        globalSuspicionConfig = { ...DEFAULT_SUSPICION_CONFIG, ...(merged.suspicionConfig || {}) }; // 🔧 v7.18.0
        if (merged.tierThresholds) globalTierThresholds = { ...DEFAULT_SETTINGS.tierThresholds, ...merged.tierThresholds };
        // 🆕 v6.0: globalTierConfig 초기화 (슬롯 전환)
        if (merged.tierSystemConfig) {
          globalTierConfig = { ...merged.tierSystemConfig };
          rebuildTierLookup(globalTierConfig);
        }
      }
      if (Array.isArray(savedTierHistory)) setTierHistory(savedTierHistory.slice(0, 50));
      if (savedCustomTagCategories && typeof savedCustomTagCategories === "object") setCustomTagCategories(savedCustomTagCategories);
      if (savedMatchFilterSettings && typeof savedMatchFilterSettings === "object") {
        if (savedMatchFilterSettings.enabled !== undefined) setMatchFilterEnabled(savedMatchFilterSettings.enabled);
        if (savedMatchFilterSettings.minTags !== undefined) setMatchFilterMinTags(savedMatchFilterSettings.minTags);
      }
      if (savedTagSentiments && typeof savedTagSentiments === "object") setTagSentiments(savedTagSentiments);
      if (savedTagAttributes && typeof savedTagAttributes === "object") setTagAttributes(savedTagAttributes);
      if (Array.isArray(savedHiddenTags)) setHiddenTags(savedHiddenTags);
      if (savedAwardSystemSettings && typeof savedAwardSystemSettings === "object") {
        // 🛠️ v7.20.0: initialize와 동일하게 누락 연도 백필 — 슬롯 전환 시 currentYearAwards 공백 방지
        //   (이전: 백필 없이 저장값만 사용 → 옛 슬롯이 "2024"만 보유 시 올해 yearlyAwards 누락 →
        //    수상 결과 탭 currentYearAwards=[] → 수상작 미표시. displayAwards가 표시는 보강하나
        //    수상 탭 배정 버튼/필터는 정의가 있어야 동작하므로 데이터 정합도 함께 복구.)
        const merged = { ...DEFAULT_AWARD_SYSTEM_SETTINGS };
        if (savedAwardSystemSettings.yearlyAwards) merged.yearlyAwards = { ...savedAwardSystemSettings.yearlyAwards };
        const years = getAwardYears();
        for (const y of years) {
          if (!merged.yearlyAwards[y]) {
            const prevYear = String(Number(y) - 1);
            merged.yearlyAwards[y] = merged.yearlyAwards[prevYear]
              ? merged.yearlyAwards[prevYear].map(a => ({ ...a }))
              : DEFAULT_AWARD_TEMPLATE.map(a => ({ ...a }));
          }
        }
        setAwardSystemSettings(merged);
      } else {
        // 🛠️ v7.20.0: 슬롯에 저장된 수상 설정이 없을 때도 전 연도 생성 (initialize와 동일, 슬롯 간 잔존 방지)
        const initial = { ...DEFAULT_AWARD_SYSTEM_SETTINGS, yearlyAwards: {} };
        for (const y of getAwardYears()) {
          initial.yearlyAwards[y] = DEFAULT_AWARD_TEMPLATE.map(a => ({ ...a }));
        }
        setAwardSystemSettings(initial);
      }
      if (Array.isArray(savedRecentChanges)) setRecentChanges(savedRecentChanges);
      if (Array.isArray(savedMatchInsights)) setMatchInsights(savedMatchInsights);
      if (savedTagRelations && typeof savedTagRelations === "object") {
        setTagRelations({ groups: savedTagRelations.groups || {}, tagToGroup: savedTagRelations.tagToGroup || {} });
      }
      if (savedUpsetFactors && typeof savedUpsetFactors === "object") {
        setUpsetFactors({ factors: Array.isArray(savedUpsetFactors.factors) ? savedUpsetFactors.factors : [], lastUpdated: savedUpsetFactors.lastUpdated || 0 });
      }
      if (savedAutoMatchSettings && typeof savedAutoMatchSettings === "object") {
        // 🔧 리셋 후 복원이므로 prev 스프레드 불필요 — 새 값으로 직접 설정
        const defaultCriteria = { ratingGap: { enabled: true, threshold: 250 }, predictionRate: { enabled: false, threshold: 75 }, winStreakGap: { enabled: false, threshold: 5 } };
        setAutoMatchSettings({
          mode: savedAutoMatchSettings.mode || "any",
          speed: savedAutoMatchSettings.speed || "fast",
          criteria: { ...defaultCriteria, ...(savedAutoMatchSettings.criteria || {}) },
        });
      }
      if (Array.isArray(savedCustomComboTraits)) setCustomComboTraits(savedCustomComboTraits);
      if (Array.isArray(savedCustomComboTargets)) setCustomComboTargets(savedCustomComboTargets);
      if (savedCoordinateSystems && typeof savedCoordinateSystems === "object") setCoordinateSystems(savedCoordinateSystems);
      
      // 🔧 v3.5.15e: pinnedTags 복원 (useEffect([]) 는 마운트 시 1회만이므로 슬롯 전환 시 별도 로드 필수)
      if (Array.isArray(savedPinnedTags)) setPinnedTags(savedPinnedTags);

      // 🔧 v7.6.0 (포트 v3.12.1): 홈 정렬/필터 슬롯 전환 시에도 복원
      // Ref 일시 false 후 setState → 다음 tick에 true 복원 (전환 중 false-save 방지)
      homeSortInitRef.current = false;
      if (savedHomeSortSettings && typeof savedHomeSortSettings === "object") {
        if (savedHomeSortSettings.sortKey) setHomeSortKey(savedHomeSortSettings.sortKey);
        if (savedHomeSortSettings.sortDir) setHomeSortDir(savedHomeSortSettings.sortDir);
        if (savedHomeSortSettings.filterTier) setFilterTier(savedHomeSortSettings.filterTier); else setFilterTier("ALL");
        if (savedHomeSortSettings.filterPlatform) setFilterPlatform(savedHomeSortSettings.filterPlatform); else setFilterPlatform("ALL");
        if (savedHomeSortSettings.filterGenre) setFilterGenre(savedHomeSortSettings.filterGenre); else setFilterGenre("ALL");
        if (savedHomeSortSettings.filterStatus) setFilterStatus(savedHomeSortSettings.filterStatus); else setFilterStatus("ALL");
        if (savedHomeSortSettings.filterFolder) setFilterFolder(savedHomeSortSettings.filterFolder); else setFilterFolder("ALL");
      } else {
        // 새 슬롯에 저장값 없으면 기본값
        setHomeSortKey("rating"); setHomeSortDir("DESC");
        setFilterTier("ALL"); setFilterPlatform("ALL"); setFilterGenre("ALL"); setFilterStatus("ALL"); setFilterFolder("ALL");
      }
      // setTimeout으로 next tick에 Ref 활성화 (setState 반영 후)
      setTimeout(() => { homeSortInitRef.current = true; }, 0);

      // 🔧 v3.6.1: addTagToRegistry는 tagRegistry 클로저(null)를 참조하므로
      //   slotRegistry를 직접 수정하여 updateTagRegistry 호출
      if (Array.isArray(savedComboTags) && savedComboTags.length > 0 && slotRegistry) {
        let migrated = 0;
        const newGeneralTags = { ...(slotRegistry.generalTags || {}) };
        if (!newGeneralTags["📁 사용자 태그"]) newGeneralTags["📁 사용자 태그"] = [];
        const userTags = [...newGeneralTags["📁 사용자 태그"]];
        for (const ct of savedComboTags) {
          if (!ALL_DEFAULT_TAGS.some(t => isSameTag(t, ct)) && !userTags.some(t => isSameTag(t, ct))) {
            userTags.push(ct);
            migrated++;
          }
        }
        if (migrated > 0) {
          newGeneralTags["📁 사용자 태그"] = userTags;
          updateTagRegistry({ ...slotRegistry, generalTags: newGeneralTags });
          console.log(`[슬롯 전환 태그 마이그레이션] 조합식 ${migrated}개 → 커스텀 태그로 통합`);
        }
        setComboTags([]);
        await setAppMeta("combo_tags", []);
      }
      
      // 6. 목록 로드
      initLoadedRef.current = false; // loadList init guard 리셋
      await loadList(undefined, undefined, "slot-switch");
      await loadPlannedList();
      await loadCoverLibrary();
      // 📂 v3.7.0: 폴더 데이터 로드
      await loadFolders();
      await loadNovelFolderMap();
      // 🎨 v3.8.0: 갤러리 카운트 로드
      await loadGalleryCount();

      // 🔧 v3.5.15e: 인사이트/패턴도 새 DB에서 재로드 (분석 탭 진입 전 일관성 보장)
      loadInsights().catch(() => {});
      loadPreferencePatterns().catch(() => {});
      
      // 7. 슬롯 메타 갱신
      const meta = await loadSlotMeta();
      setSlotMeta(meta);
      
      // 화면을 홈으로 이동 (🔧 v3.9.1: setScreen 사용 — screenRef 동기화)
      setScreen("home");
      
      Alert.alert("슬롯 전환 완료", `"${meta.slots.find(s => s.id === newSlotId)?.name || "슬롯"}"으로 전환되었습니다.`);
      
    } catch (e) {
      console.warn("슬롯 전환 오류:", e);
      // 🔧 롤백: 이전 슬롯으로 되돌리기 시도
      try {
        activeSlotId = previousSlotId;
        await resetDbConnection();
        await openDb();
        await loadList(undefined, undefined, "slot-rollback");
        const meta = await loadSlotMeta();
        meta.activeSlotId = previousSlotId;
        await saveSlotMeta(meta);
        setSlotMeta(meta);
        // 🆕 v7.0.11: broken 슬롯에 [🩹 복구 시도] 진입점 (사용자 명시 confirm 후 실행)
        // 1회 제한: 같은 슬롯에 대해 세션당 1회만 시도 가능 (_recoveryAttempted Set).
        // 자동 재시도 X — 복구 후 사용자가 직접 슬롯을 다시 탭해야 함 (사용자 결정).
        const alreadyTried = _recoveryAttempted.has(newSlotId);
        const buttons = [{ text: "확인" }];
        if (!alreadyTried) {
          buttons.push({
            text: "🩹 복구 시도",
            onPress: () => {
              Alert.alert(
                "슬롯 복구 시도",
                "이 슬롯의 -wal/-shm 캐시를 .bak로 보존한 뒤 메인 DB 무결성을 점검합니다.\n\n마지막 미반영 변경이 있다면 .bak 파일에 보존되며, 메인 DB는 절대 변경되지 않습니다.",
                [
                  { text: "취소" },
                  {
                    text: "복구 시작",
                    onPress: async () => {
                      setSlotRecovering(true);
                      try {
                        const result = await recoverSlotDb(newSlotId);
                        if (result.success) {
                          Alert.alert(
                            "복구 완료",
                            "슬롯을 다시 탭해주세요.\n\n" +
                            (result.recovered === "wal_renamed"
                              ? "(-wal/-shm은 .bak로 보존되어 SQLite 디렉터리에 남아있습니다.)"
                              : "(-wal 캐시가 없어 정리할 항목이 없었습니다.\n슬롯을 다시 탭하면 스키마 자가 치유(initDb)가 한 번 더 시도됩니다.)")
                          );
                        } else {
                          Alert.alert(
                            "복구 실패",
                            (result.error || "알 수 없는 오류") +
                            "\n\n백업 export → 새 슬롯에 import를 권장합니다."
                          );
                        }
                      } catch (recErr) {
                        console.warn("recoverSlotDb 호출 오류:", recErr);
                        Alert.alert("오류", "복구 중 오류가 발생했습니다.\n\n" + (recErr?.message || ""));
                      } finally {
                        setSlotRecovering(false);
                      }
                    },
                  },
                ]
              );
            },
          });
        }
        Alert.alert(
          "슬롯 전환 실패",
          "이전 슬롯으로 복원되었습니다.\n\n" + e.message +
          (alreadyTried ? "\n\n(이 슬롯은 이번 세션에 이미 복구를 시도했습니다.)" : ""),
          buttons
        );
      } catch (rollbackErr) {
        console.error("슬롯 롤백도 실패:", rollbackErr);
        Alert.alert("심각한 오류", "슬롯 전환 및 복원에 모두 실패했습니다.\n앱을 재시작해주세요.\n\n" + e.message);
      }
    } finally {
      setSlotSwitching(false);
      setIsLoading(false);
    }
  };
  
  // 🔧 v3.4.6: 앱이 포그라운드로 돌아올 때 DB 연결 강제 리셋
  // 🧠 v3.5.0: 백그라운드 전환 시 큐 플러시 추가
  // 🔧 v3.5.1: 포그라운드 복귀 시 데이터 리로드 추가
  useEffect(() => {
    let lastState = AppState.currentState;
    // 🆕 v7.0.2: 백그라운드 진입 시각 — PerfMonitor 비활성 시에도 동작 (이전: PerfMonitor._lastForegroundTime은
    // PerfMonitor.enabled=true일 때만 업데이트되어 항상 0 → bgDuration ≈ Date.now() → 항상 long-BG 분기 → 매 포그라운드마다 reset)
    let lastBackgroundTime = 0;

    const subscription = AppState.addEventListener("change", async (nextAppState) => {
      PerfMonitor.trackLifecycle(nextAppState === "active" ? "foreground" : "background"); // 🔬
      Breadcrumbs.lifecycle(nextAppState === "active" ? "foreground" : "background");
      // 포그라운드 → 백그라운드 전환 시: 큐 플러시
      if (lastState === "active" && nextAppState.match(/inactive|background/)) {
        console.log("앱 백그라운드 전환 - 큐 플러시 + DB 정리");
        lastBackgroundTime = Date.now();
        try {
          await choiceLogQueue.flush();
        } catch (e) {
          console.warn("백그라운드 전환 큐 플러시 실패:", e);
        }
      }

      // 백그라운드 → 포그라운드 전환 시
      if (lastState.match(/inactive|background/) && nextAppState === "active") {
        // 🔧 DB 최적화: 짧은 BG (< 5초)에서는 연결 검증만, 리셋 스킵
        // 빠른 앱 전환(멀티태스킹)에서 불필요한 resetDbConnection 9회 → 최소화
        // 🆕 v7.0.2: lastBackgroundTime 우선 사용 (PerfMonitor 의존 제거)
        const bgDuration = lastBackgroundTime > 0
          ? Date.now() - lastBackgroundTime
          : Date.now() - (PerfMonitor._lastForegroundTime || Date.now());
        const isShortBackground = bgDuration < 5000;

        if (isShortBackground) {
          console.log(`짧은 BG 복귀 (${bgDuration}ms) - 연결 검증만 수행`);
          try {
            const database = await openDb();
            await database.getAllAsync("SELECT 1;");
            console.log("DB 연결 유효 - 리셋 스킵");
          } catch (e) {
            // 🔧 v7.6.0 (포트 v3.9.2): SQLITE_BUSY/LOCKED 구분 — 경합은 리셋 불필요 (불변규칙 #4)
            const msg = (e.message || "").toLowerCase();
            const isBusy = msg.includes("busy") || msg.includes("locked");
            if (isBusy) {
              console.log("DB 경합 감지 (BUSY/LOCKED) - 리셋 스킵 (연결 유효)");
            } else {
              console.log("DB 연결 무효 - 리셋 수행");
              await resetDbConnection();
              await openDb();
              await loadList(undefined, undefined, "fg-recovery");
              await loadCoverLibrary();
            }
          }
        } else {
          console.log(`앱 포그라운드 전환 (${bgDuration}ms) - DB 연결 리셋 및 데이터 리로드`);
          // 🔧 v3.5.15c: 매칭 큐가 처리 중이면 먼저 드레인 대기
          if (!isMatchQueueIdle()) {
            console.log("포그라운드 전환: 매칭 큐 드레인 대기...");
            await waitForMatchQueueDrain(3000);
          }
          await resetDbConnection();
          try {
            await openDb();
            await new Promise(r => setTimeout(r, 200));
            console.log("DB 재연결 성공 (WAL mode)");
            await loadList(undefined, undefined, "fg-recovery");
            await loadCoverLibrary();
            loadGalleryCount().catch(() => {}); // 🎨 v3.8.0
            console.log("데이터 리로드 성공");
          } catch (e) {
            console.error("DB 재연결/리로드 실패:", e.message);
            try {
              await resetDbConnection();
              await new Promise(r => setTimeout(r, 500));
              await openDb();
              await loadList(undefined, undefined, "fg-retry");
              console.log("DB 2차 재연결 성공");
            } catch (e2) {
              console.error("DB 2차 재연결도 실패:", e2.message);
            }
          }
        }
      }
      lastState = nextAppState;
    });
    
    return () => {
      subscription.remove();
    };
  }, []);
  
  
  // -----------------------------------------
  // 📋 v3.3.0: 예정 작품 관리 함수들
  // -----------------------------------------
  
  async function loadPlannedList() {
    const _pt = PerfMonitor.enabled ? Date.now() : 0; // 🔬
    try {
      const safeDir = plannedSortDir === "ASC" ? "ASC" : "DESC";
      let orderBy = `created_at ${safeDir}`;
      if (plannedSortKey === "title") {
        orderBy = `title COLLATE NOCASE ${safeDir}`;
      } else if (plannedSortKey === "priority") {
        orderBy = `priority ${safeDir}, created_at DESC`;
      }
      const rows = await all(`SELECT * FROM planned_novels ORDER BY ${orderBy};`);
      // 🆕 v7.3.0: 가등록 카드 갤러리 카운트 배지용 — 별도 쿼리로 Map 빌드 (가독성 우선)
      let galleryCounts = new Map();
      try {
        const cnts = await all("SELECT novel_id, COUNT(*) AS cnt FROM gallery_images GROUP BY novel_id");
        galleryCounts = new Map((cnts || []).map(r => [r.novel_id, Number(r.cnt) || 0]));
      } catch (e) { console.warn("[v7.3.0] gallery_count 로드 실패:", e?.message); }
      const enriched = (rows || []).map(p => ({
        ...p,
        gallery_count: galleryCounts.get(p.id) || 0,
      }));
      setPlannedList(enriched);
      if (_pt) PerfMonitor.trackFunc("loadPlannedList", Date.now() - _pt); // 🔬
    } catch (e) {
      console.warn("loadPlannedList 오류:", e);
      if (_pt) PerfMonitor.logError("loadPlannedList", e); // 🔬
      setPlannedList([]);
    }
  }
  
  async function addPlannedNovel() {
    const _pt = PerfMonitor.enabled ? Date.now() : 0; // 🔬
    const t = (plannedTitle || "").trim();
    if (!t) {
      Alert.alert("알림", "제목은 필수입니다.");
      return;
    }
    
    setIsLoading(true);
    try {
      // 본 목록과 예정 목록 모두에서 중복 체크
      const dupMain = await first("SELECT id FROM novels WHERE title=?", [t]);
      const dupPlanned = await first("SELECT id FROM planned_novels WHERE title=?", [t]);
      if (dupMain || dupPlanned) {
        setIsLoading(false);
        Alert.alert("알림", "같은 제목이 이미 있습니다.");
        return;
      }
      
      const id = uuid();
      const now = Date.now();
      
      await exec(
        `INSERT INTO planned_novels (id,title,author,tags,platforms,note,total_episodes,cover_image,link,work_status,major_genre,sub_genre,priority,created_at,expected_rating,expected_tier,interest_level,discovery_source,first_chapter_read,scheduled_start_date,similar_novels,why_interested,tag_data,start_year,end_year)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);`,
        [
          id,
          t,
          plannedAuthor.trim(),
          plannedTags.trim(),
          JSON.stringify(plannedPlatforms),
          plannedNote.trim(),
          Number(plannedTotalEpisodes) || 0,
          plannedCoverImage,
          plannedLink.trim(),
          plannedWorkStatus,
          plannedMajorGenre.length > 0 ? JSON.stringify(plannedMajorGenre) : "",
          plannedSubGenre.length > 0 ? JSON.stringify(plannedSubGenre) : "",
          plannedPriority,
          now,
          // 🆕 v3.4: 새 필드들
          Number(plannedExpectedRating) || 1500,
          plannedExpectedTier || "",
          plannedInterestLevel,
          plannedDiscoverySource.trim(),
          plannedFirstChapterRead ? 1 : 0,
          (() => {
            if (!plannedScheduledStart) return 0;
            try {
              const ts = new Date(plannedScheduledStart).getTime();
              return isNaN(ts) ? 0 : ts;
            } catch { return 0; }
          })(),
          plannedSimilarNovels.length > 0 ? JSON.stringify(plannedSimilarNovels) : "",
          plannedWhyInterested.trim(),
          "", // 🔧 v3.9.2: tag_data 누락 수정 (UPDATE에는 있으나 INSERT에 빠져있었음)
          Number(plannedStartYear) || 0, // 🔧 v7.6.0 (포트 v3.12.3)
          Number(plannedEndYear) || 0,
        ]
      );

      // 🔧 v3.5.9: 텍스트 입력 태그 → customTags 동기화 (태그 관리 모달 연동)
      syncTagsToCustom(plannedTags.trim());
      
      // 폼 초기화
      setPlannedTitle("");
      setPlannedAuthor("");
      setPlannedTags("");
      setPlannedNote("");
      setPlannedTotalEpisodes("");
      setPlannedPlatforms([]);
      setPlannedCoverImage("");
      setPlannedLink("");
      setPlannedWorkStatus("ongoing");
      setPlannedStartYear(0); // 🔧 v7.6.0 (포트 v3.12.3)
      setPlannedEndYear(0);
      setPlannedMajorGenre([]);
      setPlannedSubGenre([]);
      setPlannedPriority(3);
      // 🆕 v3.4: 새 필드 초기화
      setPlannedExpectedRating("1500");
      setPlannedExpectedTier("");
      setPlannedInterestLevel(3);
      setPlannedDiscoverySource("");
      setPlannedFirstChapterRead(false);
      setPlannedScheduledStart("");
      setPlannedSimilarNovels([]);
      setPlannedWhyInterested("");
      
      await loadPlannedList();
      
      // 🖼️ v3.4.5: 표지가 있으면 라이브러리 상태 업데이트
      if (plannedCoverImage) {
        await updateCoverStatus(plannedCoverImage, id, "used");
        await loadCoverLibrary();
      }
      
      if (_pt) PerfMonitor.trackFunc("addPlannedNovel", Date.now() - _pt); // 🔬
      Alert.alert("완료", "예정 작품이 추가되었습니다.");
    } catch (e) {
      if (_pt) PerfMonitor.logError("addPlannedNovel", e); // 🔬
      console.warn("addPlannedNovel 오류:", e);
      Alert.alert("오류", "예정 작품 추가 중 오류가 발생했습니다.\n\n" + e.message);
    }
    setIsLoading(false);
  }
  
  async function removePlannedNovel(id) {
    Alert.alert("확인", "이 예정 작품을 삭제할까요?", [
      { text: "취소" },
      {
        text: "삭제",
        style: "destructive",
        onPress: async () => {
          // 🖼️ v3.4.5: 삭제 전에 표지 확인
          const planned = await first("SELECT cover_image FROM planned_novels WHERE id=?", [id]);
          const coverPath = planned?.cover_image;
          
          await exec("DELETE FROM planned_novels WHERE id=?", [id]);
          
          // 🖼️ v3.4.5: 표지가 있었으면 미사용으로 변경
          if (coverPath) {
            await updateCoverStatus(coverPath, null, "unused");
            await loadCoverLibrary();
          }
          
          await loadPlannedList();
        },
      },
    ]);
  }
  
  async function savePlannedEdit() {
    const _pt = PerfMonitor.enabled ? Date.now() : 0; // 🔬
    // 🔧 v3.5.8: plannedEditItemRef에서 읽어 React 배칭 지연과 무관하게 최신값 사용
    const n = plannedEditItemRef.current;
    if (!n) return;
    if (isLoading) return; // 🔧 중복 제출 가드 (saveEdit과 동일 — 중복 UPDATE/부수효과 방지)

    const newTitle = (n.title || "").trim();
    if (!newTitle) {
      Alert.alert("알림", "제목은 비울 수 없습니다.");
      return;
    }
    
    setIsLoading(true);
    try {
      // 중복 체크 (자기 자신 제외)
      const dupMain = await first("SELECT id FROM novels WHERE title=?", [newTitle]);
      const dupPlanned = await first("SELECT id FROM planned_novels WHERE title=? AND id<>?", [newTitle, n.id]);
      if (dupMain || dupPlanned) {
        setIsLoading(false);
        Alert.alert("알림", "이미 존재하는 제목입니다.");
        return;
      }
      
      // 🖼️ v3.4.5: 표지 변경 시 라이브러리 상태 업데이트
      const originalPlanned = await first("SELECT cover_image FROM planned_novels WHERE id=?", [n.id]);
      const oldCover = originalPlanned?.cover_image || "";
      const newCover = n.cover_image || "";
      
      // 🆕 v7.2.0: aliases/memorable_quote 새 편집 필드 포함 (awards는 read-only — 편집 X)
      await exec(
        `UPDATE planned_novels SET title=?, author=?, tags=?, platforms=?, note=?, total_episodes=?, cover_image=?, link=?, work_status=?, major_genre=?, sub_genre=?, priority=?, expected_rating=?, expected_tier=?, interest_level=?, discovery_source=?, first_chapter_read=?, scheduled_start_date=?, similar_novels=?, why_interested=?, tag_data=?, aliases=?, memorable_quote=?, start_year=?, end_year=? WHERE id=?;`,
        [
          newTitle,
          n.author?.trim() || "",
          n.tags?.trim() || "",
          n.platforms || "[]",
          n.note?.trim() || "",
          Number(n.total_episodes) || 0,
          newCover,
          n.link?.trim() || "",
          n.work_status || "ongoing",
          n.major_genre || "",
          n.sub_genre || "",
          Number(n.priority) || 3,
          // 🆕 v3.4: 새 필드들
          Number(n.expected_rating) || 1500,
          n.expected_tier || "",
          Number(n.interest_level) || 3,
          n.discovery_source || "",
          n.first_chapter_read ? 1 : 0,
          n.scheduled_start_date || 0,
          n.similar_novels || "",
          n.why_interested || "",
          n.tag_data || "", // 🔧 v3.5.9: tag_data 저장 누락 수정
          n.aliases || "",                  // 🆕 v7.2.0
          n.memorable_quote || "",          // 🆕 v7.2.0
          Number(n.start_year) || 0,        // 🔧 v7.6.0 (포트 v3.12.3)
          Number(n.end_year) || 0,          // 🔧 v7.6.0 (포트 v3.12.3)
          n.id,
        ]
      );
      
      // 🖼️ v3.4.5: 표지 변경 시 라이브러리 상태 업데이트
      if (oldCover !== newCover) {
        if (oldCover) {
          await updateCoverStatus(oldCover, null, "unused");
        }
        if (newCover) {
          await updateCoverStatus(newCover, n.id, "used");
        }
        await loadCoverLibrary();
      }
      
      syncTagsToCustom(n.tags?.trim() || ""); // 🔧 v3.5.9: 태그 동기화
      // 💬 v7.6.2: 편집 중 삭제된 명대사 이미지 파일 정리 (저장 성공 후에만 — 본작 saveEdit과 동일)
      if (removedQuoteImagesRef.current.length > 0) {
        for (const uri of removedQuoteImagesRef.current) {
          if (uri && uri === appSettings.quoteDefaultStyle?.bgImage) continue; // 🔧 v7.14.0 (P0): 공유 프리셋 배경 파일 보존
          FileSystem.deleteAsync(uri, { idempotent: true }).catch(() => {});
        }
        removedQuoteImagesRef.current = [];
      }
      editNewQuoteImagesRef.current = []; // 저장 성공 → 새 이미지 추적 해제 (파일 유지)
      if (_pt) PerfMonitor.trackFunc("savePlannedEdit", Date.now() - _pt); // 🔬
      setPlannedEditOpen(false);
      updatePlannedEditItem(null);
      await loadPlannedList();
    } catch (e) {
      if (_pt) PerfMonitor.logError("savePlannedEdit", e); // 🔬
      console.warn("savePlannedEdit 오류:", e);
      Alert.alert("오류", "저장 중 오류가 발생했습니다.\n\n" + e.message);
    }
    setIsLoading(false);
  }
  
  // 💬 v7.6.2: 예정 편집 취소/닫기 — 저장 없이 추가한 명대사 이미지 정리 (디스크 누수 방지).
  //   convert는 모달 밖(카드/일괄편집)에서 트리거되므로 이 경로로 전환된 이미지가 삭제될 일 없음.
  function cancelPlannedEdit() {
    if (editNewQuoteImagesRef.current.length > 0) {
      for (const uri of editNewQuoteImagesRef.current) {
        FileSystem.deleteAsync(uri, { idempotent: true }).catch(() => {});
      }
      editNewQuoteImagesRef.current = [];
    }
    removedQuoteImagesRef.current = []; // 취소 시 삭제 목록 폐기 (기존 이미지 보존)
    setPlannedEditOpen(false);
    updatePlannedEditItem(null);
  }

  // 예정 → 본 목록으로 등록 전환
  // 🆕 v7.3.0: 핵심 로직 분리 — silent (Alert X) 호출 가능. batch에서 재사용.
  // 반환: { ok: true, id, noteAdditions } 또는 { ok: false, reason: "duplicate_title"|"error", message }
  async function _doConvertPlannedToNovel(planned) {
    if (!planned || !planned.title) return { ok: false, reason: "no_input" };
    try {
      // 본 목록 중복 체크
      const dupInMain = await first("SELECT id FROM novels WHERE title=?", [planned.title]);
      if (dupInMain) return { ok: false, reason: "duplicate_title", message: planned.title };

      // 🆕 v7.2.0: id 보존 — round-trip 시 matches/gallery/folders/tier_* 자동 살아남음.
      // planned.id가 이미 novels에 있으면 (희박 — 부분 실패 잔재) 신규 uuid fallback.
      let id = planned.id || uuid();
      if (planned.id) {
        try {
          const idCollision = await first("SELECT 1 FROM novels WHERE id=?", [planned.id]);
          if (idCollision) {
            console.warn("[v7.3.0] planned.id 충돌 → 신규 uuid fallback:", planned.id);
            id = uuid();
          }
        } catch (e) {
          console.warn("[v7.3.0] id 충돌 체크 실패 (계속 진행):", e?.message);
        }
      }
      const now = Date.now();

      // 예정작품 정보를 메모에 병합
      let enhancedNote = planned.note || "";
      const noteAdditions = [];
      if (planned.why_interested) noteAdditions.push(`[관심 이유] ${planned.why_interested}`);
      if (planned.discovery_source) noteAdditions.push(`[발견 경로] ${planned.discovery_source}`);
      if (planned.expected_tier) noteAdditions.push(`[예상 티어] ${planned.expected_tier}`);
      if (planned.interest_level && planned.interest_level !== 3) {
        noteAdditions.push(`[등록 전 관심도] ${"★".repeat(planned.interest_level)}${"☆".repeat(5 - planned.interest_level)}`);
      }
      if (planned.scheduled_start_date && planned.scheduled_start_date > 0) {
        try {
          const dateStr = new Date(planned.scheduled_start_date).toLocaleDateString();
          noteAdditions.push(`[읽기 예정일] ${dateStr}`);
        } catch {}
      }
      if (planned.similar_novels) {
        try {
          const similarIds = JSON.parse(planned.similar_novels);
          if (Array.isArray(similarIds) && similarIds.length > 0) {
            const similarTitles = similarIds.map(sid => listMap.get(sid)?.title).filter(Boolean);
            if (similarTitles.length > 0) noteAdditions.push(`[비슷한 작품] ${similarTitles.join(", ")}`);
          }
        } catch {}
      }
      if (noteAdditions.length > 0) {
        enhancedNote = enhancedNote
          ? `${enhancedNote}\n\n--- 예정작품 정보 ---\n${noteAdditions.join("\n")}`
          : `--- 예정작품 정보 ---\n${noteAdditions.join("\n")}`;
      }

      const initialReadCount = planned.first_chapter_read ? 1 : 0;
      const shouldPin = (planned.priority || 3) >= 4 ? 1 : 0;

      // 🆕 v7.0.12: hybrid invariant gap=100 보존
      const initialManualTier =
        (globalTierConfig.mode !== "match" && planned.expected_tier && getActiveTierOrder(globalTierConfig).includes(planned.expected_tier))
          ? planned.expected_tier : null;
      let initialManualOrder = 0;
      try {
        if (initialManualTier) {
          const maxRow = await first("SELECT MAX(manual_order) AS m FROM novels WHERE manual_tier=?", [initialManualTier]);
          initialManualOrder = (Number(maxRow?.m) || 0) + 100;
        } else {
          const maxRow = await first("SELECT MAX(manual_order) AS m FROM novels WHERE manual_tier IS NULL OR manual_tier=''");
          initialManualOrder = (Number(maxRow?.m) || 0) + 100;
        }
      } catch (e) {
        console.warn("[v7.3.0] convertPlannedToNovel manual_order 계산 실패:", e?.message);
      }

      // 🆕 v7.2.0: hardcoded → planned 값 우선 (round-trip 데이터 보존)
      // 🆕 v7.3.1: INSERT + UPDATE baseline + DELETE planned을 단일 트랜잭션으로 묶어
      // 부분 실패 시 ROLLBACK (양 테이블 잔존 회피)
      const _baselineToRestore = Number(planned.read_count_baseline) || (Number(planned.read_count) || initialReadCount);
      await execBatch([
        {
          sql: `INSERT INTO novels (id,title,author,tags,platforms,note,read_count,rating,rd,wins,losses,match_count,tier,created_at,awards,total_episodes,status,pinned,cover_image,link,work_status,read_count_updated_at,major_genre,sub_genre,gaiden_status,gaiden_read_count,gaiden_total_episodes,reread_count,tag_data,memorable_quote,aliases,manual_tier,manual_order,start_year,end_year)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);`,
          params: [
            id,
            planned.title,
            planned.author || "",
            planned.tags || "",
            planned.platforms || "[]",
            enhancedNote,
            Number(planned.read_count) || initialReadCount,
            Number(planned.rating) || 1500,
            Number(planned.rd) || 350,
            Number(planned.wins) || 0,
            Number(planned.losses) || 0,
            Number(planned.match_count) || 0,
            globalTierConfig.defaultTier || "C",
            now,
            planned.awards || "",
            Number(planned.total_episodes) || 0,
            planned.status || "reading",
            Number(planned.pinned) || shouldPin,
            planned.cover_image || "",
            planned.link || "",
            planned.work_status || "ongoing",
            Number(planned.read_count_updated_at) || now,
            planned.major_genre || "",
            planned.sub_genre || "",
            planned.gaiden_status || "none",
            Number(planned.gaiden_read_count) || 0,
            Number(planned.gaiden_total_episodes) || 0,
            Math.max(1, Number(planned.reread_count) || 1),
            planned.tag_data || "",
            planned.memorable_quote || "",
            planned.aliases || "",
            planned.manual_tier || initialManualTier,
            initialManualOrder,
            // 🔧 v7.6.0: 예정→본작 전환 시 연재 연도 round-trip 보존
            Number(planned.start_year) || 0,
            Number(planned.end_year) || 0,
          ],
        },
        {
          sql: "UPDATE novels SET read_count_baseline=? WHERE id=?",
          params: [_baselineToRestore, id],
        },
        {
          sql: "DELETE FROM planned_novels WHERE id=?",
          params: [planned.id],
        },
      ]);
      syncTagsToCustom(planned.tags || "");

      // 표지 라이브러리 동기화
      if (planned.cover_image) {
        try { await applyNovelCover(id, planned.cover_image, null); } catch {}
      }

      // 📰 최신 변화 기록
      let majorGenreText = "-";
      if (planned.major_genre) {
        try {
          const genres = JSON.parse(planned.major_genre);
          if (Array.isArray(genres)) majorGenreText = genres.join(", ");
        } catch {}
      }
      try {
        await addRecentChange(id, planned.title, "new", {
          author: planned.author || "-",
          majorGenre: majorGenreText,
          fromPlanned: true,
        });
      } catch {}

      return { ok: true, id, noteAdditions };
    } catch (e) {
      console.warn("[v7.3.0] _doConvertPlannedToNovel 오류:", e?.message);
      return { ok: false, reason: "error", message: e?.message || "알 수 없는 오류" };
    }
  }

  // 🆕 v7.3.0: silent 호출 가능 (Alert X, 일괄 batch에서 재사용)
  async function convertPlannedToNovelSilent(planned) {
    // 🆕 v7.3.0: 자동매칭 가드 (caller에서 사전 체크 권장 — 여기서는 방어적으로 한 번 더)
    if (isAutoMatchingRef.current) return { ok: false, reason: "auto_matching" };
    return await _doConvertPlannedToNovel(planned);
  }

  async function convertPlannedToNovel(planned) {
    // 🆕 v7.3.0: 자동매칭 중 차단 (Alert로 사용자에게 안내, button-level 가드)
    if (isAutoMatchingRef.current) {
      Alert.alert("자동매칭 중", "자동매칭이 진행 중입니다.\n매칭을 멈춘 후 다시 시도하세요.");
      return;
    }
    Alert.alert(
      "등록 전환",
      `"${planned.title}"을(를) 본 목록으로 등록할까요?\n\n예정 목록의 모든 정보가 이전됩니다.`,
      [
        { text: "취소" },
        {
          text: "등록 전환",
          onPress: async () => {
            setIsLoading(true);
            try {
              const r = await _doConvertPlannedToNovel(planned);
              if (r.ok) {
                await loadPlannedList();
                await loadList(undefined, undefined, "supplement");
                if (planned.cover_image) await loadCoverLibrary();
                const infoMsg = (r.noteAdditions && r.noteAdditions.length > 0)
                  ? `\n\n예정작품 정보(${r.noteAdditions.length}건)가 메모에 추가되었습니다.`
                  : "";
                Alert.alert("완료", `"${planned.title}"이(가) 본 목록에 등록되었습니다.${infoMsg}`);
              } else if (r.reason === "duplicate_title") {
                Alert.alert("중복 알림", `"${r.message}"이(가) 본 목록에 이미 있습니다.\n\n제목을 변경한 후 다시 시도하세요.`);
              } else {
                Alert.alert("오류", `등록 전환 중 오류가 발생했습니다.\n\n${r.message || ""}`);
              }
            } finally {
              setIsLoading(false);
            }
          },
        },
      ]
    );
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 🆕 v7.3.0: 가등록 일괄편집 sub-tab — 6종 batch 함수
  // selectedIds 대신 plannedSelectedIdsRef 사용 (메인 bulk와 분리)
  // 자동매칭 가드 + setLoadingProgress + skip 카운트 패턴 일관 적용
  // ═══════════════════════════════════════════════════════════════════════════

  const togglePlannedSelected = useCallback((id) => {
    setPlannedSelectedIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  }, []);

  // 🆕 v7.3.0: 가등록 → 진등록 일괄 전환 (대칭 op)
  const batchConvertPlannedToNovels = useCallback(async () => {
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    if (isAutoMatchingRef.current) {
      Alert.alert("자동매칭 중", "자동매칭이 진행 중입니다.\n매칭을 멈춘 후 다시 시도하세요.");
      return;
    }
    Alert.alert(
      "일괄 진등록 전환",
      `선택 ${ids.length}개 가등록 작품을 진등록으로 전환할까요?\n\n title 충돌 시 해당 작품만 skip됩니다.`,
      [
        { text: "취소" },
        {
          text: "전환",
          onPress: async () => {
            setIsLoading(true);
            setLoadingProgress({ current: 0, total: ids.length, label: "진등록 전환 중..." });
            let success = 0, skipped = 0;
            try {
              for (let i = 0; i < ids.length; i++) {
                const planned = plannedList.find(p => p.id === ids[i]);
                if (!planned) { skipped++; continue; }
                const r = await convertPlannedToNovelSilent(planned);
                if (r && r.ok) success++; else skipped++;
                setLoadingProgress({ current: i + 1, total: ids.length, label: "진등록 전환 중..." });
              }
              await loadPlannedList();
              await loadList(undefined, undefined, "batch_promote");
              await loadCoverLibrary();
              setPlannedSelectedIds([]);
            } finally {
              setLoadingProgress(null);
              setIsLoading(false);
            }
            Alert.alert("완료", `진등록 전환 ${success}건${skipped > 0 ? ` · skip ${skipped}건 (title 충돌 등)` : ""}`);
          },
        },
      ]
    );
  }, [plannedList]);

  // 🆕 v7.3.0: 가등록 일괄 삭제
  const batchDeletePlanned = useCallback(async () => {
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    Alert.alert(
      "일괄 삭제",
      `선택 ${ids.length}개 가등록 작품을 삭제할까요?\n\n작품 round-trip 데이터(awards/quote/gallery)도 함께 삭제됩니다.`,
      [
        { text: "취소" },
        {
          text: "삭제",
          style: "destructive",
          onPress: async () => {
            setIsLoading(true);
            setLoadingProgress({ current: 0, total: ids.length, label: "삭제 중..." });
            try {
              const placeholders = ids.map(() => "?").join(",");
              // 🆕 v7.3.0: 표지 라이브러리 정리 (used → unused)
              try {
                const planned = await all(`SELECT id, cover_image FROM planned_novels WHERE id IN (${placeholders})`, ids);
                for (const p of (planned || [])) {
                  if (p.cover_image) {
                    await updateCoverStatus(p.cover_image, null, "unused").catch(() => {});
                  }
                }
              } catch (e) { console.warn("[v7.3.0] 가등록 일괄 표지 정리 실패:", e?.message); }

              // 🛠️ v7.3.4: 갤러리 이미지 파일 시스템 cleanup 추가 (이전: DB row만 삭제 → GALLERY_DIR 파일 누수)
              try {
                const gImgs = await all(
                  `SELECT file_path FROM gallery_images WHERE novel_id IN (${placeholders})`,
                  ids
                );
                for (const g of (gImgs || [])) {
                  await deleteCoverFromLibrary(g.file_path).catch(() => {});
                }
              } catch (gErr) { console.warn("[v7.3.4] batchDeletePlanned gallery file cleanup:", gErr?.message); }

              // 갤러리 이미지(round-trip 보존) DB row 정리
              try {
                await exec(`DELETE FROM gallery_images WHERE novel_id IN (${placeholders})`, ids);
              } catch (e) { console.warn("[v7.3.0] gallery_images 정리 실패:", e?.message); }

              // 🛠️ v7.3.4: memorable_quote 이미지 파일 cleanup 추가 (removeNovel/batchDelete와 동일 패턴)
              try {
                const qPlanned = await all(
                  `SELECT memorable_quote FROM planned_novels WHERE id IN (${placeholders}) AND memorable_quote IS NOT NULL AND memorable_quote != ''`,
                  ids
                );
                for (const p of (qPlanned || [])) {
                  try {
                    const quotes = parseQuotes(p.memorable_quote);
                    for (const q of quotes) {
                      if (isImageQuote(q) && q.uri) {
                        FileSystem.deleteAsync(q.uri, { idempotent: true }).catch(() => {});
                      }
                      const _st = getQuoteStyle(q); // 🆕 v7.8.0: 텍스트 서식 배경이미지도 정리
                      if (_st && _st.bgImage) FileSystem.deleteAsync(_st.bgImage, { idempotent: true }).catch(() => {});
                    }
                  } catch {}
                }
              } catch (qErr) { console.warn("[v7.3.4] batchDeletePlanned quote image cleanup:", qErr?.message); }

              await exec(`DELETE FROM planned_novels WHERE id IN (${placeholders})`, ids);
              await loadPlannedList();
              await loadCoverLibrary();
              setPlannedSelectedIds([]);
            } finally {
              setLoadingProgress(null);
              setIsLoading(false);
            }
            Alert.alert("완료", `${ids.length}개 가등록 삭제됨.`);
          },
        },
      ]
    );
  }, [plannedList]);

  // 🆕 v7.3.0: 일괄 태그 추가 — tag_data intensity 함께 (메인 batchAddTag 패턴)
  // 🛠️ v7.3.2: catch 추가 — 루프 중 SQL 오류 시 부분 진행 상태에서 사용자 안내
  const batchAddPlannedTag = useCallback(async () => {
    const tag = (plannedBulkTagInput || "").trim();
    if (!tag) { Alert.alert("알림", "추가할 태그를 입력하세요."); return; }
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    setIsLoading(true);
    setLoadingProgress({ current: 0, total: ids.length, label: "태그 추가 중..." });
    let successCount = 0;
    let failed = false;
    try {
      for (let i = 0; i < ids.length; i++) {
        const id = ids[i];
        const p = plannedList.find(x => x.id === id);
        if (!p) continue;
        // tags (CSV) — 중복 회피
        const existingTags = (p.tags || "").split(",").map(t => t.trim()).filter(Boolean);
        if (!existingTags.includes(tag)) existingTags.push(tag);
        const newTags = existingTags.join(", ");
        // tag_data — intensity 추가/갱신
        let td = [];
        try { td = JSON.parse(p.tag_data || "[]"); if (!Array.isArray(td)) td = []; } catch {}
        const existingIdx = td.findIndex(x => x.tag === tag);
        if (existingIdx >= 0) td[existingIdx].intensity = plannedBulkTagIntensity;
        else td.push({ tag, intensity: plannedBulkTagIntensity });
        await exec("UPDATE planned_novels SET tags=?, tag_data=? WHERE id=?", [newTags, JSON.stringify(td), id]);
        successCount++;
        setLoadingProgress({ current: i + 1, total: ids.length, label: "태그 추가 중..." });
      }
      syncTagsToCustom(tag);
      await loadPlannedList();
    } catch (e) {
      failed = true;
      console.warn("[v7.3.2] batchAddPlannedTag 오류:", e?.message);
      try { await loadPlannedList(); } catch {}
      Alert.alert("부분 실패", `태그 일괄 추가 중 오류 (${successCount}/${ids.length}건 성공): ${e?.message || "알 수 없는 오류"}`);
    } finally {
      setLoadingProgress(null);
      setIsLoading(false);
    }
    if (!failed) {
      Alert.alert("완료", `${ids.length}개 가등록에 "${tag}" 태그 추가됨 (intensity ${plannedBulkTagIntensity}).`);
    }
  }, [plannedList, plannedBulkTagInput, plannedBulkTagIntensity]);

  // 🆕 v7.3.0: 일괄 태그 삭제
  // 🛠️ v7.3.2: catch 추가 — 루프 중 SQL 오류 시 부분 진행 상태에서 사용자 안내
  const batchRemovePlannedTag = useCallback(async () => {
    const tag = (plannedBulkTagInput || "").trim();
    if (!tag) { Alert.alert("알림", "삭제할 태그를 입력하세요."); return; }
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    setIsLoading(true);
    setLoadingProgress({ current: 0, total: ids.length, label: "태그 삭제 중..." });
    let successCount = 0;
    let failed = false;
    try {
      for (let i = 0; i < ids.length; i++) {
        const id = ids[i];
        const p = plannedList.find(x => x.id === id);
        if (!p) continue;
        const remaining = (p.tags || "").split(",").map(t => t.trim()).filter(t => t && t !== tag);
        const newTags = remaining.join(", ");
        let td = [];
        try { td = JSON.parse(p.tag_data || "[]"); if (!Array.isArray(td)) td = []; } catch {}
        td = td.filter(x => x.tag !== tag);
        await exec("UPDATE planned_novels SET tags=?, tag_data=? WHERE id=?", [newTags, JSON.stringify(td), id]);
        successCount++;
        setLoadingProgress({ current: i + 1, total: ids.length, label: "태그 삭제 중..." });
      }
      await loadPlannedList();
    } catch (e) {
      failed = true;
      console.warn("[v7.3.2] batchRemovePlannedTag 오류:", e?.message);
      try { await loadPlannedList(); } catch {}
      Alert.alert("부분 실패", `태그 일괄 삭제 중 오류 (${successCount}/${ids.length}건 성공): ${e?.message || "알 수 없는 오류"}`);
    } finally {
      setLoadingProgress(null);
      setIsLoading(false);
    }
    if (!failed) {
      Alert.alert("완료", `${ids.length}개 가등록에서 "${tag}" 태그 삭제됨.`);
    }
  }, [plannedList, plannedBulkTagInput]);

  // 🆕 v7.3.0: 일괄 플랫폼 설정 (선택된 플랫폼으로 통일)
  // 🛠️ v7.3.2: 최상위 try/catch 추가 — onPress(()=>batch...)로 await 미적용 호출되어 SQL 오류 시 unhandled rejection
  const batchSetPlannedPlatforms = useCallback(async (newPlatforms) => {
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    try {
      const placeholders = ids.map(() => "?").join(",");
      await exec(
        `UPDATE planned_novels SET platforms=? WHERE id IN (${placeholders})`,
        [JSON.stringify(newPlatforms || []), ...ids]
      );
      await loadPlannedList();
      Alert.alert("완료", `${ids.length}개 가등록 플랫폼 설정됨.`);
    } catch (e) {
      console.warn("[v7.3.2] batchSetPlannedPlatforms 오류:", e?.message);
      Alert.alert("오류", "플랫폼 일괄 설정에 실패했습니다: " + (e?.message || "알 수 없는 오류"));
    }
  }, []);

  // 🆕 v7.3.0: 일괄 우선순위 변경
  // 🛠️ v7.3.2: 최상위 try/catch 추가
  const batchSetPlannedPriority = useCallback(async (priority) => {
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    const p = Math.max(1, Math.min(5, Number(priority) || 3));
    try {
      const placeholders = ids.map(() => "?").join(",");
      await exec(
        `UPDATE planned_novels SET priority=? WHERE id IN (${placeholders})`,
        [p, ...ids]
      );
      await loadPlannedList();
      Alert.alert("완료", `${ids.length}개 가등록 우선순위 ${p}로 설정됨.`);
    } catch (e) {
      console.warn("[v7.3.2] batchSetPlannedPriority 오류:", e?.message);
      Alert.alert("오류", "우선순위 일괄 변경에 실패했습니다: " + (e?.message || "알 수 없는 오류"));
    }
  }, []);

  // 🆕 v7.3.0: 일괄 작품상태 변경
  // 🛠️ v7.3.2: 최상위 try/catch 추가
  const batchSetPlannedWorkStatus = useCallback(async (status) => {
    const ids = plannedSelectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 가등록 작품을 선택해주세요.");
      return;
    }
    try {
      const placeholders = ids.map(() => "?").join(",");
      await exec(
        `UPDATE planned_novels SET work_status=? WHERE id IN (${placeholders})`,
        [status || "ongoing", ...ids]
      );
      await loadPlannedList();
      Alert.alert("완료", `${ids.length}개 가등록 작품상태 변경됨.`);
    } catch (e) {
      console.warn("[v7.3.2] batchSetPlannedWorkStatus 오류:", e?.message);
      Alert.alert("오류", "작품상태 일괄 변경에 실패했습니다: " + (e?.message || "알 수 없는 오류"));
    }
  }, []);

  // 🆕 v7.2.0: novels → planned_novels 역전환 (단건)
  // - id 보존: matches/gallery/folders/tier_verification_queue/v7.0 row 자동 살아남음
  // - title 충돌 시 abort (silent=true 시 Alert skip — 일괄 호출용)
  // - in-flight verification 세션 abort + pending 큐 cancel
  // - recent_changes 로그
  // - return: true/false (성공 여부) — caller가 후처리(loadList/loadPlannedList) 결정
  async function convertNovelToPlanned(novel, opts = {}) {
    const silent = !!opts.silent;
    if (!novel || !novel.id) return false;

    // 🆕 v7.3.0: 자동매칭 중 차단 (#1 불변조건 strict — Alert X)
    if (isAutoMatchingRef.current) {
      console.warn("[v7.3.0] convertNovelToPlanned: 자동매칭 중 — silent abort", novel.id);
      return false;
    }

    // 1. title 충돌 체크 (자기 자신 제외 — id 동일하면 OK)
    try {
      const dup = await first(
        "SELECT id FROM planned_novels WHERE title=? AND id!=?",
        [novel.title, novel.id]
      );
      if (dup) {
        if (!silent) Alert.alert("전환 불가", `"${novel.title}"이(가) 이미 가등록 목록에 있습니다.\n제목을 변경 후 다시 시도하세요.`);
        return false;
      }
    } catch (e) {
      console.warn("[v7.2.0] convertNovelToPlanned 중복 체크 실패:", e?.message);
    }

    // 1-b. id 충돌 체크 (희박 — 부분 실패 잔재로 planned에 같은 id 존재 가능)
    // 충돌 시 partial 상태로 판단, INSERT skip하고 DELETE FROM novels로 정리만 수행
    try {
      const idDup = await first("SELECT 1 FROM planned_novels WHERE id=?", [novel.id]);
      if (idDup) {
        console.warn("[v7.2.0] novel.id가 planned_novels에 이미 존재 (partial state) → INSERT skip + DELETE 정리만:", novel.id);
        try {
          await exec("DELETE FROM novels WHERE id=?", [novel.id]);
        } catch (delErr) {
          console.warn("[v7.2.0] DELETE FROM novels 실패:", delErr?.message);
          if (!silent) Alert.alert("전환 실패", "데이터 정리 중 오류");
          return false;
        }
        return true;
      }
    } catch (e) {
      console.warn("[v7.2.0] id 충돌 체크 실패 (계속 진행):", e?.message);
    }

    const now = Date.now();
    try {
      // 🆕 v7.3.1: INSERT planned + verification queue cancel + DELETE novels을 단일 트랜잭션으로
      // 부분 실패 시 ROLLBACK (양 테이블 잔존 회피)
      await execBatch([
        {
          sql: `INSERT INTO planned_novels (
            id, title, author, tags, platforms, note,
            total_episodes, cover_image, link, work_status,
            major_genre, sub_genre, priority, created_at,
            expected_rating, expected_tier, interest_level,
            discovery_source, first_chapter_read, scheduled_start_date,
            similar_novels, why_interested, tag_data,
            status, pinned, read_count, rating, rd, wins, losses, match_count,
            gaiden_status, gaiden_read_count, gaiden_total_episodes,
            manual_tier, manual_order, reread_count,
            aliases, memorable_quote, awards,
            read_count_updated_at, read_count_baseline,
            start_year, end_year
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          params: [
            novel.id, novel.title, novel.author || "",
            novel.tags || "", novel.platforms || "[]", novel.note || "",
            Number(novel.total_episodes) || 0, novel.cover_image || "",
            novel.link || "", novel.work_status || "ongoing",
            novel.major_genre || "", novel.sub_genre || "",
            // priority: pinned=1 → 5(최고), 그 외 → 3(기본)
            novel.pinned ? 5 : 3, novel.created_at || now,
            // expected_*: 현 ELO/manual_tier 보존을 위한 best-effort 매핑
            Number(novel.rating) || 1500, novel.manual_tier || "", 3,
            "", novel.read_count > 0 ? 1 : 0, 0, "", "", novel.tag_data || "",
            // 🆕 v7.2.0 round-trip 보존 필드 (16종)
            novel.status || "reading", Number(novel.pinned) || 0,
            Number(novel.read_count) || 0,
            Number(novel.rating) || 1500, Number(novel.rd) || 350,
            Number(novel.wins) || 0, Number(novel.losses) || 0,
            Number(novel.match_count) || 0,
            novel.gaiden_status || "none",
            Number(novel.gaiden_read_count) || 0,
            Number(novel.gaiden_total_episodes) || 0,
            novel.manual_tier || null, Number(novel.manual_order) || 0,
            Math.max(1, Number(novel.reread_count) || 1),
            novel.aliases || "", novel.memorable_quote || "", novel.awards || "",
            Number(novel.read_count_updated_at) || 0,
            Number(novel.read_count_baseline) || 0,
            // 🔧 v7.6.1: novel→planned 강등 시 연재 연도 보존 (누락 → round-trip 손실 수정)
            Number(novel.start_year) || 0,
            Number(novel.end_year) || 0,
          ],
        },
        // pending verification 큐 cancel — 가등록 작품은 verification 의미 없음
        {
          sql: `UPDATE tier_verification_queue SET state='cancelled', processed_at=? WHERE novel_id=? AND state='pending'`,
          params: [now, novel.id],
        },
        // DELETE FROM novels (id 보존이라 matches/gallery/folders 등은 자동 살아남음)
        {
          sql: "DELETE FROM novels WHERE id=?",
          params: [novel.id],
        },
      ]);

      // verification 세션 React state는 트랜잭션 외 (UI state라 DB 트랜잭션과 무관)
      // 🛠️ v7.3.3: candidate 변환도 abort 대상에 추가 (planned 전환 시 후보가 novels에서 사라짐 → stale 참조 방지)
      const _vsConv = verificationSessionRef?.current;
      if (_vsConv && (_vsConv.queueRow?.novel_id === novel.id || _vsConv.candidates?.some(c => c.id === novel.id))) {
        setVerificationSession(null);
        if (verificationSessionIdRef) verificationSessionIdRef.current = null;
      }

      // 5. recent_changes 로그
      try {
        await addRecentChange(novel.id, novel.title, "demote_to_planned", {
          fromTier: novel.manual_tier || novel.tier || "",
        });
      } catch {}

      return true;
    } catch (e) {
      console.warn("[v7.2.0] convertNovelToPlanned 오류:", e?.message);
      if (!silent) Alert.alert("전환 실패", e?.message || "알 수 없는 오류");
      return false;
    }
  }

  // 🆕 v7.2.0: 일괄 가등록 전환 (일괄편집 탭용)
  // — silent=true로 per-item Alert 억제 (배치에서는 결과 요약만 표시)
  // — setLoadingProgress로 진행도 표시 (대용량 batch 대응)
  // — 🆕 v7.3.0: 자동매칭 중 silent abort
  const batchConvertToPlanned = useCallback(async () => {
    const ids = selectedIdsRef.current;
    if (!ids || ids.length === 0) {
      Alert.alert("알림", "먼저 작품을 선택해주세요.");
      return;
    }
    // 🆕 v7.3.0: 자동매칭 중 차단 (Alert는 사용자 액션 직후라 button-level 가드)
    if (isAutoMatchingRef.current) {
      Alert.alert("자동매칭 중", "자동매칭이 진행 중입니다.\n매칭을 멈춘 후 다시 시도하세요.");
      return;
    }
    Alert.alert(
      "가등록 일괄 전환",
      `선택 ${ids.length}작품을 가등록으로 전환할까요?\n\n매칭/갤러리/폴더 등 모든 데이터는 보존됩니다 (id 유지). title 충돌 시 해당 작품만 skip.`,
      [
        { text: "취소" },
        {
          text: "전환",
          style: "destructive",
          onPress: async () => {
            setIsLoading(true);
            setLoadingProgress({ current: 0, total: ids.length, label: "가등록 전환 중..." });
            try {
              let success = 0, skipped = 0;
              for (let i = 0; i < ids.length; i++) {
                const id = ids[i];
                const novel = list.find(n => n.id === id);
                if (!novel) { skipped++; continue; }
                // silent=true — per-item Alert 억제
                const ok = await convertNovelToPlanned(novel, { silent: true });
                if (ok) success++; else skipped++;
                setLoadingProgress({ current: i + 1, total: ids.length, label: "가등록 전환 중..." });
              }
              await loadList(undefined, undefined, "batch_demote");
              await loadPlannedList();
              Alert.alert("완료", `전환 ${success}건${skipped > 0 ? ` · skip ${skipped}건 (title 충돌 등)` : ""}`);
            } finally {
              setLoadingProgress(null);
              setIsLoading(false);
            }
          },
        },
      ]
    );
  }, [list]);

  // -----------------------------------------
  // 🎯 v3.3.0: 오늘의 추천 웹소설 계산
  // - 1일간 유지
  // - 우선순위 (확률 가중치 적용):
  //   1) 읽지 않은 예정작 (가중치 100)
  //   2) 거의 다 읽었고 끝을 남겨둔 작품 (가중치 90)
  //   3) 취향에 맞는데 안 읽고 있는 작품 (가중치 80)
  //   4) 데이터가 비교적 적은 작품, 하차 제외 (가중치 70)
  //   5) 여러 관점에서 취향에 맞을만한 작품 (가중치 60)
  //   6) 티어 높은 덜 읽은 작품 (가중치 50)
  //   7) 기타 작품 (가중치 20)
  //   8) 완결까지 다 읽었는데 다회독 추천 (가중치 30)
  // - 최근 5회 추천 내 재추천 방지
  // -----------------------------------------
  async function refreshDailyRecommendation(forceNew = false) {
    const _pt = PerfMonitor.enabled ? Date.now() : 0; // 🔬
    try {
      const novels = await all("SELECT * FROM novels;");
      const planned = await all("SELECT * FROM planned_novels;");
      
      if ((!novels || novels.length === 0) && (!planned || planned.length === 0)) {
        setDailyReco(null);
        return;
      }

      const now = Date.now();
      const dayMs = 24 * 60 * 60 * 1000;

      // 최근 추천 히스토리 로드
      let history = await getAppMeta("reco_history") || [];
      setRecoHistory(history);
      
      // 5회 이내 추천된 작품 ID 집합
      const recentIds = new Set(history.slice(0, 5).map(h => h.novelId));

      if (!forceNew) {
        const saved = await getAppMeta("daily_reco");
        if (saved && saved.novel_id && saved.picked_at && now - saved.picked_at < dayMs) {
          // 예정작인지 본목록인지 확인
          const existingNovel = novels?.find((n) => n.id === saved.novel_id);
          const existingPlanned = planned?.find((p) => p.id === saved.novel_id);
          
          // 🔧 v7.13.0: 캐시 추천 복원 시 하차 상태 재검증 — 추천 후 dropped된 작품이 24h간 잔존하던 문제
          if (existingNovel && existingNovel.status !== "dropped") {
            setDailyReco({
              novel: existingNovel,
              pickedAt: saved.picked_at,
              reason: saved.reason || "이전 추천",
              category: saved.category || "other",
              isPlanned: false,
              tasteScore: saved.tasteScore || null,
            });
            return;
          } else if (existingPlanned) {
            setDailyReco({
              novel: existingPlanned,
              pickedAt: saved.picked_at,
              reason: saved.reason || "읽고 싶었던 예정작",
              category: saved.category || "planned_unread",
              isPlanned: true,
              tasteScore: saved.tasteScore || null,
            });
            return;
          }
        }
      }

      // 추천 후보 풀 구성 (가중치 기반)
      const candidates = [];
      const totalNovelCount = novels?.length || 0;
      
      // 🧠 v3.5.4: preference_patterns 기반 취향 데이터 로드
      // 🔧 v7.13.0: mode-aware 평균 점수 (raw ELO → getPrefScore). manual/hybrid/ratio에서 rating=1500
      //   고정으로 추천 분류가 죽던 문제 해소.
      const isMatchMode = globalTierConfig.mode === "match";
      const avgScore = totalNovelCount > 0
        ? novels.reduce((sum, n) => sum + getPrefScore(n, globalTierConfig), 0) / totalNovelCount
        : 1500;
      
      // 매칭 학습 데이터에서 취향 맵 구축
      const genreScores = {};   // genre → { winRate, sampleSize, significance }
      const tagScores = {};     // tag → { winRate, sampleSize }
      const authorScores = {};  // author → { winRate, sampleSize }
      let hasPatterns = false;
      
      try {
        const patterns = await all(`
          SELECT category, pattern_key, win_rate, sample_size, significance, confidence_lower, user_confirmed
          FROM preference_patterns 
          WHERE sample_size >= 3
        `);
        if (patterns && patterns.length > 0) {
          hasPatterns = true;
          for (const p of patterns) {
            const key = p.pattern_key;
            const confirmed = (p.user_confirmed || 0) > 0; // 🧠 v3.5.5: 사용자 확인 여부
            if (p.category === "genre_affinity" && key.startsWith("genre:")) {
              genreScores[key.slice(6)] = { winRate: p.win_rate, sampleSize: p.sample_size, significance: p.significance || 0, confirmed };
            } else if (p.category === "tag_power" && key.startsWith("tag:")) {
              tagScores[key.slice(4)] = { winRate: p.win_rate, sampleSize: p.sample_size, confirmed };
            } else if (p.category === "author_loyalty" && key.startsWith("author:")) {
              authorScores[key.slice(7)] = { winRate: p.win_rate, sampleSize: p.sample_size, confirmed };
            }
          }
        }
      } catch (e) {
        console.warn("추천 패턴 로드 실패, 폴백 사용:", e);
      }
      
      // 🔗 v3.5.5: 유사 그룹 태그 승률 합산
      // 같은 그룹의 태그 데이터를 대표 태그로 합산 (가중 평균)
      if (hasPatterns && Object.keys(tagScores).length > 0 && tagRelations?.groups) {
        const processed = new Set();
        for (const tag of Object.keys(tagScores)) {
          const rep = resolveTagToGroup(tag, tagRelations);
          if (rep === tag || processed.has(rep)) continue;
          
          // 그룹 내 모든 태그의 점수 합산
          const groupTags = getGroupTags(rep, tagRelations);
          const groupData = groupTags
            .map(t => tagScores[t])
            .filter(Boolean);
          
          if (groupData.length >= 1) {
            const totalSamples = groupData.reduce((s, d) => s + d.sampleSize, 0);
            const weightedWr = groupData.reduce((s, d) => s + d.winRate * d.sampleSize, 0) / totalSamples;
            const anyConfirmed = groupData.some(d => d.confirmed);
            
            // 대표 태그에 합산 데이터 저장
            tagScores[rep] = { winRate: weightedWr, sampleSize: totalSamples, confirmed: anyConfirmed };
            processed.add(rep);
          }
        }
      }
      
      // 폴백: 패턴 데이터가 부족하면 기존 방식(고티어 기반) 보완
      const highTierNovels = (novels || []).filter(n => (Number(n.rating) || 1500) >= 1700);
      const fallbackGenres = new Set();
      const fallbackTags = new Set();
      for (const fn of highTierNovels) {
        if (fn.major_genre) {
          try { JSON.parse(fn.major_genre).forEach(g => fallbackGenres.add(g)); } catch {}
        }
        if (fn.tags) {
          // 🆕 v3.5.8: 작품명 태그 제외
          fn.tags.split(",").map(t => t.trim()).filter(t => t && !isTagTitle(t, tagAttributes)).forEach(t => fallbackTags.add(t));
        }
      }
      
      /**
       * 🧠 통합 취향 점수 계산 (0~100)
       * preference_patterns 데이터가 있으면 매칭 학습 기반,
       * 없으면 고티어 작품 기반 폴백
       * 🧠 v3.5.5: user_confirmed 보너스, 팩터 칩용 chips[], source 필드 추가
       * @returns {{ score, factors, chips, breakdown: { genre, tag, author }, source }}
       */
      // 🆕 tagAttributes 기반 대장르 통합 (루프 밖에서 1회 계산)
      const allMajorForScore = getAllMajorTags(tagAttributes, userMajorGenres);

      function computeTasteScore(novel) {
        let genreScore = 0, tagScore = 0, authorScore = 0;
        const factors = []; // 추천 이유 텍스트
        const chips = [];   // 🧠 v3.5.5: UI 팩터 칩 [{ label, value, type, confirmed }]
        let source = "fallback"; // "pattern" | "fallback"

        // — 장르 점수 (최대 40점) —
        const novelGenres = [];
        if (novel.major_genre) {
          try {
            const mg = JSON.parse(novel.major_genre);
            if (Array.isArray(mg)) novelGenres.push(...mg);
            else if (typeof mg === "string") novelGenres.push(mg);
          } catch { if (novel.major_genre.trim()) novelGenres.push(novel.major_genre.trim()); }
        }
        // 🆕 tagAttributes 기반 대장르도 추가 (novel.tags에서 isMajor 태그 감지)
        const ntags = (novel.tags || "").split(",").map(t => t.trim()).filter(Boolean);
        for (const t of ntags) {
          if (allMajorForScore.some(m => isSameTag(m, t)) && !novelGenres.some(g => isSameTag(g, t))) {
            novelGenres.push(t);
          }
        }
        
        if (hasPatterns && Object.keys(genreScores).length > 0) {
          source = "pattern";
          for (const g of novelGenres) {
            const gs = genreScores[g];
            if (gs && gs.sampleSize >= 3) {
              // 승률 50% 초과분을 점수화 (70% → +20, 80% → +30)
              let bonus = Math.max(0, (gs.winRate - 0.5) * 100);
              // 🧠 v3.5.5: 사용자 확인 패턴은 +8 보너스
              if (gs.confirmed) bonus = Math.min(40, bonus + 8);
              genreScore = Math.max(genreScore, Math.min(40, bonus));
              if (gs.winRate >= 0.55) {
                const pct = Math.round(gs.winRate * 100);
                factors.push(`${g} 장르 선호도 ${pct}%`);
                chips.push({ label: g, value: `${pct}%`, type: "genre", confirmed: !!gs.confirmed });
              }
            }
          }
        } else {
          // 폴백: 고티어 작품과 장르 일치
          if (novelGenres.some(g => fallbackGenres.has(g))) {
            genreScore = 25;
            const matched = novelGenres.filter(g => fallbackGenres.has(g));
            if (matched.length > 0) chips.push({ label: matched[0], value: "고티어", type: "genre", confirmed: false });
          }
        }
        
        // — 태그 점수 (최대 35점) —
        // 🆕 v3.5.8: 작품명 태그 제외 (검색 편의용 → 분석 교란 방지)
        const novelTags = getAnalysisTags(novel.tags, tagAttributes, hiddenTags);
        
        if (hasPatterns && Object.keys(tagScores).length > 0) {
          source = "pattern";
          const tagHits = [];
          for (const tag of novelTags) {
            // 🔗 v3.5.5: 유사 그룹 대표 태그로 해석하여 합산된 승률 조회
            const resolved = resolveTagToGroup(tag, tagRelations);
            const ts = tagScores[resolved] || tagScores[tag];
            if (ts && ts.sampleSize >= 3 && ts.winRate >= 0.55) {
              // 🧠 v3.5.5: confirmed 태그 승률 보정
              const effectiveWr = ts.confirmed ? Math.min(1, ts.winRate + 0.05) : ts.winRate;
              tagHits.push({ tag, winRate: effectiveWr, confirmed: !!ts.confirmed });
            }
          }
          // 상위 3개 태그 평균
          tagHits.sort((a, b) => b.winRate - a.winRate);
          const topTags = tagHits.slice(0, 3);
          if (topTags.length > 0) {
            const avgWr = topTags.reduce((s, t) => s + t.winRate, 0) / topTags.length;
            tagScore = Math.min(35, Math.max(0, (avgWr - 0.5) * 100) + topTags.length * 5);
            for (const tt of topTags) {
              chips.push({ label: tt.tag, value: `${Math.round(tt.winRate * 100)}%`, type: "tag", confirmed: tt.confirmed });
            }
            if (topTags.length >= 2) {
              factors.push(`선호 태그 ${topTags.length}개 일치 (${topTags.map(t => t.tag).join(", ")})`);
            } else if (topTags.length === 1) {
              factors.push(`'${topTags[0].tag}' 태그 선호 ${Math.round(topTags[0].winRate * 100)}%`);
            }
          }
        } else {
          // 폴백
          const matchCount = novelTags.filter(t => fallbackTags.has(t)).length;
          tagScore = Math.min(25, matchCount * 8);
          if (matchCount > 0) {
            const matched = novelTags.filter(t => fallbackTags.has(t)).slice(0, 2);
            for (const mt of matched) chips.push({ label: mt, value: "고티어", type: "tag", confirmed: false });
          }
        }
        
        // — 작가 점수 (최대 25점) —
        const author = (novel.author || "").trim();
        if (author && hasPatterns) {
          const as = authorScores[author];
          if (as && as.sampleSize >= 3) {
            let aBonus = Math.max(0, (as.winRate - 0.5) * 80) + (as.sampleSize >= 10 ? 10 : 0);
            // 🧠 v3.5.5: confirmed 작가 보너스
            if (as.confirmed) aBonus = Math.min(25, aBonus + 6);
            authorScore = Math.min(25, aBonus);
            if (as.winRate >= 0.55) {
              const pct = Math.round(as.winRate * 100);
              factors.push(`${author} 작가 선호도 ${pct}%`);
              chips.push({ label: author, value: `${pct}%`, type: "author", confirmed: !!as.confirmed });
            }
          }
        }
        
        const total = Math.round(genreScore + tagScore + authorScore);
        return {
          score: Math.min(100, total),
          factors,
          chips, // 🧠 v3.5.5: UI 팩터 칩
          breakdown: {
            genre: Math.round(genreScore),
            tag: Math.round(tagScore),
            author: Math.round(authorScore),
          },
          source, // 🧠 v3.5.5: "pattern" | "fallback"
        };
      }
      
      /**
       * 취향 점수 기반 추천 이유 생성
       */
      function buildTasteReason(baseReason, taste) {
        if (taste.factors.length === 0) return baseReason;
        const tasteNote = taste.factors.slice(0, 2).join(", ");
        return `${baseReason}\n🧠 취향 분석: ${tasteNote}`;
      }

      // 1) 읽지 않은 예정작 (가중치 100)
      for (const p of (planned || [])) {
        if (recentIds.has(p.id)) continue;
        
        const taste = computeTasteScore(p);
        candidates.push({
          novel: p,
          weight: 100 + taste.score,
          category: "planned_unread",
          reason: buildTasteReason(
            `📋 아직 읽지 않은 예정작입니다.${taste.score >= 30 ? " 취향과도 잘 맞을 것 같습니다!" : ""}`,
            taste
          ),
          isPlanned: true,
          tasteScore: taste,
        });
      }

      // 본 목록 작품 분류
      for (const n of (novels || [])) {
        if (recentIds.has(n.id)) continue;
        if (n.status === "dropped") continue;
        
        const totalEp = Number(n.total_episodes) || 0;
        const readCount = Number(n.read_count) || 0;
        const rating = Number(n.rating) || 1500;
        const reliability = computeReliability(n, totalNovelCount);
        const rereadCount = Number(n.reread_count) || 1;
        const isCompleted = n.work_status === "completed";
        const readRatio = totalEp > 0 ? readCount / totalEp : 0;
        // 🔧 v7.13.0: mode-aware 점수/티어 (raw ELO rating 대신) — 비-match 모드 오분류 해소
        const score = getPrefScore(n, globalTierConfig);
        const displayTier = getDisplayTier(n, globalTierConfig);

        const taste = computeTasteScore(n);
        
        // 2) 거의 다 읽었고 끝을 남겨둔 작품 (90%+)
        if (totalEp > 0 && readRatio >= 0.9 && readRatio < 1.0 && n.status === "reading") {
          candidates.push({
            novel: n,
            weight: 90 + taste.score,
            category: "almost_done",
            reason: buildTasteReason(`📖 거의 다 읽었습니다! (${Math.round(readRatio * 100)}%) 마지막까지 읽어보세요.`, taste),
            isPlanned: false,
            tasteScore: taste,
          });
          continue;
        }
        
        // 3) 취향에 맞는데 안 읽고 있는 작품 (보류 + 취향 일치)
        if (n.status === "paused" && taste.score >= 30 && score >= avgScore) {
          candidates.push({
            novel: n,
            weight: 80 + taste.score,
            category: "taste_match_paused",
            reason: buildTasteReason(`⏸️ 보류 중이지만 취향에 맞는 작품입니다. 다시 읽어보시는 건 어떨까요?`, taste),
            isPlanned: false,
            tasteScore: taste,
          });
          continue;
        }
        
        // 4) 데이터가 비교적 적은 작품
        // 🔧 v7.13.0: match는 신뢰도(매칭 의존), 비-match는 readRatio 기반 — manual에서 reliability=0이라
        //   영영 안 잡히던 사문화 해소. 매칭 의존 문구도 모드별로 분기(밴/비-match 모순 제거).
        const dataPoor = isMatchMode
          ? (reliability > 0 && reliability < 40)
          : (totalEp > 0 && readRatio > 0 && readRatio < 0.3);
        if (dataPoor && n.status !== "dropped") {
          candidates.push({
            novel: n,
            weight: 70 + taste.score / 2,
            category: "low_data",
            reason: buildTasteReason(
              isMatchMode
                ? `📊 아직 데이터가 부족합니다. (신뢰도 ${Math.round(reliability)}%) 더 읽거나 매칭해보세요!`
                : `📊 아직 ${Math.round(readRatio * 100)}%만 읽으셨어요. 더 읽어보세요!`,
              taste
            ),
            isPlanned: false,
            tasteScore: taste,
          });
          continue;
        }
        
        // 5) 취향 분석 고점수 작품 (패턴 데이터 기반)
        if (taste.score >= 40 && n.status === "reading") {
          candidates.push({
            novel: n,
            weight: 60 + taste.score,
            category: "taste_high_tier",
            reason: buildTasteReason(isMatchMode ? `⭐ 매칭 분석 결과 취향 적합도가 높습니다!` : `⭐ 취향 적합도가 높은 작품이에요!`, taste),
            isPlanned: false,
            tasteScore: taste,
          });
          continue;
        }
        
        // 6) 티어 높은 덜 읽은 작품 (v6.0: 상위 절반 티어 동적 판정)
        // 🔧 v7.13.0: tierFromRating(rating) → getDisplayTier (mode-aware), 가중치도 score 기반
        const tier = displayTier;
        const tierOrder = getActiveTierOrder(globalTierConfig);
        if (tierRank(tier, globalTierConfig) < Math.ceil(tierOrder.length / 2) && (totalEp === 0 || readRatio < 0.5)) {
          candidates.push({
            novel: n,
            weight: 50 + (score - 1500) / 20 + taste.score / 4,
            category: "high_tier_less_read",
            reason: buildTasteReason(`🏆 ${tier} 티어 작품인데 아직 ${totalEp > 0 ? Math.round(readRatio * 100) + '%' : '조금'}밖에 안 읽었습니다.`, taste),
            isPlanned: false,
            tasteScore: taste,
          });
          continue;
        }
        
        // 7) 완결까지 다 읽었는데 다회독 추천 (취향 일치 + 상위 티어)
        // 🔧 v7.13.0: rating>=1800(ELO) → 상위 절반 티어(getDisplayTier 기반) — 비-match에서 사문화 해소
        if (isCompleted && totalEp > 0 && readRatio >= 1.0 && tierRank(displayTier, globalTierConfig) < Math.ceil(getActiveTierOrder(globalTierConfig).length / 2) && taste.score >= 25) {
          candidates.push({
            novel: n,
            weight: 30 + taste.score,
            category: "reread_recommend",
            reason: buildTasteReason(`🔄 완독한 고평점 작품! ${rereadCount > 1 ? `이미 ${rereadCount}회독 했지만 ` : ''}다시 읽어보세요.`, taste),
            isPlanned: false,
            tasteScore: taste,
          });
          continue;
        }
        
        // 8) 기타 작품 (낮은 가중치)
        if (n.status === "reading" || n.status === "finished") {
          candidates.push({
            novel: n,
            weight: 20 + taste.score / 3,
            category: "other",
            reason: buildTasteReason(`📚 목록에 있는 작품입니다.`, taste),
            isPlanned: false,
            tasteScore: taste,
          });
        }
      }

      if (candidates.length === 0) {
        setDailyReco(null);
        return;
      }

      // 가중치 기반 확률적 선택
      const totalWeight = candidates.reduce((sum, c) => sum + c.weight, 0);
      let rand = Math.random() * totalWeight;
      let pick = candidates[0];
      
      for (const c of candidates) {
        rand -= c.weight;
        if (rand <= 0) {
          pick = c;
          break;
        }
      }

      // 추천 히스토리 업데이트
      const newHistory = [
        { 
          novelId: pick.novel.id, 
          pickedAt: now, 
          category: pick.category,                                    // 🧠 v3.5.5
          tasteScore: pick.tasteScore ? pick.tasteScore.score : 0,    // 🧠 v3.5.5
          source: pick.tasteScore ? pick.tasteScore.source : "fallback", // 🧠 v3.5.5
        },
        ...history.slice(0, 9), // 최대 10개 유지
      ];
      await setAppMeta("reco_history", newHistory);
      setRecoHistory(newHistory);

      // 추천 저장
      const meta = {
        novel_id: pick.novel.id,
        picked_at: now,
        reason: pick.reason,
        category: pick.category,
        isPlanned: pick.isPlanned,
        tasteScore: pick.tasteScore || null, // 🧠 v3.5.4: 취향 점수 breakdown
      };
      await setAppMeta("daily_reco", meta);

      setDailyReco({
        novel: pick.novel,
        pickedAt: now,
        reason: pick.reason,
        category: pick.category,
        isPlanned: pick.isPlanned,
        tasteScore: pick.tasteScore || null,
      });
      if (_pt) PerfMonitor.trackFunc("refreshDailyRecommendation", Date.now() - _pt); // 🔬
    } catch (e) {
      if (_pt) PerfMonitor.logError("refreshDailyRecommendation", e); // 🔬
      console.warn("refreshDailyRecommendation 오류:", e);
      setDailyReco(null);
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // 🖼️ 표지 라이브러리 시스템 (v3.4.5)
  // ═══════════════════════════════════════════════════════════════════

  // 표지 라이브러리 로드
  // 🚀 v3.5.6: 용량 계산 분리 (FileSystem stat 비용이 크므로 표지 탭에서만 실행)
  async function loadCoverLibrary() {
    const _pt = PerfMonitor.enabled ? Date.now() : 0; // 🔬
    try {
      const rows = await all(`SELECT * FROM cover_library ORDER BY created_at DESC;`);
      setCoverLibrary(rows || []);
      if (_pt) PerfMonitor.trackFunc("loadCoverLibrary", Date.now() - _pt); // 🔬
    } catch (e) {
      if (_pt) PerfMonitor.logError("loadCoverLibrary", e); // 🔬
      console.warn("loadCoverLibrary error:", e);
      setCoverLibrary([]);
    }
  }

  // 갤러리에서 이미지 다중 선택 후 라이브러리에 저장
  async function importCoversFromGallery() {
    try {
      const compressionLevel = appSettings.coverLibrary?.compressionLevel || "light";
      const preset = COMPRESSION_PRESETS[compressionLevel] || COMPRESSION_PRESETS.light;
      
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ['images'],
        allowsMultipleSelection: true,
        quality: preset.quality,
        base64: false, // 🔧 v3.5.3: 다중 선택에서는 base64 비활성 (메모리 문제)
        // 이미지 리사이즈 (expo-image-picker SDK 48+)
        ...(preset.maxSize && {
          exif: false,
          allowsEditing: false,
        }),
      });

      if (result.canceled || !result.assets || result.assets.length === 0) {
        return;
      }

      // 🔧 v3.5.1: 갤러리에서 돌아온 후 DB 연결 확인 및 복구
      await resetDbConnection();
      try {
        await openDb();
        // 🔧 v3.5.3: DB 안정화 대기
        await new Promise(r => setTimeout(r, 300));
      } catch (dbErr) {
        console.error("갤러리 복귀 후 DB 연결 실패:", dbErr);
        Alert.alert("오류", "데이터베이스 연결이 끊어졌습니다. 앱을 다시 시작해주세요.");
        return;
      }

      const assets = result.assets;
      const total = assets.length;
      
      setCoverLibraryLoading(true);
      setCoverLibraryProgress({ current: 0, total });

      const insertQueries = [];
      let successCount = 0;

      const failErrors = []; // 🔧 v3.5.3: 실패 원인 수집
      for (let i = 0; i < assets.length; i++) {
        const asset = assets[i];
        setCoverLibraryProgress({ current: i + 1, total });
        
        // 파일 저장
        const { ext } = getImageFormat(asset);
        const saved = await saveCoverToLibrary(asset.uri, compressionLevel, ext);
        if (saved && saved.id && !saved.error) {
          const id = saved.id;
          insertQueries.push({
            sql: `INSERT INTO cover_library (id, file_path, status, novel_id, original_name, width, height, file_size, created_at)
                  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);`,
            params: [
              id,
              saved.file_path,
              "unused",
              null,
              asset.fileName || `cover_${id}.${ext}`,
              asset.width || 0,
              asset.height || 0,
              saved.file_size,
              Date.now(),
            ],
          });
          successCount++;
        } else {
          // 실패 원인 수집 (최대 3개)
          if (failErrors.length < 3) {
            failErrors.push(`#${i+1}: ${saved?.error || "null반환"} (URI: ${asset.uri?.substring(0, 50)})`);
          }
        }
      }

      if (insertQueries.length > 0) {
        await execBatch(insertQueries);
      }

      setCoverLibraryLoading(false);
      setCoverLibraryProgress({ current: 0, total: 0 });
      
      await loadCoverLibrary();
      
      // 🔧 v3.4.6: 실패 개수도 함께 표시
      const failCount = total - successCount;
      if (failCount > 0) {
        // 🔧 v3.5.3: 구체적 에러 원인 표시
        const errorDetail = failErrors.length > 0 ? "\n\n[에러 상세]\n" + failErrors.join("\n") : "";
        Alert.alert("완료", `${successCount}개 성공, ${failCount}개 실패${errorDetail}`);
      } else {
        Alert.alert("완료", `${successCount}개의 표지를 라이브러리에 추가했습니다.`);
      }
    } catch (e) {
      console.warn("importCoversFromGallery error:", e);
      setCoverLibraryLoading(false);
      setCoverLibraryProgress({ current: 0, total: 0 });
      
      // 🔧 v3.5.1: 에러 발생 시 DB 연결 복구 시도 후 데이터 리로드
      await resetDbConnection();
      try {
        await openDb();
        await loadCoverLibrary();
        await loadList(undefined, undefined, "cover-reload");  // 전체 데이터도 리로드
      } catch (recoveryErr) {
        console.error("복구 실패:", recoveryErr);
      }
      
      Alert.alert("오류", "이미지 가져오기 중 오류가 발생했습니다.\n\n데이터를 다시 불러왔습니다.");
    }
  }

  // 표지 라이브러리에서 이미지 삭제
  async function removeCoverFromLibrary(coverId) {
    try {
      const cover = coverLibrary.find(c => c.id === coverId);
      if (!cover) return;

      if (cover.status === "used") {
        Alert.alert("알림", "사용 중인 표지는 삭제할 수 없습니다. 먼저 해당 작품의 표지를 변경해주세요.");
        return;
      }

      Alert.alert("확인", "이 표지를 삭제할까요?", [
        { text: "취소" },
        {
          text: "삭제",
          style: "destructive",
          onPress: async () => {
            // 파일 삭제
            await deleteCoverFromLibrary(cover.file_path);
            // DB에서 삭제
            await exec("DELETE FROM cover_library WHERE id=?", [coverId]);
            await loadCoverLibrary();
          },
        },
      ]);
    } catch (e) {
      console.warn("removeCoverFromLibrary error:", e);
    }
  }

  // 미사용 표지 전체 삭제
  async function removeAllUnusedCovers() {
    try {
      const unusedCovers = coverLibrary.filter(c => c.status === "unused");
      if (unusedCovers.length === 0) {
        Alert.alert("알림", "삭제할 미사용 표지가 없습니다.");
        return;
      }

      Alert.alert("확인", `미사용 표지 ${unusedCovers.length}개를 모두 삭제할까요?`, [
        { text: "취소" },
        {
          text: "삭제",
          style: "destructive",
          onPress: async () => {
            setCoverLibraryLoading(true);
            setCoverLibraryProgress({ current: 0, total: unusedCovers.length }); // 🔧 v3.6.0: 진행도
            try {
              for (let i = 0; i < unusedCovers.length; i++) {
                await deleteCoverFromLibrary(unusedCovers[i].file_path);
                setCoverLibraryProgress({ current: i + 1, total: unusedCovers.length });
              }

              await exec("DELETE FROM cover_library WHERE status='unused'");
              await loadCoverLibrary();
              Alert.alert("완료", `${unusedCovers.length}개의 미사용 표지를 삭제했습니다.`);
            } finally {
              setCoverLibraryLoading(false);
              setCoverLibraryProgress({ current: 0, total: 0 });
            }
          },
        },
      ]);
    } catch (e) {
      console.warn("removeAllUnusedCovers error:", e);
      setCoverLibraryLoading(false);
    }
  }

  // 표지 상태 업데이트 (작품에 표지 적용/해제 시 호출)
  async function updateCoverStatus(filePath, novelId, status) {
    try {
      // filePath로 cover_library에서 찾기
      const cover = await first("SELECT * FROM cover_library WHERE file_path=?", [filePath]);
      if (cover) {
        await exec(
          "UPDATE cover_library SET status=?, novel_id=? WHERE id=?",
          [status, novelId || null, cover.id]
        );
      }
    } catch (e) {
      console.warn("updateCoverStatus error:", e);
    }
  }

  // 작품에 표지 적용 시 이전 표지 해제 + 새 표지 사용 중으로 변경
  async function applyNovelCover(novelId, newCoverPath, oldCoverPath) {
    try {
      // 이전 표지가 있으면 미사용으로 변경
      if (oldCoverPath && oldCoverPath !== newCoverPath) {
        await updateCoverStatus(oldCoverPath, null, "unused");
      }
      // 새 표지가 라이브러리에 있으면 사용 중으로 변경
      if (newCoverPath) {
        await updateCoverStatus(newCoverPath, novelId, "used");
      }
    } catch (e) {
      console.warn("applyNovelCover error:", e);
    }
  }

  // 표지 선택 모달에서 표지 선택 시
  async function selectCoverFromLibrary(cover) {
    try {
      const filePath = cover.file_path;
      
      if (coverSelectTarget === "new") {
        setNewCoverImage(filePath);
      } else if (coverSelectTarget === "edit") {
        setEditCoverImage(filePath);
        // 🔧 v3.5.6: 함수형 업데이트로 stale closure 방지
        updateEditItem(prev => prev ? { ...prev, cover_image: filePath } : null);
      } else if (coverSelectTarget === "planned") {
        setPlannedCoverImage(filePath);
      } else if (coverSelectTarget === "plannedEdit") {
        // 🔧 v3.5.8: 함수형 업데이트 (plannedEditItem 직접 참조 제거)
        updatePlannedEditItem(prev => prev ? { ...prev, cover_image: filePath } : null);
      }
      
      setCoverSelectModalOpen(false);
    } catch (e) {
      console.warn("selectCoverFromLibrary error:", e);
    }
  }

  // 🖼️ v3.5.6: 표지 갤러리 최적화 - useRef + useCallback (스테일 클로저 방지)
  // ⚠️ 일반 useCallback([])은 첫 렌더의 함수를 영구 캡처 → 상태 변경 후 동작 안 함
  // → ref.current에 항상 최신 함수 저장, useCallback은 ref를 통해 호출
  const removeCoverRef = useRef(removeCoverFromLibrary);
  removeCoverRef.current = removeCoverFromLibrary;
  const selectCoverRef = useRef(selectCoverFromLibrary);
  selectCoverRef.current = selectCoverFromLibrary;

  const coverGalleryDeleteHandler = useCallback((coverId) => {
    removeCoverRef.current(coverId);
  }, []);

  const coverGalleryInfoHandler = useCallback((novelTitle) => {
    Alert.alert("사용 중", `이 표지는 "${novelTitle}"에서 사용 중입니다.`, [{ text: "확인" }]);
  }, []);

  const coverSelectHandler = useCallback((cover) => {
    selectCoverRef.current(cover);
  }, []);

  const coverSelectAlertUsed = useCallback(() => {
    Alert.alert("알림", "이 표지는 이미 다른 작품에서 사용 중입니다.");
  }, []);

  // 🖼️ v3.5.6: 갤러리 아이템 레이아웃 계산 (뷰포트 높이용)
  const { width: screenWidth } = Dimensions.get("window");
  // 표지 탭 (3열): ScrollView padding 32 + Section padding 32 + gap 8×2=16
  const GALLERY_COL3_ITEM_W = (screenWidth - 64 - 16) / 3;
  const GALLERY_COL3_ITEM_H = GALLERY_COL3_ITEM_W / 0.7 + 8; // aspectRatio 0.7 + marginBottom 8
  // 갤러리 뷰포트 높이 (5행 표시)
  const GALLERY_VIEWPORT_HEIGHT = GALLERY_COL3_ITEM_H * 5;

  // ═══════════════════════════════════════════════════════════════════
  // 🎨 v3.8.0: 갤러리 이미지 시스템
  // ═══════════════════════════════════════════════════════════════════

  async function loadGalleryImages() {
    try {
      const rows = await safeDbOperation(async () => {
        // 🖼️ v7.6.2 (포트 v3.12.2): planned_novels도 LEFT JOIN — 예정작 갤러리 이미지가
        //   title NULL로 표시되던 문제 해결 (convertNovelToPlanned 후/예정작 직접 등록 모두 지원)
        return await all(`
          SELECT g.id, g.novel_id, g.file_path, g.caption, g.created_at,
                 COALESCE(n.title, p.title) as title,
                 COALESCE(n.author, p.author) as author,
                 COALESCE(n.rating, p.rating) as rating,
                 COALESCE(n.tier, '') as tier,
                 COALESCE(n.platforms, p.platforms) as platforms,
                 COALESCE(n.major_genre, p.major_genre) as major_genre,
                 CASE WHEN COALESCE(n.cover_image, p.cover_image) LIKE 'data:%' THEN '' ELSE COALESCE(n.cover_image, p.cover_image, '') END as cover_image,
                 CASE WHEN p.id IS NOT NULL THEN 1 ELSE 0 END as is_planned
          FROM gallery_images g
          LEFT JOIN novels n ON g.novel_id = n.id
          LEFT JOIN planned_novels p ON g.novel_id = p.id
          ORDER BY g.created_at DESC
        `);
      }, "loadGalleryImages");
      setGalleryImages(rows || []);
      setGalleryCount((rows || []).length);
    } catch (e) {
      console.warn("loadGalleryImages error:", e);
    }
  }

  async function loadGalleryCount() {
    try {
      const row = await first("SELECT COUNT(*) as c FROM gallery_images");
      setGalleryCount(row?.c || 0);
    } catch (e) {
      console.warn("loadGalleryCount error:", e);
    }
  }

  async function addGalleryImages(novelId) {
    try {
      // 작품 존재 확인 (삭제된 작품 방어)
      // 🖼️ v7.6.2 (포트 v3.12.2): 예정작(planned_novels)도 갤러리 등록 허용
      const novelExists = await first("SELECT id FROM novels WHERE id=? UNION SELECT id FROM planned_novels WHERE id=?", [novelId, novelId]);
      if (!novelExists) {
        Alert.alert("오류", "선택한 작품이 삭제되었습니다. 다시 선택해주세요.");
        setGalleryRegNovel(null);
        return;
      }
      // 현재 개수 체크
      const existingRow = await first("SELECT COUNT(*) as c FROM gallery_images WHERE novel_id=?", [novelId]);
      const existing = existingRow?.c || 0;
      const remaining = GALLERY_IMAGE_MAX_COUNT - existing;
      if (remaining <= 0) {
        Alert.alert("알림", `이 작품은 이미 최대 ${GALLERY_IMAGE_MAX_COUNT}장이 등록되어 있습니다.`);
        return;
      }

      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ['images'],
        allowsMultipleSelection: true,
        selectionLimit: remaining,
        quality: 0.8,
        base64: false,
      });

      // DB 연결 복구 (Android 필수, 300ms 안정화 대기)
      await resetDbConnection();
      try { await openDb(); await new Promise(r => setTimeout(r, 300)); } catch (dbErr) {
        console.warn("gallery ImagePicker DB 재연결 실패:", dbErr.message);
      }

      if (result.canceled || !result.assets?.length) return;

      setGalleryLoading(true);
      // 🔧 ImagePicker가 selectionLimit을 무시하는 Android 기기 대응: 재검증
      const assets = result.assets.slice(0, remaining);
      let successCount = 0;
      let failCount = 0;
      const queries = [];

      for (let i = 0; i < assets.length; i++) {
        const asset = assets[i];
        const { ext } = getImageFormat(asset);
        const saved = await saveGalleryImage(asset.uri, ext);

        if (saved && saved.id && !saved.error) {
          queries.push({
            sql: "INSERT INTO gallery_images (id, novel_id, file_path, caption, created_at) VALUES (?,?,?,?,?);",
            params: [saved.id, novelId, saved.file_path, "", Date.now()],
          });
          successCount++;
        } else {
          failCount++;
          console.warn("gallery image save failed:", saved?.error);
        }
      }

      if (queries.length > 0) await execBatch(queries);

      setGalleryLoading(false);
      await loadGalleryImages();

      if (failCount > 0) {
        Alert.alert("완료", `${successCount}장 등록, ${failCount}장 실패`);
      } else {
        Alert.alert("완료", `${successCount}장이 등록되었습니다.`);
      }
    } catch (e) {
      setGalleryLoading(false);
      console.warn("addGalleryImages error:", e);
      Alert.alert("오류", "이미지 등록 중 문제가 발생했습니다: " + (e.message || e));
    }
  }

  async function deleteGalleryImage(imgId, filePath) {
    Alert.alert("확인", "이 이미지를 삭제할까요?", [
      { text: "취소", style: "cancel" },
      {
        text: "삭제",
        style: "destructive",
        onPress: async () => {
          try {
            // DB 먼저 삭제 (트랜잭션 안전), 파일은 실패해도 허용
            await exec("DELETE FROM gallery_images WHERE id=?", [imgId]);
            deleteCoverFromLibrary(filePath).catch(() => {});
            await loadGalleryImages();
          } catch (e) {
            console.warn("deleteGalleryImage error:", e);
            Alert.alert("오류", "이미지 삭제 중 문제가 발생했습니다.");
          }
        },
      },
    ]);
  }

  async function updateGalleryCaption(imgId, caption) {
    try {
      // 낙관적 업데이트 먼저
      setGalleryImages(prev => prev.map(g => g.id === imgId ? { ...g, caption } : g));
      await exec("UPDATE gallery_images SET caption=? WHERE id=?", [caption, imgId]);
    } catch (e) {
      console.warn("updateGalleryCaption error:", e);
      // DB 실패 시 롤백
      await loadGalleryImages();
    }
  }

  async function changeGalleryNovel(imgId, newNovelId) {
    try {
      // 대상 작품 20장 제한 체크
      const targetCount = await first("SELECT COUNT(*) as c FROM gallery_images WHERE novel_id=?", [newNovelId]);
      if ((targetCount?.c || 0) >= GALLERY_IMAGE_MAX_COUNT) {
        Alert.alert("알림", `대상 작품은 이미 최대 ${GALLERY_IMAGE_MAX_COUNT}장이 등록되어 있습니다.`);
        return;
      }
      await exec("UPDATE gallery_images SET novel_id=? WHERE id=?", [newNovelId, imgId]);
      await loadGalleryImages();
      setGalleryChangeNovelTarget(null);
      setGalleryNovelPickerOpen(false);
    } catch (e) {
      console.warn("changeGalleryNovel error:", e);
    }
  }

  async function loadMatchStats() {
    try {
      const novels = await all(`SELECT id FROM novels;`);
      const n = novels?.length || 0;
      if (n < 2) {
        setMatchStats({ total: 0, done: 0, percent: 0 });
        return;
      }
      const total = (n * (n - 1)) / 2;
      const rows = await all(
        `SELECT COUNT(DISTINCT (CASE WHEN a_id < b_id THEN a_id || '|' || b_id ELSE b_id || '|' || a_id END)) AS c FROM matches;`
      );
      const done = rows?.[0]?.c || 0;
      const percent = total > 0 ? Math.min(100, Math.round((done / total) * 100)) : 0;
      setMatchStats({ total, done, percent });
    } catch (e) {
      console.warn("loadMatchStats 오류:", e);
      setMatchStats({ total: 0, done: 0, percent: 0 });
    }
  }

  // 🔮 v3.0.3: 승부예측 분석 시스템
  // 두 작품 간 직접 대결 전적 조회
  async function getHeadToHead(aId, bId) {
    const matches = await all(
      `SELECT winner_id FROM matches WHERE (a_id=? AND b_id=?) OR (a_id=? AND b_id=?)`,
      [aId, bId, bId, aId]
    );
    let aWins = 0, bWins = 0;
    for (const m of (matches || [])) {
      if (m.winner_id === aId) aWins++;
      else if (m.winner_id === bId) bWins++;
    }
    return { aWins, bWins, total: (matches || []).length };
  }

  // 장르 상성 분석 (같은 장르 간 전적 집계)
  // 🔧 v3.5.15: 결과 캐시 추가 (30초 TTL) — 매 매칭마다 SELECT * FROM matches 방지
  const genreMatchupCacheRef = useRef({ data: {}, ts: 0, TTL: 30000 });
  
  async function analyzeGenreMatchup(genreA, genreB) {
    if (!genreA || !genreB) return null;
    if (genreA === genreB) return { type: "same", advantage: 0 };
    
    // 🔧 v3.5.15: 캐시 확인 (동일 장르 조합에 대해 30초간 재사용)
    const cacheKey = genreA < genreB ? `${genreA}|${genreB}` : `${genreB}|${genreA}`;
    const cache = genreMatchupCacheRef.current;
    if (cache.data[cacheKey] && cache.data[cacheKey].ts && (Date.now() - cache.data[cacheKey].ts < cache.TTL)) {
      const cached = cache.data[cacheKey];
      // genreA/genreB 순서에 따라 advantage 부호 조정
      // 🔧 v3.5.15b: cached.genreA 기준 비교 (cacheKey.startsWith는 알파벳순이라 원래 순서와 무관)
      if (cached.type === "cross") {
        const isOriginalOrder = cached.genreA === genreA;
        return isOriginalOrder ? { ...cached } : { ...cached, advantage: -cached.advantage, genreA: genreB, genreB: genreA, genreAWins: cached.genreBWins, genreBWins: cached.genreAWins };
      }
      return cached;
    }
    
    const novelsA = await all(`SELECT id FROM novels WHERE major_genre LIKE ?`, [`%${genreA}%`]);
    const novelsB = await all(`SELECT id FROM novels WHERE major_genre LIKE ?`, [`%${genreB}%`]);
    
    if (!novelsA || novelsA.length === 0 || !novelsB || novelsB.length === 0) return null;
    
    const idsA = new Set(novelsA.map(n => n.id));
    const idsB = new Set(novelsB.map(n => n.id));
    
    const matches = await all(`SELECT a_id, b_id, winner_id FROM matches`);
    
    let genreAWins = 0, genreBWins = 0;
    for (const m of (matches || [])) {
      const aIsGenreA = idsA.has(m.a_id) && !idsA.has(m.b_id);
      const bIsGenreA = idsA.has(m.b_id) && !idsA.has(m.a_id);
      const aIsGenreB = idsB.has(m.a_id) && !idsB.has(m.b_id);
      const bIsGenreB = idsB.has(m.b_id) && !idsB.has(m.a_id);
      
      if ((aIsGenreA && bIsGenreB) || (aIsGenreB && bIsGenreA)) {
        if (idsA.has(m.winner_id)) genreAWins++;
        else if (idsB.has(m.winner_id)) genreBWins++;
      }
    }
    
    const total = genreAWins + genreBWins;
    if (total === 0) return null;
    
    const advantage = (genreAWins - genreBWins) / total;
    const result = { type: "cross", genreA, genreB, genreAWins, genreBWins, total, advantage, ts: Date.now() };
    
    // 캐시 저장 (per-entry timestamp)
    cache.data[cacheKey] = result;
    
    return result;
  }

  // 종합 승부예측 분석
  async function analyzeMatchPrediction(A, B) {
    if (!A || !B) return null;
    
    // 1. Elo 기반 예상 승률
    const eloWinRateA = expected(A.rating, B.rating);
    const eloWinRateB = 1 - eloWinRateA;
    
    // 2. 직접 대결 전적
    const h2h = await getHeadToHead(A.id, B.id);
    
    // 3. RD 신뢰도 (낮을수록 신뢰도 높음)
    const rdA = A.rd || 350;
    const rdB = B.rd || 350;
    const reliabilityA = Math.max(0, 1 - (rdA - 60) / 290); // 60~350 → 1~0
    const reliabilityB = Math.max(0, 1 - (rdB - 60) / 290);
    
    // 4. 읽은 회차 비율 (더 많이 읽은 작품에 대한 확신)
    const readRatioA = A.total_episodes > 0 ? (A.read_count / A.total_episodes) : 0.5;
    const readRatioB = B.total_episodes > 0 ? (B.read_count / B.total_episodes) : 0.5;
    
    // 5. 전체 승률
    const totalWinRateA = A.match_count > 0 ? A.wins / A.match_count : 0.5;
    const totalWinRateB = B.match_count > 0 ? B.wins / B.match_count : 0.5;
    
    // 6. 장르 상성 (선택적)
    let majorGenreA = null;
    let majorGenreB = null;
    try {
      majorGenreA = A.major_genre ? JSON.parse(A.major_genre)[0] : null;
    } catch { /* 파싱 실패 시 null 유지 */ }
    try {
      majorGenreB = B.major_genre ? JSON.parse(B.major_genre)[0] : null;
    } catch { /* 파싱 실패 시 null 유지 */ }
    let genreMatchup = null;
    try {
      genreMatchup = await analyzeGenreMatchup(majorGenreA, majorGenreB);
    } catch (e) {
      // 장르 분석 실패해도 계속 진행
    }
    
    // 종합 예측 (가중 평균)
    // Elo 50% + 직접대결 20% + 전체승률 15% + 신뢰도 10% + 장르상성 5%
    let predictedWinRateA = eloWinRateA * 0.5;
    
    // 직접 대결 전적 반영
    if (h2h.total > 0) {
      const h2hWinRateA = h2h.aWins / h2h.total;
      predictedWinRateA += h2hWinRateA * 0.2;
    } else {
      predictedWinRateA += 0.5 * 0.2; // 전적 없으면 50%로 가정
    }
    
    // 전체 승률 반영
    predictedWinRateA += (totalWinRateA / ((totalWinRateA + totalWinRateB) || 1)) * 0.15;
    
    // 신뢰도 반영 (신뢰도 높은 쪽 약간 유리)
    const reliabilityFactor = (reliabilityA - reliabilityB) * 0.1 + 0.5;
    predictedWinRateA += reliabilityFactor * 0.1;
    
    // 장르 상성 반영
    if (genreMatchup && genreMatchup.type === "cross") {
      // A의 장르가 genreA면 advantage 그대로, 아니면 반전
      const isAFirstGenre = majorGenreA === genreMatchup.genreA;
      const genreFactor = isAFirstGenre ? genreMatchup.advantage : -genreMatchup.advantage;
      predictedWinRateA += (genreFactor * 0.5 + 0.5) * 0.05;
    } else {
      predictedWinRateA += 0.5 * 0.05;
    }
    
    // 결과 정규화
    predictedWinRateA = Math.max(0.01, Math.min(0.99, predictedWinRateA));
    const predictedWinRateB = 1 - predictedWinRateA;
    
    // 예측 결과 결정
    const predictedWinner = predictedWinRateA >= 0.5 ? "A" : "B";
    const confidence = Math.abs(predictedWinRateA - 0.5) * 2; // 0~1 (0.5면 0, 극단이면 1)
    
    // 이변 가능성 (예측 확률이 낮은데 실제로 이기면 이변)
    const upsetThreshold = 0.35; // 35% 미만 승률에서 이기면 이변
    
    return {
      eloWinRateA,
      eloWinRateB,
      h2h,
      reliabilityA,
      reliabilityB,
      readRatioA,
      readRatioB,
      totalWinRateA,
      totalWinRateB,
      genreMatchup,
      predictedWinRateA,
      predictedWinRateB,
      predictedWinner,
      confidence,
      upsetThreshold,
    };
  }

  // 매치 결과 분석 및 인사이트 생성
  // 🆕 v7.0.6 (m3): tagRelationsSnapshot 인자 추가 — decide() 진입 시 캡처된 스냅샷 사용으로 큐 task 내부 stale closure 회피
  // 🔧 v7.0.7 (MAJ-5): tagAttributesSnapshot도 함께 받음 — analyzeUpsetCauses 내부에서 tagAttributes 클로저 참조하므로 동일한 stale 위험
  async function analyzeMatchResult(A, B, winnerId, prediction, tagRelationsSnapshot, tagAttributesSnapshot) {
    if (!prediction) return null;

    const winner = winnerId === A.id ? "A" : "B";
    const winnerNovel = winner === "A" ? A : B;
    const loserNovel = winner === "A" ? B : A;
    const isUpset = (
      (winner === "A" && prediction.predictedWinRateA < prediction.upsetThreshold) ||
      (winner === "B" && prediction.predictedWinRateB < prediction.upsetThreshold)
    );

    // 예측 정확도
    const wasCorrect = prediction.predictedWinner === winner;

    // 🔮 v3.0.3: 이변 원인 분석
    // 🆕 v7.0.6 (m3): 인자로 받은 snapshot 우선 사용 (대비: 큐 지연 중 tagRelations state 변경)
    // 🔧 v7.0.7 (MAJ-5): tagAttributesSnapshot도 analyzeUpsetCauses에 전달 (불변규칙 #2 완전 충족)
    let upsetCauses = [];
    if (isUpset) {
      upsetCauses = analyzeUpsetCauses(winnerNovel, loserNovel, tagRelationsSnapshot || tagRelations, tagAttributesSnapshot || tagAttributes);
    }
    
    // 인사이트 생성
    const insight = {
      id: uuid(),
      timestamp: Date.now(),
      novelAId: A.id,
      novelATitle: A.title,
      novelBId: B.id,
      novelBTitle: B.title,
      winnerId,
      winnerTitle: winnerId === A.id ? A.title : B.title,
      loserId: winnerId === A.id ? B.id : A.id,
      loserTitle: winnerId === A.id ? B.title : A.title,
      majorGenreA: A.major_genre,
      majorGenreB: B.major_genre,
      ratingDiff: Math.abs(A.rating - B.rating),
      predictedWinRate: winner === "A" ? prediction.predictedWinRateA : prediction.predictedWinRateB,
      isUpset,
      wasCorrect,
      h2h: prediction.h2h, // 직접대결 전적 (aWins, bWins, total)
      upsetCauses, // 🔮 이변 원인 후보
    };
    
    // 인사이트 저장 (🔧 React 18+ 배칭 대응: updater 내 부수효과 제거)
    setMatchInsights(prev => {
      const updated = [insight, ...prev].slice(0, 200); // 최대 200개 유지
      safeDefer(() => deferSetAppMeta("match_insights", updated));
      return updated;
    });
    
    // 🔮 이변 발생 시 요인 업데이트
    if (isUpset && upsetCauses.length > 0) {
      updateUpsetFactors(upsetCauses, insight);
    }
    
    return insight;
  }

  // 🔮 v3.0.3: 이변 원인 분석 함수
  // 🎯 v3.1.2: 농도 가중치를 적용한 이변 분석
  // 🔧 v7.0.7 (MAJ-5): tagAttrs 인자 추가 — 큐 task 지연 중 tagAttributes state 변경 시 stale closure 회피 (불변규칙 #2)
  function analyzeUpsetCauses(winner, loser, relations, tagAttrs) {
    const causes = [];
    const _tagAttrs = tagAttrs || tagAttributes; // backward compat: 인자 미전달 시 closure fallback

    // 1. 태그 차이 분석 (🏷️ v3.1.2: 농도 포함)
    // 🆕 v3.5.8: 작품명 태그 제외
    const winnerTags = new Set((winner.tags || "").split(",").map(t => t.trim()).filter(t => t && !isTagTitle(t, _tagAttrs)));
    const loserTags = new Set((loser.tags || "").split(",").map(t => t.trim()).filter(t => t && !isTagTitle(t, _tagAttrs)));
    
    // tag_data에서 농도 맵 생성
    let winnerIntensity = {};
    let loserIntensity = {};
    try {
      const wd = JSON.parse(winner.tag_data || "[]");
      if (Array.isArray(wd)) wd.forEach(t => { winnerIntensity[t.tag] = t.intensity || 3; });
    } catch {}
    try {
      const ld = JSON.parse(loser.tag_data || "[]");
      if (Array.isArray(ld)) ld.forEach(t => { loserIntensity[t.tag] = t.intensity || 3; });
    } catch {}
    
    // 승자에게만 있는 태그 (긍정적 요인 후보)
    for (const tag of winnerTags) {
      if (!loserTags.has(tag)) {
        // 유사 태그 그룹 찾기
        const groupKey = findSimilarGroupKey(tag, relations);
        const intensity = winnerIntensity[tag] || 3;
        causes.push({
          type: "tag_only_winner",
          key: groupKey || tag,
          originalTag: tag,
          direction: "positive",
          intensity, // 🏷️ v3.1.2: 농도 추가
          weight: intensity / 3, // 농도 가중치 (3이 기준 1.0)
        });
      }
    }
    
    // 패자에게만 있는 태그 (부정적 요인 후보)
    for (const tag of loserTags) {
      if (!winnerTags.has(tag)) {
        const groupKey = findSimilarGroupKey(tag, relations);
        const intensity = loserIntensity[tag] || 3;
        causes.push({
          type: "tag_only_loser",
          key: groupKey || tag,
          originalTag: tag,
          direction: "negative",
          intensity, // 🏷️ v3.1.2: 농도 추가
          weight: intensity / 3,
        });
      }
    }
    
    // 2. 장르 차이 분석
    const winnerGenres = parseGenreArray(winner.major_genre);
    const loserGenres = parseGenreArray(loser.major_genre);
    
    for (const g of winnerGenres) {
      if (!loserGenres.includes(g)) {
        causes.push({
          type: "genre_preference",
          key: g,
          direction: "positive",
          weight: 1,
        });
      }
    }
    
    for (const g of loserGenres) {
      if (!winnerGenres.includes(g)) {
        causes.push({
          type: "genre_aversion",
          key: g,
          direction: "negative",
          weight: 1,
        });
      }
    }
    
    // 3. 플랫폼 차이
    const winnerPlats = parsePlatforms(winner.platforms);
    const loserPlats = parsePlatforms(loser.platforms);
    
    for (const p of winnerPlats) {
      if (!loserPlats.includes(p)) {
        causes.push({
          type: "platform_preference",
          key: p,
          direction: "positive",
        });
      }
    }
    
    // 4. 작가 (승자 작가 선호 가능성)
    if (winner.author && winner.author !== loser.author) {
      causes.push({
        type: "author_preference",
        key: winner.author,
        direction: "positive",
      });
    }
    
    // 5. 읽은 비율 차이 (많이 읽은 작품 선호)
    const winnerReadRatio = winner.total_episodes > 0 ? winner.read_count / winner.total_episodes : 0;
    const loserReadRatio = loser.total_episodes > 0 ? loser.read_count / loser.total_episodes : 0;
    if (winnerReadRatio > loserReadRatio + 0.3) {
      causes.push({
        type: "read_engagement",
        key: "high_read_ratio",
        direction: "positive",
      });
    }
    
    return causes;
  }

  // 🔗 유사 태그 그룹 키 찾기
  function findSimilarGroupKey(tag, relations) {
    if (!relations || !relations.tagToGroup || !relations.groups) return null;
    
    const groupId = relations.tagToGroup[tag];
    if (!groupId) return null;
    
    const group = relations.groups[groupId];
    if (!group || group.type !== "similar") return null;
    
    // 그룹의 대표 태그 (첫 번째 태그)를 키로 사용
    return `[SIM:${group.tags[0] || tag}]`;
  }

  // 🔗 v3.0.3: 태그 관계도 관리 함수들
  
  // 태그의 그룹 정보 조회
  const getTagGroupInfo = useCallback((tag) => {
    const groupId = tagRelations.tagToGroup[tag];
    if (!groupId) return null;
    return tagRelations.groups[groupId] || null;
  }, [tagRelations]);
  
  // 유사 태그들 조회 (그룹 내 다른 태그들)
  const getSimilarTags = useCallback((tag) => {
    const group = getTagGroupInfo(tag);
    if (!group || group.type !== "similar") return [];
    return group.tags.filter(t => t !== tag);
  }, [getTagGroupInfo]);
  
  // 상반 태그들 조회
  const getOppositeTags = useCallback((tag) => {
    const group = getTagGroupInfo(tag);
    if (!group) return [];
    if (!tagRelations?.groups) return [];
    
    // 이 그룹과 상반 관계인 그룹 찾기
    const opposites = [];
    for (const [gId, g] of Object.entries(tagRelations.groups)) {
      if (g.type === "opposite" && g.relatedGroupId === group.id) {
        opposites.push(...(g.tags || []));
      }
      if (group.type === "opposite" && group.relatedGroupId === gId) {
        opposites.push(...(g.tags || []));
      }
    }
    return opposites;
  }, [tagRelations, getTagGroupInfo]);
  
  // 새 그룹 생성
  const createTagGroup = useCallback((name, type, tags, relatedGroupId = null) => {
    const groupId = uuid();
    const newGroup = {
      id: groupId,
      name,
      type, // "similar" | "opposite"
      tags: [...new Set(tags)],
      relatedGroupId, // 상반 관계일 때 연결된 그룹
      createdAt: Date.now(),
    };
    
    setTagRelations(prev => {
      const newGroups = { ...prev.groups, [groupId]: newGroup };
      const newTagToGroup = { ...prev.tagToGroup };
      
      // 태그 → 그룹 매핑 업데이트
      for (const tag of tags) {
        newTagToGroup[tag] = groupId;
      }
      
      const updated = { groups: newGroups, tagToGroup: newTagToGroup };
      deferSetAppMeta("tag_relations", updated);
      return updated;
    });
    
    return groupId;
  }, []);
  
  // 그룹에 태그 추가
  const addTagToGroup = useCallback((groupId, tag) => {
    setTagRelations(prev => {
      const group = prev.groups[groupId];
      if (!group) return prev;
      
      // 이미 다른 그룹에 있으면 제거
      const oldGroupId = prev.tagToGroup[tag];
      const newGroups = { ...prev.groups };
      
      if (oldGroupId && oldGroupId !== groupId) {
        const oldGroup = newGroups[oldGroupId];
        if (oldGroup) {
          newGroups[oldGroupId] = {
            ...oldGroup,
            tags: oldGroup.tags.filter(t => t !== tag),
          };
        }
      }
      
      // 새 그룹에 추가
      newGroups[groupId] = {
        ...group,
        tags: [...new Set([...group.tags, tag])],
      };
      
      const newTagToGroup = { ...prev.tagToGroup, [tag]: groupId };
      const updated = { groups: newGroups, tagToGroup: newTagToGroup };
      deferSetAppMeta("tag_relations", updated);
      return updated;
    });
  }, []);
  
  // 그룹에서 태그 제거
  const removeTagFromGroup = useCallback((groupId, tag) => {
    setTagRelations(prev => {
      const group = prev.groups[groupId];
      if (!group) return prev;
      
      const newTags = group.tags.filter(t => t !== tag);
      const newGroups = { ...prev.groups };
      const newTagToGroup = { ...prev.tagToGroup };
      
      if (newTags.length === 0) {
        // 그룹이 비면 삭제
        delete newGroups[groupId];
      } else {
        newGroups[groupId] = { ...group, tags: newTags };
      }
      
      delete newTagToGroup[tag];
      
      const updated = { groups: newGroups, tagToGroup: newTagToGroup };
      deferSetAppMeta("tag_relations", updated);
      return updated;
    });
  }, []);
  
  // 그룹 삭제
  const deleteTagGroup = useCallback((groupId) => {
    setTagRelations(prev => {
      const group = prev.groups[groupId];
      if (!group) return prev;
      
      const newGroups = { ...prev.groups };
      const newTagToGroup = { ...prev.tagToGroup };
      
      // 그룹의 모든 태그 매핑 제거
      for (const tag of group.tags) {
        delete newTagToGroup[tag];
      }
      
      delete newGroups[groupId];
      
      const updated = { groups: newGroups, tagToGroup: newTagToGroup };
      deferSetAppMeta("tag_relations", updated);
      return updated;
    });
  }, []);
  
  // 태그 관계 모달 열기
  const openTagRelationModal = useCallback((tag) => {
    if (!tag) {
      // 🔧 v3.5.7: 관리 모드 (태그 없이 열기)
      setTagRelationTarget(null);
      setTagRelationEditGroup(null);
      deferOpen(setTagRelationModalOpen); // 🔧 v3.5.8
      return;
    }
    setTagRelationTarget(tag);
    const groupInfo = getTagGroupInfo(tag);
    setTagRelationEditGroup(groupInfo);
    deferOpen(setTagRelationModalOpen); // 🔧 v3.5.8
  }, [getTagGroupInfo]);

  // 🔮 이변 요인 업데이트
  function updateUpsetFactors(causes, insight) {
    setUpsetFactors(prev => {
      const factors = [...prev.factors];
      
      for (const cause of causes) {
        const existingIdx = factors.findIndex(
          f => f.type === cause.type && f.key === cause.key && f.direction === cause.direction
        );
        
        if (existingIdx >= 0) {
          // 기존 요인 업데이트
          factors[existingIdx] = {
            ...factors[existingIdx],
            occurrences: factors[existingIdx].occurrences + 1,
            examples: [
              `${insight.winnerTitle} vs ${insight.loserTitle}`,
              ...factors[existingIdx].examples.slice(0, 4),
            ],
          };
        } else {
          // 새 요인 추가
          factors.push({
            id: uuid(),
            type: cause.type,
            key: cause.key,
            originalTag: cause.originalTag,
            direction: cause.direction,
            occurrences: 1,
            examples: [`${insight.winnerTitle} vs ${insight.loserTitle}`],
          });
        }
      }
      
      // 신뢰도 계산 (현재 이변 요인 수 기반 — stale closure 방지)
      const totalUpsets = (factors.filter(f => f.occurrences > 0).length || 1) + 1;
      for (const f of factors) {
        f.confidence = Math.min(1, f.occurrences / totalUpsets);
      }
      
      // 발생 횟수 순 정렬
      factors.sort((a, b) => b.occurrences - a.occurrences);
      
      const updated = {
        factors: factors.slice(0, 100), // 최대 100개
        lastUpdated: Date.now(),
      };
      
      deferSetAppMeta("upset_factors", updated);
      return updated;
    });
  }

  // 🏷️ 태그 사용 빈도 및 공동 출현 통계 업데이트
  // 🔧 v3.5.11 성능: counts만 즉시, coOccurrences는 500ms 후 지연 계산
  // + 태그 해시 비교로 데이터 미변경 시 재계산 스킵
  const tagHashRef = useRef("");
  const coOccTimerRef = useRef(null);
  const matchStatsTimerRef = useRef(null); // 🔧 v3.5.14: loadMatchStats 디바운스
  const loadListRunningRef = useRef(false); // 🔧 v3.5.15c: loadList 동시 실행 방지
  
  function updateTagUsageCounts(novels) {
    // P2: 태그 해시 비교 — 데이터 미변경 시 스킵
    // 🔧 v3.5.14: 순서 무관 해시 — id 포함 후 sort하여 ORDER BY 변경에 무관하게 비교
    // 이전: rating 변경 → ORDER BY 순서 변경 → 해시 불일치 → 매칭마다 242ms 재계산 (불필요)
    // 수정: id:tags 조합을 정렬하여 태그가 실제 변경될 때만 재계산
    const tagHash = novels.map(n => `${n.id}:${n.tags || ""}|${n.major_genre || ""}|${n.sub_genre || ""}`).sort().join("||");
    if (tagHash === tagHashRef.current) return;
    tagHashRef.current = tagHash;
    
    // P0: counts만 즉시 계산 (O(n*m) ~20ms)
    const counts = countTagUsageFast(novels);
    setTagUsageCounts(counts);
    
    // P0: coOccurrences는 500ms 후 지연 계산 (O(n*m²) ~280ms)
    if (coOccTimerRef.current) clearTimeout(coOccTimerRef.current);
    coOccTimerRef.current = setTimeout(() => {
      const coOcc = countTagCoOccurrences(novels);
      setTagCoOccurrences(coOcc);
      coOccTimerRef.current = null;
    }, 500);
  }

  // 🏷️ 태그 선택 모달 열기 (새 방식)
  const [tagModalInitialTags, setTagModalInitialTags] = useState([]);
  const [tagModalInitialMajor, setTagModalInitialMajor] = useState([]);
  const [tagModalInitialSub, setTagModalInitialSub] = useState([]);
  const [tagModalInitialTagData, setTagModalInitialTagData] = useState([]); // 🏷️ v5.0

  function openTagModal(target, initialTags = [], majorGenre = "", subGenre = "", tagData = []) {
    // 🔧 v3.5.12: coOccurrences가 아직 계산 안 됐으면 즉시 계산 (지연 타이머 대기 방지)
    if (Object.keys(tagCoOccurrences).length === 0 && list.length > 0) {
      const coOcc = countTagCoOccurrences(list);
      setTagCoOccurrences(coOcc);
    }
    setTagModalTarget(target);
    setTagModalInitialTags(initialTags);
    setTagModalInitialMajor(parseGenreArray(majorGenre));
    setTagModalInitialSub(parseGenreArray(subGenre));
    setTagModalInitialTagData(tagData); // 🏷️ v5.0
    deferOpen(setTagModalOpen); // 🔧 v3.5.8
  }

  // 🏷️ 태그 선택 모달 확인 콜백
  // 🔧 v3.4.4: 대장르/부장르도 일반 태그처럼 텍스트 입력창과 완전 동기화
  // ⚠️ 설계 의도: 대장르/부장르는 "특별한" 태그가 아니라 일반 태그와 동일하게 취급됨
  //    - 텍스트 입력창에 모든 태그(일반+대장르+부장르)가 표시됨
  //    - 텍스트를 지우면 해당 태그(대장르/부장르 포함)가 삭제됨
  //    - 텍스트로 입력하면 자동으로 대장르/부장르 여부를 감지하여 분류됨
  const handleTagModalConfirm = useCallback((selectedTags, selectedMajor, selectedSub, tagData = []) => {
    // JSON 배열로 저장 (내부 구분용)
    const majorJson = selectedMajor.length > 0 ? JSON.stringify(selectedMajor) : "";
    const subJson = selectedSub.length > 0 ? JSON.stringify(selectedSub) : "";
    
    // 🔧 v3.4.4: 모든 태그를 하나의 문자열로 합침 (대장르, 부장르, 일반 태그 순)
    // 이렇게 하면 텍스트 입력창에서 모든 태그를 볼 수 있고 편집할 수 있음
    // 🔧 v3.5.14: isSameTag 기반 중복 제거 (대장르+일반에 같은 태그 선택 시 방지)
    const allTagsArray = deduplicateTags([...selectedMajor, ...selectedSub, ...selectedTags]);
    const allTagsString = allTagsArray.join(", ");
    
    // 🏷️ v5.0: tagData JSON 문자열
    const tagDataJson = tagData && tagData.length > 0 ? JSON.stringify(tagData) : "";
    
    // 🔧 v7.6.0 (포트 v3.12.0): 태그→연도 단방향 자동 동기화
    // 1990~2099 4자리 매치만 채택, 이미 설정된 값은 유지 (사용자 입력 우선)
    const extractYears = (text) => {
      const matches = [...(text || "").matchAll(/\b(19[9]\d|20\d{2})\b/g)]
        .map(m => Number(m[1])).filter(y => y >= 1990 && y <= 2099);
      return [...new Set(matches)].sort((a, b) => a - b);
    };

    if (tagModalTarget === "new") {
      setTags(allTagsString);
      setNewMajorGenre(selectedMajor);
      setNewSubGenre(selectedSub);
      setNewTagData(tagData); // 🏷️ v5.0
      const extracted = extractYears(allTagsString);
      if (extracted.length > 0) {
        setNewStartYear(prev => prev > 0 ? prev : extracted[0]);
        setNewEndYear(prev => prev > 0 ? prev : (extracted.length > 1 ? extracted[extracted.length - 1] : 0));
      }
    } else if (tagModalTarget === "edit" || tagModalTarget === "supplement") {
      // 🔧 v3.5.6: 함수형 업데이트로 stale closure 방지
      updateEditItem(prev => prev ? {
        ...prev,
        tags: allTagsString, // 🔧 v3.4.4: 모든 태그 포함
        major_genre: majorJson,
        sub_genre: subJson,
        tag_data: tagDataJson, // 🏷️ v5.0
      } : null);
      const extracted = extractYears(allTagsString);
      if (extracted.length > 0) {
        setEditStartYear(prev => prev > 0 ? prev : extracted[0]);
        setEditEndYear(prev => prev > 0 ? prev : (extracted.length > 1 ? extracted[extracted.length - 1] : 0));
      }
    } else if (tagModalTarget === "planned") {
      // 🆕 v3.4.3: 예정탭 편집에서 태그 선택
      // 🔧 v3.5.8: 함수형 업데이트로 stale closure 방지
      updatePlannedEditItem(prev => prev ? {
        ...prev,
        tags: allTagsString, // 🔧 v3.4.4: 모든 태그 포함
        major_genre: majorJson,
        sub_genre: subJson,
        tag_data: tagDataJson, // 🔧 v3.5.9: 예정작에도 tag_data 저장
      } : null);
    } else if (tagModalTarget === "plannedNew") {
      // 🔧 v3.4.5: 예정탭 신규 등록에서 태그 선택
      setPlannedTags(allTagsString);
      setPlannedMajorGenre(selectedMajor);
      setPlannedSubGenre(selectedSub);
    }
    setTagModalOpen(false);
  }, [tagModalTarget]); // 🔧 v3.5.8: plannedEditItem 제거 (함수형 업데이트로 직접 참조 불필요)

  // (이전 toggleMajorGenre, toggleSubGenre, toggleTagInModal은 TagSelectModal 내부로 이동됨)

  // 🏷️ 커스텀 태그 삭제
  // 🔧 v3.5.9: 태그 삭제 시 연관 메타데이터 일괄 정리
  async function cleanupTagMetadata(tag) {
    // 🔧 v3.5.9: 함수형 setState로 stale closure 방지 (일괄 삭제 시 안전)
    // 🔧 v3.5.13: isSameTag 사용으로 공백/alias 변형도 정확히 정리
    // 고정 태그에서 제거 (🔧 React 18+ 배칭 대응: updater 내 부수효과 → setTimeout)
    setPinnedTags(prev => {
      if (!prev.some(t => isSameTag(t, tag))) return prev;
      const next = prev.filter(t => !isSameTag(t, tag));
      safeDefer(() => deferSetAppMeta("pinned_tags", next));
      return next;
    });
    // 숨김 태그에서 제거
    setHiddenTags(prev => {
      if (!prev.some(t => isSameTag(t, tag))) return prev;
      const next = prev.filter(t => !isSameTag(t, tag));
      safeDefer(() => deferSetAppMeta("hidden_tags", next));
      return next;
    });
    // 감정 속성 제거
    setTagSentiments(prev => {
      const matchKey = Object.keys(prev).find(k => isSameTag(k, tag));
      if (!matchKey) return prev;
      const next = { ...prev };
      delete next[matchKey];
      safeDefer(() => deferSetAppMeta("tag_sentiments", next));
      return next;
    });
    // tagAttributes (isMajor/isSub/isTitle) 제거
    setTagAttributes(prev => {
      const matchKey = Object.keys(prev).find(k => isSameTag(k, tag));
      if (!matchKey) return prev;
      const next = { ...prev };
      delete next[matchKey];
      safeDefer(() => deferSetAppMeta("tag_attributes", next));
      return next;
    });
    // 🔧 v3.6.2: tag_relations (관계도/유사그룹)에서 제거
    setTagRelations(prev => {
      if (!prev || !prev.groups) return prev;
      const matchGroup = Object.keys(prev.tagToGroup || {}).find(k => isSameTag(k, tag));
      if (!matchGroup) return prev;
      const groupId = prev.tagToGroup[matchGroup];
      const group = prev.groups[groupId];
      if (!group) return prev;
      const newTags = group.tags.filter(t => !isSameTag(t, tag));
      const newGroups = { ...prev.groups };
      const newTagToGroup = { ...prev.tagToGroup };
      if (newTags.length <= 1) {
        // 그룹에 태그가 1개 이하면 그룹 자체 삭제
        delete newGroups[groupId];
        for (const t of (group.tags || [])) {
          const mk = Object.keys(newTagToGroup).find(k => isSameTag(k, t));
          if (mk) delete newTagToGroup[mk];
        }
      } else {
        newGroups[groupId] = { ...group, tags: newTags };
        delete newTagToGroup[matchGroup];
      }
      const updated = { groups: newGroups, tagToGroup: newTagToGroup };
      safeDefer(() => deferSetAppMeta("tag_relations", updated));
      return updated;
    });
    // 🔧 v3.6.2: coordinateSystems (좌표계)에서 제거
    setCoordinateSystems(prev => {
      if (!prev) return prev;
      let changed = false;
      const next = {};
      for (const [csId, cs] of Object.entries(prev)) {
        if (cs.tags) {
          const matchKey = Object.keys(cs.tags).find(k => isSameTag(k, tag));
          if (matchKey) {
            changed = true;
            const newTags = { ...cs.tags };
            delete newTags[matchKey];
            next[csId] = { ...cs, tags: newTags };
            continue;
          }
        }
        next[csId] = cs;
      }
      if (!changed) return prev;
      safeDefer(() => saveTagCoordinateSystems(next));
      return next;
    });
  }

  // 🔧 v3.5.9: 작품 저장 시 텍스트 입력 태그 → customTags 자동 동기화
  // 태그 관리 모달에서 보이지 않는 문제 근본 해결
  function syncTagsToCustom(tagsString) {
    if (!tagsString || !tagsString.trim() || !tagRegistry) return;
    const inputTags = tagsString.split(",").map(t => t.trim()).filter(Boolean);
    const allMajor = getAllMajorTags(tagAttributes, userMajorGenres);
    const allSub = getAllSubTags(tagAttributes, userSubGenres);
    const toAdd = inputTags.filter(tag => {
      if (ALL_DEFAULT_TAGS.some(t => isSameTag(t, tag))) return false;
      if (customTags.some(t => isSameTag(t, tag))) return false;
      if (allMajor.some(t => isSameTag(t, tag))) return false;
      if (allSub.some(t => isSameTag(t, tag))) return false;
      // 🆕 숨긴 태그는 자동 등록하지 않음
      if (hiddenTags.some(t => isSameTag(t, tag))) return false;
      return true;
    });
    if (toAdd.length === 0) return;
    const cat = "📁 사용자 태그";
    const newGeneralTags = { ...tagRegistry.generalTags };
    if (!newGeneralTags[cat]) newGeneralTags[cat] = [];
    const existing = newGeneralTags[cat];
    const reallyNew = toAdd.filter(t => !existing.some(e => isSameTag(e, t)));
    if (reallyNew.length === 0) return;
    newGeneralTags[cat] = [...existing, ...reallyNew];
    updateTagRegistry({ ...tagRegistry, generalTags: newGeneralTags });
  }

  async function removeCustomTag(tag) {
    removeTagFromRegistry(tag);
    await cleanupTagMetadata(tag); // 🔧 v3.5.9
  }

  // 🏷️ 커스텀 태그 직접 추가 (TagSelectModal에서 사용)
  // 🔧 v3.5.12: isSameTag로 공백 무시 중복 체크, comboTags 체크 제거
  async function addCustomTagDirect(tag) {
    if (!tag) return;
    if (customTags.some(t => isSameTag(t, tag)) || ALL_DEFAULT_TAGS.some(t => isSameTag(t, tag)) || userMajorGenres.some(t => isSameTag(t, tag)) || userSubGenres.some(t => isSameTag(t, tag))) {
      Alert.alert("알림", "이미 존재하는 태그입니다.");
      return;
    }
    addTagToRegistry(tag);
  }

  // 🔗 조합식 태그 추가
  // 🔧 v3.5.12: 조합식 태그 분류 폐지 — addComboTag는 customTags에 추가
  async function addComboTag(comboTag) {
    if (!comboTag) return;
    // 공백 무시 중복 체크
    if (customTags.some(t => isSameTag(t, comboTag))) {
      Alert.alert("알림", "이미 존재하는 태그입니다.");
      return;
    }
    addTagToRegistry(comboTag);
  }

  // 🔧 v3.5.12: 조합식 분류 폐지 — removeComboTag은 removeCustomTag으로 위임
  async function removeComboTag(comboTag) {
    await removeCustomTag(comboTag);
  }

  // 🔗 v3.0.4: 조합 요소(특성) 추가
  async function addCustomComboTrait(trait) {
    const t = (trait || "").trim();
    if (!t) return;
    if (COMBO_TAG_TRAITS.includes(t) || customComboTraits.includes(t)) {
      Alert.alert("알림", "이미 존재하는 특성입니다.");
      return;
    }
    const newList = [...customComboTraits, t];
    setCustomComboTraits(newList);
    await setAppMeta("custom_combo_traits", newList);
  }

  // 🔗 v3.0.4: 조합 요소(특성) 삭제
  async function removeCustomComboTrait(trait) {
    if (COMBO_TAG_TRAITS.includes(trait)) {
      Alert.alert("알림", "기본 특성은 삭제할 수 없습니다.");
      return;
    }
    const newList = customComboTraits.filter(t => t !== trait);
    setCustomComboTraits(newList);
    await setAppMeta("custom_combo_traits", newList);
  }

  // 🔗 v3.0.4: 조합 요소(대상) 추가
  async function addCustomComboTarget(target) {
    const t = (target || "").trim();
    if (!t) return;
    if (COMBO_TAG_TARGETS.includes(t) || customComboTargets.includes(t)) {
      Alert.alert("알림", "이미 존재하는 대상입니다.");
      return;
    }
    const newList = [...customComboTargets, t];
    setCustomComboTargets(newList);
    await setAppMeta("custom_combo_targets", newList);
  }

  // 🔗 v3.0.4: 조합 요소(대상) 삭제
  async function removeCustomComboTarget(target) {
    if (COMBO_TAG_TARGETS.includes(target)) {
      Alert.alert("알림", "기본 대상은 삭제할 수 없습니다.");
      return;
    }
    const newList = customComboTargets.filter(t => t !== target);
    setCustomComboTargets(newList);
    await setAppMeta("custom_combo_targets", newList);
  }

  // 🏷️ 사용자 대장르 삭제
  async function removeUserMajorGenre(genre) {
    if (tagRegistry) {
      updateTagRegistry({...tagRegistry, majorGenres: (tagRegistry.majorGenres || []).filter(t => !isSameTag(t, genre))});
    }
  }

  // 🏷️ 사용자 부장르 삭제
  async function removeUserSubGenre(genre) {
    if (tagRegistry) {
      updateTagRegistry({...tagRegistry, subGenres: (tagRegistry.subGenres || []).filter(t => !isSameTag(t, genre))});
    }
  }

  // 🏷️ 중복 태그 정리 (전체 태그에서 중복 제거)
  // 🔧 v3.5.15b: 작품별 DB 데이터 중복도 일괄 정리 추가
  async function cleanupDuplicateTags() {
    setIsLoading(true);
    try {
      let metaFixed = 0;

      // 🔧 v3.6.1: registry 단일 중복 제거 (구 state는 자동 파생)
      if (tagRegistry) {
        const newRegistry = { ...tagRegistry };
        newRegistry.majorGenres = deduplicateTags(newRegistry.majorGenres || []);
        newRegistry.subGenres = deduplicateTags(newRegistry.subGenres || []);
        const newGeneral = {};
        for (const [cat, tags] of Object.entries(newRegistry.generalTags || {})) {
          const deduped = deduplicateTags(tags);
          if (deduped.length > 0) newGeneral[cat] = deduped;
        }
        newRegistry.generalTags = newGeneral;
        // Count how many were removed
        const oldTotal = (tagRegistry.majorGenres || []).length + (tagRegistry.subGenres || []).length + Object.values(tagRegistry.generalTags || {}).flat().length;
        const newTotal = newRegistry.majorGenres.length + newRegistry.subGenres.length + Object.values(newRegistry.generalTags).flat().length;
        metaFixed = oldTotal - newTotal;
        if (metaFixed > 0) updateTagRegistry(newRegistry);
      }

      // 🔧 v3.5.15b: 작품별 DB 데이터 중복도 일괄 정리
      const novelResult = await deduplicateExistingNovelTags();

      if (novelResult.fixed > 0) {
        await loadList(undefined, undefined, "dedup");
      }

      const msgs = [];
      if (metaFixed > 0) msgs.push(`태그 목록에서 ${metaFixed}개 중복 제거`);
      if (novelResult.fixed > 0) msgs.push(`${novelResult.fixed}개 작품의 중복 태그 정리`);

      Alert.alert("완료", msgs.length > 0
        ? `중복 태그 정리 완료!\n${msgs.join("\n")}`
        : "중복 태그가 없습니다.");
    } catch (e) {
      console.warn("cleanupDuplicateTags 오류:", e);
      Alert.alert("오류", "중복 태그 정리 중 오류가 발생했습니다.\n" + (e.message || e));
    }
    setIsLoading(false);
  }

  // ═══════════════════════════════════════════════════════════════
  // 🏷️ 태그 관리 고급 함수 (v2.3)
  // ═══════════════════════════════════════════════════════════════

  // 상단 고정 태그 로드 → 메인 초기화 Promise.all로 이동 (슬롯 경쟁 조건 방지)

  async function savePinnedTags(tags) {
    setPinnedTags(tags);
    await setAppMeta("pinned_tags", tags);
  }

  // 숨김 태그 로드 → 메인 초기화 Promise.all에서 처리 (슬롯 경쟁 조건 방지)

  // 🏆 검토 탭 전환 시 선택 초기화
  useEffect(() => {
    if (screen !== "review") {
      setReviewSelectedIds([]);
    }
  }, [screen]);

  async function saveHiddenTags(tags) {
    setHiddenTags(tags);
    await setAppMeta("hidden_tags", tags);
  }

  // 🔧 v3.5.16: 태그 정렬 모드 → 메인 초기화에서 로드 (슬롯 경쟁 조건 방지)

  function handleChangeTagSortMode(mode) {
    setTagSortMode(mode);
    setAppMeta("tag_sort_mode", mode);
  }

  // 🔧 v3.5.16: 마지막 사용 탭 → 메인 초기화에서 로드 (슬롯 경쟁 조건 방지)

  function handleChangeTagLastTab(tab) {
    setTagLastTab(tab);
    setAppMeta("tag_last_tab", tab);
  }

  function handleChangeTagPreviewExpanded(expanded) {
    setTagPreviewExpanded(expanded);
    setAppMeta("tag_preview_expanded", expanded);
  }

  // ═══════════════════════════════════════════════════════════════
  // 🔧 v3.6.0: Tag Registry — 모든 태그의 유일한 저장소
  // ═══════════════════════════════════════════════════════════════

  /** 단일 진입점: 모듈 변수 + React state + 영구 저장을 항상 함께 수행 */
  function updateTagRegistry(registry) {
    applyTagRegistry(registry);
    setTagRegistry(registry);
    setAppMeta("tag_registry", registry);
  }

  /** 앱 시작 시 레지스트리 로드 (없으면 시드) */
  async function loadTagRegistry() {
    let registry = await getAppMeta("tag_registry");
    if (!registry) {
      registry = await seedTagRegistry();
      await setAppMeta("tag_registry", registry);
      // 시드 완료 후 deprecated 키 정리
      await setAppMeta("custom_tags", null);
      await setAppMeta("user_major_genres", null);
      await setAppMeta("user_sub_genres", null);
      await setAppMeta("custom_tag_categories", null);
    }
    updateTagRegistry(registry);
    return registry; // 🔧 v3.6.1: 호출자가 React 배치 업데이트 전에도 사용 가능
  }

  /* =========================================================
     📱 플랫폼 레지스트리 CRUD (태그 레지스트리 패턴 답습)
     ========================================================= */
  function updatePlatformRegistry(registry) {
    applyPlatformRegistry(registry);
    setPlatformRegistry(registry);
    setAppMeta("platform_registry", registry);
  }

  async function loadPlatformRegistry() {
    let registry = await getAppMeta("platform_registry");
    if (!registry) {
      // 첫 실행: factory 기본값으로 시드
      registry = {
        version: 1,
        platforms: [...FACTORY_PLATFORM_OPTIONS],
        urls: { ...FACTORY_PLATFORM_URLS },
      };
      await setAppMeta("platform_registry", registry);
    }
    applyPlatformRegistry(registry);
    setPlatformRegistry(registry);
    return registry;
  }

  function addPlatform(name) {
    const trimmed = (name || "").trim();
    if (!trimmed) return false;
    if (PLATFORM_OPTIONS.some(p => p === trimmed)) {
      Alert.alert("알림", "이미 존재하는 플랫폼입니다.");
      return false;
    }
    const reg = platformRegistry || { version: 1, platforms: [...FACTORY_PLATFORM_OPTIONS], urls: {} };
    updatePlatformRegistry({
      ...reg,
      platforms: [...reg.platforms, trimmed],
    });
    return true;
  }

  function removePlatform(name) {
    const reg = platformRegistry;
    if (!reg) return;
    const isFactory = FACTORY_PLATFORM_OPTIONS.includes(name);
    Alert.alert(
      isFactory ? "기본 플랫폼 숨기기" : "플랫폼 삭제",
      isFactory
        ? `"${name}" 기본 플랫폼을 목록에서 숨길까요?\n\n기존 작품의 데이터는 보존되며, "기본값으로 초기화"로 복원할 수 있습니다.`
        : `"${name}" 플랫폼을 목록에서 삭제할까요?\n\n기존 작품의 플랫폼 데이터는 보존됩니다.`,
      [
        { text: "취소" },
        {
          text: isFactory ? "숨기기" : "삭제", style: "destructive",
          onPress: () => {
            const newUrls = { ...reg.urls };
            delete newUrls[name];
            updatePlatformRegistry({
              ...reg,
              platforms: reg.platforms.filter(p => p !== name),
              urls: newUrls,
            });
            // 필터가 삭제된 플랫폼이면 리셋
            if (filterPlatform === name) setFilterPlatform("ALL");
            if (plannedFilterPlatform === name) setPlannedFilterPlatform("ALL");
          },
        },
      ]
    );
  }

  function resetPlatformsToFactory() {
    Alert.alert(
      "초기화",
      "플랫폼 목록을 기본값으로 초기화할까요?",
      [
        { text: "취소" },
        {
          text: "초기화", style: "destructive",
          onPress: () => {
            updatePlatformRegistry({
              version: 1,
              platforms: [...FACTORY_PLATFORM_OPTIONS],
              urls: { ...FACTORY_PLATFORM_URLS },
            });
          },
        },
      ]
    );
  }

  /** 첫 실행 시드: FACTORY + 기존 사용자 데이터 병합 */
  async function seedTagRegistry() {
    // React state가 아닌 app_meta에서 직접 로드 (로딩 순서 의존성 제거)
    const existingMajor = (await getAppMeta("user_major_genres")) || [];
    const existingSub = (await getAppMeta("user_sub_genres")) || [];
    const existingCats = (await getAppMeta("custom_tag_categories")) || {};
    const existingCustom = (await getAppMeta("custom_tags")) || [];

    // 기존 커스텀 카테고리 + 미분류 커스텀 태그를 generalTags에 통합
    const mergedGeneral = { ...FACTORY_GENERAL_TAGS };
    // 기존 커스텀 카테고리 병합
    if (existingCats && typeof existingCats === "object") {
      for (const [catName, catTags] of Object.entries(existingCats)) {
        if (Array.isArray(catTags) && catTags.length > 0) {
          mergedGeneral[`📂 ${catName}`] = deduplicateTags(catTags);
        }
      }
    }
    // 기존 커스텀 태그 → "📁 사용자 태그" 카테고리
    if (existingCustom.length > 0) {
      mergedGeneral["📁 사용자 태그"] = deduplicateTags(existingCustom);
    }

    return {
      version: 1,
      majorGenres: deduplicateTags([...FACTORY_MAJOR_GENRES, ...existingMajor]),
      subGenres: deduplicateTags([...FACTORY_SUB_GENRES, ...existingSub]),
      generalTags: mergedGeneral,
      characterCategories: { ...FACTORY_CHARACTER_CATEGORIES },
      aliases: { ...FACTORY_TAG_ALIASES },
      spectrumGroups: { ...FACTORY_TAG_SPECTRUM_GROUPS },
      // 🆕 카테고리 관리 필드 초기화
      hiddenCategories: [],
      categoryAliases: {},
      userCategories: [],
    };
  }

  /** 프리셋 초기화: FACTORY 기본값으로 전체 교체 */
  function resetTagRegistryToFactory() {
    updateTagRegistry({
      version: 1,
      majorGenres: [...FACTORY_MAJOR_GENRES],
      subGenres: [...FACTORY_SUB_GENRES],
      generalTags: { ...FACTORY_GENERAL_TAGS },
      characterCategories: { ...FACTORY_CHARACTER_CATEGORIES },
      aliases: { ...FACTORY_TAG_ALIASES },
      spectrumGroups: { ...FACTORY_TAG_SPECTRUM_GROUPS },
      // 🆕 카테고리 관리 필드 리셋
      hiddenCategories: [],
      categoryAliases: {},
      userCategories: [],
    });
  }

  /** 🔧 v6.0.1: 함수형 업데이트 기반 registry 변경 (stale closure 방지) */
  /** 🔧 모듈 변수는 즉시 갱신 (렌더링 시 최신 값 참조 보장), DB만 safeDefer */
  function updateTagRegistryFn(updaterFn) {
    let nextResult = null;
    setTagRegistry(prev => {
      if (!prev) return prev;
      const next = updaterFn(prev);
      if (next === prev) return prev;
      nextResult = next;
      return next;
    });
    // 부수효과: updater 밖에서 실행 (saveAppSettings과 동일 패턴)
    if (nextResult) {
      applyTagRegistry(nextResult); // 모듈 변수 즉시 갱신 (GENERAL_TAGS, ALL_DEFAULT_TAGS 등)
      safeDefer(() => setAppMeta("tag_registry", nextResult)); // DB만 비동기
    }
  }

  /** 레지스트리에 태그 추가 (카테고리 미지정 시 "📁 사용자 태그") */
  function addTagToRegistry(tag, category = "📁 사용자 태그") {
    if (!tag) return;
    if (ALL_DEFAULT_TAGS.some(t => isSameTag(t, tag))) return;
    updateTagRegistryFn(prev => {
      const newGeneralTags = { ...prev.generalTags };
      if (!newGeneralTags[category]) newGeneralTags[category] = [];
      // 이미 있으면 무시
      if (newGeneralTags[category].some(t => isSameTag(t, tag))) return prev;
      newGeneralTags[category] = [...newGeneralTags[category], tag];
      return { ...prev, generalTags: newGeneralTags };
    });
  }

  /** 레지스트리에서 태그 제거 (모든 카테고리에서 검색하여 제거) */
  function removeTagFromRegistry(tag) {
    if (!tag) return;
    updateTagRegistryFn(prev => {
      const newRegistry = { ...prev };
      newRegistry.majorGenres = newRegistry.majorGenres.filter(t => !isSameTag(t, tag));
      newRegistry.subGenres = newRegistry.subGenres.filter(t => !isSameTag(t, tag));
      const newGeneral = {};
      const userCats = newRegistry.userCategories || [];
      for (const [cat, tags] of Object.entries(newRegistry.generalTags)) {
        const filtered = tags.filter(t => !isSameTag(t, tag));
        // 🆕 userCategories에 있는 카테고리는 빈 배열이어도 보존
        if (filtered.length > 0 || userCats.includes(cat)) {
          newGeneral[cat] = filtered;
        }
      }
      newRegistry.generalTags = newGeneral;
      return newRegistry;
    });
  }

  /** 🆕 레지스트리에서 다수 태그 일괄 제거 (1회 updateTagRegistryFn = 1회 DB write) */
  function batchRemoveTagsFromRegistry(tagsToRemove) {
    if (!tagsToRemove || tagsToRemove.length === 0) return;
    updateTagRegistryFn(prev => {
      const newRegistry = { ...prev };
      const shouldRemove = (t) => tagsToRemove.some(d => isSameTag(t, d));
      newRegistry.majorGenres = newRegistry.majorGenres.filter(t => !shouldRemove(t));
      newRegistry.subGenres = newRegistry.subGenres.filter(t => !shouldRemove(t));
      const newGeneral = {};
      const userCats = newRegistry.userCategories || [];
      for (const [cat, tags] of Object.entries(newRegistry.generalTags)) {
        const filtered = tags.filter(t => !shouldRemove(t));
        if (filtered.length > 0 || userCats.includes(cat)) {
          newGeneral[cat] = filtered;
        }
      }
      newRegistry.generalTags = newGeneral;
      return newRegistry;
    });
  }

  /** 🆕 다수 태그의 메타데이터 일괄 정리 (4회 setState + 4회 deferSetAppMeta만) */
  function cleanupTagMetadataBatch(tagsToClean) {
    if (!tagsToClean || tagsToClean.length === 0) return;
    const shouldClean = (t) => tagsToClean.some(d => isSameTag(t, d));
    const shouldCleanKey = (k) => tagsToClean.some(d => isSameTag(k, d));

    setPinnedTags(prev => {
      if (!prev.some(t => shouldClean(t))) return prev;
      const next = prev.filter(t => !shouldClean(t));
      safeDefer(() => deferSetAppMeta("pinned_tags", next));
      return next;
    });
    setHiddenTags(prev => {
      if (!prev.some(t => shouldClean(t))) return prev;
      const next = prev.filter(t => !shouldClean(t));
      safeDefer(() => deferSetAppMeta("hidden_tags", next));
      return next;
    });
    setTagSentiments(prev => {
      const matchKeys = Object.keys(prev).filter(k => shouldCleanKey(k));
      if (matchKeys.length === 0) return prev;
      const next = { ...prev };
      for (const k of matchKeys) delete next[k];
      safeDefer(() => deferSetAppMeta("tag_sentiments", next));
      return next;
    });
    setTagAttributes(prev => {
      const matchKeys = Object.keys(prev).filter(k => shouldCleanKey(k));
      if (matchKeys.length === 0) return prev;
      const next = { ...prev };
      for (const k of matchKeys) delete next[k];
      safeDefer(() => deferSetAppMeta("tag_attributes", next));
      return next;
    });
    // 🔧 v3.6.2: tag_relations (관계도/유사그룹)에서 배치 제거
    setTagRelations(prev => {
      if (!prev || !prev.groups) return prev;
      const newGroups = { ...prev.groups };
      const newTagToGroup = { ...prev.tagToGroup };
      let changed = false;
      for (const tag of tagsToClean) {
        const matchKey = Object.keys(newTagToGroup).find(k => isSameTag(k, tag));
        if (!matchKey) continue;
        changed = true;
        const groupId = newTagToGroup[matchKey];
        const group = newGroups[groupId];
        if (!group) { delete newTagToGroup[matchKey]; continue; }
        const newTags = group.tags.filter(t => !isSameTag(t, tag));
        if (newTags.length <= 1) {
          for (const t of (group.tags || [])) {
            const mk = Object.keys(newTagToGroup).find(k => isSameTag(k, t));
            if (mk) delete newTagToGroup[mk];
          }
          delete newGroups[groupId];
        } else {
          newGroups[groupId] = { ...group, tags: newTags };
          delete newTagToGroup[matchKey];
        }
      }
      if (!changed) return prev;
      const updated = { groups: newGroups, tagToGroup: newTagToGroup };
      safeDefer(() => deferSetAppMeta("tag_relations", updated));
      return updated;
    });
    // 🔧 v3.6.2: coordinateSystems (좌표계)에서 배치 제거
    setCoordinateSystems(prev => {
      if (!prev) return prev;
      let changed = false;
      const next = {};
      for (const [csId, cs] of Object.entries(prev)) {
        if (cs.tags) {
          const matchKeys = Object.keys(cs.tags).filter(k => shouldCleanKey(k));
          if (matchKeys.length > 0) {
            changed = true;
            const newTags = { ...cs.tags };
            for (const mk of matchKeys) delete newTags[mk];
            next[csId] = { ...cs, tags: newTags };
            continue;
          }
        }
        next[csId] = cs;
      }
      if (!changed) return prev;
      safeDefer(() => saveTagCoordinateSystems(next));
      return next;
    });
  }

  // ═══════════════════════════════════════════════════════════════
  // 🆕 카테고리 관리 CRUD
  // ═══════════════════════════════════════════════════════════════

  function renameCategory(oldName, newName) {
    if (!oldName || !newName || oldName === newName) return;
    updateTagRegistryFn(prev => {
      const aliases = { ...(prev.categoryAliases || {}) };
      aliases[oldName] = newName.trim();
      return { ...prev, categoryAliases: aliases };
    });
  }

  function toggleHideCategory(name) {
    if (!name) return;
    updateTagRegistryFn(prev => {
      const hidden = [...(prev.hiddenCategories || [])];
      const idx = hidden.indexOf(name);
      if (idx >= 0) {
        hidden.splice(idx, 1);
      } else {
        hidden.push(name);
      }
      return { ...prev, hiddenCategories: hidden };
    });
  }

  function addCategory(name) {
    const trimmed = (name || "").trim();
    if (!trimmed) return false;
    updateTagRegistryFn(prev => {
      const generalTags = { ...(prev.generalTags || {}) };
      if (generalTags[trimmed]) return prev; // 이미 존재
      generalTags[trimmed] = [];
      const userCats = [...(prev.userCategories || [])];
      if (!userCats.includes(trimmed)) userCats.push(trimmed);
      return { ...prev, generalTags, userCategories: userCats };
    });
    return true;
  }

  function deleteCategory(name) {
    if (!name) return;
    // "📁 사용자 태그"는 기본 카테고리이므로 삭제 불가
    if (name === "📁 사용자 태그") return;
    updateTagRegistryFn(prev => {
      const generalTags = { ...(prev.generalTags || {}) };
      const tagsToMove = generalTags[name] || [];
      delete generalTags[name];

      // 소속 태그를 "📁 사용자 태그"로 이동 (중복 제거)
      const targetCat = "📁 사용자 태그";
      if (!generalTags[targetCat]) generalTags[targetCat] = [];
      const existing = generalTags[targetCat];
      for (const tag of tagsToMove) {
        if (!existing.some(e => isSameTag(e, tag))) {
          existing.push(tag);
        }
      }
      generalTags[targetCat] = existing;

      // userCategories에서 제거
      const userCats = (prev.userCategories || []).filter(c => c !== name);
      // hiddenCategories에서 제거
      const hiddenCats = (prev.hiddenCategories || []).filter(c => c !== name);
      // categoryAliases에서 제거
      const aliases = { ...(prev.categoryAliases || {}) };
      delete aliases[name];

      return { ...prev, generalTags, userCategories: userCats, hiddenCategories: hiddenCats, categoryAliases: aliases };
    });
  }

  function moveTagToCategory(tag, toCat) {
    if (!tag || !toCat) return;
    updateTagRegistryFn(prev => {
      const generalTags = { ...(prev.generalTags || {}) };

      // 모든 카테고리에서 태그 제거
      for (const [cat, tags] of Object.entries(generalTags)) {
        generalTags[cat] = tags.filter(t => !isSameTag(t, tag));
      }

      // 대상 카테고리에 추가
      if (!generalTags[toCat]) generalTags[toCat] = [];
      if (!generalTags[toCat].some(t => isSameTag(t, tag))) {
        generalTags[toCat] = [...generalTags[toCat], tag];
      }

      // 빈 카테고리 정리 (userCategories에 있는 건 보존)
      const userCats = prev.userCategories || [];
      for (const [cat, tags] of Object.entries(generalTags)) {
        if (tags.length === 0 && !userCats.includes(cat)) {
          delete generalTags[cat];
        }
      }

      return { ...prev, generalTags };
    });
  }

  // 🎭 v2.8: 태그 속성 저장
  async function saveTagSentiments(sentiments) {
    setTagSentiments(sentiments);
    await setAppMeta("tag_sentiments", sentiments);
  }

  // 🎭 v2.8: 태그 속성 변경
  async function setTagSentiment(tag, sentiment) {
    const updated = { ...tagSentiments, [tag]: sentiment };
    // 기본값이면 삭제 (저장 공간 절약)
    if (sentiment === TAG_SENTIMENT.NEUTRAL && !DEFAULT_TAG_SENTIMENTS[tag]) {
      delete updated[tag];
    }
    await saveTagSentiments(updated);
  }

  // 🎭 v2.8: 태그의 실제 속성 가져오기
  function getActualTagSentiment(tag) {
    return getTagSentiment(tag, tagSentiments);
  }

  // 🆕 v3.4: 태그 속성(대장르/부장르) 저장
  async function saveTagAttributes(attrs) {
    setTagAttributes(attrs);
    await setAppMeta("tag_attributes", attrs);
  }

  // 🆕 v3.4: 태그 대장르 속성 토글
  async function toggleTagMajor(tag) {
    const current = isTagMajor(tag, tagAttributes, userMajorGenres);
    const updated = { 
      ...tagAttributes, 
      [tag]: { ...tagAttributes[tag], isMajor: !current } 
    };
    await saveTagAttributes(updated);
  }

  // 🆕 v3.4: 태그 부장르 속성 토글
  async function toggleTagSub(tag) {
    const current = isTagSub(tag, tagAttributes, userSubGenres);
    const updated = { 
      ...tagAttributes, 
      [tag]: { ...tagAttributes[tag], isSub: !current } 
    };
    await saveTagAttributes(updated);
  }

  // 🆕 v3.4: 특정 태그가 대장르인지 확인
  function checkIsTagMajor(tag) {
    return isTagMajor(tag, tagAttributes, userMajorGenres);
  }

  // 🆕 v3.4: 특정 태그가 부장르인지 확인
  function checkIsTagSub(tag) {
    return isTagSub(tag, tagAttributes, userSubGenres);
  }

  // 🔧 v3.5.9: 작품명 태그 토글 (TagSelectModal 롱프레스에서 사용)
  async function toggleTagTitle(tag) {
    const current = isTagTitle(tag, tagAttributes);
    const updated = {
      ...tagAttributes,
      [tag]: { ...tagAttributes[tag], isTitle: !current }
    };
    await saveTagAttributes(updated);
  }

  // 태그 숨김 토글
  async function toggleHideTag(tag) {
    // 🔧 v3.5.8: 함수형 업데이트로 stale closure 방지
    // 🔧 v3.5.15b: isSameTag로 공백/alias 변형 일관 비교
    setHiddenTags(prev => {
      const next = prev.some(t => isSameTag(t, tag)) ? prev.filter(t => !isSameTag(t, tag)) : [...prev, tag];
      setAppMeta("hidden_tags", next);
      return next;
    });
  }

  // 태그 상단 고정 토글
  async function togglePinTag(tag) {
    // 🔧 v3.5.8: 함수형 업데이트로 stale closure 방지
    // 🔧 v3.5.15b: isSameTag로 공백/alias 변형 일관 비교
    setPinnedTags(prev => {
      const next = prev.some(t => isSameTag(t, tag)) ? prev.filter(t => !isSameTag(t, tag)) : [...prev, tag];
      setAppMeta("pinned_tags", next);
      return next;
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 🆕 Phase 1: TagEditModal 통합 지원 함수들 (v3.2.1)
  // ═══════════════════════════════════════════════════════════════════════════
  
  /**
   * 태그 사용 현황 통계 계산
   * @param {string} tag - 태그명
   * @returns {{ count: number, avgIntensity: number, avgRating: number }}
   */
  function getTagUsageStats(tag) {
    if (!tag || !list || list.length === 0) {
      return { count: 0, avgIntensity: null, avgRating: null };
    }
    
    const normalizedTag = normalizeTag(tag);
    let count = 0;
    let totalIntensity = 0;
    let intensityCount = 0;
    let totalRating = 0;
    
    for (const novel of list) {
      // tag_data에서 찾기
      if (novel.tag_data) {
        try {
          const tagData = JSON.parse(novel.tag_data);
          const found = tagData.find(td => normalizeTag(td.tag) === normalizedTag);
          if (found) {
            count++;
            if (found.intensity) {
              totalIntensity += found.intensity;
              intensityCount++;
            }
            totalRating += novel.rating || 1500;
            continue;
          }
        } catch (e) {}
      }
      
      // 기존 tags 필드에서 찾기
      // 🔧 v3.5.15b: isSameTag로 공백/alias 변형 일관 비교
      if (novel.tags) {
        const tags = novel.tags.split(",").map(t => t.trim()).filter(Boolean);
        if (tags.some(t => isSameTag(t, tag))) {
          count++;
          totalRating += novel.rating || 1500;
        }
      }
    }
    
    return {
      count,
      avgIntensity: intensityCount > 0 ? totalIntensity / intensityCount : null,
      avgRating: count > 0 ? totalRating / count : null,
    };
  }
  
  /**
   * TagEditModal 일괄 저장 핸들러
   * @param {string} tag - 태그명
   * @param {{ pinned?: boolean, hidden?: boolean, sentiment?: string }} changes - 변경사항
   */
  async function handleTagEditModalSave(tag, changes) {
    try {
      // 고정 상태 변경
      // 🔧 v3.5.11: 함수형 업데이트로 stale closure 방지
      // 🔧 v3.5.15b: isSameTag로 공백/alias 변형 일관 비교
      if (changes.pinned !== undefined) {
        setPinnedTags(prev => {
          const isPinned = prev.some(t => isSameTag(t, tag));
          if (changes.pinned && !isPinned) {
            const next = [...prev, tag];
            safeDefer(() => setAppMeta("pinned_tags", next));
            return next;
          } else if (!changes.pinned && isPinned) {
            const next = prev.filter(t => !isSameTag(t, tag));
            safeDefer(() => setAppMeta("pinned_tags", next));
            return next;
          }
          return prev;
        });
      }
      
      // 숨김 상태 변경
      // 🔧 v3.5.11: 함수형 업데이트로 stale closure 방지
      // 🔧 v3.5.15b: isSameTag로 공백/alias 변형 일관 비교
      if (changes.hidden !== undefined) {
        setHiddenTags(prev => {
          const isHidden = prev.some(t => isSameTag(t, tag));
          if (changes.hidden && !isHidden) {
            const next = [...prev, tag];
            safeDefer(() => setAppMeta("hidden_tags", next));
            return next;
          } else if (!changes.hidden && isHidden) {
            const next = prev.filter(t => !isSameTag(t, tag));
            safeDefer(() => setAppMeta("hidden_tags", next));
            return next;
          }
          return prev;
        });
      }
      
      // 🔧 v6.0.1: 속성(감정) 변경 — 함수형 업데이트로 stale closure 방지
      // 부수효과(setAppMeta)는 updater 외부에서 실행 (React 순수성 보장)
      if (changes.sentiment !== undefined) {
        const newSentiment = changes.sentiment || null;
        setTagSentiments(prev => {
          const currentSentiment = getTagSentiment(tag, prev);
          if (newSentiment === currentSentiment) return prev;
          const updated = { ...prev };
          if (newSentiment === null) {
            delete updated[tag];
          } else {
            updated[tag] = newSentiment;
          }
          // 🔧 React 18+ 배칭 대응: setTimeout으로 렌더 이후 저장
          safeDefer(() => setAppMeta("tag_sentiments", updated));
          return updated;
        });
      }

      // 🔧 v6.0.1: 작품명 태그 속성 변경 — 함수형 업데이트로 stale closure 방지
      if (changes.isTitle !== undefined) {
        setTagAttributes(prev => {
          const currentIsTitle = !!(prev[tag]?.isTitle);
          if (changes.isTitle === currentIsTitle) return prev; // 변경 없으면 early return
          const attrs = { ...prev };
          if (changes.isTitle) {
            attrs[tag] = { ...(attrs[tag] || {}), isTitle: true };
          } else {
            if (attrs[tag]) {
              delete attrs[tag].isTitle;
              if (Object.keys(attrs[tag]).length === 0) delete attrs[tag];
            }
          }
          // 🔧 React 18+ 배칭 대응: setTimeout으로 렌더 이후 저장
          safeDefer(() => setAppMeta("tag_attributes", attrs));
          return attrs;
        });
      }
    } catch (e) {
      console.warn("handleTagEditModalSave error:", e);
    }
  }
  
  /**
   * 좌표계 편집 모달 열기 (TagEditModal에서 호출)
   * @param {string} tag - 태그명
   * @param {string|null} systemId - 특정 좌표계 ID (null이면 선택 화면)
   */
  function handleEditCoordinate(tag, systemId) {
    // 태그 편집 모달 닫기
    setTagEditModalOpen(false);
    setEditingTag(null);
    
    if (systemId && coordinateSystems[systemId]) {
      // 특정 좌표계 편집
      setEditingCoordSystem({ id: systemId, ...coordinateSystems[systemId] });
      setEditingCoordTag(tag);
    } else {
      // 좌표계 선택 화면 (전체 목록)
      // 첫 번째 좌표계를 열거나 기본값
      const firstSystemId = Object.keys(coordinateSystems)[0];
      if (firstSystemId) {
        setEditingCoordSystem({ id: firstSystemId, ...coordinateSystems[firstSystemId] });
        setEditingCoordTag(tag);
      }
    }
    deferOpen(setCoordManageOpen); // 🔧 v3.5.8
  }

  // 태그에 대장르 속성 추가 (기존 위치에서 제거하지 않음)
  // 🔧 stale closure 방지: updateTagRegistryFn(함수형 업데이트) 사용
  async function promoteToMajorGenre(tag) {
    if (listHasTag(MAJOR_GENRES, tag) || listHasTag(userMajorGenres, tag)) {
      Alert.alert("알림", "이미 대장르 속성이 있습니다.");
      return;
    }
    updateTagRegistryFn(prev => {
      if (prev.majorGenres.some(t => isSameTag(t, tag))) return prev;
      return { ...prev, majorGenres: [...prev.majorGenres, tag] };
    });
    Alert.alert("완료", `"${tag}"에 대장르 속성을 추가했습니다.`);
  }

  // 태그에 부장르 속성 추가 (기존 위치에서 제거하지 않음)
  // 🔧 stale closure 방지: updateTagRegistryFn(함수형 업데이트) 사용
  async function promoteToSubGenre(tag) {
    if (listHasTag(SUB_GENRES, tag) || listHasTag(userSubGenres, tag)) {
      Alert.alert("알림", "이미 부장르 속성이 있습니다.");
      return;
    }
    updateTagRegistryFn(prev => {
      if (prev.subGenres.some(t => isSameTag(t, tag))) return prev;
      return { ...prev, subGenres: [...prev.subGenres, tag] };
    });
    Alert.alert("완료", `"${tag}"에 부장르 속성을 추가했습니다.`);
  }

  // 조합식 태그 → 일반 태그로 변환
  // 🔧 v3.5.12: 조합→커스텀 변환 불필요 (이미 통합됨)
  async function comboToCustomTag(comboTag) {
    Alert.alert("알림", `"${comboTag}"는 이미 커스텀 태그입니다.`);
  }

  // 대장르 속성 제거
  async function demoteMajorToCustom(genre) {
    // 기본 대장르는 제거 불가 — 단, 레지스트리 전환 후에는 모든 장르가 편집 가능
    if (listHasTag(MAJOR_GENRES, genre) && !(tagRegistry && tagRegistry.majorGenres.some(t => isSameTag(t, genre)))) {
      Alert.alert("알림", "기본 제공 대장르는 속성을 제거할 수 없습니다.");
      return;
    }
    // 🔧 stale closure 방지: updateTagRegistryFn(함수형 업데이트) 사용
    updateTagRegistryFn(prev => {
      const filtered = prev.majorGenres.filter(t => !isSameTag(t, genre));
      if (filtered.length === prev.majorGenres.length) return prev;
      return { ...prev, majorGenres: filtered };
    });
    // 🔧 v3.5.9: tagAttributes.isMajor도 함께 제거 (잔존 방지, 함수형 setState)
    // 🔧 React 18+ 배칭 대응: setTimeout으로 부수효과 실행
    setTagAttributes(prev => {
      if (!prev[genre]?.isMajor) return prev;
      const updated = { ...prev, [genre]: { ...prev[genre] } };
      delete updated[genre].isMajor;
      if (Object.keys(updated[genre]).length === 0) delete updated[genre];
      safeDefer(() => deferSetAppMeta("tag_attributes", updated));
      return updated;
    });
    Alert.alert("완료", `"${genre}"의 대장르 속성을 제거했습니다.`);
  }

  // 부장르 속성 제거
  async function demoteSubToCustom(genre) {
    // 기본 부장르는 제거 불가 — 단, 레지스트리 전환 후에는 모든 장르가 편집 가능
    if (listHasTag(SUB_GENRES, genre) && !(tagRegistry && tagRegistry.subGenres.some(t => isSameTag(t, genre)))) {
      Alert.alert("알림", "기본 제공 부장르는 속성을 제거할 수 없습니다.");
      return;
    }
    // 🔧 stale closure 방지: updateTagRegistryFn(함수형 업데이트) 사용
    updateTagRegistryFn(prev => {
      const filtered = prev.subGenres.filter(t => !isSameTag(t, genre));
      if (filtered.length === prev.subGenres.length) return prev;
      return { ...prev, subGenres: filtered };
    });
    // 🔧 v3.5.9: tagAttributes.isSub도 함께 제거 (잔존 방지, 함수형 setState)
    // 🔧 React 18+ 배칭 대응: setTimeout으로 부수효과 실행
    setTagAttributes(prev => {
      if (!prev[genre]?.isSub) return prev;
      const updated = { ...prev, [genre]: { ...prev[genre] } };
      delete updated[genre].isSub;
      if (Object.keys(updated[genre]).length === 0) delete updated[genre];
      safeDefer(() => deferSetAppMeta("tag_attributes", updated));
      return updated;
    });
    Alert.alert("완료", `"${genre}"의 부장르 속성을 제거했습니다.`);
  }

  // 미사용 태그 찾기 (작품에 한 번도 사용되지 않은 태그)
  // 🔧 v3.5.12: comboTags 제거 (customTags로 통합)
  function findUnusedTags() {
    const usedTags = new Set();
    for (const n of list) {
      const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
      tags.forEach(t => usedTags.add(t));
      parseMajorSub(n.major_genre).forEach(g => usedTags.add(g));
      parseMajorSub(n.sub_genre).forEach(g => usedTags.add(g));
    }
    
    const unusedCustom = customTags.filter(t => !usedTags.has(t));
    const unusedMajor = userMajorGenres.filter(g => !usedTags.has(g));
    const unusedSub = userSubGenres.filter(g => !usedTags.has(g));
    
    // 하위 호환: unusedCombo는 항상 빈 배열
    return { unusedCustom, unusedCombo: [], unusedMajor, unusedSub };
  }

  // 미사용 태그 정리
  async function cleanupUnusedTags() {
    const { unusedCustom, unusedMajor, unusedSub } = findUnusedTags();
    const total = unusedCustom.length + unusedMajor.length + unusedSub.length;
    
    if (total === 0) {
      Alert.alert("알림", "미사용 태그가 없습니다.");
      return;
    }
    
    Alert.alert(
      "미사용 태그 정리",
      `미사용 태그 ${total}개를 삭제합니다.\n\n` +
      `커스텀: ${unusedCustom.length}개\n` +
      `대장르: ${unusedMajor.length}개\n` +
      `부장르: ${unusedSub.length}개`,
      [
        { text: "취소" },
        {
          text: "삭제",
          style: "destructive",
          onPress: async () => {
            // 🔧 v6.0.1: 일괄 제거 — updateTagRegistryFn으로 stale closure 방지
            const allUnused = [...unusedCustom, ...unusedMajor, ...unusedSub];
            if (allUnused.length > 0) {
              updateTagRegistryFn(prev => {
                const newRegistry = { ...prev };
                newRegistry.majorGenres = newRegistry.majorGenres.filter(t => !allUnused.some(u => isSameTag(t, u)));
                newRegistry.subGenres = newRegistry.subGenres.filter(t => !allUnused.some(u => isSameTag(t, u)));
                const newGeneral = {};
                for (const [cat, tags] of Object.entries(newRegistry.generalTags)) {
                  const filtered = tags.filter(t => !allUnused.some(u => isSameTag(t, u)));
                  if (filtered.length > 0) newGeneral[cat] = filtered;
                }
                newRegistry.generalTags = newGeneral;
                return newRegistry;
              });
            }
            Alert.alert("완료", `미사용 태그 ${total}개를 삭제했습니다.`);
          }
        }
      ]
    );
  }

  // 🆕 v7.10.0: 태그 이름변경 / 병합 — 전 작품 + 메타데이터 전반을 새 이름으로 이전.
  //   새 이름(to)이 이미 존재하면 자연스럽게 병합(중복 제거). delete+재태깅 없이 통합 가능.
  //   주의: 학습 패턴(preference_patterns)은 병합 충돌/유령 방지를 위해 정리(재학습됨).
  async function renameTagGlobally(oldTag, newTag) {
    const from = (oldTag || "").trim();
    const to = (newTag || "").trim();
    if (!from || !to) { Alert.alert("이름 변경", "새 태그 이름을 입력하세요."); return; }
    if (isSameTag(from, to)) { Alert.alert("이름 변경", "기존 이름과 동일합니다."); return; }
    setIsLoading(true);
    try {
      // 1) novels + planned_novels 재작성 (정확 태그만 치환 + 병합 시 중복 제거)
      let affected = 0;
      for (const tableName of ["novels", "planned_novels"]) {
        const rows = await all(`SELECT id, tags, tag_data, major_genre, sub_genre FROM ${tableName}`);
        const updates = [];
        for (const row of (rows || [])) {
          let changed = false;
          let { tags, tag_data, major_genre, sub_genre } = row;
          // tags (CSV) — 치환 후 dedupe(isSameTag)
          if (tags && tags.split(",").some(t => isSameTag(t.trim(), from))) {
            const arr = tags.split(",").map(t => t.trim()).filter(Boolean);
            const out = [];
            for (const t of arr) {
              const v = isSameTag(t, from) ? to : t;
              if (!out.some(x => isSameTag(x, v))) out.push(v);
            }
            const ns = out.join(", ");
            if (ns !== tags) { tags = ns; changed = true; }
          }
          // tag_data (JSON [{tag,intensity}]) — 치환 후 동일 태그 병합(강도는 최댓값)
          if (tag_data) {
            try {
              const parsed = JSON.parse(tag_data);
              if (Array.isArray(parsed)) {
                let td = false;
                const merged = [];
                for (const item of parsed) {
                  if (!item || item.tag == null) { merged.push(item); continue; }
                  const v = isSameTag(item.tag, from) ? to : item.tag;
                  if (v !== item.tag) td = true;
                  const ex = merged.find(m => m && isSameTag(m.tag, v));
                  if (ex) { td = true; if ((Number(item.intensity) || 0) > (Number(ex.intensity) || 0)) ex.intensity = item.intensity; }
                  else merged.push({ ...item, tag: v });
                }
                if (td) { tag_data = JSON.stringify(merged); changed = true; }
              }
            } catch {}
          }
          // major_genre / sub_genre (JSON []) — 치환 + dedupe
          for (const fld of ["major_genre", "sub_genre"]) {
            const cur = fld === "major_genre" ? major_genre : sub_genre;
            if (!cur) continue;
            try {
              const arr = JSON.parse(cur);
              if (Array.isArray(arr)) {
                let ch = false;
                const out = [];
                for (const g of arr) {
                  const v = isSameTag(g, from) ? to : g;
                  if (v !== g) ch = true;
                  if (!out.some(x => isSameTag(x, v))) out.push(v); else ch = true;
                }
                if (ch) {
                  const js = JSON.stringify(out);
                  if (fld === "major_genre") major_genre = js; else sub_genre = js;
                  changed = true;
                }
              }
            } catch {}
          }
          if (changed) updates.push({ sql: `UPDATE ${tableName} SET tags=?, tag_data=?, major_genre=?, sub_genre=? WHERE id=?`, params: [tags, tag_data, major_genre, sub_genre, row.id] });
        }
        for (let i = 0; i < updates.length; i += 50) await execBatch(updates.slice(i, i + 50));
        affected += updates.length;
      }

      // 2) 레지스트리 rename(+dedupe)
      updateTagRegistryFn(prev => {
        const nr = { ...prev };
        const ren = (list) => {
          if (!Array.isArray(list)) return list;
          const out = [];
          for (const t of list) {
            const v = isSameTag(t, from) ? to : t;
            if (!out.some(x => isSameTag(x, v))) out.push(v);
          }
          return out;
        };
        nr.majorGenres = ren(nr.majorGenres);
        nr.subGenres = ren(nr.subGenres);
        const ng = {};
        for (const [cat, tags] of Object.entries(nr.generalTags || {})) ng[cat] = ren(tags);
        nr.generalTags = ng;
        return nr;
      });

      // 3) 메타데이터 이전: pinned/hidden(배열), sentiment/attributes(객체 키)
      const renameInArray = (prev) => {
        if (!prev.some(t => isSameTag(t, from))) return null;
        const out = [];
        for (const t of prev) { const v = isSameTag(t, from) ? to : t; if (!out.some(x => isSameTag(x, v))) out.push(v); }
        return out;
      };
      setPinnedTags(prev => { const n = renameInArray(prev); if (!n) return prev; safeDefer(() => deferSetAppMeta("pinned_tags", n)); return n; });
      setHiddenTags(prev => { const n = renameInArray(prev); if (!n) return prev; safeDefer(() => deferSetAppMeta("hidden_tags", n)); return n; });
      const transferKey = (setter, metaKey) => setter(prev => {
        const mk = Object.keys(prev).find(k => isSameTag(k, from));
        if (!mk) return prev;
        const next = { ...prev };
        const tk = Object.keys(next).find(k => isSameTag(k, to));
        if (!tk) next[to] = next[mk]; // 대상 없으면 이전, 있으면 대상 유지(병합)
        delete next[mk];
        safeDefer(() => deferSetAppMeta(metaKey, next));
        return next;
      });
      transferKey(setTagSentiments, "tag_sentiments");
      transferKey(setTagAttributes, "tag_attributes");

      // 4) tag_relations: from 키를 to로 rename(그룹 내 dedupe)
      setTagRelations(prev => {
        if (!prev || !prev.tagToGroup) return prev;
        const mk = Object.keys(prev.tagToGroup).find(k => isSameTag(k, from));
        if (!mk) return prev;
        const gid = prev.tagToGroup[mk];
        const grp = prev.groups?.[gid];
        const newGroups = { ...prev.groups };
        const newT2G = { ...prev.tagToGroup };
        delete newT2G[mk];
        if (grp) {
          const newTags = [];
          for (const t of (grp.tags || [])) { const v = isSameTag(t, from) ? to : t; if (!newTags.some(x => isSameTag(x, v))) newTags.push(v); }
          newGroups[gid] = { ...grp, tags: newTags };
          if (!Object.keys(newT2G).some(k => isSameTag(k, to))) newT2G[to] = gid;
        }
        const updated = { groups: newGroups, tagToGroup: newT2G };
        safeDefer(() => deferSetAppMeta("tag_relations", updated));
        return updated;
      });

      // 5) coordinateSystems: from 키를 to로 rename
      setCoordinateSystems(prev => {
        if (!prev) return prev;
        let changed = false;
        const next = {};
        for (const [csId, cs] of Object.entries(prev)) {
          if (cs.tags) {
            const mk = Object.keys(cs.tags).find(k => isSameTag(k, from));
            if (mk) {
              changed = true;
              const nt = { ...cs.tags };
              const val = nt[mk]; delete nt[mk];
              const tk = Object.keys(nt).find(k => isSameTag(k, to));
              if (!tk) nt[to] = val; // 대상 없으면 이전(있으면 대상 유지)
              next[csId] = { ...cs, tags: nt };
              continue;
            }
          }
          next[csId] = cs;
        }
        if (!changed) return prev;
        safeDefer(() => saveTagCoordinateSystems(next));
        return next;
      });

      // 6) preference_patterns: from의 학습 패턴 정리(병합 충돌/유령 방지 — 재학습됨)
      try {
        const _nf = normalizeTag(from);
        await exec("DELETE FROM preference_patterns WHERE (category IN ('tag_power','tag_aversion') AND pattern_key IN (?, ?)) OR (category='genre_affinity' AND pattern_key IN (?, ?));",
          [`tag:${from}`, `tag:${_nf}`, `genre:${from}`, `genre:${_nf}`]);
      } catch (e) { console.warn('[renameTag] pattern cleanup:', e?.message); }

      await loadList(undefined, undefined, "tag_rename");
      Alert.alert("완료", `"${from}" → "${to}" 이름 변경/병합 완료 (${affected}개 작품 수정).\n\n관계·좌표 설정도 함께 이전됐어요.`);
    } catch (e) {
      console.warn('[renameTag] failed:', e?.message);
      Alert.alert("오류", "태그 이름 변경 중 오류가 발생했습니다.\n\n" + (e?.message || ""));
    } finally {
      setIsLoading(false);
    }
  }

  // 전체 범위에서 태그 삭제 (작품 데이터에서도 제거)
  async function deleteTagGlobally(tag) {
    Alert.alert(
      "전체 삭제",
      `"${tag}" 태그를 모든 작품에서 삭제합니다.\n이 작업은 되돌릴 수 없습니다.`,
      [
        { text: "취소" },
        {
          text: "삭제",
          style: "destructive",
          onPress: async () => {
            // 1. registry에서 태그 제거 (구 state 자동 파생)
            removeTagFromRegistry(tag);
            
            // 2. 모든 작품에서 해당 태그 제거
            // 🔧 v3.5.13: tag_data도 함께 정리 (batchRemoveTag와 동일 수준)
            // 🔧 v7.14.0 (P0): novels + planned_novels 모두 스캔 — 이전엔 novels만 처리해 예정작에
            //   유령 태그가 남아 승격 시 부활했음(renameTagGlobally는 두 테이블 처리). 동일 정합으로 보강.
            const updates = [];
            for (const tableName of ["novels", "planned_novels"]) {
              const rows = await all(`SELECT id, tags, tag_data, major_genre, sub_genre FROM ${tableName};`);
              for (const n of (rows || [])) {
                let changed = false;
                // 🔧 v3.5.13: isSameTag 사용으로 공백/alias 변형도 정확히 제거
                const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
                const newTags = tags.filter(t => !isSameTag(t, tag));
                if (newTags.length !== tags.length) changed = true;
                const majors = parseMajorSub(n.major_genre);
                const newMajors = majors.filter(g => !isSameTag(g, tag));
                if (newMajors.length !== majors.length) changed = true;
                const subs = parseMajorSub(n.sub_genre);
                const newSubs = subs.filter(g => !isSameTag(g, tag));
                if (newSubs.length !== subs.length) changed = true;
                let tagData = [];
                try { tagData = JSON.parse(n.tag_data || "[]"); if (!Array.isArray(tagData)) tagData = []; } catch { tagData = []; }
                const newTagData = tagData.filter(td => !isSameTag(td.tag, tag));
                if (newTagData.length !== tagData.length) changed = true;

                if (changed) {
                  updates.push({
                    sql: `UPDATE ${tableName} SET tags=?, tag_data=?, major_genre=?, sub_genre=? WHERE id=?`,
                    params: [
                      newTags.join(", "),
                      newTagData.length > 0 ? JSON.stringify(newTagData) : "",
                      JSON.stringify(newMajors),
                      JSON.stringify(newSubs),
                      n.id
                    ]
                  });
                }
              }
            }
            if (updates.length > 0) {
              await execBatch(updates);
            }
            // 🔧 v3.5.9: 연관 메타데이터 일괄 정리 (고정/숨김/감정/속성)
            const isDefault = ALL_DEFAULT_TAGS.some(t => isSameTag(t, tag));
            await cleanupTagMetadata(tag); // 🔧 숨김 포함 모든 메타데이터 제거
            // 🔧 v7.10.0: 학습 패턴(preference_patterns)도 정리 — 안 그러면 삭제된 태그가
            //   취향점수/추천에 유령으로 계속 기여하고, 같은 이름 재생성 시 과거 승패가 되살아남.
            try {
              const _nt = normalizeTag(tag);
              await exec(
                "DELETE FROM preference_patterns WHERE (category IN ('tag_power','tag_aversion') AND pattern_key IN (?, ?)) OR (category='genre_affinity' AND pattern_key IN (?, ?));",
                [`tag:${tag}`, `tag:${_nt}`, `genre:${tag}`, `genre:${_nt}`]
              );
            } catch (e) { console.warn('[deleteTag] pattern cleanup failed:', e?.message); }
            // 🆕 기본 태그는 cleanup 이후 다시 숨김 추가
            if (isDefault) {
              toggleHideTag(tag);
            }
            await loadList(undefined, undefined, "batch");
            Alert.alert("완료", `"${tag}" 태그를 전체에서 삭제했습니다. (${updates.length}개 작품 수정)`);
          }
        }
      ]
    );
  }

  // 🆕 일괄 전체 삭제 (한 번의 소설 스캔으로 다중 태그 제거 — O(N) 최적화)
  async function batchDeleteTagsGlobally(tagsToDelete) {
    if (!tagsToDelete || tagsToDelete.length === 0) return;
    if (isLoading) return; // 🔧 v3.6.0: 동시 실행 보호

    setIsLoading(true);
    setLoadingProgress({ current: 0, total: 0, label: "태그 일괄 삭제 중..." });
    try {
    // 1. 레지스트리에서 모든 태그 제거
    updateTagRegistryFn(prev => {
      const newRegistry = { ...prev };
      newRegistry.majorGenres = newRegistry.majorGenres.filter(t => !tagsToDelete.some(d => isSameTag(t, d)));
      newRegistry.subGenres = newRegistry.subGenres.filter(t => !tagsToDelete.some(d => isSameTag(t, d)));
      const newGeneral = {};
      for (const [cat, tags] of Object.entries(newRegistry.generalTags)) {
        const filtered = tags.filter(t => !tagsToDelete.some(d => isSameTag(t, d)));
        // 🆕 userCategories에 있는 카테고리는 빈 배열이어도 보존
        if (filtered.length > 0 || (newRegistry.userCategories || []).includes(cat)) {
          newGeneral[cat] = filtered;
        }
      }
      newRegistry.generalTags = newGeneral;
      return newRegistry;
    });

    // 2. 모든 작품(+예정작)에서 해당 태그들 일괄 제거 (한 번의 스캔)
    // 🔧 v7.14.0 (P0): planned_novels도 포함 — 단건 deleteTagGlobally와 동일 이유(예정작 유령 태그 부활 방지)
    const updates = [];
    const isSameTagBatch = (t) => tagsToDelete.some(d => isSameTag(t, d));

    for (const tableName of ["novels", "planned_novels"]) {
      const rows = await all(`SELECT id, tags, tag_data, major_genre, sub_genre FROM ${tableName};`);
      for (const n of (rows || [])) {
        let changed = false;
        const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
        const newTags = tags.filter(t => !isSameTagBatch(t));
        if (newTags.length !== tags.length) changed = true;
        const majors = parseMajorSub(n.major_genre);
        const newMajors = majors.filter(g => !isSameTagBatch(g));
        if (newMajors.length !== majors.length) changed = true;
        const subs = parseMajorSub(n.sub_genre);
        const newSubs = subs.filter(g => !isSameTagBatch(g));
        if (newSubs.length !== subs.length) changed = true;
        let tagData = [];
        try { tagData = JSON.parse(n.tag_data || "[]"); if (!Array.isArray(tagData)) tagData = []; } catch { tagData = []; }
        const newTagData = tagData.filter(td => !isSameTagBatch(td.tag));
        if (newTagData.length !== tagData.length) changed = true;

        if (changed) {
          updates.push({
            sql: `UPDATE ${tableName} SET tags=?, tag_data=?, major_genre=?, sub_genre=? WHERE id=?`,
            params: [
              newTags.join(", "),
              newTagData.length > 0 ? JSON.stringify(newTagData) : "",
              JSON.stringify(newMajors),
              JSON.stringify(newSubs),
              n.id
            ]
          });
        }
      }
    }
    if (updates.length > 0) {
      await execBatch(updates, (cur, tot) => setLoadingProgress({ current: cur, total: tot, label: "태그 일괄 삭제 중..." }));
    }

    // 3. 🔧 배치 최적화: per-tag cleanupTagMetadata → cleanupTagMetadataBatch
    //    (N회 setState × 4 → 4회 setState로 축소)
    cleanupTagMetadataBatch(tagsToDelete);

    // 🔧 v7.10.0: 학습 패턴(preference_patterns)도 일괄 정리 (단건 deleteTagGlobally와 동일 이유 — orphan 방지)
    try {
      const keySet = new Set();
      for (const tag of tagsToDelete) {
        const _nt = normalizeTag(tag);
        keySet.add(`tag:${tag}`); keySet.add(`tag:${_nt}`);
        keySet.add(`genre:${tag}`); keySet.add(`genre:${_nt}`);
      }
      const keys = [...keySet];
      if (keys.length > 0) {
        const ph = keys.map(() => "?").join(",");
        await exec(
          `DELETE FROM preference_patterns WHERE category IN ('tag_power','tag_aversion','genre_affinity') AND pattern_key IN (${ph});`,
          keys
        );
      }
    } catch (e) { console.warn('[batchDeleteTags] pattern cleanup failed:', e?.message); }

    // 기본 태그는 cleanup 이후 다시 숨김 추가
    const defaultTagsToHide = tagsToDelete.filter(tag => ALL_DEFAULT_TAGS.some(t => isSameTag(t, tag)));
    if (defaultTagsToHide.length > 0) {
      setHiddenTags(prev => {
        const next = [...prev];
        for (const tag of defaultTagsToHide) {
          if (!next.some(t => isSameTag(t, tag))) {
            next.push(tag);
          }
        }
        safeDefer(() => deferSetAppMeta("hidden_tags", next));
        return next;
      });
    }

    await loadList(undefined, undefined, "batch");
    Alert.alert("완료", `${tagsToDelete.length}개 태그를 전체에서 삭제했습니다. (${updates.length}개 작품 수정)`);
    } finally {
      setLoadingProgress(null);
      setIsLoading(false);
    }
  }

  // 🏷️ 작품에 적용된 태그 중 기본 목록에 없는 것들을 커스텀 태그로 자동 수집
  async function syncCustomTagsFromNovels(novels, currentCustomTags) {
    const allDefaultSet = new Set([
      ...ALL_DEFAULT_TAGS,
      ...MAJOR_GENRES,
      ...SUB_GENRES,
    ]);
    const currentCustomSet = new Set(currentCustomTags);
    const newTags = new Set();

    for (const n of novels) {
      // 일반 태그
      const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
      for (const tag of tags) {
        if (!allDefaultSet.has(tag) && !currentCustomSet.has(tag)) {
          newTags.add(tag);
        }
      }
      // 대장르
      const majors = parseMajorSub(n.major_genre);
      for (const g of majors) {
        if (!listHasTag(MAJOR_GENRES, g) && !listHasTag(userMajorGenres, g) && !currentCustomSet.has(g)) {
          // 대장르는 userMajorGenres에 추가하지 않고, 일단 커스텀 태그로
          if (!allDefaultSet.has(g)) newTags.add(g);
        }
      }
      // 부장르
      const subs = parseMajorSub(n.sub_genre);
      for (const g of subs) {
        if (!listHasTag(SUB_GENRES, g) && !listHasTag(userSubGenres, g) && !currentCustomSet.has(g)) {
          if (!allDefaultSet.has(g)) newTags.add(g);
        }
      }
    }

    // 🆕 숨긴 태그는 자동 수집에서 제외
    // 🔧 O(1) 룩업으로 성능 최적화 + Set 순회 중 삭제 방지
    if (hiddenTags.length > 0) {
      const hiddenKeySet = buildTagKeySet(hiddenTags);
      const toRemove = [];
      for (const nt of newTags) {
        if (hiddenKeySet.has(normalizeTagKey(nt))) {
          toRemove.push(nt);
        }
      }
      for (const t of toRemove) newTags.delete(t);
    }
    if (newTags.size > 0) {
      for (const t of newTags) addTagToRegistry(t);
      console.log(`자동 수집된 커스텀 태그 ${newTags.size}개:`, Array.from(newTags));
    }
  }

  // 🏷️ 사용자 대장르 추가
  async function addUserMajorGenre(genreInput) {
    const genre = (genreInput || "").trim();
    if (!genre) return;
    if (listHasTag(MAJOR_GENRES, genre) || listHasTag(userMajorGenres, genre)) {
      Alert.alert("알림", "이미 존재하는 대장르입니다.");
      return;
    }
    // 🔧 v3.6.1: registry 단일 경로
    if (tagRegistry) {
      updateTagRegistry({
        ...tagRegistry,
        majorGenres: [...new Set([...tagRegistry.majorGenres, genre])],
      });
    }
  }

  // 🏷️ 사용자 부장르 추가
  async function addUserSubGenre(genreInput) {
    const genre = (genreInput || "").trim();
    if (!genre) return;
    if (listHasTag(SUB_GENRES, genre) || listHasTag(userSubGenres, genre)) {
      Alert.alert("알림", "이미 존재하는 부장르입니다.");
      return;
    }
    // 🔧 v3.6.1: registry 단일 경로
    if (tagRegistry) {
      updateTagRegistry({
        ...tagRegistry,
        subGenres: [...new Set([...tagRegistry.subGenres, genre])],
      });
    }
  }

  // 🏷️ 전체 대장르 목록 (기본 + 사용자 + tagAttributes)
  // 🔧 v3.5.11: getAllMajorTags 사용하여 tagAttributes 기반 대장르도 포함
  const allMajorGenres = useMemo(() => {
    return getAllMajorTags(tagAttributes, userMajorGenres);
  }, [userMajorGenres, tagAttributes, tagRegistry]);

  // 🏷️ 전체 부장르 목록 (기본 + 사용자 + tagAttributes)
  const allSubGenres = useMemo(() => {
    return getAllSubTags(tagAttributes, userSubGenres);
  }, [userSubGenres, tagAttributes, tagRegistry]);

  // 🏷️ 전체 태그 목록 (기본 + 커스텀, 사용빈도순 정렬)
  const allTagsSorted = useMemo(() => {
    const allTags = [...ALL_GENERAL_TAGS, ...customTags];
    return sortTagsByUsage(allTags, tagUsageCounts);
  }, [customTags, tagUsageCounts, tagRegistry]);

  // 🏷️ 정렬된 대장르 목록 (사용빈도순)
  // 🔧 v3.5.11: tagAttributes 반영
  const sortedMajorGenres = useMemo(() => {
    return sortTagsByUsage(getAllMajorTags(tagAttributes, userMajorGenres), tagUsageCounts);
  }, [userMajorGenres, tagUsageCounts, tagAttributes]);

  // 🏷️ 정렬된 부장르 목록 (사용빈도순)
  const sortedSubGenres = useMemo(() => {
    return sortTagsByUsage(getAllSubTags(tagAttributes, userSubGenres), tagUsageCounts);
  }, [userSubGenres, tagUsageCounts, tagAttributes]);

  // 🏷️ 일반 태그 카테고리별 정렬 목록
  const sortedGeneralTags = useMemo(() => {
    const result = {};
    for (const [category, tagList] of Object.entries(GENERAL_TAGS)) {
      result[category] = sortTagsByUsage(tagList, tagUsageCounts);
    }
    // 🆕 v3.5.9: 커스텀 태그 카테고리 병합
    if (customTagCategories && typeof customTagCategories === "object") {
      for (const [catName, catTags] of Object.entries(customTagCategories)) {
        if (!Array.isArray(catTags) || catTags.length === 0) continue;
        result[`📂 ${catName}`] = sortTagsByUsage(catTags, tagUsageCounts);
      }
    }
    return result;
  }, [tagUsageCounts, customTagCategories, tagRegistry]);

  // 🆕 v3.5.9: 전체 태그 목록 (검색/자동완성용)
  // 🔧 v3.5.12: comboTags 제거 (customTags로 통합)
  const allTagsForSearch = useMemo(() => {
    const set = new Set(ALL_DEFAULT_TAGS);
    customTags.forEach(t => set.add(t));
    userMajorGenres.forEach(t => set.add(t));
    userSubGenres.forEach(t => set.add(t));
    // 커스텀 카테고리 태그도 포함
    if (customTagCategories) {
      for (const catTags of Object.values(customTagCategories)) {
        if (Array.isArray(catTags)) catTags.forEach(t => set.add(t));
      }
    }
    return [...set].sort();
  }, [customTags, userMajorGenres, userSubGenres, customTagCategories, tagRegistry]);

  // =========================================================
  // ⚙️ 설정 관리 함수 (v2.6)
  // =========================================================
  
  // 설정 저장 (변경 시 자동 호출)
  function saveAppSettings(newSettings) {
    // 🔧 v7.16.5: 영속화 신뢰성 근본 수정.
    //   [이전 결함] mergedResult를 setState 업데이터의 '부수효과'로 캡처 → React 19가 업데이터를
    //   동기 실행하지 않으면(보류 업데이트 존재/배칭 등) mergedResult=null → if(mergedResult) 건너뜀
    //   → setAppMeta 미호출 → 해당 호출의 설정(특히 명언 프리셋)이 앱 재시작 시 원복.
    //   [수정] appSettingsRef(렌더 동기화)로 최신 설정을 동기 참조해 merged를 확정 → setState·globals·
    //   영속화 모두 reliable. 연속 호출도 ref 즉시 갱신으로 체이닝.
    const prev = appSettingsRef.current || DEFAULT_SETTINGS;
    const merged = { ...prev };
    for (const key of Object.keys(newSettings)) {
      if (key === 'plannedFields' || key === 'supplement' || key === 'recentChanges' || key === 'coverLibrary' || key === 'tierSystemConfig' || key === 'suspicionConfig') {
        // nested object는 deep merge
        merged[key] = { ...(prev[key] || {}), ...newSettings[key] };
        // 🆕 v6.0: tierSystemConfig의 tiers 배열은 교체 (merge 아님)
        if (key === 'tierSystemConfig' && newSettings[key].tiers) {
          merged[key].tiers = newSettings[key].tiers;
        }
      } else {
        merged[key] = newSettings[key];
      }
    }
    appSettingsRef.current = merged; // 연속 호출이 최신 merged를 prev로 보도록 즉시 동기화
    setAppSettings(merged);

    // 부수효과: 전역 변수 갱신 + DB 영속화 (merged 확정 → reliable)
    try {
      if (newSettings.tierThresholds) {
        globalTierThresholds = { ...globalTierThresholds, ...newSettings.tierThresholds };
      }
      if (newSettings.tierSystemConfig || merged.tierSystemConfig) {
        const tsc = merged.tierSystemConfig || DEFAULT_TIER_SYSTEM_CONFIG;
        globalTierConfig = { ...tsc };
        rebuildTierLookup(globalTierConfig);
        if (tsc.tiers) {
          const th = {};
          for (const t of tsc.tiers) {
            if (t.key !== tsc.defaultTier) th[t.key] = t.threshold;
          }
          globalTierThresholds = th;
        }
      }
      // 🔧 v7.18.0: 의심도 계수 전역 동기화 (globalTierConfig 패턴)
      if (newSettings.suspicionConfig) {
        globalSuspicionConfig = { ...DEFAULT_SUSPICION_CONFIG, ...(merged.suspicionConfig || {}) };
      }
    } catch (e) {
      console.warn("saveAppSettings: global update error:", e);
    }
    safeDefer(() => setAppMeta("app_settings", merged));
  }

  // 🆕 v7.19.0: 타모드 → 하이브리드 전환 시 초기화 전략 적용 + 모드 전환 마무리.
  //   strategy: "keep"(현재 티어·순위 고정) | "redistribute"(순위 유지 + 티어 백분위 재분배) | "reset"(완전 비움)
  const applyHybridInit = async (strategy) => {
    if (modeChangingRef.current) return;
    modeChangingRef.current = true;
    try {
      const oldConfig = { ...globalTierConfig };           // 전환 전 모드(여기 기준으로 현재 표시 티어 계산)
      const tierOrder = getActiveTierOrder(oldConfig);
      if (strategy === "reset") {
        // ③ 완전 비움 — manual_tier/order/의심신호 모두 클리어 → 하이브리드가 ELO로 표시(백지)
        await exec("UPDATE novels SET manual_tier=NULL, manual_order=0, suspicion_score=0, user_flagged_suspect=0;");
      } else {
        const novels = await all("SELECT id, rating, manual_tier, manual_order FROM novels");
        // 현재 표시 순위(티어→레이팅 내림차순)로 정렬 — 순위탭/rankedEntries와 동일 기준
        const sorted = [...(novels || [])].sort((a, b) => {
          const ta = tierRank(getDisplayTier(a, oldConfig), oldConfig);
          const tb = tierRank(getDisplayTier(b, oldConfig), oldConfig);
          if (ta !== tb) return ta - tb;
          return (Number(b.rating) || 0) - (Number(a.rating) || 0);
        });
        let tierForPos = null;
        if (strategy === "redistribute") {
          // ② 순위 유지 + 티어 백분위 재분배 (computeRatioTierMap과 동일한 top-down 채움)
          const total = sorted.length;
          const ratios = tierOrder.map(k => Math.max(0, Number(hybridInitRatios?.[k]) || 0));
          let sumR = ratios.reduce((a, b) => a + b, 0);
          if (sumR <= 0) { for (let i = 0; i < ratios.length; i++) ratios[i] = 1; sumR = ratios.length || 1; }
          const cumCounts = []; let acc = 0, prev = 0;
          for (let i = 0; i < ratios.length; i++) {
            acc += ratios[i] / sumR * total;
            let c = Math.round(acc);
            if (c < prev) c = prev;
            if (ratios[i] > 0 && c === prev && prev < total) c = prev + 1;
            cumCounts.push(c); prev = c;
          }
          if (cumCounts.length) cumCounts[cumCounts.length - 1] = total;
          tierForPos = (pos) => { for (let t = 0; t < cumCounts.length; t++) if (pos < cumCounts[t]) return t; return cumCounts.length - 1; };
        }
        const perTier = {};
        const queries = sorted.map((n, pos) => {
          const t = strategy === "redistribute" ? tierOrder[tierForPos(pos)] : getDisplayTier(n, oldConfig);
          perTier[t] = (perTier[t] || 0) + 1;
          return { sql: "UPDATE novels SET manual_tier=?, manual_order=? WHERE id=?", params: [t, perTier[t] * 100, n.id] };
        });
        for (let i = 0; i < queries.length; i += 50) await execBatch(queries.slice(i, i + 50));
      }
      saveAppSettings({ tierSystemConfig: { ...oldConfig, mode: "hybrid" } });
      setHybridInitOpen(false);
      setHybridInitShowRatio(false);
      if (screen === "review") setScreen("tierManage"); // hybrid에서 검토 탭 숨김
      await loadList(undefined, undefined, "settings");
      Alert.alert("완료", "하이브리드 모드로 변경되었습니다.");
    } catch (e) {
      Alert.alert("오류", "초기화 적용 실패: " + (e?.message || e));
    } finally {
      modeChangingRef.current = false;
    }
  };
  
  // 🆕 v6.0: 티어 히스토리 저장 (gated 티어 관련만 영속화)
  async function saveTierHistory(newHistory) {
    const gated = getGatedTiers(globalTierConfig);
    const filtered = newHistory.filter(h =>
      gated.includes(h.from) || gated.includes(h.to)
    );
    const limited = filtered.slice(0, 50);
    setTierHistory(limited);
    await setAppMeta("tier_history", limited);
  }

  // 티어 변경 기록 추가 (모든 변경 기록, 저장은 gated 관련만)
  function addTierHistoryEntry(id, title, from, to) {
    const entry = { id, title, from, to, at: Date.now() };
    setTierHistory(prev => {
      const updated = [entry, ...prev].slice(0, 50);
      const gated = getGatedTiers(globalTierConfig);
      if (gated.includes(from) || gated.includes(to)) {
        setAppMeta("tier_history", updated.filter(h =>
          gated.includes(h.from) || gated.includes(h.to)
        ).slice(0, 50));
      }
      return updated;
    });
  }
  
  // =========================================================
  // ↩️ 전역 되돌리기 스택 (v2.6)
  // =========================================================
  
  // 되돌리기 항목 추가
  function pushUndo(type, payload, description) {
    setUndoStack(prev => {
      const maxSize = appSettings.undoStackSize || 30;
      return [{ type, payload, description, at: Date.now() }, ...prev].slice(0, maxSize);
    });
  }
  
  // 마지막 작업 되돌리기
  async function performUndo() {
    if (undoStack.length === 0) {
      Alert.alert("알림", "되돌릴 작업이 없습니다.");
      return;
    }
    
    const item = undoStack[0];
    
    try {
      switch (item.type) {
        case 'tier_change':
          // 티어 변경 되돌리기 (gated 티어가 아니면 null로 복원)
          // 🆕 v7.0.6 (M11): manual_order도 함께 복원 — 페이로드 누락 시 fallback 0 (backward compat)
          // 🔧 hybrid/manual 모드는 manual_tier가 사용자 진실 — prevTier 그대로 복원 (헤더 정책: 절대 NULL 강제 금지)
          //    match 모드만 기존 휴리스틱 유지 (prevTier가 ELO 표시 티어일 수 있어 비-gated는 자동(null) 복귀)
          const _restoreTier = globalTierConfig.mode === "match"
            ? (isGatedTier(item.payload.prevTier, globalTierConfig) ? item.payload.prevTier : null)
            : (item.payload.prevTier || null);
          await exec("UPDATE novels SET manual_tier=?, manual_order=? WHERE id=?", [
            _restoreTier,
            Number(item.payload.prevManualOrder) || 0,
            item.payload.id
          ]);
          addTierHistoryEntry(item.payload.id, item.payload.title, item.payload.newTier, item.payload.prevTier);
          // v7.0.1 (M3 fix): hybrid에서 큐 정합성 — 변경된 적 없는 상태로 복귀하므로 pending 큐 cancel
          if (globalTierConfig.mode === "hybrid") {
            await exec(
              `UPDATE tier_verification_queue SET state='cancelled', processed_at=? WHERE novel_id=? AND state='pending'`,
              [Date.now(), item.payload.id]
            );
            // 🆕 v7.0.3: in-flight 세션이 같은 작품에 대한 것이면 abort (이전: undo 후 finalize가 자리 재이동시킴)
            if (verificationSession && verificationSession.queueRow?.novel_id === item.payload.id) {
              setVerificationSession(null);
              verificationSessionIdRef.current = null;
            }
          }
          break;

        case 'tier_batch':
          // 일괄 티어 변경 되돌리기
          // 🆕 v7.0.6 (M11): manual_order도 함께 복원 — 페이로드 누락 시 fallback 0 (backward compat)
          for (const change of item.payload.changes) {
            const _restoreTierB = globalTierConfig.mode === "match"
              ? (isGatedTier(change.prevTier, globalTierConfig) ? change.prevTier : null)
              : (change.prevTier || null);
            await exec("UPDATE novels SET manual_tier=?, manual_order=? WHERE id=?", [
              _restoreTierB,
              Number(change.prevManualOrder) || 0,
              change.id
            ]);
          }
          // v7.0.1 (M3 fix): hybrid 큐 정합성
          if (globalTierConfig.mode === "hybrid" && item.payload.changes.length > 0) {
            const ids = item.payload.changes.map(c => c.id);
            const placeholders = ids.map(() => "?").join(",");
            await exec(
              `UPDATE tier_verification_queue SET state='cancelled', processed_at=? WHERE novel_id IN (${placeholders}) AND state='pending'`,
              [Date.now(), ...ids]
            );
            // 🆕 v7.0.3: 일괄 undo도 in-flight 세션 abort
            if (verificationSession && ids.includes(verificationSession.queueRow?.novel_id)) {
              setVerificationSession(null);
              verificationSessionIdRef.current = null;
            }
          }
          break;

        // 🆕 v7.0.6 (C1): 사용자 결정 — saveEdit이 tier+meta 동시 변경 시 부분 복원의 혼란 회피.
        // 동시 변경 시 marker push → 사용자가 undo 시도하면 명시적 안내 표시 후 stack에서 pop만 수행.
        // 🔧 v7.0.7 (CRIT-2): 이전 break은 switch 이후 공통 success alert("되돌렸습니다")로 fallthrough되어
        // "되돌릴 수 없음" → "되돌렸습니다" 이중 모순 alert 발생. 직접 stack pop 후 return으로 차단.
        case 'non_undoable':
          Alert.alert(
            "되돌릴 수 없음",
            item.payload?.reason || "되돌리기가 불가능한 변경이 포함되어 있습니다."
          );
          setUndoStack(prev => prev.slice(1));
          return;

        case 'novel_delete':
          // 작품 삭제 되돌리기 (복원)
          // 🆕 v7.0.2: manual_order 컬럼 누락 보강 — 미포함 시 hybrid 정렬에서 0 그룹으로 떨어져 gap=100 invariant 깨짐
          const n = item.payload.novel;
          await exec(
            // 🔧 v7.6.0: start_year/end_year/match_ban 복원 추가 (n은 SELECT * 캡처 → 필드 존재, 미존재 시 0 폴백)
            `INSERT INTO novels (id,title,author,tags,platforms,note,read_count,rating,rd,wins,losses,match_count,tier,created_at,awards,total_episodes,status,pinned,cover_image,link,work_status,read_count_updated_at,major_genre,sub_genre,gaiden_status,gaiden_read_count,gaiden_total_episodes,manual_tier,manual_order,reread_count,tag_data,aliases,memorable_quote,start_year,end_year,match_ban)
             VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);`,
            [n.id, n.title, n.author, n.tags, n.platforms, n.note, n.read_count, n.rating, n.rd, n.wins, n.losses, n.match_count, n.tier, n.created_at, n.awards, n.total_episodes, n.status, n.pinned, n.cover_image, n.link, n.work_status, n.read_count_updated_at, n.major_genre, n.sub_genre, n.gaiden_status, n.gaiden_read_count, n.gaiden_total_episodes, n.manual_tier, Number(n.manual_order) || 0, n.reread_count || 1, n.tag_data || "", n.aliases || "", n.memorable_quote || "", Number(n.start_year) || 0, Number(n.end_year) || 0, Number(n.match_ban) || 0]
          );
          // 🔧 v3.6.2: 복원된 작품의 표지를 라이브러리에서 "사용중"으로 동기화
          if (n.cover_image) {
            await applyNovelCover(n.id, n.cover_image, null);
            await loadCoverLibrary();
          }
          break;

        case 'match_delete':
          // 매칭 삭제 되돌리기
          const m = item.payload.match;
          await exec(
            `INSERT INTO matches (id,a_id,b_id,winner_id,decided_by,gap_when_matched,k_factor_used,created_at) VALUES (?,?,?,?,?,?,?,?);`,
            [m.id, m.a_id, m.b_id, m.winner_id, m.decided_by, m.gap_when_matched, m.k_factor_used, m.created_at]
          );
          await rebuildAllFromMatches(tagAttributes);
          break;

        // 🆕 v7.13.0: 일괄 작업 되돌리기 (광범위 변경인데 undo 불가하던 도태 해소)
        case 'read_count_batch':
          for (const c of item.payload.changes) {
            await exec("UPDATE novels SET read_count=?, read_count_updated_at=? WHERE id=?", [Number(c.prevReadCount) || 0, c.prevUpdatedAt ?? null, c.id]);
          }
          break;
        case 'status_batch':
          for (const c of item.payload.changes) {
            await exec("UPDATE novels SET status=? WHERE id=?", [c.prevStatus ?? "reading", c.id]);
          }
          break;
        case 'work_status_batch':
          for (const c of item.payload.changes) {
            await exec("UPDATE novels SET work_status=? WHERE id=?", [c.prevWorkStatus ?? "ongoing", c.id]);
          }
          break;

        default:
          Alert.alert("알림", "알 수 없는 작업 유형입니다.");
          return;
      }
      
      setUndoStack(prev => prev.slice(1));
      await loadList(undefined, undefined, "op");
      Alert.alert("완료", `"${item.description}" 작업을 되돌렸습니다.`);
      
    } catch (e) {
      console.warn("undo 오류:", e);
      Alert.alert("오류", "되돌리기 중 오류가 발생했습니다.");
    }
  }
  
  // 자동 승인 체크 (매칭 후 호출)
  async function checkAutoApprove(novelId) {
    if (!appSettings.autoApproveEnabled) return;
    
    const novel = await first("SELECT * FROM novels WHERE id=?", [novelId]);
    if (!novel) return;

    // 🆕 v6.0: manual/hybrid 모드에서는 자동 승인 불필요
    if (globalTierConfig.mode !== "match") return;

    const recommended = tierFromRating(novel.rating, globalTierConfig);
    const actual = getDisplayTier(novel, globalTierConfig);

    // 이미 gated 티어면 스킵
    if (isGatedTier(actual, globalTierConfig)) return;

    // 권장이 gated 티어가 아니면 스킵
    if (!isGatedTier(recommended, globalTierConfig)) return;
    
    // 조건 체크
    const minWins = appSettings.autoApproveMinWins || 10;
    const maxLosses = appSettings.autoApproveMaxLosses || 3;
    const minMatches = appSettings.autoApproveMinMatches || 15;
    
    if ((novel.wins || 0) >= minWins && 
        (novel.losses || 0) <= maxLosses && 
        (novel.match_count || 0) >= minMatches) {
      // 자동 승인
      await exec("UPDATE novels SET manual_tier=? WHERE id=?", [recommended, novelId]);
      addTierHistoryEntry(novelId, novel.title, actual, recommended);
      pushUndo('tier_change', {
        id: novelId,
        title: novel.title,
        prevTier: actual,
        newTier: recommended
      }, `자동 승인: ${novel.title} → ${recommended}`);
      
      // 📰 v3.0: 자동 승인 기록
      await addRecentChange(novelId, novel.title, "tier_review", {
        from: actual,
        to: recommended,
        action: "auto_approve"
      });
    }
  }

  // ============================================
  // 🧠 취향 발견 시스템 Phase 2: 데이터 로드 (v3.5.0)
  // ============================================
  
  /** 인사이트 대기열 로드 (미표시 + 최근 표시된 것) */
  async function loadInsights() {
    try {
      setInsightLoading(true);
      // 🔧 DB 최적화: CASE ORDER BY → 상태별 개별 쿼리 후 JS 병합
      // CASE 정렬은 인덱스를 무시하고 전체 테이블 스캔 → 196ms
      // 상태별 쿼리는 idx_iq_status_sort 인덱스 활용 가능
      const [pending, shown, rest] = await Promise.all([
        all(`SELECT * FROM insight_queue WHERE status = 'pending' ORDER BY priority DESC, created_at DESC LIMIT 20`),
        all(`SELECT * FROM insight_queue WHERE status = 'shown' ORDER BY priority DESC, created_at DESC LIMIT 20`),
        all(`SELECT * FROM insight_queue WHERE status IN ('confirmed', 'rejected') ORDER BY priority DESC, created_at DESC LIMIT 20`),
      ]);
      const rows = [...(pending || []), ...(shown || []), ...(rest || [])].slice(0, 20);
      setInsightList(rows);
    } catch (e) {
      console.warn("loadInsights 오류:", e);
      setInsightList([]);
    } finally {
      setInsightLoading(false);
    }
  }

  /** 상위 패턴 요약 로드 (높은 신뢰도 순) */
  // 🔧 DB 최적화: getCachedPatterns 활용 (TTL 10초 캐시) + JS 필터링
  // 기존: 매번 DB 쿼리 248ms → 캐시 히트 시 0ms
  async function loadPreferencePatterns() {
    try {
      const cached = await getCachedPatterns(3);
      const rows = cached
        .filter(p => p.confidence_lower > 0.1)
        .sort((a, b) => b.win_rate - a.win_rate || b.sample_size - a.sample_size)
        .slice(0, 30);
      setPreferencePatterns(rows);
    } catch (e) {
      console.warn("loadPreferencePatterns 오류:", e);
      setPreferencePatterns([]);
    }
  }

  /** 인사이트에 사용자 응답 기록 */
  async function handleInsightResponse(insightId, response) {
    // response: 'confirmed' | 'rejected' | 'skipped'
    try {
      const timestamp = Date.now();
      await exec(`
        UPDATE insight_queue 
        SET status = ?, user_response = ?, responded_at = ?
        WHERE id = ?
      `, [response === 'skipped' ? 'dismissed' : response, response, timestamp, insightId]);
      
      // 확인/거부된 인사이트는 가중치 학습에 반영
      if (response === 'confirmed' || response === 'rejected') {
        await recordInsightFeedback(insightId, response);
      }
      
      await loadInsights();
    } catch (e) {
      console.warn("handleInsightResponse 오류:", e);
    }
  }

  /** 인사이트 피드백을 가중치 학습에 반영 */
  async function recordInsightFeedback(insightId, response) {
    try {
      const insight = await first("SELECT * FROM insight_queue WHERE id = ?", [insightId]);
      if (!insight) return;
      
      // 관련 패턴의 user_confirmed 업데이트
      if (insight.pattern_id) {
        const delta = response === 'confirmed' ? 1 : -1;
        await exec(`
          UPDATE preference_patterns 
          SET user_confirmed = COALESCE(user_confirmed, 0) + ?
          WHERE id = ?
        `, [delta, insight.pattern_id]);
      }
      
      // 가중치 조정 트리거 (5개 피드백마다)
      const feedbackCount = await first(`
        SELECT COUNT(*) as cnt FROM insight_queue 
        WHERE status IN ('confirmed', 'rejected')
      `);
      if (feedbackCount && feedbackCount.cnt % 5 === 0) {
        await adjustWeightsFromFeedback();
      }
    } catch (e) {
      console.warn("recordInsightFeedback 오류:", e);
    }
  }

  /** 피드백 기반 가중치 자동 조정 */
  async function adjustWeightsFromFeedback() {
    try {
      // 확인된 인사이트의 패턴 유형 분석
      const confirmed = await all(`
        SELECT insight_type, COUNT(*) as cnt 
        FROM insight_queue 
        WHERE status = 'confirmed'
        GROUP BY insight_type
      `);
      
      const rejected = await all(`
        SELECT insight_type, COUNT(*) as cnt 
        FROM insight_queue 
        WHERE status = 'rejected'
        GROUP BY insight_type
      `);
      
      // 확인/거부 비율로 가중치 미세 조정
      const currentWeights = await getActiveWeights();
      if (!currentWeights) return;
      
      // 가중치 필드만 복사 (버전, 메타데이터 제외)
      const weightFields = [
        'w_elo', 'w_h2h', 'w_overall_winrate', 'w_reliability',
        'w_genre_matchup', 'w_tag_power', 'w_read_preference',
        'w_author_affinity', 'w_coordinate_zone'
      ];
      
      const weights = {};
      for (const field of weightFields) {
        weights[field] = Number(currentWeights[field]) || 0.1;
      }
      
      const adjustmentRate = 0.02; // 2% 조정
      
      // insight_type → weight 필드 매핑
      const typeToWeight = {
        'genre_matchup': 'w_genre_matchup',
        'genre_affinity': 'w_genre_matchup',
        'tag_power': 'w_tag_power',
        'author_loyalty': 'w_author_affinity',
        'rating_behavior': 'w_reliability',
        // 범용 타입들은 무시 (discover, confirm, deep)
      };
      
      // 확인된 유형 가중치 상승
      for (const row of confirmed) {
        const weightField = typeToWeight[row.insight_type];
        if (weightField && weights[weightField] !== undefined) {
          weights[weightField] = Math.min(0.3, weights[weightField] * (1 + adjustmentRate));
        }
      }
      
      // 거부된 유형 가중치 하락
      for (const row of rejected) {
        const weightField = typeToWeight[row.insight_type];
        if (weightField && weights[weightField] !== undefined) {
          weights[weightField] = Math.max(0.01, weights[weightField] * (1 - adjustmentRate));
        }
      }
      
      // 정규화 (합이 1이 되도록)
      const total = Object.values(weights).reduce((a, b) => a + b, 0);
      if (total > 0 && total !== 1) {
        for (const key of Object.keys(weights)) {
          weights[key] = weights[key] / total;
        }
      }
      
      // 변경된 가중치 추적
      const changedWeights = [];
      for (const field of weightFields) {
        if (Math.abs(weights[field] - (currentWeights[field] || 0)) > 0.001) {
          changedWeights.push(field);
        }
      }
      
      // 변경사항이 없으면 저장 안 함
      if (changedWeights.length === 0) return;
      
      // 기존 활성 가중치 비활성화 + 새 버전 저장 (원자적 실행)
      await execBatch([
        {
          sql: `UPDATE weight_config SET is_active = 0 WHERE is_active = 1`,
          params: [],
        },
        {
          sql: `INSERT INTO weight_config (
            w_elo, w_h2h, w_overall_winrate, w_reliability,
            w_genre_matchup, w_tag_power, w_read_preference,
            w_author_affinity, w_coordinate_zone,
            change_source, change_reason, changed_weights,
            is_active, created_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)`,
          params: [
            weights.w_elo,
            weights.w_h2h,
            weights.w_overall_winrate,
            weights.w_reliability,
            weights.w_genre_matchup,
            weights.w_tag_power,
            weights.w_read_preference,
            weights.w_author_affinity,
            weights.w_coordinate_zone,
            'user_feedback',
            '피드백 기반 자동 조정',
            JSON.stringify(changedWeights),
            Date.now(),
          ],
        },
      ]);
      
      console.log("[adjustWeightsFromFeedback] 가중치 조정 완료:", changedWeights);
      invalidateWeightsCache(); // 🔧 v3.5.14: 캐시 무효화
      
    } catch (e) {
      console.warn("adjustWeightsFromFeedback 오류:", e);
    }
  }

  /** 현재 매칭에 대한 예측 생성 */
  async function generateMatchPrediction(novelA, novelB) {
    if (!novelA || !novelB) {
      setMatchPrediction(null);
      return;
    }
    
    try {
      const prediction = await generateEnhancedPrediction(novelA, novelB, tagAttributes);
      setMatchPrediction(prediction);
    } catch (e) {
      console.warn("generateMatchPrediction 오류:", e);
      setMatchPrediction(null);
    }
  }

