                          for (const [id, sys] of Object.entries(DEFAULT_COORDINATE_SYSTEMS)) {
                            merged[id] = { ...sys };
                          }
                          setCoordinateSystems(merged);
                          await saveTagCoordinateSystems(merged);
                          Alert.alert("완료", "기본 좌표계가 초기화되었습니다.");
